	OtherProjectiles = ProjectileAimbot:CreateToggle({
		Name = 'Other Projectiles',
		Default = true,
		Function = function(call)
			if Blacklist then Blacklist.Object.Visible = call end
		end
	})

	Blacklist = ProjectileAimbot:CreateTextList({
		Name = 'Blacklist',
		Darker = true,
		Default = {'telepearl'},
		Visible = OtherProjectiles.Enabled
	})

	CustomPredictions = ProjectileAimbot:CreateToggle({
		Name = 'Custom Predictions',
		Default = false,
		Tooltip = 'lets u control how much it leads the target urself',
		Function = function(callback)
			if PredictHorizontal then PredictHorizontal.Object.Visible = callback end
			if PredictVertical then PredictVertical.Object.Visible = callback end
		end
	})
	PredictHorizontal = ProjectileAimbot:CreateSlider({
		Name = 'Horizontal',
		Min = 0,
		Max = 300,
		Default = 100,
		Suffix = '%',
		Darker = true,
		Visible = false
	})
	PredictVertical = ProjectileAimbot:CreateSlider({
		Name = 'Vertical',
		Min = 0,
		Max = 300,
		Default = 100,
		Suffix = '%',
		Darker = true,
		Visible = false
	})
	AutoCharge = ProjectileAimbot:CreateToggle({
		Name = "AutoCharge",
		Default = true,
		Function = function(v)
			if skidPAChargePercent and skidPAChargePercent.Object then skidPAChargePercent.Object.Visible = v end
		end
	})
	skidPAChargePercent = ProjectileAimbot:CreateSlider({
		Name = 'Charge Percent',
		Min = 1,
		Max = 100,
		Default = 100,
	})
end)

local Attacking


run(function()
	local LocalPlayer = lplr
	local Entity = entitylib
	local Camera = gameCamera
	local TweenService = tweenService
	local RunService = runService
	local UserInputService = inputService
	local PredictionLib = prediction
	local TargetInfo = targetinfo
	local getTinkerMount = bedwars.getTinkerMount
	local watchProjectile = bedwars.watchProjectile
	local SwordTiming = vape.Libraries.swordtiming
	local Killaura
	local Targets
	local Sort
	local FastHits
	local AlsoUse
	local SwingRange
	local AttackRange
	local SwingTime
	local AttackSpeed
	local HighHitreg
	local Hitreg
	local BurstHits
	local BurstDelay
	local AngleSlider
	local AirHits
	local MaxTargets
	local Mouse
	local AFKCheck
