run(function()
	local AutoAdetunde
	local PriorityList
	local UpgradeToMax
	local DelaySlider
	local BeforeDeath
	local DeathHealth
	local upgradeNames = {
		'Strength',
		'Speed',
		'Shield',
		'Strength > Speed > Shield',
		'Strength > Shield > Speed',
		'Speed > Strength > Shield',
		'Speed > Shield > Strength',
		'Shield > Strength > Speed',
		'Shield > Speed > Strength'
	}
	local upgradeKeys = {Strength = 'strength', Speed = 'speed', Shield = 'shield'}
	local upgradeIndex = 1
	local upgradeRemote
	local upgradeMeta
	local crystalType

	task.spawn(function()
		upgradeRemote = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('UpgradeFrostyHammer')
	end)

	task.spawn(function()
		pcall(function()
			upgradeMeta = require(replicatedStorage.TS.games.bedwars.items['frosty-hammer']['frosty-hammer-upgrades']).FrostyHammerUpgradeMeta
		end)
		pcall(function()
			crystalType = require(replicatedStorage.TS.item['item-type']).ItemType.FROST_CRYSTAL
		end)
	end)

	local function getLevels()
		return {
			strength = lplr:GetAttribute('strength') or 0,
			speed = lplr:GetAttribute('speed') or 0,
			shield = lplr:GetAttribute('shield') or 0
		}
	end

	local function getMaxLevel(key, levels)
		local tiers = upgradeMeta and upgradeMeta[key] and upgradeMeta[key].tiers
		local max = tiers and #tiers or 3
		for k, v in levels do
			if k ~= key and v >= max then
				return max - 1
			end
		end
		return max
	end

	local function getPrice(key, level)
		local tiers = upgradeMeta and upgradeMeta[key] and upgradeMeta[key].tiers
		local tier = tiers and tiers[level + 1]
		return tier and tier.price or 0
	end

	local function getCrystals()
		if not crystalType then return math.huge end
		local item = getItem(crystalType)
		return item and item.amount or 0
	end

	local function canBuy(key, levels, crystals)
		local level = levels[key]
		if level >= getMaxLevel(key, levels) then return false end
		return crystals >= getPrice(key, level)
	end

	local function sendUpgrade(key)
		pcall(function()
			upgradeRemote:InvokeServer(key)
		end)
	end

	local function lowHealth()
		local char = lplr.Character
		local hp = char and char:GetAttribute('Health')
		local maxHp = char and char:GetAttribute('MaxHealth')
		if not hp or not maxHp or maxHp <= 0 then return false end
		return (hp / maxHp) * 100 <= DeathHealth.Value
	end

	local function pickNext(order, levels, crystals, dump)
		if dump then
			for i = 0, #order - 1 do
				local idx = (upgradeIndex + i - 1) % #order + 1
				if canBuy(order[idx], levels, crystals) then
					upgradeIndex = idx % #order + 1
					return order[idx]
				end
			end
			return nil
		end

		if UpgradeToMax.Enabled or #order == 1 then
			for _, k in order do
				if levels[k] < getMaxLevel(k, levels) then
					return canBuy(k, levels, crystals) and k or nil
				end
			end
			return nil
		end

		if upgradeIndex > #order then upgradeIndex = 1 end
		for i = 0, #order - 1 do
			local idx = (upgradeIndex + i - 1) % #order + 1
			local k = order[idx]
			if levels[k] < getMaxLevel(k, levels) then
				if canBuy(k, levels, crystals) then
					upgradeIndex = idx % #order + 1
					return k
				end
				return nil
			end
		end
		return nil
	end

	local function getOrder()
		local order = {}
		for part in tostring(PriorityList.Value):gmatch('[^>]+') do
			local trimmed = part:match('^%s*(.-)%s*$')
			if upgradeKeys[trimmed] then
				table.insert(order, upgradeKeys[trimmed])
			end
		end
		return order
	end

	AutoAdetunde = vape.Categories.Kits:CreateModule({
		Name = 'AutoAdetunde',
		Function = function(callback)
			if callback then
				upgradeIndex = 1
				cleanThread(AutoAdetunde, task.spawn(function()
					repeat
						local dump = false
						if upgradeRemote and entitylib.isAlive and store.hand and store.hand.tool and store.hand.tool.Name == 'frosty_hammer' then
							local order = getOrder()
							if #order > 0 then
								dump = BeforeDeath.Enabled and lowHealth()
								local key = (dump or not BeforeDeath.Enabled) and pickNext(order, getLevels(), getCrystals(), dump) or nil
								if key then
									sendUpgrade(key)
								else
									dump = false
								end
							end
						end
						task.wait(dump and 0.1 or math.max(DelaySlider.Value, 0.3))
					until not AutoAdetunde.Enabled
				end))
			end
		end,
		Tooltip = 'auto upgrades the pick u chose when u got the crystals'
	})

	PriorityList = AutoAdetunde:CreateDropdown({
		Name = 'Priority',
		List = upgradeNames,
		Default = 'Strength',
		Function = function(val)
			upgradeIndex = 1
			if UpgradeToMax and UpgradeToMax.Object then
				UpgradeToMax.Object.Visible = tostring(val):find('>', 1, true) ~= nil
			end
		end
	})

	UpgradeToMax = AutoAdetunde:CreateToggle({
		Name = 'Upgrade to Max',
		Default = false,
		Visible = false,
		Darker = true,
		Tooltip = 'dumps every crystal into the first upgrade in ur path til its capped, then moves to the next one instead of switchin every time'
	})

	DelaySlider = AutoAdetunde:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 2,
		Default = 0.3,
		Decimal = 10,
		Suffix = 's'
	})

	BeforeDeath = AutoAdetunde:CreateToggle({
		Name = 'upgrade before death',
		Default = false,
		Tooltip = 'saves ur crystals and only upgrades when u bout to die so they aint wasted gng',
		Function = function(callback)
			if DeathHealth and DeathHealth.Object then
				DeathHealth.Object.Visible = callback
			end
		end
	})

	DeathHealth = AutoAdetunde:CreateSlider({
		Name = 'death hp',
		Min = 1,
		Max = 100,
		Default = 20,
		Suffix = '%',
		Darker = true,
		Visible = false,
		Tooltip = 'how low ur hp gotta be before it dumps everything'
	})

	task.defer(function()
		if UpgradeToMax and UpgradeToMax.Object then
			UpgradeToMax.Object.Visible = tostring(PriorityList.Value):find('>', 1, true) ~= nil
		end
		if DeathHealth and DeathHealth.Object and BeforeDeath then
			DeathHealth.Object.Visible = BeforeDeath.Enabled
		end
	end)
end)

run(function()
    local AutoWhisper
    local PlayerDropdown
    local AutoHeal
    local AutoHealSlider
    local AutoFly
    local LimitToItem
    local RefreshButton
    local running = false
    local healRunning = false
    local flyRunning = false
    local currentTarget = nil
    local currentMountedPlayer = nil
    local fallCheckTimer = 0
    local hasActivatedFly = false
    
    local function isHoldingOwlOrb()
        if not entitylib.isAlive then return false end
        
        local inventory = store.inventory
        if inventory and inventory.inventory and inventory.inventory.hand then
            local handItem = inventory.inventory.hand
            if handItem and handItem.itemType == "owl_orb" then
                return true
            end
        end
        return false
    end
    
    local function getMountedPlayer()
        local owlTarget = lplr:GetAttribute('OwlTarget')
        if owlTarget then
            return playersService:GetPlayerByUserId(owlTarget)
        end
        return nil
    end
    
    local function mountBirdToPlayer(targetPlayer)
        if not targetPlayer or not targetPlayer.Character then return false end
        
        if LimitToItem.Enabled and not isHoldingOwlOrb() then
            return false
        end
        
        local success = false
        pcall(function()
            local result = bedwars.Client:Get(remotes.SummonOwl).instance:InvokeServer(targetPlayer)
            
            if result then
            task.wait(0.05)
            
            pcall(function()
    			bedwars.Client:Get(remotes.UseAbility).instance:FireServer("SUMMON_OWL")
			end)
                
                currentMountedPlayer = targetPlayer
                success = true
            end
        end)
        
        return success
    end
    
    local function demountOwl()
        pcall(function()
            bedwars.Client:Get(remotes.UseAbility).instance:FireServer("DEACTIVE_OWL")
            
            task.wait(0.05)
            
            bedwars.Client:Get(remotes.RemoveOwl).instance:FireServer()
        end)
        
        currentMountedPlayer = nil
    end
    
    local function healTarget()
        pcall(function()
            replicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility"):FireServer("OWL_HEAL")
        end)
    end
    
    local function isFalling(player)
        if not player or not player.Character or not player.Character.PrimaryPart then
            return false
        end
        
        local velocity = player.Character.PrimaryPart.AssemblyLinearVelocity.Y
        return velocity < -20
    end
    
	local voidRayParams = RaycastParams.new()
	voidRayParams.FilterType = Enum.RaycastFilterType.Blacklist
	voidRayParams.RespectCanCollide = true

	local function isAboveVoid(player)
		if not player or not player.Character or not player.Character.PrimaryPart then
			return false
		end
		
		local rayOrigin = player.Character.PrimaryPart.Position
		local rayDirection = Vector3.new(0, -1000, 0)
		
		voidRayParams.FilterDescendantsInstances = {player.Character, gameCamera}
		
		local rayResult = workspace:Raycast(rayOrigin, rayDirection, voidRayParams)
		
		if not rayResult then
			return true
		end
		
		return rayResult.Distance > 200
	end
    
    local function activateFly()
        pcall(function()
            replicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility"):FireServer("OWL_LIFT")
            
            hasActivatedFly = true
            task.spawn(function()
                task.wait(85)
                hasActivatedFly = false
            end)
        end)
    end
    
    local OwlAuraToggle
    local OwlTargets
    local OwlRange
    local OwlSort
    local owlAuraConn
    local OWL_SPEED = 220
    local OWL_GRAVITY = 35
    local OWL_COOLDOWN = 0.85
    local OWL_MARGIN = 0.05
    local OWL_AIM_HOLD = 0.15
    local owlNextFire = 0
    local owlBusy = false

    local function owlDamageSort(a, b)
        local ta = tonumber(a.Entity and a.Entity.Character and a.Entity.Character:GetAttribute('LastDamageTakenTime')) or 0
        local tb = tonumber(b.Entity and b.Entity.Character and b.Entity.Character:GetAttribute('LastDamageTakenTime')) or 0
        if ta == tb then
            return a.Magnitude < b.Magnitude
        end
        return ta > tb
    end

    local function getOwlSort()
        local mode = OwlSort and OwlSort.Value or 'Distance'
        if mode == 'Damage' then return owlDamageSort end
        if mode == 'Cursor' then return sortmethods.Cursor end
        return nil
    end

    local function setOwlOptionsVisible(val)
        if OwlTargets and OwlTargets.Object then OwlTargets.Object.Visible = val end
        if OwlRange and OwlRange.Object then OwlRange.Object.Visible = val end
        if OwlSort and OwlSort.Object then OwlSort.Object.Visible = val end
    end
    local owlRay = RaycastParams.new()
    owlRay.FilterType = Enum.RaycastFilterType.Include

    local function getOwlModel()
        return workspace:FindFirstChild("ClientOwl")
    end

    local function getBulletOrigin(owl)
        if not owl then return nil end
        local bo = owl:FindFirstChild("bulletOrigin", true)
        if bo and bo:IsA('Attachment') then return bo.WorldPosition end
        local primary = owl.PrimaryPart or owl:FindFirstChild("Handle") or owl:FindFirstChildWhichIsA('BasePart', true)
        return primary and primary.Position or nil
    end

    local function getOwlRemotes()
        local rbxts = replicatedStorage:FindFirstChild("rbxts_include")
        local netManaged = rbxts
            and rbxts:FindFirstChild("node_modules")
            and rbxts.node_modules:FindFirstChild("@rbxts")
            and rbxts.node_modules["@rbxts"]:FindFirstChild("net")
            and rbxts.node_modules["@rbxts"].net:FindFirstChild("out")
            and rbxts.node_modules["@rbxts"].net.out:FindFirstChild("_NetManaged")
        if not netManaged then return nil, nil end
        return netManaged:FindFirstChild("OwlAiming"), netManaged:FindFirstChild("OwlFireProjectile")
    end

    local function getOwlAimPoint(fromPos, ent)
        local map = workspace:FindFirstChild('Map')
        owlRay.FilterDescendantsInstances = map and {map} or {}
        local root = ent.RootPart
        local vel = root.AssemblyLinearVelocity or Vector3.zero
        local airborne = (ent.Humanoid and ent.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(vel.Y) > 0.01
        local calc = prediction.SolveTrajectory(fromPos, OWL_SPEED, OWL_GRAVITY, root.Position, vel, workspace.Gravity, ent.HipHeight or 2, ent.Jumping and 42.6 or nil, owlRay, airborne, root.Position, root, nil, true)
        return calc or root.Position
    end

    local function owlCanShoot(owl)
        if owl:GetAttribute('Status') == 2 then return false end
        local owlPart = owl.PrimaryPart
        local carrier = getMountedPlayer()
        local carrierRoot = carrier and carrier.Character and carrier.Character.PrimaryPart
        if owlPart and carrierRoot and (owlPart.Position - carrierRoot.Position).Magnitude > 15 then
            return false
        end
        return true
    end

    local function owlShoot(owl, ent)
        local owlAiming, owlFire = getOwlRemotes()
        local owlHandle = owl.PrimaryPart or owl:FindFirstChild("Handle")
        if not (owlAiming and owlFire and owlHandle) then return end
        owlAiming:FireServer({ owl = owlHandle, starting = true })
        task.wait(math.max(OWL_AIM_HOLD, owlNextFire - workspace:GetServerTimeNow()))
        local fromPos = getBulletOrigin(owl)
        local stillGood = fromPos and ent.RootPart and ent.RootPart.Parent and AutoWhisper.Enabled and OwlAuraToggle.Enabled
        owlAiming:FireServer({ owl = owlHandle, starting = false })
        if not stillGood then return end
        local direction = (getOwlAimPoint(fromPos, ent) - fromPos).Unit * OWL_SPEED
        owlFire:FireServer({
            fromPosition = fromPos,
            direction = direction,
            offset = nil,
            ProjectileRefId = httpService:GenerateGUID(false):sub(1, 8):upper(),
            initialVelocity = direction
        })
        owlNextFire = workspace:GetServerTimeNow() + OWL_COOLDOWN + OWL_MARGIN
    end

    local function stopOwlAura()
        if owlAuraConn then
            owlAuraConn:Disconnect()
            owlAuraConn = nil
        end
    end

    local function startOwlAura()
        stopOwlAura()
        owlAuraConn = runService.Heartbeat:Connect(function()
            if owlBusy then return end
            if workspace:GetServerTimeNow() < owlNextFire - OWL_AIM_HOLD then return end
            if not entitylib.isAlive then return end
            local owl = getOwlModel()
            if not owl or not owlCanShoot(owl) then return end
            local fromPos = getBulletOrigin(owl)
            if not fromPos then return end
            local wallIgnore = false
            if OwlTargets and OwlTargets.Walls and OwlTargets.Walls.Enabled then
                wallIgnore = {owl}
                local carrier = getMountedPlayer()
                if carrier and carrier.Character then
                    table.insert(wallIgnore, carrier.Character)
                end
            end
            local ent = entitylib.EntityPosition({
                Range = OwlRange and OwlRange.Value or 40,
                Part = 'RootPart',
                Origin = fromPos,
                Wallcheck = wallIgnore,
                Players = OwlTargets and OwlTargets.Players and OwlTargets.Players.Enabled,
                NPCs = OwlTargets and OwlTargets.NPCs and OwlTargets.NPCs.Enabled,
                Sort = getOwlSort(),
            })
            if not ent or not ent.RootPart then return end
            owlBusy = true
            task.spawn(function()
                pcall(owlShoot, owl, ent)
                owlBusy = false
            end)
        end)
    end

    AutoWhisper = vape.Categories.Kits:CreateModule({
        Name = "AutoWhisper",
        Function = function(callback)
            if callback and OwlAuraToggle and OwlAuraToggle.Enabled then
                startOwlAura()
            else
                stopOwlAura()
            end
            running = callback
            healRunning = callback
            flyRunning = callback
            
            if callback then
                task.spawn(function()
                    while running do
                        if LimitToItem.Enabled and not isHoldingOwlOrb() then
                            task.wait(0.2)
                            continue
                        end
                        
                        local targetPlayer = playersService:FindFirstChild(PlayerDropdown.Value)
                        if targetPlayer then
                            currentTarget = targetPlayer
                            
                            local mountedTo = getMountedPlayer()
                            
                            if mountedTo ~= targetPlayer then
                                if mountedTo and mountedTo ~= targetPlayer then
                                    demountOwl()
                                    task.wait(0.3)
                                end
                                
                                if not mountedTo or mountedTo ~= targetPlayer then
                                    local success = mountBirdToPlayer(targetPlayer)
                                    if not success then
                                        task.wait(0.5)
                                    else
                                        task.wait(1)
                                    end
                                end
                            else
                                task.wait(0.5)
                            end
                        else
                            task.wait(0.5)
                        end
                    end
                end)
                
                if AutoHeal.Enabled then
                    task.spawn(function()
                        while healRunning and AutoHeal.Enabled do
                            if currentTarget then
                                local health, maxHealth = getPlayerHealth(currentTarget)
                                if health and maxHealth and maxHealth > 0 then
                                    local healthPercent = (health / maxHealth) * 100
                                    if healthPercent < AutoHealSlider.Value and healthPercent < 90 then
                                        healTarget()
                                        task.wait(8.5)
                                    end
                                end
                            end
                            
                            task.wait(0.5)
                        end
                    end)
                end
                
                if AutoFly.Enabled then
                    task.spawn(function()
                        while flyRunning and AutoFly.Enabled do
                            if currentTarget and not hasActivatedFly then
                                if isFalling(currentTarget) and isAboveVoid(currentTarget) then
                                    fallCheckTimer = fallCheckTimer + 0.1
                                    
                                    if fallCheckTimer >= 0.5 then
                                        activateFly()
                                        fallCheckTimer = 0
                                    end
                                else
                                    fallCheckTimer = 0
                                end
                            else
                                fallCheckTimer = 0
                            end
                            
                            task.wait(0.1)
                        end
                    end)
                end
                
                AutoWhisper:Clean(playersService.PlayerAdded:Connect(function()
                    task.wait(0.5)
                    local newList = getTeammates(true)
                    if PlayerDropdown then
                        PlayerDropdown:Change(newList)
                        
                        if #newList > 0 then
                            if not PlayerDropdown.Value or PlayerDropdown.Value == "" or not table.find(newList, PlayerDropdown.Value) then
                                PlayerDropdown:SetValue(newList[1])
                            end
                        end
                    end
                end))
                
                AutoWhisper:Clean(playersService.PlayerRemoving:Connect(function(player)
                    task.wait(0.5)
                    local newList = getTeammates(true)
                    if PlayerDropdown then
                        PlayerDropdown:Change(newList)
                        
                        if #newList > 0 then
                            if not PlayerDropdown.Value or PlayerDropdown.Value == "" or not table.find(newList, PlayerDropdown.Value) then
                                PlayerDropdown:SetValue(newList[1])
                            end
                        end
                    end
                    
                    if currentTarget == player then
                        currentTarget = nil
                        currentMountedPlayer = nil
                    end
                end))
                
                AutoWhisper:Clean(lplr:GetAttributeChangedSignal('Team'):Connect(function()
                    task.wait(0.5)
                    local newList = getTeammates(true)
                    if PlayerDropdown then
                        PlayerDropdown:Change(newList)
                        
                        if #newList > 0 then
                            if not PlayerDropdown.Value or PlayerDropdown.Value == "" or not table.find(newList, PlayerDropdown.Value) then
                                PlayerDropdown:SetValue(newList[1])
                            end
                        end
                    end
                    currentTarget = nil
                    currentMountedPlayer = nil
                    hasActivatedFly = false
                end))
                
            else
                running = false
                healRunning = false
                flyRunning = false
                currentTarget = nil
                currentMountedPlayer = nil
                hasActivatedFly = false
                fallCheckTimer = 0
            end
        end,
    })
    
    PlayerDropdown = AutoWhisper:CreateDropdown({
        Name = "Bird Target",
        List = {},
        Function = function(val)
            if val then
                local targetPlayer = playersService:FindFirstChild(val)
                if targetPlayer then
                    currentTarget = targetPlayer
                end
            end
        end,
    })
    RefreshButton = AutoWhisper:CreateButton({
        Name = "Refresh Teammates",
        Function = function()
            task.spawn(function()
                local newList = getTeammates(true)
                
                if PlayerDropdown then
                    pcall(function()
                        PlayerDropdown:Change(newList)
                        
                        if #newList > 0 then
                            if not PlayerDropdown.Value or PlayerDropdown.Value == "" or not table.find(newList, PlayerDropdown.Value) then
                                PlayerDropdown:SetValue(newList[1])
                            else
                                PlayerDropdown:SetValue(PlayerDropdown.Value)
                            end
                        end
                    end)
                end
                
                notif("AutoWhisper", string.format("teammate list (%d teammates)", #newList), 2)
            end)
        end,
    })
    
    LimitToItem = AutoWhisper:CreateToggle({
        Name = "Limit to Owl Orb",
        Default = true,
        Function = function(val)
        end,
    })

    AutoFly = AutoWhisper:CreateToggle({
        Name = "Auto Fly",
        Default = true,
        Function = function(val)
            if AutoWhisper.Enabled then
                if val then
                    flyRunning = true
                    hasActivatedFly = false
                    fallCheckTimer = 0
                    
                    task.spawn(function()
                        while flyRunning and AutoFly.Enabled do
                            if currentTarget and not hasActivatedFly then
                                if isFalling(currentTarget) and isAboveVoid(currentTarget) then
                                    fallCheckTimer = fallCheckTimer + 0.1
                                    
                                    if fallCheckTimer >= 0.5 then
                                        activateFly()
                                        fallCheckTimer = 0
                                    end
                                else
                                    fallCheckTimer = 0
                                end
                            else
                                fallCheckTimer = 0
                            end
                            
                            task.wait(0.1)
                        end
                    end)
                else
                    flyRunning = false
                    hasActivatedFly = false
                    fallCheckTimer = 0
                end
            end
        end,
    })
    
    AutoHeal = AutoWhisper:CreateToggle({
        Name = "Auto Heal",
        Default = true,
        Function = function(val)
            if AutoHealSlider and AutoHealSlider.Object then
                AutoHealSlider.Object.Visible = val
            end
            
            if AutoWhisper.Enabled then
                if val then
                    healRunning = true
                    task.spawn(function()
                        while healRunning and AutoHeal.Enabled do
                            if currentTarget then
                                local health, maxHealth = getPlayerHealth(currentTarget)
                                if not (health and maxHealth and maxHealth > 0) then task.wait(0.5) continue end
                                local healthPercent = (health / maxHealth) * 100
                                if healthPercent < AutoHealSlider.Value and healthPercent < 90 then
                                    healTarget()
                                    task.wait(8.5)
                                end
                            end
                            
                            task.wait(0.5)
                        end
                    end)
                else
                    healRunning = false
                end
            end
        end,
    })
    
    AutoHealSlider = AutoWhisper:CreateSlider({
        Name = "Heal Threshold",
        Min = 1,
        Max = 100,
        Default = 50,
        Suffix = "%",
    })

    OwlAuraToggle = AutoWhisper:CreateToggle({
        Name = "Owl Aura",
        Default = false,
        Function = function(val)
            setOwlOptionsVisible(val)
            if AutoWhisper.Enabled and val then
                startOwlAura()
            else
                stopOwlAura()
            end
        end,
        Tooltip = 'ur owl shoots whoever close to it on its own',
    })

    OwlTargets = AutoWhisper:CreateTargets({
        Players = true,
        NPCs = false,
        Walls = true,
        Visible = false
    })

    OwlRange = AutoWhisper:CreateSlider({
        Name = "Aura Range",
        Min = 10,
        Max = 60,
        Default = 40,
        Visible = false,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end,
    })

    OwlSort = AutoWhisper:CreateDropdown({
        Name = "Aura Sort",
        List = {'Distance', 'Damage', 'Cursor'},
        Default = 'Distance',
        Visible = false,
        Tooltip = 'who the owl goes for first, damage means whoever got hit last',
    })

    task.defer(function()
        setOwlOptionsVisible(OwlAuraToggle.Enabled)
    end)
end)

run(function()
	local AutoLasso
	local Targets
	local Range
	local Angle
	local LimitToLasso
	local ArrowCharge

	local projectileRemote = {InvokeServer = function() end}
	task.spawn(function()
		projectileRemote = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('ProjectileFire')
	end)
	local handGunRemote = {InvokeServer = function() end}
	task.spawn(function()
		handGunRemote = game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("HandGunFireRequest")
	end)

	local rayCheck = RaycastParams.new()
	local lastShot = 0
	local autoLassoLoop

	local function doLasso()
		if not entitylib.isAlive then return false end
		if LimitToLasso.Enabled then
			if not store.hand or not store.hand.tool or store.hand.tool.Name ~= 'lasso' then
				return false
			end
		end

		local lasso = getItem('lasso')
		if not lasso then return false end

		local ent = entitylib.EntityPosition({
			Range = Range.Value,
			Part = 'RootPart',
			Wallcheck = Targets.Walls.Enabled,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Sort = sortmethods.Distance
		})
		if not ent or not ent.RootPart then return false end

		local selfpos = entitylib.character.RootPart.Position
		local localfacing = gameCamera.CFrame.LookVector * Vector3.new(1, 0, 1)
		local delta = (ent.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
		if delta.Magnitude <= 0.001 then return false end
		if math.acos(math.clamp(localfacing:Dot(delta.Unit), -1, 1)) > (math.rad(Angle.Value) / 2) then return false end
		local meta = bedwars.ProjectileMeta['lasso']
		local projSpeed = (meta and tonumber(meta.launchVelocity)) or 200
		local gravity = (meta and tonumber(meta.gravitationalAcceleration)) or 135
		local hip = ent.HipHeight or (ent.Humanoid and ent.Humanoid.HipHeight) or 2
		local leadPos = ent.RootPart.Position + Vector3.new(0, hip * 0.15, 0)
		local vel = ent.RootPart.AssemblyLinearVelocity or ent.RootPart.Velocity
		local calc = prediction.SolveTrajectory(selfpos, projSpeed, gravity, leadPos, vel, workspace.Gravity, hip, ent.Jumping and 42.6 or nil, rayCheck, nil, ent.RootPart.Position, ent.RootPart, nil, true)
		if not calc then return false end
		local originalSlot = store.inventory.hotbarSlot
		local lassoSlot
		for i, v in store.inventory.hotbar do
			if v.item and v.item.itemType == 'lasso' then
				lassoSlot = i - 1
				break
			end
		end

		local swapped = false
		if lassoSlot and lassoSlot ~= originalSlot and not LimitToLasso.Enabled then
			hotbarSwitch(lassoSlot)
			task.wait(0.03)
			swapped = true
		end

		local res = projectileRemote:InvokeServer(
			lasso.tool,
			'lasso',
			'lasso',
			selfpos,
			selfpos,
			CFrame.lookAt(selfpos, calc).LookVector * projSpeed,
			httpService:GenerateGUID(true),
			{
				drawDurationSeconds = 1,
				shotId = httpService:GenerateGUID(false)
			},
			workspace:GetServerTimeNow() - 0.045
		)

		if swapped then
			hotbarSwitch(originalSlot)
		end

		return res and true or false
	end

	local function startAutoLassoLoop()
		if autoLassoLoop then return end
		autoLassoLoop = task.spawn(function()
			while AutoLasso and AutoLasso.Enabled do
				local ok, fired = pcall(doLasso)
				task.wait((ok and fired) and 0.5 or 0.1)
			end
			autoLassoLoop = nil
		end)
	end

	local function stopAutoLassoLoop()
		if autoLassoLoop then
			task.cancel(autoLassoLoop)
			autoLassoLoop = nil
		end
	end

	AutoLasso = vape.Categories.Kits:CreateModule({
		Name = 'AutoLasso',
		Function = function(callback)
			if callback then
				startAutoLassoLoop()
			else
				stopAutoLassoLoop()
			end
		end
	})

	Targets = AutoLasso:CreateTargets({Players = true})
	Range = AutoLasso:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 60,
		Default = 60,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	Angle = AutoLasso:CreateSlider({
		Name = 'Max angle',
		Min = 1,
		Max = 360,
		Default = 120
	})
	LimitToLasso = AutoLasso:CreateToggle({
		Name = 'Limit to Lasso',
		Default = false,
	})
end)

run(function()
	local InfiniteSigrid
	local Kit = 'elk_master'
	local running = false

	InfiniteSigrid = vape.Categories.Kits:CreateModule({
		Name = 'InfiniteSigrid',
		Tooltip = 'ride yo shitty ass elk forever',
		Function = function(call)
			if call then
				if running then return end
				running = true
				task.spawn(function()
					repeat
						if entitylib.isAlive then
							if store.equippedKit == Kit then
								local Mount = bedwars.Client:Get('ElkKitMounted')
								if Mount then
									Mount:SendToServer()
								end
							end
						end
						task.wait(0.1)
					until not InfiniteSigrid.Enabled or not running
					running = false
				end)
			else
				running = false
			end
		end
	})
end)

run(function()
	local MinerSpy
	local IgnoreTeammatesMiner

	MinerSpy = vape.Categories.Kits:CreateModule({
		Name = "MinerSpy",
		Tooltip = 'notifies when players get petrified or mined by a miner',
		Function = function(callback)
			if callback then
				MinerSpy:Clean(bedwars.Client:OnEvent("Petrified", function(tbl)
					if not MinerSpy.Enabled then return end
					local victim = playersService:GetPlayerFromCharacter(tbl.to)
					local killer = playersService:GetPlayerFromCharacter(tbl.killer)
					if not victim then return end

					if IgnoreTeammatesMiner.Enabled then
						if victim.Team == lplr.Team then return end
					end

					local victimName = victim.Name
					victimName = victimName:sub(1, 1):upper() .. victimName:sub(2)

					local killerText = ''
					if killer then
						local killerName = killer.Name
						killerName = killerName:sub(1, 1):upper() .. killerName:sub(2)
						killerText = ' by ' .. killerName
					end

					notif("MinerSpy", victimName .. " was petrified" .. killerText, 8)
				end))

				MinerSpy:Clean(bedwars.Client:OnEvent("PetrifiedPlayerDestroyed", function(tbl)
					if not MinerSpy.Enabled then return end
					local destroyer = tbl.destroyer

					local destroyerText = 'Unknown'
					if destroyer then
						local destroyerName = destroyer.Name
						destroyerText = destroyerName:sub(1, 1):upper() .. destroyerName:sub(2)
						if IgnoreTeammatesMiner.Enabled and destroyer.Team == lplr.Team then return end
					end

					local rewardText = ''
					if tbl.rewards then
						local totals = {}
						local order = {}
						for _, reward in ipairs(tbl.rewards) do
							local item = tostring(reward.itemType) or 'unknown'
							local amount = tonumber(reward.amount) or 0
							if not totals[item] then
								totals[item] = 0
								table.insert(order, item)
							end
							totals[item] = totals[item] + amount
						end
						local parts = {}
						for _, item in ipairs(order) do
							table.insert(parts, item .. ' x' .. totals[item])
						end
						if #parts > 0 then
							rewardText = ' | Loot: ' .. table.concat(parts, ', ')
						end
					end

					notif("MinerSpy", destroyerText .. " mined a petrified player" .. rewardText, 8)
				end))
			end
		end
	})
	IgnoreTeammatesMiner = MinerSpy:CreateToggle({Name='Ignore Teammates',Default=true})
end)

run(function()
	local AutoVulcan
	local Targets
	local ArrowCharge
	local turretfiretime = {}
	local netman = game:GetService("ReplicatedStorage").rbxts_include.node_modules["@rbxts"].net.out._NetManaged
	local turretTargets = {}
	local Sort
	local AimTurretRemote = netman:FindFirstChild("AimTurret")
	local PFR = netman:FindFirstChild("ProjectileFire")
	local turretthread = {}
	local Distance
	local PHR = netman:FindFirstChild("ProjectileHit")
	local RTR = netman:FindFirstChild("RaycastTurret")
	local LimitTablet

	local function tableFind(tab, val)
		for _, v in ipairs(tab) do
			if v == val then return true end
		end
		return false
	end

	local function isHoldingTablet()
		local hand = store.hand
		return hand and hand.tool and hand.tool.Name and hand.tool.Name:find('tablet') ~= nil
	end

	local function getOwnedTurrets()
		local turrets = {}
		for _, block in ipairs(store.blocks or {}) do
			if block.Name == "camera_turret"
				and block:GetAttribute("PlacedByUserId") == lplr.UserId
				and block.Parent
			then
				table.insert(turrets, block)
			end
		end
		return turrets
	end

	local function isTargetValid(ent, turretPos)
		if not ent or not ent.Character then return false end
		if not ent.RootPart or not ent.RootPart.Parent then return false end
		if (ent.Character:GetAttribute("Health") or 0) <= 0 then return false end
		if (turretPos - ent.RootPart.Position).Magnitude > (Distance and Distance.Value or 1000) then return false end
		return true
	end

	local function getTarget(turret)
		local turretPos = turret.Position
		local locked = turretTargets[turret]
		if isTargetValid(locked, turretPos) then
			return locked
		end

		local ent = entitylib.EntityPosition({
			Origin = turretPos,
			Range = Distance and Distance.Value or 1000,
			Part = "RootPart",
			Players = Targets and Targets.Players.Enabled or true,
			NPCs = Targets and Targets.NPCs.Enabled or true,
			Sort = sortmethods and Sort and sortmethods[Sort.Value] or nil
		})

		turretTargets[turret] = ent
		return ent
	end

	local turretBlockPosCache = {}

	local function fireTurret(turret)
		if not turret or not turret.Parent then return end
		if LimitTablet and LimitTablet.Enabled and not isHoldingTablet() then return end

		local turretPos = turret.Position
		local blockPos = turretBlockPosCache[turret]
		if not blockPos then
			blockPos = bedwars.BlockController:getBlockPosition(turretPos)
			turretBlockPosCache[turret] = blockPos
		end
		local ent = getTarget(turret)
		if not ent or not ent.RootPart then return end

		local char = ent.Character
		local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or ent.RootPart
		local targetVel = ent.RootPart.AssemblyLinearVelocity or Vector3.zero
		local travel = (torso.Position - turretPos).Magnitude / 300
		local targetPos = torso.Position + targetVel * travel

		local lookDir = targetPos - turretPos
		if lookDir.Magnitude < 0.1 then return end
		lookDir = lookDir.Unit

		local flatMag = Vector3.new(lookDir.X, 0, lookDir.Z).Magnitude
		local yaw = math.atan2(-lookDir.X, -lookDir.Z)
		local pitch = math.atan2(lookDir.Y, flatMag > 0 and flatMag or 0.001)

		if AimTurretRemote then
			pcall(function()
				AimTurretRemote:FireServer({
					angleX = math.deg(yaw),
					angleY = math.deg(pitch),
					turretBlockPos = blockPos,
				})
			end)
		end

		local now = tick()
		if (now - (turretfiretime[turret] or 0)) < (FireRate and FireRate.Value or 0.05) then return end
		turretfiretime[turret] = now

		local fireId = httpService:GenerateGUID(false):sub(1, 8)
		local shotId = httpService:GenerateGUID(false):sub(1, 8)
		local targetChar = ent.Character
		local shootOrigin = turretPos + lookDir * 2 + Vector3.new(0, 1, 0)
		local velocity = lookDir * 300

		task.spawn(function()
			local firedId
			local myKit = lplr.Character and lplr.Character:GetAttribute('Kit')
			if PFR and myKit ~= 'block-kicker' then
				pcall(function()
					firedId = PFR:InvokeServer(
						turret, nil, "turretBullet",
						shootOrigin, turretPos, velocity,
						fireId,
						{ shotId = shotId, drawDurationSec = 0 },
						workspace:GetServerTimeNow() - 0.045 - 0.045
					)
				end)
			elseif RTR then
				pcall(function()
					local targetDir = (targetPos - turretPos).Unit * 500
					RTR:FireServer(turret, turretPos + Vector3.new(0, 1, 0), targetDir, blockPos)
				end)
			end

			if not firedId then
				turretTargets[turret] = nil
				return
			end

			task.wait(0.05)
			if not targetChar or not targetChar.Parent then return end
			if (targetChar:GetAttribute("Health") or 0) <= 0 then return end

			if PHR then
				pcall(function() PHR:FireServer(firedId, targetChar) end)
				task.wait(0.02)
				if targetChar and targetChar.Parent and (targetChar:GetAttribute("Health") or 0) > 0 then
					pcall(function() PHR:FireServer(firedId, targetChar) end)
				end
			end
		end)
	end

	local function startTurretLoop(turret)
		if turretthread[turret] then return end

		turretthread[turret] = task.spawn(function()
			while AutoVulcan.Enabled and turret and turret.Parent do
				if entitylib.isAlive then
					pcall(fireTurret, turret)
				end
				task.wait(0.05)
			end
			turretthread[turret] = nil
			turretTargets[turret] = nil
			turretfiretime[turret] = nil
		end)
	end

	local function stopAllLoops()
		for _, thread in pairs(turretthread) do
			pcall(task.cancel, thread)
		end
		table.clear(turretthread)
		table.clear(turretTargets)
		table.clear(turretfiretime)
		table.clear(turretBlockPosCache)
	end

	AutoVulcan = vape.Categories.Kits:CreateModule({
		Name = 'AutoVulcan',
		Function = function(callback)
			if callback then
				cleanThread(AutoVulcan, task.spawn(function()
					while AutoVulcan.Enabled do
						local turrets = getOwnedTurrets()
						for _, turret in ipairs(turrets) do
							startTurretLoop(turret)
						end
						for turret, thread in pairs(turretthread) do
							if not turret.Parent then
								pcall(task.cancel, thread)
								turretthread[turret] = nil
								turretTargets[turret] = nil
								turretfiretime[turret] = nil
							end
						end
						task.wait(1)
					end
				end))
				AutoVulcan:Clean(stopAllLoops)
			else
				stopAllLoops()
			end
		end,
	})

	Targets = AutoVulcan:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = false,
	})

	FireRate = AutoVulcan:CreateSlider({
		Name = 'Fire Rate',
		Min = 0,
		Max = 3,
		Default = 0,
		Tooltip = 'Shots per second',
	})

	Distance = AutoVulcan:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 1000,
		Default = 1000,
		Suffix = function(val) return val == 1 and 'stud' or 'studs' end,
	})

	Sort = AutoVulcan:CreateDropdown({
		Name = 'Target mode',
		List = getSortList({'Distance', 'Health', 'Cursor'}),
		Default = 'Distance',
	})

	LimitTablet = AutoVulcan:CreateToggle({
		Name = 'Limit to tablet',
		Default = false,
		Tooltip = 'only works when u holdin the tablet'
	})
end)

run(function()
	local InstantJade
	local old = nil
	
    InstantJade = vape.Categories.Kits:CreateModule({
		Name = "InstantJade",
		Tooltip = "no cooldown on the jade hammer",
		Function = function(callback)
			if callback then
				if old then return end
				old = bedwars.CooldownController.isOnCooldown
				bedwars.CooldownController.isOnCooldown = function(self, id)
					if id ~= nil and string.find(tostring(id):lower(), 'jade', 1, true) then
						return false
					end
					if type(old) ~= 'function' then return false end
					return old(self, id)
				end
			else
				if old then
					bedwars.CooldownController.isOnCooldown = old
					old = nil
				end
			end
		end
	})
end)

