run(function()
	local KitSpy
	local BeehiveToggle
	local BeehiveBackground
	local BeehiveColor
	local LuciaToggle
	local LuciaIgnoreTeammates
	local LuciaDisplayName
	local FishermanToggle
	local FishermanIgnoreTeammates
	local BountyHunterToggle
	local BountyTargetToggle
	local BountyLootToggle
	local huntTargets = {}
	local BeehiveFolder = Instance.new('Folder')
	BeehiveFolder.Parent = vape.gui
	local BeehiveReference = {}
	local trackedPinatas = {}
	local FishNames = {
		fish_iron = "Iron Fish",
		fish_diamond = "Diamond Fish",
		fish_emerald = "Emerald Fish",
		fish_special = "Special Fish",
		fish_gold = "Gold Fish",
	}

	local function addBlur(parent)
		local blur = Instance.new('ImageLabel')
		blur.Name = 'Blur'
		blur.Size = UDim2.new(1, 89, 1, 52)
		blur.Position = UDim2.fromOffset(-48, -31)
		blur.BackgroundTransparency = 1
		blur.Image = getcustomasset('elevate/assets/new/blur.png')
		blur.ScaleType = Enum.ScaleType.Slice
		blur.SliceCenter = Rect.new(52, 31, 261, 502)
		blur.Parent = parent
		return blur
	end

	local function isMyBeehive(beehive)
		if not beehive then return false end
		local placedBy = beehive:GetAttribute("PlacedByUserId")
		return placedBy and placedBy == lplr.UserId
	end

	local function getBeehiveOwnerName(beehive)
		if not beehive then return "Unknown" end
		local placedBy = beehive:GetAttribute("PlacedByUserId")
		if not placedBy then return "Unknown" end
		local player = playersService:GetPlayerByUserId(placedBy)
		if player then return player.Name end
		return "Player"
	end

	local function getBeehiveOwner(beehive)
		if not beehive then return nil end
		local placedBy = beehive:GetAttribute("PlacedByUserId")
		if not placedBy then return nil end
		return playersService:GetPlayerByUserId(placedBy)
	end

	local function AddedBeehive(beehive)
		if isMyBeehive(beehive) then return end
		if BeehiveReference[beehive] then return end

		local level = beehive:GetAttribute("Level") or 0
		local ownerName = getBeehiveOwnerName(beehive)
		local owner = getBeehiveOwner(beehive)
		if not owner then return end

		local billboard = Instance.new('BillboardGui')
		billboard.Parent = BeehiveFolder
		billboard.Name = 'beehive-spy'
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 4, 0)
		billboard.Size = UDim2.fromOffset(120, 40)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = beehive

		local blur = addBlur(billboard)
		blur.Visible = BeehiveBackground and BeehiveBackground.Enabled or true

		local hue, sat, val, opacity = 0, 0, 1, 0.5
		if BeehiveColor then
			hue, sat, val, opacity = BeehiveColor.Hue, BeehiveColor.Sat, BeehiveColor.Value, BeehiveColor.Opacity
		end

		local frame = Instance.new('Frame')
		frame.Size = UDim2.fromScale(1, 1)
		frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
		frame.BackgroundTransparency = 1 - ((BeehiveBackground and BeehiveBackground.Enabled or true) and opacity or 0)
		frame.BorderSizePixel = 0
		frame.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 6)
		uicorner.Parent = frame
		local nameLabel = Instance.new('TextLabel')
		nameLabel.Name = 'OwnerName'
		nameLabel.Size = UDim2.new(1, 0, 0.4, 0)
		nameLabel.Position = UDim2.new(0, 0, 0, -20)
		nameLabel.BackgroundTransparency = 1
		nameLabel.Text = ownerName
		nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
		nameLabel.TextSize = 12
		nameLabel.Font = Enum.Font.GothamBold
		nameLabel.TextStrokeTransparency = 0.5
		nameLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
		nameLabel.Parent = billboard
		local homeLabel = Instance.new('ImageLabel')
		homeLabel.Size = UDim2.fromOffset(20, 20)
		homeLabel.Position = UDim2.new(0, 5, 0.5, 0)
		homeLabel.AnchorPoint = Vector2.new(0, 0.5)
		homeLabel.BackgroundTransparency = 1
		homeLabel.BorderSizePixel = 0
		homeLabel.Image = bedwars.getIcon({itemType = 'beehive'}, true)
		homeLabel.Parent = frame
		local levelLabel = Instance.new('TextLabel')
		levelLabel.Name = 'Level'
		levelLabel.Size = UDim2.new(0, 25, 1, 0)
		levelLabel.Position = UDim2.new(1, -30, 0, 0)
		levelLabel.BackgroundTransparency = 1
		levelLabel.Text = tostring(level)
		levelLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
		levelLabel.TextSize = 16
		levelLabel.Font = Enum.Font.GothamBold
		levelLabel.TextStrokeTransparency = 0.5
		levelLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
		levelLabel.Parent = frame

		BeehiveReference[beehive] = {
			billboard = billboard,
			levelLabel = levelLabel,
			frame = frame,
		}

		KitSpy:Clean(beehive:GetAttributeChangedSignal("Level"):Connect(function()
			local ref = BeehiveReference[beehive]
			if ref and ref.levelLabel then
				ref.levelLabel.Text = tostring(beehive:GetAttribute("Level") or 0)
			end
		end))
	end

	local function RemovedBeehive(beehive)
		if BeehiveReference[beehive] then
			BeehiveReference[beehive].billboard:Destroy()
			BeehiveReference[beehive] = nil
		end
	end

	local function setupBeehiveSpy()
		for _, beehive in collectionService:GetTagged('beehive') do
			AddedBeehive(beehive)
		end

		KitSpy:Clean(collectionService:GetInstanceAddedSignal('beehive'):Connect(function(beehive)
			task.wait(0.1)
			AddedBeehive(beehive)
		end))

		KitSpy:Clean(collectionService:GetInstanceRemovedSignal('beehive'):Connect(function(beehive)
			RemovedBeehive(beehive)
		end))
	end

	local function cleanupBeehive()
		BeehiveFolder:ClearAllChildren()
		table.clear(BeehiveReference)
	end

	local function getPlayerName(player)
		if LuciaDisplayName and LuciaDisplayName.Enabled then
			return player.DisplayName ~= "" and player.DisplayName or player.Name
		end
		return player.Name
	end

	local function getTeamName(player)
		if player.Team then return player.Team.Name end
		return "Unknown"
	end

	local function getCandyAmount(pinataPart)
		return pinataPart:GetAttribute("Coin") or 0
	end

	local function isTeammateSpy(pinataPart)
		if not LuciaIgnoreTeammates or not LuciaIgnoreTeammates.Enabled then return false end
		local placerId = pinataPart:GetAttribute("PlacedByUserId") or pinataPart:GetAttribute("PlacerId")
		if not placerId then
			local parent = pinataPart.Parent
			if parent then
				placerId = parent:GetAttribute("PlacedByUserId") or parent:GetAttribute("PlacerId")
			end
		end
		if placerId then
			if placerId == lplr.UserId then return true end
			local placer = playersService:GetPlayerByUserId(placerId)
			if placer and placer.Team == lplr.Team then return true end
		end
		return false
	end

	local function setupLuciaSpy()
		local util = require(game:GetService("ReplicatedStorage").TS.games.bedwars.kit.kits['piggy-bank']['piggy-bank-util']).PiggyBankUtil
		for _, obj in pairs(workspace:GetDescendants()) do
			if obj:IsA("BasePart") and obj.Name == "pinata" then
				if not isTeammateSpy(obj) then
					local placerId = obj:GetAttribute("PlacedByUserId") or obj:GetAttribute("PlacerId")
					if placerId then
						local placer = playersService:GetPlayerByUserId(placerId)
						trackedPinatas[obj] = {
							player = placer,
							lastCandy = getCandyAmount(obj),
							exists = true,
							placedTime = tick()
						}
					end
				end
			end
		end

		KitSpy:Clean(workspace.DescendantAdded:Connect(function(obj)
			if not LuciaToggle.Enabled then return end
			if obj:IsA("BasePart") and obj.Name == "pinata" then
				task.wait(0.2)
				if not isTeammateSpy(obj) then
					local placerId = obj:GetAttribute("PlacedByUserId") or obj:GetAttribute("PlacerId")
					if placerId then
						local placer = playersService:GetPlayerByUserId(placerId)
						trackedPinatas[obj] = {
							player = placer,
							lastCandy = getCandyAmount(obj),
							exists = true,
							placedTime = tick()
						}
					end
				end
			end
		end))

		KitSpy:Clean(bedwars.Client:Get("PiggyBankPop"):Connect(function(self)
			if not LuciaToggle.Enabled then return end
			local plr = self.awardedPlayer
			if not plr then return end
			if LuciaIgnoreTeammates and LuciaIgnoreTeammates.Enabled then
				if plr == lplr or (plr.Team and plr.Team == lplr.Team) then return end
			end

			local rewards = util:getRewardsFromCoins(self.coins)
			local I, D, E = 0, 0, 0
			for _, reward in ipairs(rewards) do
				if reward.itemType == "iron" then
					I = I + (reward.amount or 0)
				elseif reward.itemType == "diamond" then
					D = D + (reward.amount or 0)
				elseif reward.itemType == "emerald" then
					E = E + (reward.amount or 0)
				end
			end

			local playerName = getPlayerName(plr)
			local teamName = getTeamName(plr)
			local loot = string.format("%d irons, %d diamonds, %d emeralds", I, D, E)

			notif("KitSpy", string.format("%s (%s) opened their pinata and got %s", playerName, teamName, loot), 8)

			for pinataPart, data in pairs(trackedPinatas) do
				if data.player and data.player.UserId == plr.UserId then
					trackedPinatas[pinataPart] = nil
				end
			end
		end))

		local counter = 0
		KitSpy:Clean(runService.Heartbeat:Connect(function()
			if not LuciaToggle.Enabled then return end
			counter = counter + 1
			if counter % 6 ~= 0 then return end

			local toRemove = {}
			for pinataPart, data in pairs(trackedPinatas) do
				if pinataPart and pinataPart.Parent then
					local currentCandy = getCandyAmount(pinataPart)
					if currentCandy ~= data.lastCandy then
						local difference = currentCandy - data.lastCandy
						if difference > 0 and data.player then
							local playerName = getPlayerName(data.player)
							local teamName = getTeamName(data.player)
							notif("KitSpy", string.format("%s (%s) deposited %d candy (now %d)", playerName, teamName, difference, currentCandy), 5)
						end
						data.lastCandy = currentCandy
					end
				else
					if data.exists and data.player then
						local timeSincePlaced = tick() - (data.placedTime or tick())
						if timeSincePlaced > 2 then
							local playerName = getPlayerName(data.player)
							local teamName = getTeamName(data.player)
							notif("KitSpy", string.format("%s (%s) broke their pinata (had %d candy)", playerName, teamName, data.lastCandy), 5)
						end
					end
					table.insert(toRemove, pinataPart)
				end
			end

			for _, pinataPart in ipairs(toRemove) do
				trackedPinatas[pinataPart] = nil
			end
		end))
	end

	local function cleanupLucia()
		table.clear(trackedPinatas)
	end

	local function setupBountyHunterSpy()
		bedwars.Client:WaitFor(remotes.BountyHunterTargetChanged):andThen(function(rbx)
			KitSpy:Clean(rbx:Connect(function(tbl)
				if not BountyHunterToggle.Enabled then return end
				local hunter = tbl.hunter
				if not hunter then return end
				huntTargets[hunter] = {targetUserId = tbl.newTargetUserId, reward = tbl.reward}
				if not BountyTargetToggle.Enabled then return end
				local hunterName = getPlayerName(hunter)
				local targetPlr = tbl.newTargetUserId and tbl.newTargetUserId ~= 0 and playersService:GetPlayerByUserId(tbl.newTargetUserId)
				if targetPlr then
					notif("KitSpy", hunterName .. " is huntin " .. getPlayerName(targetPlr), 8)
				else
					notif("KitSpy", hunterName .. " lost their bounty target", 8)
				end
			end))
		end)

		KitSpy:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
			if not BountyHunterToggle.Enabled or not BountyLootToggle.Enabled then return end
			local killer = playersService:GetPlayerFromCharacter(deathTable.fromEntity)
			local killed = playersService:GetPlayerFromCharacter(deathTable.entityInstance)
			if not killer or not killed then return end
			local info = huntTargets[killer]
			if not info or info.targetUserId ~= killed.UserId then return end
			local reward = info.reward
			local iron = reward and reward.iron or 0
			local emerald = reward and reward.emerald or 0
			local lootText = 'iron x' .. iron
			if emerald and emerald > 0 then
				lootText = lootText .. ', emerald x' .. emerald
			end
			notif("KitSpy", getPlayerName(killer) .. " bounty killed " .. getPlayerName(killed) .. " | Loot: " .. lootText, 8)
			huntTargets[killer] = nil
		end))
	end

	local function cleanupBountyHunter()
		table.clear(huntTargets)
	end

	local function setupFishermanSpy()
		bedwars.Client:WaitFor(remotes.FishCaught):andThen(function(rbx)
			KitSpy:Clean(rbx:Connect(function(tbl)
				if not FishermanToggle.Enabled then return end
				local char = tbl.catchingPlayer and tbl.catchingPlayer.Character
				if not char then return end
				local fish = tbl.dropData and tbl.dropData.fishModel
				local allDrops = tbl.dropData and tbl.dropData.drops
				local plrName = char.Name
				local str = plrName:sub(1, 1):upper() .. plrName:sub(2)
				local strfish = FishNames[tostring(fish)] or 'Unknown Fish'
				local lootText = ''
				if allDrops then
					local totals = {}
					local order = {}
					for _, drop in ipairs(allDrops) do
						local item = tostring(drop.itemType) or 'unknown'
						local amount = tonumber(drop.amount) or 0
						if not totals[item] then
							totals[item] = 0
							table.insert(order, item)
						end
						totals[item] = totals[item] + amount
					end
					local parts = {}
					for _, item in ipairs(order) do
						table.insert(parts, item .. ' x' .. math.ceil(totals[item] * 1.4))
					end
					if #parts > 0 then
						lootText = ' | Loot: ' .. table.concat(parts, ', ')
					end
				end
				if FishermanIgnoreTeammates and FishermanIgnoreTeammates.Enabled then
					local currentplr = playersService:GetPlayerFromCharacter(char)
					if currentplr and currentplr.Team == lplr.Team then return end
				end
				notif("KitSpy", str .. " caught a " .. strfish .. lootText, 8)
			end))
		end)
	end

	KitSpy = vape.Categories.Kits:CreateModule({
		Name = "KitSpy",
		Tooltip = "gives u info on stuff other ppl are doing with certain kits - piston inspired :D",
		Function = function(callback)
			if callback then
				if BeehiveToggle.Enabled then setupBeehiveSpy() end
				if LuciaToggle.Enabled then setupLuciaSpy() end
				if FishermanToggle.Enabled then setupFishermanSpy() end
				if BountyHunterToggle.Enabled then setupBountyHunterSpy() end
			else
				cleanupBeehive()
				cleanupLucia()
				cleanupBountyHunter()
			end
		end
	})

	BeehiveToggle = KitSpy:CreateToggle({
		Name = 'Beehive',
		Function = function(callback)
			if BeehiveBackground and BeehiveBackground.Object then BeehiveBackground.Object.Visible = callback end
			if BeehiveColor and BeehiveColor.Object then BeehiveColor.Object.Visible = callback and BeehiveBackground.Enabled end
			if KitSpy.Enabled then
				if callback then setupBeehiveSpy() else cleanupBeehive() end
			end
		end
	})

	BeehiveBackground = KitSpy:CreateToggle({
		Name = 'Beehive Background',
		Default = true,
		Darker = true,
		Visible = false,
		Function = function(callback)
			if BeehiveColor and BeehiveColor.Object then BeehiveColor.Object.Visible = callback end
			for _, ref in BeehiveReference do
				if ref and ref.frame then
					local opacity = BeehiveColor and BeehiveColor.Opacity or 0.5
					ref.frame.BackgroundTransparency = 1 - (callback and opacity or 0)
				end
				if ref and ref.billboard then
					local blur = ref.billboard:FindFirstChild("Blur")
					if blur then blur.Visible = callback end
				end
			end
		end
	})

	BeehiveColor = KitSpy:CreateColorSlider({
		Name = 'Beehive Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Darker = true,
		Visible = false,
		Function = function(hue, sat, val, opacity)
			for _, ref in BeehiveReference do
				if ref and ref.frame then
					ref.frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
					ref.frame.BackgroundTransparency = 1 - (BeehiveBackground.Enabled and opacity or 0)
				end
			end
		end
	})

	LuciaToggle = KitSpy:CreateToggle({
		Name = 'Lucia',
		Function = function(callback)
			if LuciaIgnoreTeammates and LuciaIgnoreTeammates.Object then LuciaIgnoreTeammates.Object.Visible = callback end
			if LuciaDisplayName and LuciaDisplayName.Object then LuciaDisplayName.Object.Visible = callback end
			if KitSpy.Enabled then
				if callback then setupLuciaSpy() else cleanupLucia() end
			end
		end
	})

	LuciaIgnoreTeammates = KitSpy:CreateToggle({
		Name = 'Lucia Ignore Teammates',
		Default = true,
		Darker = true,
		Visible = false,
	})

	LuciaDisplayName = KitSpy:CreateToggle({
		Name = 'Lucia Display Name',
		Default = false,
		Darker = true,
		Visible = false,
	})

	FishermanToggle = KitSpy:CreateToggle({
		Name = 'Fisherman',
		Function = function(callback)
			if FishermanIgnoreTeammates and FishermanIgnoreTeammates.Object then FishermanIgnoreTeammates.Object.Visible = callback end
			if KitSpy.Enabled and callback then
				setupFishermanSpy()
			end
		end
	})

	FishermanIgnoreTeammates = KitSpy:CreateToggle({
		Name = 'Fisherman Ignore Teammates',
		Default = true,
		Darker = true,
		Visible = false,
	})

	BountyHunterToggle = KitSpy:CreateToggle({
		Name = 'Bounty Hunter',
		Tooltip = 'shows u who a bounty hunter is huntin and the loot they get when they get em',
		Function = function(callback)
			if BountyTargetToggle and BountyTargetToggle.Object then BountyTargetToggle.Object.Visible = callback end
			if BountyLootToggle and BountyLootToggle.Object then BountyLootToggle.Object.Visible = callback end
			if KitSpy.Enabled then
				if callback then setupBountyHunterSpy() else cleanupBountyHunter() end
			end
		end
	})

	BountyTargetToggle = KitSpy:CreateToggle({
		Name = 'Bounty Hunter Target',
		Default = true,
		Darker = true,
		Visible = false,
	})

	BountyLootToggle = KitSpy:CreateToggle({
		Name = 'Bounty Hunter Loot',
		Default = true,
		Darker = true,
		Visible = false,
	})
	local DrillToggle, DrillNotify, DrillESPToggle, DrillTeamCheck
	local drillFolder = Instance.new('Folder')
	drillFolder.Parent = vape.gui
	local drillRefs, drillConns, drillLast = {}, {}, {}
	local drillActive = false

	local function drillOwner(drill)
		local id = drill:GetAttribute('PlacedByUserId')
		return id and playersService:GetPlayerByUserId(id) or nil
	end

	local function drillSkip(drill)
		local owner = drillOwner(drill)
		if owner == lplr then return true end
		local myTeam = lplr:GetAttribute('Team')
		return owner ~= nil and ((myTeam ~= nil and owner:GetAttribute('Team') == myTeam) or (lplr.Team ~= nil and owner.Team == lplr.Team))
	end

	local function drillLoot(drill)
		local itemType = drill:GetAttribute('ItemType')
		return itemType, itemType and (drill:GetAttribute(itemType) or 0) or 0
	end

	local function drillUpdate(drill)
		local gui = drillRefs[drill]
		if not gui then return end
		local itemType, amount = drillLoot(drill)
		local owner = drillOwner(drill)
		gui.Label.Text = (owner and owner.DisplayName or 'drill') .. (itemType and (' | ' .. amount .. ' ' .. itemType:gsub('_', ' ')) or '') .. ' | ' .. math.floor(drill:GetAttribute('Health') or 0) .. ' hp'
	end

	local function drillAddESP(drill)
		if drillRefs[drill] or drillSkip(drill) then return end
		local head = drill:FindFirstChild('Head') or drill.PrimaryPart or drill:FindFirstChildWhichIsA('BasePart')
		if not head then return end
		local gui = Instance.new('BillboardGui')
		gui.Name = 'drill-spy'
		gui.Size = UDim2.fromOffset(200, 22)
		gui.StudsOffsetWorldSpace = Vector3.new(0, 4, 0)
		gui.AlwaysOnTop = true
		gui.Adornee = head
		gui.Parent = drillFolder
		local label = Instance.new('TextLabel')
		label.Name = 'Label'
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundColor3 = Color3.new(0, 0, 0)
		label.BackgroundTransparency = 0.45
		label.TextColor3 = Color3.new(1, 1, 1)
		label.TextStrokeTransparency = 0.4
		label.TextSize = 13
		label.Font = Enum.Font.GothamBold
		label.Parent = gui
		local corner = Instance.new('UICorner')
		corner.CornerRadius = UDim.new(0, 4)
		corner.Parent = label
		drillRefs[drill] = gui
		drillUpdate(drill)
	end

	local function drillRemoveESP(drill)
		if drillRefs[drill] then
			drillRefs[drill]:Destroy()
			drillRefs[drill] = nil
		end
	end

	local function drillWatch(drill, fresh)
		if drillLast[drill] ~= nil then return end
		local _, amount = drillLoot(drill)
		drillLast[drill] = amount
		local owner = drillOwner(drill)
		if fresh and DrillNotify.Enabled and not drillSkip(drill) then
			notif('Kit Spy', (owner and owner.DisplayName or 'someone') .. ' placed a drill', 4)
		end
		table.insert(drillConns, drill.AttributeChanged:Connect(function()
			local itemType, now = drillLoot(drill)
			local before = drillLast[drill] or 0
			drillLast[drill] = now
			if now < before and DrillNotify.Enabled and not drillSkip(drill) then
				notif('Kit Spy', (owner and owner.DisplayName or 'someone') .. ' took ' .. (before - now) .. ' ' .. tostring(itemType or 'loot'):gsub('_', ' ') .. ' from their drill', 4)
			end
			if DrillESPToggle.Enabled then
				drillUpdate(drill)
			end
		end))
		if DrillESPToggle.Enabled then
			drillAddESP(drill)
		end
	end

	local function drillStop()
		drillActive = false
		for _, conn in drillConns do
			conn:Disconnect()
		end
		table.clear(drillConns)
		table.clear(drillLast)
		for drill in drillRefs do
			drillRemoveESP(drill)
		end
	end

	local function drillStart()
		if drillActive then return end
		drillActive = true
		for _, obj in workspace:GetDescendants() do
			if obj:IsA('Model') and obj.Name == 'Drill' then
				drillWatch(obj, false)
			end
		end
		table.insert(drillConns, workspace.DescendantAdded:Connect(function(obj)
			if obj:IsA('Model') and obj.Name == 'Drill' then
				task.wait(0.2)
				if obj.Parent then
					drillWatch(obj, true)
				end
			end
		end))
		table.insert(drillConns, workspace.DescendantRemoving:Connect(function(obj)
			if drillLast[obj] ~= nil then
				drillLast[obj] = nil
				drillRemoveESP(obj)
			end
		end))
	end

	task.spawn(function()
		while vape.Loaded ~= false do
			local want = KitSpy and KitSpy.Enabled and DrillToggle and DrillToggle.Enabled
			if want and not drillActive then
				drillStart()
			elseif not want and drillActive then
				drillStop()
			end
			task.wait(0.5)
		end
		drillStop()
	end)

	DrillToggle = KitSpy:CreateToggle({
		Name = 'Drill',
		Tooltip = 'tells u when someone places a drill or takes loot from their drill',
		Function = function(callback)
			if DrillNotify and DrillNotify.Object then DrillNotify.Object.Visible = callback end
			if DrillESPToggle and DrillESPToggle.Object then DrillESPToggle.Object.Visible = callback end
		end
	})
	DrillNotify = KitSpy:CreateToggle({
		Name = 'Drill Notifications',
		Default = true,
		Darker = true,
		Visible = false
	})
	DrillESPToggle = KitSpy:CreateToggle({
		Name = 'Drill ESP',
		Darker = true,
		Visible = false,
		Tooltip = 'shows who owns each drill, whats in it and its health',
		Function = function(callback)
			if not drillActive then return end
			for drill in drillLast do
				if callback then drillAddESP(drill) else drillRemoveESP(drill) end
			end
		end
	})
	task.defer(function()
		local on = DrillToggle.Enabled
		DrillNotify.Object.Visible = on
		DrillESPToggle.Object.Visible = on
	end)
end)

run(function()
    local StarCollector
    local CollectionToggle
    local Animation
    local RangeSlider
    local ESPToggle
    local ESPNotify
    local ESPBackground
    local ESPColor
    local SwordCheck
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui
    local Reference = {}
    local starCooldowns = {}
    local COOLDOWN_TIME = 0.5
    local lastNotification = 0
    local spawnQueue = {}
    local notificationCooldown = 1
    local collectionRunning = false

    local function sendNotification(count)
        notif("Star ESP", string.format("%d stars spawned", count), 3)
    end

    local function processSpawnQueue()
        if #spawnQueue > 0 then
            local currentTime = tick()
            if currentTime - lastNotification >= notificationCooldown then
                sendNotification(#spawnQueue)
                lastNotification = currentTime
                spawnQueue = {}
            else
                task.delay(notificationCooldown - (currentTime - lastNotification), function()
                    if #spawnQueue > 0 then
                        sendNotification(#spawnQueue)
                        spawnQueue = {}
                    end
                end)
            end
        end
    end

    local function getProperImage(v)
        local parent = v.Parent
        if parent and parent:IsA("Model") then
            local modelName = parent.Name
            if modelName == "CritStar" then
                return bedwars.getIcon({itemType = 'crit_star'}, true)
            elseif modelName == "VitalityStar" then
                return bedwars.getIcon({itemType = 'vitality_star'}, true)
            elseif modelName:find("vitality") or modelName:lower():find("vitality") then
                return bedwars.getIcon({itemType = 'vitality_star'}, true)
            elseif modelName:find("crit") or modelName:lower():find("crit") then
                return bedwars.getIcon({itemType = 'crit_star'}, true)
            end
        end
        return bedwars.getIcon({itemType = 'crit_star'}, true)
    end

    local function Added(v)
        if Reference[v] then return end
        local _bpUserId = v:GetAttribute('PlacedByUserId')
        if _bpUserId then
            local _bpOk, _bpOwner = pcall(function() return playersService:GetPlayerByUserId(_bpUserId) end)
        end
        
        local billboard = Instance.new('BillboardGui')
        billboard.Parent = Folder
        billboard.Name = 'stars'
        billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
        billboard.Size = UDim2.fromOffset(36, 36)
        billboard.AlwaysOnTop = true
        billboard.ClipsDescendants = false
        billboard.Adornee = v
        
        local blur = addBlur(billboard)
        blur.Visible = ESPBackground.Enabled
        
        local image = Instance.new('ImageLabel')
        image.Size = UDim2.fromOffset(36, 36)
        image.Position = UDim2.fromScale(0.5, 0.5)
        image.AnchorPoint = Vector2.new(0.5, 0.5)
        image.BackgroundColor3 = Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)
        image.BackgroundTransparency = 1 - (ESPBackground.Enabled and ESPColor.Opacity or 0)
        image.BorderSizePixel = 0
        image.Image = getProperImage(v)
        image.Parent = billboard
        
        local uicorner = Instance.new('UICorner')
        uicorner.CornerRadius = UDim.new(0, 4)
        uicorner.Parent = image
        
        Reference[v] = billboard
        
        if ESPNotify.Enabled then
            table.insert(spawnQueue, {item = 'star', time = tick()})
            processSpawnQueue()
        end
    end

    local function Removed(v)
        if Reference[v] then
            Reference[v]:Destroy()
            Reference[v] = nil
        end
        starCooldowns[v] = nil
    end

    local function setupESP()
        for _, v in collectionService:GetTagged('stars') do
            if v:IsA("Model") and v.PrimaryPart then
                Added(v.PrimaryPart)
            end
        end

        StarCollector:Clean(collectionService:GetInstanceAddedSignal('stars'):Connect(function(v)
            if v:IsA("Model") and v.PrimaryPart then
                task.wait(0.1)
                Added(v.PrimaryPart)
            end
        end))

        StarCollector:Clean(collectionService:GetInstanceRemovedSignal('stars'):Connect(function(v)
            if v.PrimaryPart then
                Removed(v.PrimaryPart)
            end
        end))
        
        local _scLastUpdate = 0
        StarCollector:Clean(runService.RenderStepped:Connect(function()
            if not ESPToggle.Enabled then return end
            local _now = tick()
            if _now - _scLastUpdate < 0.1 then return end
            _scLastUpdate = _now
            
            for v, billboard in pairs(Reference) do
                if not v or not v.Parent then
                    Removed(v)
                    continue
                end

                local shouldShow = true

                if SwordCheck.Enabled and isSword() then
                    shouldShow = false
                end

                billboard.Enabled = shouldShow
            end
        end))
    end

    local function collectStar(star)
        if not star or not star.Parent then return end
        
        if Animation.Enabled and entitylib.isAlive then
            bedwars.GameAnimationUtil:playAnimation(lplr, bedwars.AnimationType.PUNCH)
            bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)
        end
        
        bedwars.StarCollectorController:collectEntity(lplr, star, star.Name)
    end

	local function startCollection()
		collectionRunning = true
		task.spawn(function()
			while collectionRunning and StarCollector.Enabled and CollectionToggle.Enabled do
				if not entitylib.isAlive then
					task.wait(0.1)
					continue
				end

				local localPosition = entitylib.character.RootPart.Position
				local range = RangeSlider.Value
				local collected = false

				for _, v in collectionService:GetTagged('stars') do
					if not collectionRunning or not StarCollector.Enabled or not CollectionToggle.Enabled then
						break
					end

					if v:IsA("Model") and v.PrimaryPart then
						local starPos = v.PrimaryPart.Position
						local distance = (localPosition - starPos).Magnitude

						if distance <= range then
							local lastAttempt = starCooldowns[v]
							if lastAttempt and tick() - lastAttempt < COOLDOWN_TIME then
								continue
							end
							starCooldowns[v] = tick()
							collectStar(v)
							collected = true
							break
						end
					end
				end

				task.wait(collected and 0.1 or 0.2)
			end
			collectionRunning = false
		end)
	end

    StarCollector = vape.Categories.Kits:CreateModule({
        Name = 'AutoStar',
        Function = function(callback)
            if callback then
                if ESPToggle.Enabled then 
                    setupESP() 
                end
                
                if CollectionToggle.Enabled then
                    startCollection()
                end
            else
                collectionRunning = false
                Folder:ClearAllChildren()
                table.clear(Reference)
                table.clear(spawnQueue)
                table.clear(starCooldowns)
                lastNotification = 0
            end
        end,
    })
    
    CollectionToggle = StarCollector:CreateToggle({
        Name = 'Auto Collect',
        Default = true,
        Function = function(callback)
            if Animation and Animation.Object then Animation.Object.Visible = callback end
            if RangeSlider and RangeSlider.Object then RangeSlider.Object.Visible = callback end
            
            if callback and StarCollector.Enabled then
                startCollection()
            else
                collectionRunning = false
            end
        end
    })
    
    Animation = StarCollector:CreateToggle({
        Name = 'Animation',
        Default = true,
    })
    
    RangeSlider = StarCollector:CreateSlider({
        Name = 'Range',
        Min = 1, 
        Max = 18,
        Default = 10,
        Decimal = 1,
        Suffix = ' studs',
    })
    
    ESPToggle = StarCollector:CreateToggle({
        Name = 'Star ESP',
        Default = false,
        Function = function(callback)
            if ESPNotify and ESPNotify.Object then ESPNotify.Object.Visible = callback end
            if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = callback end
            if ESPColor and ESPColor.Object then ESPColor.Object.Visible = callback end
            if SwordCheck and SwordCheck.Object then SwordCheck.Object.Visible = callback end
            
            if StarCollector.Enabled then
                if callback then 
                    setupESP() 
                else
                    Folder:ClearAllChildren()
                    table.clear(Reference)
                end
            end
        end
    })
    
    ESPNotify = StarCollector:CreateToggle({
        Name = 'Notify',
        Default = false,
    })
    
    ESPBackground = StarCollector:CreateToggle({
        Name = 'Background',
        Default = true,
        Function = function(callback)
            if ESPColor and ESPColor.Object then ESPColor.Object.Visible = callback end
            for _, v in Reference do
                if v and v:FindFirstChild("ImageLabel") then
                    v.ImageLabel.BackgroundTransparency = 1 - (callback and ESPColor.Opacity or 0)
                    if v:FindFirstChild("Blur") then
                        v.Blur.Visible = callback
                    end
                end
            end
        end
    })
    
    ESPColor = StarCollector:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for _, v in Reference do
                if v and v:FindFirstChild("ImageLabel") then
                    v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
                    v.ImageLabel.BackgroundTransparency = 1 - opacity
                end
            end
        end,
        Darker = true
    })
    SwordCheck = StarCollector:CreateToggle({
        Name = 'Sword Check',
        Default = false,
    })

    task.defer(function()
        local espOn = ESPToggle and ESPToggle.Enabled
        if ESPNotify and ESPNotify.Object then ESPNotify.Object.Visible = espOn end
        if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = espOn end
        if ESPColor and ESPColor.Object then ESPColor.Object.Visible = espOn end
        if SwordCheck and SwordCheck.Object then SwordCheck.Object.Visible = espOn end
    end)
end)

run(function()
    local Melody
    local SelfHeal
    local TeammateHeal
    local RangeSlider
    local PlayerDropdown
    local healRunning = false
    local lastHealTime = 0
    local healCooldown = 1

    local function getItem(itemName)
        if not entitylib.isAlive then return false end
        
        local inventory = store.inventory
        if inventory and inventory.inventory and inventory.inventory.hand then
            local handItem = inventory.inventory.hand
            if handItem and handItem.itemType == itemName then
                return true
            end
        end
        return false
    end

    local function getLowestHealthTeammate()
        if not entitylib.isAlive then return nil end

        local localPosition = entitylib.character.RootPart.Position
        local range = RangeSlider.Value
        local picked = PlayerDropdown and PlayerDropdown.Value

        if picked and picked ~= 'None' then
            for _, v in entitylib.List do
                if v.Player and v.Player ~= lplr and v.Player.Name == picked then
                    local distance = (localPosition - v.RootPart.Position).Magnitude
                    if distance <= range and v.Health < v.MaxHealth then
                        return v
                    end
                    return nil
                end
            end
            return nil
        end

        local lowestHp = math.huge
        local targetEntity = nil

        for _, v in entitylib.List do
            if v.Player and v.Player ~= lplr and v.Player:GetAttribute('Team') == lplr:GetAttribute('Team') then
                local distance = (localPosition - v.RootPart.Position).Magnitude

                if distance <= range and v.Health < lowestHp and v.Health < v.MaxHealth then
                    lowestHp = v.Health
                    targetEntity = v
                end
            end
        end

        return targetEntity
    end

    local function shouldSelfHeal()
        if not entitylib.isAlive then return false end
        
        local currentHealth = lplr.Character:GetAttribute('Health') or 0
        local maxHealth = lplr.Character:GetAttribute('MaxHealth') or 100
        
        return currentHealth < maxHealth
    end

    local function performHeal(target)
        local currentTime = tick()
        if currentTime - lastHealTime < healCooldown then
            return false
        end
        
        if not getItem('guitar') then
            return false
        end
        
        bedwars.Client:Get(remotes.GuitarHeal):SendToServer({
            healTarget = target
        })
        
        lastHealTime = currentTime
        return true
    end

    local function startHealing()
        healRunning = true
        task.spawn(function()
            while healRunning and Melody.Enabled do
                if not entitylib.isAlive then
                    task.wait(0.1)
                    continue
                end
                
                if not getItem('guitar') then
                    task.wait(0.2)
                    continue
                end
                
                local healed = false
                
                if SelfHeal.Enabled and shouldSelfHeal() then
                    if performHeal(lplr.Character) then
                        healed = true
                    end
                end
                
                if not healed and TeammateHeal.Enabled then
                    local teammate = getLowestHealthTeammate()
                    if teammate then
                        if performHeal(teammate.Character) then
                            healed = true
                        end
                    end
                end
                
                task.wait(0.1)
            end
            healRunning = false
        end)
    end

    Melody = vape.Categories.Kits:CreateModule({
        Name = 'AutoMelody',
        Function = function(callback)
            if callback then
                lastHealTime = 0
                startHealing()
                local function refreshList()
                    if PlayerDropdown and type(PlayerDropdown.SetList) == 'function' then
                        local list = {'None'}
                        for _, name in ipairs(getTeammates(true)) do
                            table.insert(list, name)
                        end
                        PlayerDropdown:SetList(list)
                    end
                end
                refreshList()
                Melody:Clean(playersService.PlayerAdded:Connect(function() task.wait(0.5) refreshList() end))
                Melody:Clean(playersService.PlayerRemoving:Connect(function() task.wait(0.5) refreshList() end))
                Melody:Clean(lplr:GetAttributeChangedSignal('Team'):Connect(function() task.wait(1) refreshList() end))
            else
                healRunning = false
                lastHealTime = 0
            end
        end,
        Tooltip = 'auto heal yourself and teammates with guitar'
    })
    
    SelfHeal = Melody:CreateToggle({
        Name = 'Self Heal',
        Default = true,
    })
    
    TeammateHeal = Melody:CreateToggle({
        Name = 'Teammate Heal',
        Default = true,
        Function = function(callback)
            if RangeSlider and RangeSlider.Object then
                RangeSlider.Object.Visible = callback
            end
        end
    })
    
    RangeSlider = Melody:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 20,
        Default = 20,
        Decimal = 1,
        Suffix = ' studs',
    })

    PlayerDropdown = Melody:CreateDropdown({
        Name = 'Target Teammate',
        List = {'None'},
        Default = 'None',
        Tooltip = 'pick who u wanna heal, None just heals whoevers lowest hp'
    })
end)

run(function()
    local autoZenoModule
    local targetSettings
    local targetSelectionMode
    local itemLimitToggle
    local shockwaveToggle
    local shockwaveRadius
    local lightningStrikeToggle
    local lightningStormToggle
    local attackRange
    local actionDelay

    local function fetchAttackItem()
        if itemLimitToggle.Enabled then
            local wizardStaff = (store.hand.tool and store.hand.tool.Name:find('wizard_staff')) and store.hand.tool or nil
            return wizardStaff, wizardStaff and getHotbar(wizardStaff) or nil, wizardStaff and (tonumber(wizardStaff.Name:sub(#wizardStaff.Name, #wizardStaff.Name)) or 1) or nil
        end

        if store.hand.tool and store.hand.tool.Name:find('wizard_staff') then
            local item = store.hand.tool
            return item, getHotbar(item), tonumber(item.Name:sub(#item.Name, #item.Name)) or 1
        end

        for index, item in pairs(store.inventory.inventory.items) do
            if item.itemType:find('wizard_staff') then
                switchItem(item, 0)
                return item, index, tonumber(item.itemType:sub(#item.itemType, #item.itemType)) or 1
            end
        end

        return nil
    end

    autoZenoModule = vape.Categories.Kits:CreateModule({
        Name = 'AutoZeno',
        Function = function(callback)
            if callback then
                repeat
                    if entitylib.isAlive then
                        local staff, _, level = fetchAttackItem()

                        if staff then
                            local playerPosition = entitylib.character.RootPart.Position
                            local nearestEntity = entitylib.EntityPosition({
                                Origin = playerPosition,
                                Range = (attackRange.Value < 6 and shockwaveToggle.Enabled and 7) or attackRange.Value,
                                Part = 'RootPart',
                                Players = targetSettings.Players.Enabled,
                                NPCs = targetSettings.NPCs.Enabled,
                                Sort = sortmethods[targetSelectionMode.Value]
                            })

                            if nearestEntity then
                                if shockwaveToggle.Enabled and level > 2 then
                                    if bedwars.AbilityController:canUseAbility('SHOCKWAVE') and (playerPosition - nearestEntity.RootPart.Position).Magnitude <= shockwaveRadius.Value then
                                        bedwars.AbilityController:useAbility('SHOCKWAVE', newproxy(true), {
                                            target = CFrame.lookAt(playerPosition, nearestEntity.RootPart.Position).LookVector
                                        })
                                        task.wait(actionDelay.Value)
                                    end
                                end

                                if lightningStrikeToggle.Enabled and bedwars.AbilityController:canUseAbility('LIGHTNING_STRIKE') then
                                    bedwars.AbilityController:useAbility('LIGHTNING_STRIKE', newproxy(true), {
                                        target = nearestEntity.RootPart.Position + ((nearestEntity.Humanoid.MoveDirection or Vector3.zero) * (1 + lplr:GetNetworkPing()))
                                    })
                                    task.wait(actionDelay.Value)
                                end

                                if lightningStormToggle.Enabled and level > 1 then
                                    if bedwars.AbilityController:canUseAbility('LIGHTNING_STORM') then
                                        bedwars.AbilityController:useAbility('LIGHTNING_STORM', newproxy(true), {
                                            target = nearestEntity.RootPart.Position + ((nearestEntity.Humanoid.MoveDirection or Vector3.zero) * (1 + lplr:GetNetworkPing()))
                                        })
                                        task.wait(actionDelay.Value)
                                    end
                                end
                            end
                        end
                    end
                    task.wait(0.1)
                until not autoZenoModule.Enabled
            end
        end,
    })

    targetSettings = autoZenoModule:CreateTargets({
        Players = true,
        NPCs = false
    })

    local availableSortingMethods = {'Damage', 'Distance'}
    for method in sortmethods do
        if not table.find(availableSortingMethods, method) then
            table.insert(availableSortingMethods, method)
        end
    end

    targetSelectionMode = autoZenoModule:CreateDropdown({
        Name = 'Target Mode',
        List = availableSortingMethods,
        Default = 'Distance'
    })

    itemLimitToggle = autoZenoModule:CreateToggle({
        Name = 'Limit to item',
        Default = true
    })

    lightningStrikeToggle = autoZenoModule:CreateToggle({
        Name = 'Use Lightning Strike',
        Default = true
    })

    lightningStormToggle = autoZenoModule:CreateToggle({
        Name = 'Use Lightning Storm'
    })

    shockwaveRadius = autoZenoModule:CreateSlider({
        Name = 'Shockwave Range',
        Visible = false,
        Darker = true,
        Min = 1,
        Max = 12,
        Suffix = function(value)
            return value > 1 and 'studs' or 'stud'
        end,
        Decimal = 5,
        Default = 12
    })

    shockwaveToggle = autoZenoModule:CreateToggle({
        Name = 'Auto Shockwave',
        Function = function(enabled)
            pcall(function()
                shockwaveRadius.Object.Visible = enabled
            end)
        end
    })

    attackRange = autoZenoModule:CreateSlider({
        Name = 'Attack Range',
        Min = 1,
        Max = 60,
        Default = 35,
        Suffix = function(value)
            return value > 1 and 'studs' or 'stud'
        end,
        Decimal = 5
    })

    actionDelay = autoZenoModule:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 10,
        Default = 0.5,
        Decimal = 5,
        Suffix = function(value)
            return value > 1 and 'secs' or 'sec'
        end
    })
end)

run(function()
    local AutoGinger
    local LimitToItem
    local BreakDelay
    local BreakDelaySlider
    local AutoSwitch
    local SwitchMode
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui
    local lastBreakTime = 0
    local lastPlaceTime = 0
    local placeCheckConnection
    local justPlacedGumdrop = false
    local lastPlacedPosition = nil
    
    _G.gingerLock = _G.gingerLock or false
    
    local function getGumdropSlot()
        for i, v in store.inventory.hotbar do
            if v.item and v.item.itemType == "gumdrop_bounce_pad" then
                return i - 1
            end
        end
        return nil
    end
    
    local function getPredictedPosition()
        if not (lplr.Character and lplr.Character.PrimaryPart) then return nil end
        local root = lplr.Character.PrimaryPart
        local velocity = root.AssemblyLinearVelocity
        local horizontalVelocity = Vector3.new(velocity.X, 0, velocity.Z)
        local speed = horizontalVelocity.Magnitude
        if speed < 1 then return root.Position end
        local predictionTime = math.clamp(speed / 40, 0.15, 0.35)
        return root.Position + (horizontalVelocity * predictionTime)
    end
    
    local function forceBreak(block)
        if not block then return end
        lastBreakTime = tick()
        justPlacedGumdrop = false
        task.spawn(function()
            for i = 1, 6 do
                if not block or not block.Parent then return end
                pcall(bedwars.breakBlock, block, false, nil, true)
                task.wait(0.05)
            end
        end)
    end
    
    local function tryPlaceGumdrop()
        if not AutoSwitch.Enabled or _G.gingerLock then return end
        if not (lplr.Character and lplr.Character.PrimaryPart) then return end
        
        local inFirstPerson = isFirstPerson()
        if SwitchMode.Value == 'First Person' and not inFirstPerson then return end
        if SwitchMode.Value == 'Third Person' and inFirstPerson then return end
        
        local velocity = lplr.Character.PrimaryPart.AssemblyLinearVelocity.Y
        if velocity >= -5 then return end
        
        local gumdropSlot = getGumdropSlot()
        if not gumdropSlot then return end
        
        local root = lplr.Character.PrimaryPart
        local targetPos = getPredictedPosition() or root.Position
        local checkPos = targetPos - Vector3.new(0, 3, 0)
        local groundBlockPos = nil
        
        for i = 1, 16 do
            local testPos = checkPos - Vector3.new(0, 3 * (i - 1), 0)
            local block, blockpos = getPlacedBlock(roundPos(testPos))
            if block then
                groundBlockPos = blockpos * 3
                break
            end
        end
        
        if not groundBlockPos then return end
        
        local distanceToGround = root.Position.Y - groundBlockPos.Y
        if distanceToGround < 9 or distanceToGround > 18 then return end
        
        local placePos = groundBlockPos + Vector3.new(0, 3, 0)
        if lastPlacedPosition and (lastPlacedPosition - placePos).Magnitude < 1 then return end
        if getPlacedBlock(placePos) then return end
        
        _G.gingerLock = true
        
        if hotbarSwitch(gumdropSlot) then
            task.wait(0.03)
            local success = pcall(function()
                bedwars.placeBlock(placePos, "gumdrop_bounce_pad", false)
            end)
            
            if success then
                lastPlaceTime = tick()
                justPlacedGumdrop = true
                lastPlacedPosition = placePos
                
                task.wait(0.03)
                local pickaxeSlot = getPickaxeSlot()
                if pickaxeSlot then
                    hotbarSwitch(pickaxeSlot)
                    task.wait(0.08)
                    local placedBlock = getPlacedBlock(placePos)
                    if placedBlock and placedBlock.Name == "gumdrop_bounce_pad" then
                        forceBreak(placedBlock)
                    end
                end
            end
        end
        
        _G.gingerLock = false
    end
    
    AutoGinger = vape.Categories.Kits:CreateModule({
        Name = 'AutoGinger',
        Function = function(callback)
            if callback then
                local old = bedwars.LaunchPadController.attemptLaunch
                bedwars.LaunchPadController.attemptLaunch = function(...)
                    local res = {old(...)}
                    local self, block = ...
                    
                    if block:GetAttribute('PlacedByUserId') == lplr.UserId and
                       (block.Position - entitylib.character.RootPart.Position).Magnitude < 30 then

                        if LimitToItem.Enabled and not AutoSwitch.Enabled and not isHoldingPickaxe() then
                            return unpack(res)
                        end

                        local inFP = isFirstPerson()
                        local cameraAllowed = not AutoSwitch.Enabled or ((SwitchMode.Value ~= 'First Person' or inFP) and (SwitchMode.Value ~= 'Third Person' or not inFP))

                        if isHoldingPickaxe() then
                            local shouldBreak = true
                            if not AutoSwitch.Enabled and BreakDelay.Enabled and not justPlacedGumdrop then
                                if (tick() - lastBreakTime) < BreakDelaySlider.Value then
                                    shouldBreak = false
                                end
                            end
                            if shouldBreak then
                                forceBreak(block)
                            end
                        elseif AutoSwitch.Enabled and cameraAllowed and not _G.gingerLock then
                            local pickaxeSlot = getPickaxeSlot()
                            if pickaxeSlot then
                                _G.gingerLock = true
                                task.spawn(function()
                                    if hotbarSwitch(pickaxeSlot) then
                                        task.wait(0.03)
                                        forceBreak(block)
                                    end
                                    task.wait(0.2)
                                    _G.gingerLock = false
                                end)
                            end
                        elseif not LimitToItem.Enabled then
                            forceBreak(block)
                        end
                    end
                    
                    return unpack(res)
                end
                
				if AutoSwitch.Enabled then
                    if placeCheckConnection then
                        placeCheckConnection:Disconnect()
                        placeCheckConnection = nil
                    end
                    placeCheckConnection = runService.RenderStepped:Connect(function()
                        if not _G.gingerLock and entitylib.isAlive and tick() - lastPlaceTime > 0.15 then
                            tryPlaceGumdrop()
                        end
                    end)
                end
                
                AutoGinger:Clean(function()
                    bedwars.LaunchPadController.attemptLaunch = old
                    if placeCheckConnection then
                        placeCheckConnection:Disconnect()
                        placeCheckConnection = nil
                    end
                end)
            else
                lastBreakTime = 0
                lastPlaceTime = 0
                justPlacedGumdrop = false
                lastPlacedPosition = nil
                _G.gingerLock = false
                if placeCheckConnection then
                    placeCheckConnection:Disconnect()
                    placeCheckConnection = nil
                end
            end
        end,
        Tooltip = 'really just advanced autokit'
    })

    LimitToItem = AutoGinger:CreateToggle({
        Name = 'Limit to Pickaxe',
        Default = true,
    })
    
    BreakDelay = AutoGinger:CreateToggle({
        Name = 'Break Delay',
        Default = false,
        Function = function(callback)
            if BreakDelaySlider and BreakDelaySlider.Object then
                BreakDelaySlider.Object.Visible = callback and not AutoSwitch.Enabled
            end
        end,
    })
    
    BreakDelaySlider = AutoGinger:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 2,
        Default = 0.5,
        Decimal = 10,
        Suffix = 's',
        Visible = false,
    })
    
	AutoSwitch = AutoGinger:CreateToggle({
        Name = 'Auto-Switch',
        Default = false,
        Function = function(callback)
            if SwitchMode and SwitchMode.Object then SwitchMode.Object.Visible = callback end
            if BreakDelay and BreakDelay.Object then BreakDelay.Object.Visible = not callback end
            if BreakDelaySlider and BreakDelaySlider.Object then
                BreakDelaySlider.Object.Visible = (not callback) and BreakDelay.Enabled
            end
            if LimitToItem and LimitToItem.Object then LimitToItem.Object.Visible = not callback end

            if placeCheckConnection then
                placeCheckConnection:Disconnect()
                placeCheckConnection = nil
            end

            if callback and AutoGinger.Enabled then
                placeCheckConnection = runService.RenderStepped:Connect(function()
                    if not _G.gingerLock and entitylib.isAlive and tick() - lastPlaceTime > 0.15 then
                        tryPlaceGumdrop()
                    end
                end)
            end
        end,
    })
    
    SwitchMode = AutoGinger:CreateDropdown({
        Name = 'Camera Mode',
        List = {'Both', 'First Person', 'Third Person'},
        Default = 'Both',
        Visible = false,
    })
end)

run(function()
    local Beekeeper
    local isRealBee
    local CollectionToggle
	local LimitToNet
	local HiveLimit
	local function maxHiveLevel()
		return HiveLimit and HiveLimit.Value or 12
	end
    local maxedBeehives = {}
    local maxedNotificationSent = {}
    local CollectionDelay
    local DelaySlider
    local RangeSlider
    local ESPToggle
    local BeesESP
    local BeesNotify
    local BeesBackground
    local BeesColor
    local BeehiveESP
    local ShowOtherBeehives
    local BeehiveBackground
    local BeehiveColor
    local AutoDeposit
    local DepositDelay
    local DepositDelaySlider
    local DepositRange
    local ESPLimitToNet  
    local collectionRunning = false
    local depositRunning = false
    local BeesFolder = Instance.new('Folder')
    BeesFolder.Parent = vape.gui
    local BeehiveFolder = Instance.new('Folder')
    BeehiveFolder.Parent = vape.gui
    local BeesReference = {}
    local BeehiveReference = {}
    local lastNotification = 0
    local spawnQueue = {}
    local notificationCooldown = 1

    local function sendNotification(count)
        notif("Bee ESP", string.format("%d bees spawned", count), 3)
    end

    local function processSpawnQueue()
        if #spawnQueue > 0 then
            local currentTime = tick()
            if currentTime - lastNotification >= notificationCooldown then
                sendNotification(#spawnQueue)
                lastNotification = currentTime
                spawnQueue = {}
            else
                task.delay(notificationCooldown - (currentTime - lastNotification), function()
                    if #spawnQueue > 0 then
                        sendNotification(#spawnQueue)
                        spawnQueue = {}
                    end
                end)
            end
        end
    end

    local function getBeeIcon()
        return bedwars.getIcon({itemType = 'bee'}, true)
    end

    local function AddedBee(v)
        if BeesReference[v] then return end
        local model = v.Parent
        if model and not isRealBee(model) then
            return
        end
        
        local billboard = Instance.new('BillboardGui')
        billboard.Parent = BeesFolder
        billboard.Name = 'bee'
        billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
        billboard.Size = UDim2.fromOffset(36, 36)
        billboard.AlwaysOnTop = true
        billboard.ClipsDescendants = false
        billboard.Adornee = v
        
        local blur = addBlur(billboard)
        blur.Visible = BeesBackground.Enabled
        
        local image = Instance.new('ImageLabel')
        image.Size = UDim2.fromOffset(36, 36)
        image.Position = UDim2.fromScale(0.5, 0.5)
        image.AnchorPoint = Vector2.new(0.5, 0.5)
        image.BackgroundColor3 = Color3.fromHSV(BeesColor.Hue, BeesColor.Sat, BeesColor.Value)
        image.BackgroundTransparency = 1 - (BeesBackground.Enabled and BeesColor.Opacity or 0)
        image.BorderSizePixel = 0
        image.Image = getBeeIcon()
        image.Parent = billboard
        
        local uicorner = Instance.new('UICorner')
        uicorner.CornerRadius = UDim.new(0, 4)
        uicorner.Parent = image
        
        BeesReference[v] = billboard
        
        if BeesNotify.Enabled then
            table.insert(spawnQueue, {item = 'bee', time = tick()})
            processSpawnQueue()
        end
    end

    local function RemovedBee(v)
        if BeesReference[v] then
            BeesReference[v]:Destroy()
            BeesReference[v] = nil
        end
    end

    local function isMyBeehive(beehive)
        if not beehive then return false end
        local placedBy = beehive:GetAttribute("PlacedByUserId")
        return placedBy and placedBy == lplr.UserId
    end
    
    local function getBeehiveOwnerName(beehive)
        if not beehive then return "Unknown" end
        local placedBy = beehive:GetAttribute("PlacedByUserId")
        if not placedBy then return "Unknown" end
        
        local player = game.Players:GetPlayerByUserId(placedBy)
        if player then
            return player.Name
        end
        
        return "Player"
    end

    local function AddedBeehive(beehive)
        local isOwn = isMyBeehive(beehive)
        
        if not isOwn and not (ShowOtherBeehives and ShowOtherBeehives.Enabled) then 
            return 
        end
        
        if BeehiveReference[beehive] then return end
        
        local level = beehive:GetAttribute("Level") or 0
        local isMaxed = level >= maxHiveLevel() and isOwn
        
        if isMaxed and isOwn then
            maxedBeehives[beehive] = true
        end
        
        local ownerName = isOwn and nil or getBeehiveOwnerName(beehive)
        local hasOwnerName = ownerName ~= nil
        
        local billboard = Instance.new('BillboardGui')
        billboard.Parent = BeehiveFolder
        billboard.Name = 'beehive-esp'
        billboard.StudsOffsetWorldSpace = Vector3.new(0, 4, 0)
        billboard.Size = isMaxed and UDim2.fromOffset(90, 40) or (hasOwnerName and UDim2.fromOffset(120, 40) or UDim2.fromOffset(80, 30))
        billboard.AlwaysOnTop = true
        billboard.ClipsDescendants = false
        billboard.Adornee = beehive
        
        local blur = addBlur(billboard)
        blur.Visible = BeehiveBackground.Enabled
        
        local frame = Instance.new('Frame')
        frame.Size = UDim2.fromScale(1, 1)
        frame.BackgroundColor3 = isMaxed and Color3.fromRGB(255, 50, 50) or Color3.fromHSV(BeehiveColor.Hue, BeehiveColor.Sat, BeehiveColor.Value)
        frame.BackgroundTransparency = 1 - (BeehiveBackground.Enabled and (isMaxed and 0.5 or BeehiveColor.Opacity) or 0)
        frame.BorderSizePixel = 0
        frame.Parent = billboard
        
        local uicorner = Instance.new('UICorner')
        uicorner.CornerRadius = UDim.new(0, 6)
        uicorner.Parent = frame
        
        if hasOwnerName then
            local nameLabel = Instance.new('TextLabel')
            nameLabel.Name = 'OwnerName'
            nameLabel.Size = UDim2.new(1, 0, 0.4, 0)
            nameLabel.Position = UDim2.new(0, 0, 0, -20)
            nameLabel.BackgroundTransparency = 1
            nameLabel.Text = ownerName
            nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
            nameLabel.TextSize = 12
            nameLabel.Font = Enum.Font.GothamBold
            nameLabel.TextStrokeTransparency = 0.5
            nameLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
            nameLabel.Parent = billboard
        end
        
        local homeImage = Instance.new('ImageLabel')
		homeImage.Size = UDim2.fromOffset(20, 20)
		homeImage.Position = UDim2.new(0, 5, 0.5, 0)
		homeImage.AnchorPoint = Vector2.new(0, 0.5)
		homeImage.BackgroundTransparency = 1
		homeImage.BorderSizePixel = 0
		homeImage.Image = bedwars.getIcon({itemType = 'beehive'}, true)
		homeImage.Parent = frame
        
        local beeImage = Instance.new('ImageLabel')
        beeImage.Size = UDim2.fromOffset(18, 18)
        beeImage.Position = UDim2.new(0.5, -5, 0.5, 0)
        beeImage.AnchorPoint = Vector2.new(0, 0.5)
        beeImage.BackgroundTransparency = 1
        beeImage.Image = getBeeIcon()
        beeImage.Parent = frame
        
        local levelLabel = Instance.new('TextLabel')
        levelLabel.Name = 'Level'
        levelLabel.Size = UDim2.new(0, 25, 1, 0)
        levelLabel.Position = UDim2.new(1, -30, 0, 0)
        levelLabel.BackgroundTransparency = 1
        levelLabel.Text = tostring(level)
        levelLabel.TextColor3 = isMaxed and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(255, 255, 255)
        levelLabel.TextSize = 16
        levelLabel.Font = Enum.Font.GothamBold
        levelLabel.TextStrokeTransparency = 0.5
        levelLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
        levelLabel.Parent = frame
        
        if isMaxed and isOwn then
            local maxText = Instance.new('TextLabel')
            maxText.Name = 'MaxText'
            maxText.Size = UDim2.new(1, 0, 0.4, 0)
            maxText.Position = UDim2.new(0, 0, 0, hasOwnerName and -40 or -20)
            maxText.BackgroundTransparency = 1
            maxText.Text = "MAX"
            maxText.TextColor3 = Color3.fromRGB(255, 50, 50)
            maxText.TextSize = 12
            maxText.Font = Enum.Font.GothamBold
            maxText.TextStrokeTransparency = 0.5
            maxText.TextStrokeColor3 = Color3.new(0, 0, 0)
            maxText.Parent = billboard
        end
        
        BeehiveReference[beehive] = {
            billboard = billboard,
            levelLabel = levelLabel,
            beehive = beehive,
            isMaxed = isMaxed,
            isOwn = isOwn
        }
        
        local function updateLevel()
            local level = beehive:GetAttribute("Level") or 0
            local isMaxed = level >= maxHiveLevel() and isOwn
            
            if isMaxed and isOwn then
                maxedBeehives[beehive] = true
                
                if not maxedNotificationSent[beehive] then
                    notif("Bee Keeper", "Beehive is full (MAX)", 3)
                    maxedNotificationSent[beehive] = true
                end
                
                if BeehiveReference[beehive] and BeehiveReference[beehive].billboard then
                    local maxText = BeehiveReference[beehive].billboard:FindFirstChild("MaxText")
                    if not maxText then
                        maxText = Instance.new('TextLabel')
                        maxText.Name = 'MaxText'
                        maxText.Size = UDim2.new(1, 0, 0.4, 0)
                        maxText.Position = UDim2.new(0, 0, 0, hasOwnerName and -40 or -20)
                        maxText.BackgroundTransparency = 1
                        maxText.Text = "MAX"
                        maxText.TextColor3 = Color3.fromRGB(255, 50, 50)
                        maxText.TextSize = 12
                        maxText.Font = Enum.Font.GothamBold
                        maxText.TextStrokeTransparency = 0.5
                        maxText.TextStrokeColor3 = Color3.new(0, 0, 0)
                        maxText.Parent = BeehiveReference[beehive].billboard
                    end
                    
                    local frame = BeehiveReference[beehive].billboard:FindFirstChild("Frame")
                    if frame then
                        frame.BackgroundColor3 = Color3.fromRGB(255, 50, 50)
                        frame.BackgroundTransparency = 1 - (BeehiveBackground.Enabled and 0.5 or 0)
                    end
                end
            else
                if isOwn then
                    maxedBeehives[beehive] = nil
                    maxedNotificationSent[beehive] = nil
                end
                
                if BeehiveReference[beehive] and BeehiveReference[beehive].billboard then
                    local maxText = BeehiveReference[beehive].billboard:FindFirstChild("MaxText")
                    if maxText then
                        maxText:Destroy()
                    end
                    
                    local frame = BeehiveReference[beehive].billboard:FindFirstChild("Frame")
                    if frame then
                        frame.BackgroundColor3 = Color3.fromHSV(BeehiveColor.Hue, BeehiveColor.Sat, BeehiveColor.Value)
                        frame.BackgroundTransparency = 1 - (BeehiveBackground.Enabled and BeehiveColor.Opacity or 0)
                    end
                end
            end
            
            if BeehiveReference[beehive] and BeehiveReference[beehive].levelLabel then
                BeehiveReference[beehive].levelLabel.Text = tostring(level)
            end
            
            if BeehiveReference[beehive] then
                BeehiveReference[beehive].isMaxed = isMaxed
            end
        end
        
        updateLevel()
        
        if isOwn then
            Beekeeper:Clean(beehive:GetAttributeChangedSignal("Level"):Connect(updateLevel))
        else
            Beekeeper:Clean(beehive:GetAttributeChangedSignal("Level"):Connect(function()
                local level = beehive:GetAttribute("Level") or 0
                if BeehiveReference[beehive] and BeehiveReference[beehive].levelLabel then
                    BeehiveReference[beehive].levelLabel.Text = tostring(level)
                end
            end))
        end
    end


    local function RemovedBeehive(beehive)
        if BeehiveReference[beehive] then
            BeehiveReference[beehive].billboard:Destroy()
            BeehiveReference[beehive] = nil
        end
    end

    local function getBeeId(v)
        if not v then return nil end

        local beeId = v:GetAttribute('BeeId')
        if beeId ~= nil then
            return beeId
        end

        local part = v.PrimaryPart or v:FindFirstChildWhichIsA('BasePart', true)
        return part and part:GetAttribute('BeeId')
    end

    isRealBee = function(v)
        local beeId = getBeeId(v)
        return beeId ~= nil and beeId > -1
    end

    local function setupBeesESP()
        for _, tagName in {'bee', 'MeadowBee', 'ChromaBee'} do
            for _, v in collectionService:GetTagged(tagName) do
                if v:IsA("Model") and v.PrimaryPart then
                    if isRealBee(v) then
                        AddedBee(v.PrimaryPart)
                    end
                end
            end

            Beekeeper:Clean(collectionService:GetInstanceAddedSignal(tagName):Connect(function(v)
                if v:IsA("Model") and v.PrimaryPart then
                    task.wait(0.1)
                    if isRealBee(v) then
                        AddedBee(v.PrimaryPart)
                    end
                end
            end))

            Beekeeper:Clean(collectionService:GetInstanceRemovedSignal(tagName):Connect(function(v)
                if v.PrimaryPart then
                    RemovedBee(v.PrimaryPart)
                end
            end))
        end
    end

    local function setupBeehiveESP()
        for _, beehive in collectionService:GetTagged('beehive') do
            AddedBeehive(beehive)
        end

        Beekeeper:Clean(collectionService:GetInstanceAddedSignal('beehive'):Connect(function(beehive)
            task.wait(0.1)
            AddedBeehive(beehive)
        end))

        Beekeeper:Clean(collectionService:GetInstanceRemovedSignal('beehive'):Connect(function(beehive)
            RemovedBeehive(beehive)
        end))
    end

    local function isHoldingBeeNet()
        if not store.hand or not store.hand.tool then return false end

        local name = store.hand.tool.Name

        return name == 'bee_net'
            or name == 'bee-net'
            or name == 'beekeeper_chroma_bee_net'
            or name == 'beekeeper_meadow_bee_net'
    end

	local function kitCollection(id, func, range, specific)
		repeat
			if entitylib.isAlive then
				local objs = type(id) == 'table' and id or collection(id, Beekeeper)
				local localPosition = entitylib.character.RootPart.Position
				for _, v in objs do
					if not Beekeeper.Enabled then break end
					local part = not v:IsA('Model') and v or v.PrimaryPart
					if part and (part.Position - localPosition).Magnitude <= range then
						local success, err = pcall(func, v)
						task.wait(0.02)
					end
				end
			end
			task.wait(0.05)
		until not Beekeeper.Enabled
	end

    local collectionThreads = {}

    local function startCollection()
        collectionRunning = true
        for _, tagName in {'bee', 'MeadowBee', 'ChromaBee'} do
            local thread = task.spawn(function()
                kitCollection(tagName, function(v)
                    if not isRealBee(v) then return end
                    if LimitToNet.Enabled and not isHoldingBeeNet() then return end
                    bedwars.Client:Get(remotes.BeePickup):SendToServer({beeId = getBeeId(v)})
                end, RangeSlider.Value, false)
            end)
            table.insert(collectionThreads, thread)
        end
        Beekeeper:Clean(function()
            for _, thread in collectionThreads do
                task.cancel(thread)
            end
            table.clear(collectionThreads)
        end)
    end

    local function startDeposit()
        depositRunning = true
        task.spawn(function()
            while depositRunning and Beekeeper.Enabled and AutoDeposit.Enabled do
                if not entitylib.isAlive then 
                    task.wait(0.1) 
                    continue 
                end
                
                local currentTool = store.hand and store.hand.tool
                if not currentTool or currentTool.Name ~= 'bee' then
                    task.wait(0.1)
                    continue
                end
                
                local localPosition = entitylib.character.RootPart.Position
                local range = DepositRange.Value
                local depositedThisCycle = false
                
                local availableBeehives = {}
                for _, beehive in collectionService:GetTagged('beehive') do
                    if isMyBeehive(beehive) and not maxedBeehives[beehive] then
                        local beehivePos = beehive.Position
                        local distance = (localPosition - beehivePos).Magnitude
                        
                        if distance <= range then
                            table.insert(availableBeehives, {
                                beehive = beehive,
                                distance = distance
                            })
                        end
                    end
                end
                
                table.sort(availableBeehives, function(a, b)
                    return a.distance < b.distance
                end)
                
                for _, beehiveData in ipairs(availableBeehives) do
                    if not depositRunning or not Beekeeper.Enabled or not AutoDeposit.Enabled then 
                        break 
                    end
                    local beehive = beehiveData.beehive
                    if maxedBeehives[beehive] then
                        continue
                    end
                    
                    local prompt = beehive:FindFirstChildOfClass("ProximityPrompt")
                    
                    if prompt and prompt.Enabled then
                        if DepositDelay.Enabled and DepositDelaySlider.Value > 0 then
                            local originalDuration = prompt.HoldDuration
                            prompt.HoldDuration = DepositDelaySlider.Value
                            
                            if fireproximityprompt then
                                fireproximityprompt(prompt)
                            else
                                prompt:InputHoldBegin()
                                task.wait(DepositDelaySlider.Value)
                                prompt:InputHoldEnd()
                            end
                            
                            task.wait(DepositDelaySlider.Value + 0.1)
                            prompt.HoldDuration = originalDuration
                        else
                            if fireproximityprompt then
                                fireproximityprompt(prompt)
                            else
                                prompt:InputHoldBegin()
                                prompt:InputHoldEnd()
                            end
                            task.wait(0.1)
                        end
                        
                        depositedThisCycle = true
                        break 
                    end
                end
                
                if not depositedThisCycle and #availableBeehives > 0 then
                    local allMaxed = true
                    for _, beehiveData in ipairs(availableBeehives) do
                        if not maxedBeehives[beehiveData.beehive] then
                            allMaxed = false
                            break
                        end
                    end
                    
                    if allMaxed then
                        notif("Bee Keeper", "All nearby beehives are full", 3)
                    end
                end
                
                task.wait(depositedThisCycle and 0.3 or 0.2)
            end
            depositRunning = false
        end)
    end

    Beekeeper = vape.Categories.Kits:CreateModule({
        Name = 'AutoBeekeeper',
        Function = function(callback)
            if callback then
                if ESPToggle.Enabled then
                    if BeesESP.Enabled then
                        setupBeesESP()
                    end
                    if BeehiveESP.Enabled then
                        setupBeehiveESP()
                    end
                end
                
                if CollectionToggle.Enabled then
                    startCollection()
                end
                
                if AutoDeposit.Enabled then
                    startDeposit()
                end
                
                local _bkLastUpdate = 0
                Beekeeper:Clean(runService.RenderStepped:Connect(function()
                    if not ESPToggle.Enabled then return end
                    local _now = tick()
                    if _now - _bkLastUpdate < 0.1 then return end
                    _bkLastUpdate = _now
                    
                    for v, billboard in pairs(BeesReference) do
                        if not v or not v.Parent then
                            RemovedBee(v)
                            continue
                        end

                        local shouldShow = true

                        if ESPLimitToNet.Enabled and not isHoldingBeeNet() then
                            shouldShow = false
                        end

                        billboard.Enabled = shouldShow
                    end
                    
                    for beehive, ref in pairs(BeehiveReference) do
                        if not beehive or not beehive.Parent then
                            RemovedBeehive(beehive)
                            continue
                        end

                        local shouldShow = true

                        if ESPLimitToNet.Enabled and not isHoldingBeeNet() then
                            shouldShow = false
                        end

                        if ref.billboard then
                            ref.billboard.Enabled = shouldShow
                        end
                    end
                end))
            else
                collectionRunning = false
                depositRunning = false
                BeesFolder:ClearAllChildren()
                BeehiveFolder:ClearAllChildren()
                table.clear(BeesReference)
                table.clear(BeehiveReference)
                table.clear(spawnQueue)
                lastNotification = 0
            end
        end,
    })
    
    CollectionToggle = Beekeeper:CreateToggle({
        Name = 'Auto Collect',
        Default = true,
        Function = function(callback)
            if LimitToNet and LimitToNet.Object then LimitToNet.Object.Visible = callback end
            if CollectionDelay and CollectionDelay.Object then CollectionDelay.Object.Visible = callback end
            if DelaySlider and DelaySlider.Object then DelaySlider.Object.Visible = (callback and CollectionDelay.Enabled) end
            if RangeSlider and RangeSlider.Object then RangeSlider.Object.Visible = callback end
            
            if callback and Beekeeper.Enabled then
                startCollection()
            else
                collectionRunning = false
            end
        end
    })
    
    LimitToNet = Beekeeper:CreateToggle({
        Name = 'Limit to Net',
        Default = false,
    })
    
    CollectionDelay = Beekeeper:CreateToggle({
        Name = 'Collection Delay',
        Default = false,
        Function = function(callback)
            if DelaySlider and DelaySlider.Object then
                DelaySlider.Object.Visible = callback
            end
        end
    })
    
    DelaySlider = Beekeeper:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 2,
        Default = 0.5,
        Decimal = 10,
        Suffix = 's',
    })
    
    RangeSlider = Beekeeper:CreateSlider({
        Name = 'Range',
        Min = 1, 
        Max = 10,
        Default = 10,
        Decimal = 1,
        Suffix = ' studs',
    })
    
    ESPToggle = Beekeeper:CreateToggle({
        Name = 'ESP',
        Default = true,
		Function = function(callback)
			if BeesESP and BeesESP.Object then BeesESP.Object.Visible = callback end
			if BeehiveESP and BeehiveESP.Object then BeehiveESP.Object.Visible = callback end
			if ESPLimitToNet and ESPLimitToNet.Object then ESPLimitToNet.Object.Visible = callback end

			if not callback then
				if BeesNotify and BeesNotify.Object then BeesNotify.Object.Visible = false end
				if BeesBackground and BeesBackground.Object then BeesBackground.Object.Visible = false end
				if BeesColor and BeesColor.Object then BeesColor.Object.Visible = false end
				if ShowOtherBeehives and ShowOtherBeehives.Object then ShowOtherBeehives.Object.Visible = false end
				if BeehiveBackground and BeehiveBackground.Object then BeehiveBackground.Object.Visible = false end
				if BeehiveColor and BeehiveColor.Object then BeehiveColor.Object.Visible = false end
			else
				if BeesESP and BeesESP.Enabled then
					if BeesNotify and BeesNotify.Object then BeesNotify.Object.Visible = true end
					if BeesBackground and BeesBackground.Object then BeesBackground.Object.Visible = true end
					if BeesColor and BeesColor.Object then BeesColor.Object.Visible = BeesBackground.Enabled end
				end
				if BeehiveESP and BeehiveESP.Enabled then
					if ShowOtherBeehives and ShowOtherBeehives.Object then ShowOtherBeehives.Object.Visible = true end
					if BeehiveBackground and BeehiveBackground.Object then BeehiveBackground.Object.Visible = true end
					if BeehiveColor and BeehiveColor.Object then BeehiveColor.Object.Visible = BeehiveBackground.Enabled end
				end
			end

			if Beekeeper.Enabled then
				if callback then
					if BeesESP.Enabled then setupBeesESP() end
					if BeehiveESP.Enabled then setupBeehiveESP() end
				else
					BeesFolder:ClearAllChildren()
					BeehiveFolder:ClearAllChildren()
					table.clear(BeesReference)
					table.clear(BeehiveReference)
				end
			end
		end
    })
    
    ESPLimitToNet = Beekeeper:CreateToggle({
        Name = 'Limit to Net',
        Default = false,
    })
    
    BeesESP = Beekeeper:CreateToggle({
        Name = 'Bees',
        Default = false,
        Function = function(callback)
            if BeesNotify and BeesNotify.Object then BeesNotify.Object.Visible = callback end
            if BeesBackground and BeesBackground.Object then BeesBackground.Object.Visible = callback end
            if BeesColor and BeesColor.Object then BeesColor.Object.Visible = callback end
            
            if Beekeeper.Enabled and ESPToggle.Enabled then
                if callback then setupBeesESP() else
                    BeesFolder:ClearAllChildren()
                    table.clear(BeesReference)
                end
            end
        end
    })
    
    BeesNotify = Beekeeper:CreateToggle({
        Name = 'Notify',
        Default = false,
    })
    
    BeesBackground = Beekeeper:CreateToggle({
        Name = 'Background',
        Default = true,
        Function = function(callback)
            if BeesColor and BeesColor.Object then BeesColor.Object.Visible = callback end
            for _, v in BeesReference do
                if v and v:FindFirstChild("ImageLabel") then
                    v.ImageLabel.BackgroundTransparency = 1 - (callback and BeesColor.Opacity or 0)
                    if v:FindFirstChild("Blur") then
                        v.Blur.Visible = callback
                    end
                end
            end
        end
    })
    
	BeesColor = Beekeeper:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Function = function(hue, sat, val, opacity)
			for _, v in BeesReference do
				if v and v:FindFirstChild("ImageLabel") then
					v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
					v.ImageLabel.BackgroundTransparency = 1 - opacity
				end
			end
		end,
		Darker = true
	})
    
    BeehiveESP = Beekeeper:CreateToggle({
        Name = 'Beehives',
        Default = false,
        Function = function(callback)
            if ShowOtherBeehives and ShowOtherBeehives.Object then ShowOtherBeehives.Object.Visible = callback end
            if BeehiveBackground and BeehiveBackground.Object then BeehiveBackground.Object.Visible = callback end
            if BeehiveColor and BeehiveColor.Object then BeehiveColor.Object.Visible = callback end
            
            if Beekeeper.Enabled and ESPToggle.Enabled then
                if callback then setupBeehiveESP() else
                    BeehiveFolder:ClearAllChildren()
                    table.clear(BeehiveReference)
                end
            end
        end
    })
    
    ShowOtherBeehives = Beekeeper:CreateToggle({
        Name = 'Show Others',
        Default = false,
        Function = function(callback)
            if Beekeeper.Enabled and ESPToggle.Enabled and BeehiveESP.Enabled then
                BeehiveFolder:ClearAllChildren()
                table.clear(BeehiveReference)
                setupBeehiveESP()
            end
        end
    })
    
    BeehiveBackground = Beekeeper:CreateToggle({
        Name = 'Beehive Background',
        Default = true,
        Function = function(callback)
            if BeehiveColor and BeehiveColor.Object then BeehiveColor.Object.Visible = callback end
            for _, ref in BeehiveReference do
                if ref and ref.billboard then
                    local frame = ref.billboard:FindFirstChild("Frame")
                    if frame then
                        if ref.isMaxed and ref.isOwn then
                            frame.BackgroundTransparency = 1 - (callback and 0.5 or 0)
                        else
                            frame.BackgroundTransparency = 1 - (callback and BeehiveColor.Opacity or 0)
                        end
                    end
                    if ref.billboard:FindFirstChild("Blur") then
                        ref.billboard.Blur.Visible = callback
                    end
                end
            end
        end
    })
    
    BeehiveColor = Beekeeper:CreateColorSlider({
        Name = 'Beehive Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for _, ref in BeehiveReference do
                if ref and ref.billboard then
                    local frame = ref.billboard:FindFirstChild("Frame")
                    if frame and not (ref.isMaxed and ref.isOwn) then
                        frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
                        frame.BackgroundTransparency = 1 - opacity
                    end
                end
            end
        end,
        Darker = true
    })
    
    AutoDeposit = Beekeeper:CreateToggle({
        Name = 'Auto Deposit',
        Default = false,
		Function = function(callback)
			if DepositDelay and DepositDelay.Object then DepositDelay.Object.Visible = callback end
			if DepositDelaySlider and DepositDelaySlider.Object then DepositDelaySlider.Object.Visible = (callback and DepositDelay.Enabled) end
			if DepositRange and DepositRange.Object then DepositRange.Object.Visible = callback end
			if HiveLimit and HiveLimit.Object then HiveLimit.Object.Visible = callback end
			
			if not callback then
				if DepositDelaySlider and DepositDelaySlider.Object then DepositDelaySlider.Object.Visible = false end
			end

			if callback and Beekeeper.Enabled then
				startDeposit()
			else
				depositRunning = false
			end
		end
    })
    
    DepositDelay = Beekeeper:CreateToggle({
        Name = 'Deposit Delay',
        Default = false,
        Function = function(callback)
            if DepositDelaySlider and DepositDelaySlider.Object then
                DepositDelaySlider.Object.Visible = callback
            end
        end
    })
    
    DepositDelaySlider = Beekeeper:CreateSlider({
        Name = 'Deposit Delay',
        Min = 0,
        Max = 2,
        Default = 0.5,
        Decimal = 10,
        Suffix = 's',
    })
    
    DepositRange = Beekeeper:CreateSlider({
        Name = 'Deposit Range',
        Min = 1,
        Max = 10,
        Default = 10,
        Decimal = 1,
        Suffix = ' studs',
    })
    
    HiveLimit = Beekeeper:CreateSlider({
        Name = 'Hive Limit',
        Min = 1,
        Max = 20,
        Default = 12,
        Decimal = 1,
        Suffix = ' bees',
        Function = function()
            table.clear(maxedBeehives)
            table.clear(maxedNotificationSent)
        end
    })
	task.defer(function()
		if HiveLimit and HiveLimit.Object then HiveLimit.Object.Visible = AutoDeposit.Enabled end
		if DelaySlider and DelaySlider.Object then DelaySlider.Object.Visible = CollectionDelay.Enabled end
		if not ESPToggle.Enabled or not BeesESP.Enabled then
			if BeesNotify and BeesNotify.Object then BeesNotify.Object.Visible = false end
			if BeesBackground and BeesBackground.Object then BeesBackground.Object.Visible = false end
			if BeesColor and BeesColor.Object then BeesColor.Object.Visible = false end
		else
			if BeesColor and BeesColor.Object then BeesColor.Object.Visible = BeesBackground.Enabled end
		end

		if not ESPToggle.Enabled or not BeehiveESP.Enabled then
			if ShowOtherBeehives and ShowOtherBeehives.Object then ShowOtherBeehives.Object.Visible = false end
			if BeehiveBackground and BeehiveBackground.Object then BeehiveBackground.Object.Visible = false end
			if BeehiveColor and BeehiveColor.Object then BeehiveColor.Object.Visible = false end
		else
			if BeehiveColor and BeehiveColor.Object then BeehiveColor.Object.Visible = BeehiveBackground.Enabled end
		end

		if AutoDeposit and not AutoDeposit.Enabled then
			if DepositDelay and DepositDelay.Object then DepositDelay.Object.Visible = false end
			if DepositDelaySlider and DepositDelaySlider.Object then DepositDelaySlider.Object.Visible = false end
			if DepositRange and DepositRange.Object then DepositRange.Object.Visible = false end
		end

		if DepositDelaySlider and DepositDelaySlider.Object then
			DepositDelaySlider.Object.Visible = (AutoDeposit.Enabled and DepositDelay.Enabled)
		end
	end)
end)

run(function()
    local Fisherman
    local AutoMinigameToggle
    local CompleteDelaySlider
    local PullAnimationToggle
    local MinigameAnimationToggle
    local BlacklistOption
    local Blacklist
    local ESPToggle
	local AutoCastDelay
	local AutoCast
    local ESPNotifyToggle
    local Players = playersService
	local RunService = runService
	local lplr = Players.LocalPlayer
	local RandomizeToggle
    local RandomRange
	local waitTime
    local fishNames = {
		fish_iron = "Iron Fish",
		fish_diamond = "Diamond Fish",
		fish_gold = "Gold Fish",
		fish_special = "Special Fish",
		fish_emerald = "Emerald Fish",
	}

    local function buildMessage(fishModel, drops)
        local fishName = fishNames[fishModel] or fishModel

        if not drops or #drops == 0 then
            if fishModel == "fish_special" then
                return "You caught a " .. fishName .. "! (special item incoming)"
            end
            return "You caught a " .. fishName .. "!"
        end

        local totals = {}
        local order = {}
        for _, drop in ipairs(drops) do
            local item = tostring(drop.itemType) or 'unknown'
            local amount = tonumber(drop.amount) or 0
            if not totals[item] then
                totals[item] = 0
                table.insert(order, item)
            end
            totals[item] = totals[item] + amount
        end

        if fishModel == "fish_special" then
            return "You caught a " .. fishName .. "! You will receive a " .. table.concat(order, ", ")
        end

        local parts = {}
        for _, item in ipairs(order) do
            table.insert(parts, math.ceil(totals[item] * 1.4) .. "x " .. item)
        end

        return "You caught a " .. fishName .. "! Receiving " .. table.concat(parts, ", ")
    end

    local notifQueue = {}
	local function safeNotif(title, msg, dur)
		table.insert(notifQueue, {title=title, message=msg, duration=dur or 5})
	end
	local heartbeatConn = nil

    local autoMinigameActive    = false
    local pullAnimationTrack    = nil
    local successAnimationTrack = nil
    local espOld                = nil

	local function getBait()
		for _, v in workspace:GetChildren() do
			if v.Name == "fisherman_bobber" and v:GetAttribute("ProjectileShooter") == lplr.UserId then
				return v
			end
		end

		return
	end

    local function stopAllAnimations()
        if pullAnimationTrack then
            pcall(function() pullAnimationTrack:Stop() end)
            pullAnimationTrack = nil
        end
        if successAnimationTrack then
            pcall(function() successAnimationTrack:Stop() end)
            successAnimationTrack = nil
        end
    end

    local function setupESP()
        if not bedwars or not bedwars.FishingMinigameController then
            warn("[AutoFisher] FishingMinigameController not found")
            return
        end
        if espOld then return end 
        espOld = bedwars.FishingMinigameController.startMinigame

        bedwars.FishingMinigameController.startMinigame = function(self, dropData, result)
            if ESPToggle.Enabled and ESPNotifyToggle.Enabled and dropData and dropData.fishModel then
                safeNotif("Fisherman ESP", buildMessage(dropData.fishModel, dropData.drops), 8)
            end
            return espOld(self, dropData, result)
        end

        Fisherman:Clean(function()
            if espOld then
                bedwars.FishingMinigameController.startMinigame = espOld
                espOld = nil
            end
        end)
    end

    local function cleanupESP()
        if espOld then
            bedwars.FishingMinigameController.startMinigame = espOld
            espOld = nil
        end
    end

    local function setupAutoMinigame()
        if not bedwars or not bedwars.FishingMinigameController then
            warn("[AutoFisher] FishingMinigameController not found")
            return
        end

        local old = bedwars.FishingMinigameController.startMinigame

        bedwars.FishingMinigameController.startMinigame = function(self, dropData, result)
            if not AutoMinigameToggle.Enabled then
                return old(self, dropData, result)
            end

            if BlacklistOption.Enabled and dropData and dropData.fishModel then
                if table.find(Blacklist.ListEnabled, dropData.fishModel) then
                    local hum = lplr.Character and lplr.Character:FindFirstChildOfClass("Humanoid")
                    if hum and hum:GetState() ~= Enum.HumanoidStateType.Jumping then
                        hum:ChangeState(Enum.HumanoidStateType.Jumping)
                    end
                    return old(self, dropData, result)
                end
            end

            autoMinigameActive = true
            stopAllAnimations()

            local waitTime = 0
            if RandomizeToggle and RandomizeToggle.Enabled then
                local min = RandomRange.ValueMin
                local max = RandomRange.ValueMax
                waitTime = min + (max - min) * math.random()
            else
                waitTime = CompleteDelaySlider.Value
            end

            task.spawn(function()
                if PullAnimationToggle.Enabled and waitTime > 0 then
                    local ok, track = pcall(function()
                        return bedwars.GameAnimationUtil:playAnimation(
                            lplr, bedwars.AnimationType.FISHING_ROD_PULLING
                        )
                    end)
                    if ok and track then pullAnimationTrack = track end
                end

                if waitTime > 0 then
                    task.wait(waitTime)
                end

                if pullAnimationTrack then
                    pcall(function() pullAnimationTrack:Stop() end)
                    pullAnimationTrack = nil
                end

                if MinigameAnimationToggle.Enabled then
                    local ok, track = pcall(function()
                        return bedwars.GameAnimationUtil:playAnimation(
                            lplr, bedwars.AnimationType.FISHING_ROD_CATCH_SUCCESS
                        )
                    end)
                    if ok and track then successAnimationTrack = track end
                end

                if result then
                    pcall(function() result({ win = true }) end)
                end

                task.wait(0.5)

                if successAnimationTrack then
                    pcall(function() successAnimationTrack:Stop() end)
                    successAnimationTrack = nil
                end

                autoMinigameActive = false
            end)
        end

        Fisherman:Clean(function()
            bedwars.FishingMinigameController.startMinigame = old
            stopAllAnimations()
        end)
    end

	local function setupAutoCast()
		task.spawn(function()
			repeat
				if entitylib.isAlive and AutoCast.Enabled and (store.hand.tool and store.hand.tool.Name == 'fishing_rod') then
					local position = workspace.CurrentCamera.ViewportSize / 2
					local ray = cloneref(lplr:GetMouse()).UnitRay

					if not getBait() and not workspace:Raycast(entitylib.character.Head.Position + (ray.Direction * 6), Vector3.new(0, -20, 0)) then
						task.wait(AutoCastDelay:GetRandomValue())

						for _, v in {true, false} do
							VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, v, game, 1)
							task.wait()
						end
						task.wait(0.5)
					end
				end
				task.wait(0.1)
			until not Fisherman.Enabled
		end)
	end

    Fisherman = vape.Categories.Kits:CreateModule({
		Name = "AutoFisher",
		Function = function(callback)
            if callback then
                if ESPToggle.Enabled then setupESP() end
                if AutoMinigameToggle.Enabled then setupAutoMinigame() end
                setupAutoCast()

                heartbeatConn = RunService.Heartbeat:Connect(function()
                    if #notifQueue == 0 then return end
                    local entry = table.remove(notifQueue, 1)
                    pcall(notif, entry.title, entry.message, entry.duration)
                end)
                Fisherman:Clean(heartbeatConn)

            else
                autoMinigameActive = false
                stopAllAnimations()
                cleanupESP()
                notifQueue = {} 
            end
        end
    })

    AutoMinigameToggle = Fisherman:CreateToggle({
		Name = "Auto Minigame",
		Default = false,
		Function = function(cv)
			if CompleteDelaySlider and CompleteDelaySlider.Object then
				CompleteDelaySlider.Object.Visible = cv and not (RandomizeToggle and RandomizeToggle.Enabled)
			end
			if PullAnimationToggle and PullAnimationToggle.Object then PullAnimationToggle.Object.Visible = cv end
			if MinigameAnimationToggle and MinigameAnimationToggle.Object then MinigameAnimationToggle.Object.Visible = cv end
			if RandomizeToggle and RandomizeToggle.Object then RandomizeToggle.Object.Visible = cv end
			if RandomRange and RandomRange.Object then RandomRange.Object.Visible = cv and RandomizeToggle.Enabled end
			if Fisherman.Enabled and cv then setupAutoMinigame() end
		end
	})

	CompleteDelaySlider = Fisherman:CreateSlider({
		Name = "Complete Delay",
		Min = 0,
		Max = 5,
		Default = 1,
		Decimal = 10,
		Suffix = "s",
		Visible = false,
	})

	RandomizeToggle = Fisherman:CreateToggle({
		Name = "Randomize Timing",
		Default = false,
		Function = function(cv)
			if RandomRange and RandomRange.Object then RandomRange.Object.Visible = cv end
			if CompleteDelaySlider and CompleteDelaySlider.Object then CompleteDelaySlider.Object.Visible = not cv end
		end
	})

	RandomRange = Fisherman:CreateTwoSlider({
		Name = "Random Delay Range",
		Min = 0.1,
		Max = 5,
		DefaultMin = 0.5,
		DefaultMax = 2,
		Decimal = 10,
		Visible = false,
	})

	PullAnimationToggle = Fisherman:CreateToggle({
		Name = "Pull Animation",
		Default = true,
		Visible = false,
	})

	MinigameAnimationToggle = Fisherman:CreateToggle({
		Name = "Success Animation",
		Default = true,
		Visible = false,
	})

	BlacklistOption = Fisherman:CreateToggle({
		Name = "Blacklist",
		Default = false,
		Function = function(cv)
			if Blacklist and Blacklist.Object then Blacklist.Object.Visible = cv end
		end
	})

	Blacklist = Fisherman:CreateTextList({
		Name = "Blacklist Fish",
		Default = {"fish_iron"}
	})

	AutoCast = Fisherman:CreateToggle({
		Name 	= "AutoCast",
		Default = false,
		Function = function(callback)
			if callback then
				if AutoCastDelay and AutoCastDelay.Object then AutoCastDelay.Object.Visible = callback end
				if AutoCast.Enabled and callback then setupAutoCast() end
			end
		end
	})

	AutoCastDelay = Fisherman:CreateTwoSlider({
		Name 	= "Cast Delay",
		Min 	= 0,
		Max 	= 5,
		Decimal = 5,
		DefaultMin = 0.3,
		DefaultMax = 1.2,
		Darker 	= true,
		Visible = AutoCast.Enabled
	})	

    ESPToggle = Fisherman:CreateToggle({
		Name = "Fisherman ESP",
		Default = false,
		Function = function(cv)
			if ESPNotifyToggle and ESPNotifyToggle.Object then ESPNotifyToggle.Object.Visible = cv end
			if Fisherman.Enabled then
				if cv then setupESP() else cleanupESP() end
			end
		end
	})

	ESPNotifyToggle = Fisherman:CreateToggle({
		Name = "Notify Loot",
		Default = true,
		Visible = false,
	})

	task.defer(function()
		local minigameOn = AutoMinigameToggle and AutoMinigameToggle.Enabled
		local randomOn = RandomizeToggle and RandomizeToggle.Enabled
		if Blacklist and Blacklist.Object then Blacklist.Object.Visible = BlacklistOption and BlacklistOption.Enabled or false end
		if AutoCastDelay and AutoCastDelay.Object then AutoCastDelay.Object.Visible = AutoCast and AutoCast.Enabled or false end
		if ESPNotifyToggle and ESPNotifyToggle.Object then ESPNotifyToggle.Object.Visible = ESPToggle and ESPToggle.Enabled or false end
		if PullAnimationToggle and PullAnimationToggle.Object then PullAnimationToggle.Object.Visible = minigameOn or false end
		if MinigameAnimationToggle and MinigameAnimationToggle.Object then MinigameAnimationToggle.Object.Visible = minigameOn or false end
		if RandomizeToggle and RandomizeToggle.Object then RandomizeToggle.Object.Visible = minigameOn or false end
		if RandomRange and RandomRange.Object then RandomRange.Object.Visible = (minigameOn and randomOn) or false end
		if CompleteDelaySlider and CompleteDelaySlider.Object then CompleteDelaySlider.Object.Visible = (minigameOn and not randomOn) or false end
	end)
end)

run(function()
	local CannonHandController = bedwars.CannonHandController
	local CannonController = bedwars.CannonController
	local oldLaunchSelf = CannonHandController.launchSelf
	local oldStopAiming = CannonController.stopAiming
	local oldStartAiming = CannonController.startAiming
	local AutoDavey
	local AutoDaveyAutojump
	local AutoDaveyAutoLaunch
	local AutoDaveyAutoBreak
	local AutoDaveyPickaxeCheck
	local AutoDaveyAutoSwitch
	local LaunchDelay
	local BreakDelay
	local isLaunching = false
	local didAutoLaunch = false

	local function getCannonSlot()
		for i, v in pairs(store.inventory.hotbar) do
			if v.item then
				local t = tostring(v.item.itemType):lower()
				if t:find("cannon") then
					return i - 1
				end
			end
		end
		return nil
	end

	local function hasWoodPickaxeOnly()
		local bestTier = 0
		for _, slot in pairs(store.inventory.hotbar) do
			if slot.item then
				local t = tostring(slot.item.itemType):lower()
				if t == "wood_pickaxe" and bestTier < 1 then
					bestTier = 1
				elseif (t:find("pickaxe") or t:find("drill")) and t ~= "wood_pickaxe" then
					bestTier = 2
				end
			end
		end
		return bestTier == 1
	end

	local function getNearestCannon()
		if not entitylib.isAlive then return nil end
		local nearest
		local nearestDist = math.huge
		for i, v in pairs(CannonController.getCannons()) do
			pcall(function()
				local dist = (v.Position - entitylib.character.RootPart.Position).Magnitude
				if dist < nearestDist and dist < 30 then
					nearestDist = dist
					nearest = v
				end
			end)
		end
		return nearest
	end

	local function findCannonModel(pos)
		local closest = nil
		local closestDist = 8
		for _, obj in store.blocks do
			if obj and obj:IsA("BasePart") and obj.Name == "cannon" then
				local dist = (obj.Position - pos).Magnitude
				if dist < closestDist then
					closestDist = dist
					closest = obj
				end
			end
		end
		return closest
	end

	local function doBreakCannon(cannon)
		if not entitylib.isAlive then return end
		if not cannon or not cannon.Parent then return end
		local block, blockpos = getPlacedBlock(cannon.Position)
		if block and block.Name == 'cannon' and
		   (entitylib.character.RootPart.Position - block.Position).Magnitude < 30 then
			pcall(bedwars.breakBlock, block, false, nil, true)
		else
			local directBlock = findCannonModel(cannon.Position)
			if directBlock and directBlock.Parent then
				pcall(bedwars.breakBlock, directBlock, false, nil, true)
			end
		end
	end

	local function firstHitCannon(cannon)
		if not entitylib.isAlive then return end
		if not cannon or not cannon.Parent then return end
		if hasWoodPickaxeOnly() then
			doBreakCannon(cannon)
		end
	end

	local function breakCannon(cannon, shootfunc)
		if not entitylib.isAlive then
			isLaunching = false
			return shootfunc()
		end

		local cannonSlot = nil

		if AutoDaveyAutoSwitch.Enabled and not isHoldingPickaxe() then
			local pickaxeSlot = getPickaxeSlot()
			if not pickaxeSlot then
				notif("AutoDavey", "No pickaxe found in hotbar!", 3)
				if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
					entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
				end
				isLaunching = false
				return shootfunc()
			end
			cannonSlot = getCannonSlot()
			if hotbarSwitch(pickaxeSlot) then
				task.wait(0.05)
			end
		end

		if AutoDaveyPickaxeCheck.Enabled and not isHoldingPickaxe() then
			notif("AutoDavey", "You need to HOLD a pickaxe to break cannons!", 3)
			if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
				entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
			end
			isLaunching = false
			return shootfunc()
		end

		if BreakDelay.Value > 0 then
			task.wait(BreakDelay.Value)
		end

		local cannonRef = cannon
		if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
			entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
		end
		shootfunc()
		isLaunching = false

		task.spawn(function()
			task.wait(0.05)
			doBreakCannon(cannonRef)
			task.wait(0.35)
			if cannonRef and cannonRef.Parent then
				doBreakCannon(cannonRef)
			end
			if AutoDaveyAutoSwitch.Enabled and cannonSlot then
				task.wait(0.05)
				hotbarSwitch(cannonSlot)
			end
		end)
	end

	AutoDavey = vape.Categories.Kits:CreateModule({
		Name = 'AutoDavey',
		Function = function(callback)
			if callback then
				CannonHandController.launchSelf = function(...)
					if isLaunching then
						isLaunching = false
						return oldLaunchSelf(...)
					end
					isLaunching = true
					if LaunchDelay.Value > 0 then
						task.wait(LaunchDelay.Value)
					end
					if AutoDaveyAutoBreak.Enabled then
						local cannon = getNearestCannon()
						if cannon then
							local args = {...}
							breakCannon(cannon, function()
								oldLaunchSelf(unpack(args))
							end)
							return
						else
							if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
								entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
							end
							local res = oldLaunchSelf(...)
							isLaunching = false
							return res
						end
					else
						if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
							entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
						end
						local res = oldLaunchSelf(...)
						isLaunching = false
						return res
					end
				end

				local aimedCannon = nil
				CannonController.startAiming = function(...)
					didAutoLaunch = false
					isLaunching = false
					local result = oldStartAiming(...)
					aimedCannon = getNearestCannon()
					return result
				end

				CannonController.stopAiming = function(...)
					local cannon = aimedCannon or getNearestCannon()
					local result = oldStopAiming(...)
					aimedCannon = nil
					isLaunching = false
					if AutoDaveyAutoLaunch.Enabled and not didAutoLaunch then
						didAutoLaunch = true
						if AutoDaveyAutoBreak.Enabled and AutoDaveyPickaxeCheck.Enabled and not isHoldingPickaxe() and not AutoDaveyAutoSwitch.Enabled then
							notif("AutoDavey", "Hold a pickaxe to auto-break!", 3)
							return result
						end
						if cannon then
							task.spawn(function()
								pcall(CannonHandController.launchSelf, CannonHandController, cannon)
							end)
						end
					end
					return result
				end

				local firstHitDebounce = {}
				AutoDavey:Clean(workspace.DescendantAdded:Connect(function(obj)
					if not (obj:IsA("BasePart") and obj.Name == "cannon") then return end
					if firstHitDebounce[obj] then return end
					firstHitDebounce[obj] = true
					task.spawn(function()
						task.wait(0.5)
						if AutoDaveyAutoBreak.Enabled and hasWoodPickaxeOnly() then
							local dist = entitylib.isAlive
								and (entitylib.character.RootPart.Position - obj.Position).Magnitude
								or math.huge
							if dist < 20 and obj.Parent then
								firstHitCannon(obj)
							end
						end
						firstHitDebounce[obj] = nil
					end)
				end))
			else
				CannonHandController.launchSelf = oldLaunchSelf
				CannonController.stopAiming = oldStopAiming
				CannonController.startAiming = oldStartAiming
				isLaunching = false
				didAutoLaunch = false
			end
		end,
	})

	LaunchDelay = AutoDavey:CreateSlider({
		Name = 'Launch Delay',
		Min = 0,
		Max = 2,
		Default = 0,
		Decimal = 10,
		Suffix = 's',
	})
	BreakDelay = AutoDavey:CreateSlider({
		Name = 'Break Delay',
		Min = 0,
		Max = 2,
		Default = 0,
		Decimal = 10,
		Suffix = 's',
	})

	AutoDaveyAutojump = AutoDavey:CreateToggle({
		Name = 'Auto Jump',
		Default = true,
	})
	AutoDaveyAutoLaunch = AutoDavey:CreateToggle({
		Name = 'Auto Launch',
		Default = true,
		Tooltip = 'automatically lauches u after your done aiming'
	})
	AutoDaveyAutoBreak = AutoDavey:CreateToggle({
		Name = 'Auto Break',
		Default = true,
		Tooltip = 'auto breaks cannon when you lauch'
	})
	AutoDaveyPickaxeCheck = AutoDavey:CreateToggle({
		Name = 'Pickaxe Check',
		Default = true,
	})
	AutoDaveyAutoSwitch = AutoDavey:CreateToggle({
		Name = 'AutoSwitch Pickaxe',
		Default = false,
		Tooltip = 'switches to pickaxe when breaking thens switches back to cannon'
	})
end)

run(function()
	local KitESP
	local Notify
	local Background
	local Color = {}
	local Reference = {}
	local Folder = Instance.new('Folder')
    local currentSize = 36
	Folder.Parent = vape.gui
	
	local ESPKits = {
		alchemist = {'alchemist_ingedients', 'thorns'},
		beekeeper = {'bee', 'bee'},
		bigman = {'treeOrb', 'natures_essence_1'},
		ghost_catcher = {'ghost', 'ghost_orb'},
		metal_detector = {'hidden-metal', 'iron'},
		sheep_herder = {'SheepModel', 'purple_hay_bale'},
		sorcerer = {'alchemy_crystal', 'wild_flower'},
		star_collector = {'stars', 'crit_star'},
		black_market_trader = {'shadow_coin', 'shadow_coin'},
		miner = {'petrified-player', 'large_rock'},
		trapper = {'snap_trap', 'snap_trap'},
		mage = {'ElementTome', 'mage_spellbook'},
	}
	local NONTaggedKits = {
		necromancer = {'Gravestone', true},
		battery = {'Open', true},
	}
	local DescendantKits = {
		['farmer_cletus'] = {
			{'carrot', 'carrot_seeds'},
			{'melon', 'melon_seeds'},
			{'pumpkin', 'pumpkin_seeds'},
		},
	}

	local function isMineOnMyTeam(part)
		local teamAttr = part:GetAttribute('Team') or part:GetAttribute('TeamId') or part:GetAttribute('TeamID')
		if teamAttr then
			local myTeam = lplr:GetAttribute('Team') or lplr:GetAttribute('TeamId') or lplr:GetAttribute('TeamID')
			if myTeam and tostring(teamAttr) == tostring(myTeam) then
				return true
			end
		end
		local placedBy = part:GetAttribute('PlacedByUserId')
		if placedBy then
			local player = playersService:GetPlayerByUserId(placedBy)
			if player then
				local myTeam = lplr:GetAttribute('Team')
				if myTeam and player:GetAttribute('Team') == myTeam then
					return true
				end
			end
		end
		return false
	end

	local function getAlchemistImage(v)
		local name = v and v.Name or ''
		if name == 'Mushrooms' then
			return bedwars.getIcon({itemType = 'mushrooms'}, true)
		elseif name == 'Thorns' then
			return bedwars.getIcon({itemType = 'thorns'}, true)
		else
			return bedwars.getIcon({itemType = 'wild_flower'}, true)
		end
	end

	local function getStarImage(v)
		local parent = v and v.Parent
		if parent and parent:IsA("Model") then
			local modelName = parent.Name
			if modelName == "CritStar" or modelName:lower():find("crit") then
				return bedwars.getIcon({itemType = 'crit_star'}, true)
			elseif modelName == "VitalityStar" or modelName:lower():find("vitality") then
				return bedwars.getIcon({itemType = 'vitality_star'}, true)
			end
		end
		return bedwars.getIcon({itemType = 'crit_star'}, true)
	end

	local function Added(v, icon, non)
		if Reference[v] then return end
		if Notify.Enabled then
			vape:CreateNotification("KitESP", `New object is added {v.Name}`, 2)
		end
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = icon
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(currentSize, currentSize)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = v
		local blur = addBlur(billboard)
		blur.Visible = Background.Enabled
		local image = Instance.new('ImageLabel')
		image.Size = UDim2.fromOffset(currentSize, currentSize)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
		image.BorderSizePixel = 0
		if non then
			image.Image = icon
		else
			image.Image = bedwars.getIcon({itemType = icon}, true)
		end
		image.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 4)
		uicorner.Parent = image
		Reference[v] = billboard
	end

	local function AddedStar(v)
		if not v or not v.Parent then return end
		if Reference[v] then return end

		if Notify.Enabled then
			vape:CreateNotification("KitESP", `New object is added {v.Name}`, 2)
		end
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'star'
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(currentSize, currentSize)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = v
		local blur = addBlur(billboard)
		blur.Visible = Background.Enabled
		local image = Instance.new('ImageLabel')
		image.Size = UDim2.fromOffset(currentSize, currentSize)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
		image.BorderSizePixel = 0
		image.Image = getStarImage(v)
		image.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 4)
		uicorner.Parent = image
		Reference[v] = billboard
	end
	
	local currentConnections = {}
	local currentKit = nil

	local function disconnectAll()
		for _, conn in ipairs(currentConnections) do
			conn:Disconnect()
		end
		table.clear(currentConnections)
	end

	local function isRealBee(v)
		if not v then return false end

		local beeId = v:GetAttribute('BeeId')

		if beeId == nil then
			local part = v.PrimaryPart or v:FindFirstChildWhichIsA('BasePart', true)
			beeId = part and part:GetAttribute('BeeId')
		end

		return beeId ~= nil and beeId > -1
	end

	local function addKit(tag, icon)
		if tag == 'bee' then
			local beeIcon = bedwars.getIcon({itemType = 'bee'}, true)
			for _, tagName in {'bee', 'MeadowBee', 'ChromaBee'} do
				local connAdded = collectionService:GetInstanceAddedSignal(tagName):Connect(function(v)
					if v:IsA("Model") and v.PrimaryPart then
						task.wait(0.1)
						if isRealBee(v) then
							Added(v.PrimaryPart, beeIcon, true)
						end
					end
				end)
				table.insert(currentConnections, connAdded)
				local connRemoved = collectionService:GetInstanceRemovedSignal(tagName):Connect(function(v)
					if v.PrimaryPart and Reference[v.PrimaryPart] then
						Reference[v.PrimaryPart]:Destroy()
						Reference[v.PrimaryPart] = nil
					end
				end)
				table.insert(currentConnections, connRemoved)
				for _, v in collectionService:GetTagged(tagName) do
					if v:IsA("Model") and v.PrimaryPart and isRealBee(v) then
						Added(v.PrimaryPart, beeIcon, true)
					end
				end
			end
			return
		end
		if tag == 'alchemist_ingedients' then
			local connAdded = collectionService:GetInstanceAddedSignal(tag):Connect(function(v)
				if v.PrimaryPart then
					task.wait(0.1)
					if Reference[v.PrimaryPart] then return end
					local billboard = Instance.new('BillboardGui')
					billboard.Parent = Folder
					billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
					billboard.Size = UDim2.fromOffset(currentSize, currentSize)
					billboard.AlwaysOnTop = true
					billboard.ClipsDescendants = false
					billboard.Adornee = v.PrimaryPart
					local blur = addBlur(billboard)
					blur.Visible = Background.Enabled
					local image = Instance.new('ImageLabel')
					image.Size = UDim2.fromOffset(currentSize, currentSize)
					image.Position = UDim2.fromScale(0.5, 0.5)
					image.AnchorPoint = Vector2.new(0.5, 0.5)
					image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
					image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
					image.BorderSizePixel = 0
					image.Image = getAlchemistImage(v)
					image.Parent = billboard
					local uicorner = Instance.new('UICorner')
					uicorner.CornerRadius = UDim.new(0, 4)
					uicorner.Parent = image
					Reference[v.PrimaryPart] = billboard
				end
			end)
			table.insert(currentConnections, connAdded)
			local connRemoved = collectionService:GetInstanceRemovedSignal(tag):Connect(function(v)
				if v.PrimaryPart and Reference[v.PrimaryPart] then
					Reference[v.PrimaryPart]:Destroy()
					Reference[v.PrimaryPart] = nil
				end
			end)
			table.insert(currentConnections, connRemoved)
			for _, v in collectionService:GetTagged(tag) do
				if v.PrimaryPart and not Reference[v.PrimaryPart] then
					local billboard = Instance.new('BillboardGui')
					billboard.Parent = Folder
					billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
					billboard.Size = UDim2.fromOffset(currentSize, currentSize)
					billboard.AlwaysOnTop = true
					billboard.ClipsDescendants = false
					billboard.Adornee = v.PrimaryPart
					local blur = addBlur(billboard)
					blur.Visible = Background.Enabled
					local image = Instance.new('ImageLabel')
					image.Size = UDim2.fromOffset(currentSize, currentSize)
					image.Position = UDim2.fromScale(0.5, 0.5)
					image.AnchorPoint = Vector2.new(0.5, 0.5)
					image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
					image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
					image.BorderSizePixel = 0
					image.Image = getAlchemistImage(v)
					image.Parent = billboard
					local uicorner = Instance.new('UICorner')
					uicorner.CornerRadius = UDim.new(0, 4)
					uicorner.Parent = image
					Reference[v.PrimaryPart] = billboard
				end
			end
			return
		end
		if tag == 'stars' then
			local connAdded = collectionService:GetInstanceAddedSignal(tag):Connect(function(v)
				if v:IsA("Model") and v.PrimaryPart then
					task.wait(0.1)
					AddedStar(v.PrimaryPart)
				end
			end)
			table.insert(currentConnections, connAdded)
			local connRemoved = collectionService:GetInstanceRemovedSignal(tag):Connect(function(v)
				if v.PrimaryPart and Reference[v.PrimaryPart] then
					Reference[v.PrimaryPart]:Destroy()
					Reference[v.PrimaryPart] = nil
				end
			end)
			table.insert(currentConnections, connRemoved)
			for _, v in collectionService:GetTagged(tag) do
				if v:IsA("Model") and v.PrimaryPart then
					AddedStar(v.PrimaryPart)
				end
			end
			return
		end

		if tag == 'petrified-player' then
			local connAdded = collectionService:GetInstanceAddedSignal(tag):Connect(function(v)
				if v.PrimaryPart and not isMineOnMyTeam(v.PrimaryPart) then
					Added(v.PrimaryPart, icon, false)
				end
			end)
			table.insert(currentConnections, connAdded)
			local connRemoved = collectionService:GetInstanceRemovedSignal(tag):Connect(function(v)
				if v.PrimaryPart and Reference[v.PrimaryPart] then
					Reference[v.PrimaryPart]:Destroy()
					Reference[v.PrimaryPart] = nil
				end
			end)
			table.insert(currentConnections, connRemoved)
			for _, v in collectionService:GetTagged(tag) do
				if v.PrimaryPart and not isMineOnMyTeam(v.PrimaryPart) then
					Added(v.PrimaryPart, icon, false)
				end
			end
			return
		end

		local connAdded = collectionService:GetInstanceAddedSignal(tag):Connect(function(v)
			if tag == 'bee' and (v.Name:find('TamedBee') or v:FindFirstChild('TamedBee')) then return end
			Added(v.PrimaryPart, icon, false)
		end)
		table.insert(currentConnections, connAdded)
		local connRemoved = collectionService:GetInstanceRemovedSignal(tag):Connect(function(v)
			if Reference[v.PrimaryPart] then
				Reference[v.PrimaryPart]:Destroy()
				Reference[v.PrimaryPart] = nil
			end
		end)
		table.insert(currentConnections, connRemoved)
		for _, v in collectionService:GetTagged(tag) do
			if tag == 'bee' and (v.Name:find('TamedBee') or v:FindFirstChild('TamedBee')) then continue end
			Added(v.PrimaryPart, icon, false)
		end
	end

	local function addKitNon(objName, icon)
		if typeof(icon) == "boolean" then
			if objName == "Gravestone" then
				icon = "rbxassetid://6307844310"
			elseif objName == "Open" then
				icon = "rbxassetid://10159166528"
			else
				icon = bedwars.getIcon({itemType = icon}, true) or ''
			end
		else
			icon = bedwars.getIcon({itemType = icon}, true)
		end
		local connAdded = workspace.ChildAdded:Connect(function(child)
			if child:IsA("Model") and child.Name == objName then
				task.wait(0.1)
				if child.PrimaryPart then
					Added(child, icon, true)
				end
			end
		end)
		table.insert(currentConnections, connAdded)
		local connRemoved = workspace.ChildRemoved:Connect(function(child)
			if child:IsA("Model") and child.Name == objName then
				if Reference[child] then
					Reference[child]:Destroy()
					Reference[child] = nil
				end
			end
		end)
		table.insert(currentConnections, connRemoved)
	end

	local function addKitDescendant(partName, icon)
		local resolvedIcon = bedwars.getIcon({itemType = icon}, true)
		
		local function shouldSkip(obj)
			local p = obj.Parent
			while p and p ~= workspace do
				if p.Name == partName then return true end
				p = p.Parent
			end
			return false
		end

		scanDescendants(workspace, function(obj)
			if obj:IsA("BasePart") and obj.Name == partName and not shouldSkip(obj) then
				if not Reference[obj] then
					Added(obj, resolvedIcon, true)
				end
			end
		end)
		local connAdded = workspace.DescendantAdded:Connect(function(obj)
			if obj:IsA("BasePart") and obj.Name == partName and not shouldSkip(obj) then
				task.wait(0.1)
				if not Reference[obj] then
					Added(obj, resolvedIcon, true)
				end
			end
		end)
		table.insert(currentConnections, connAdded)
		local connRemoved = workspace.DescendantRemoving:Connect(function(obj)
			if obj:IsA("BasePart") and obj.Name == partName and Reference[obj] then
				Reference[obj]:Destroy()
				Reference[obj] = nil
			end
		end)
		table.insert(currentConnections, connRemoved)
	end

	local function setupKit(kitName)
		local kit = ESPKits[kitName]
		local nontag = NONTaggedKits[kitName]
		local desctag = DescendantKits[kitName]
		if kit then
			addKit(kit[1], kit[2])
		end
		if nontag then
			addKitNon(nontag[1], nontag[2])
		end
		if desctag then
			for _, entry in ipairs(desctag) do
				addKitDescendant(entry[1], entry[2])
			end
		end
	end

	KitESP = vape.Categories.Kits:CreateModule({
		Name = 'KitESP',
		Function = function(callback)
			if callback then
				task.spawn(function()
					while KitESP.Enabled do
						if not currentKit then
							repeat
								task.wait()
							until store.equippedKit ~= '' or not KitESP.Enabled
							if not KitESP.Enabled then break end
						end
						local newKit = table.concat(getLocalKits(), ',')
						if newKit ~= currentKit then
							disconnectAll()
							Folder:ClearAllChildren()
							table.clear(Reference)
							for _, kit in ipairs(getLocalKits()) do
								setupKit(kit)
							end
							currentKit = newKit
						end
						task.wait(1)
					end
					disconnectAll()
					Folder:ClearAllChildren()
					table.clear(Reference)
					currentKit = nil
				end)
			else
				disconnectAll()
				Folder:ClearAllChildren()
				table.clear(Reference)
				currentKit = nil
			end
		end,
		Tooltip = 'esp for kits'
	})
	Notify = KitESP:CreateToggle({
		Name = "Notify",
		Default = false
	})
	Background = KitESP:CreateToggle({
		Name = 'Background',
		Function = function(callback)
			if Color.Object then Color.Object.Visible = callback end
			for _, v in Reference do
				v.ImageLabel.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
				v.Blur.Visible = callback
			end
		end,
		Default = true
	})
    Color = KitESP:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for _, v in Reference do
                v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
                v.ImageLabel.BackgroundTransparency = 1 - opacity
            end
        end,
        Darker = true
    })
    Sizeable = KitESP:CreateToggle({
        Name = "Sizeable",
        Default = false,
        Function = function(callback)
            if callback then
                SizeSlider.Object.Visible = true
                currentSize = SizeSlider.Value or 36
                for _, v in Reference do
                    v.Size = UDim2.fromOffset(currentSize, currentSize)
                    v.ImageLabel.Size = UDim2.fromOffset(currentSize, currentSize)
                end
            else
                SizeSlider.Object.Visible = false
                currentSize = 36
                for _, v in Reference do
                    v.Size = UDim2.fromOffset(currentSize, currentSize)
                    v.ImageLabel.Size = UDim2.fromOffset(currentSize, currentSize)
                end
            end
        end
    })
    SizeSlider = KitESP:CreateSlider({
        Name = "Size",
        Default = 36,
        Min = 10,
        Max = 80,
        Visible = false,
        Function = function(value)
            if not Sizeable.Enabled then return end
            currentSize = value
            for _, v in Reference do
                v.Size = UDim2.fromOffset(value, value)
                v.ImageLabel.Size = UDim2.fromOffset(value, value)
            end
        end
    })

    task.defer(function()
        if Color and Color.Object then
            Color.Object.Visible = Background.Enabled  
        end
    end)
end)

run(function()
	local AutoCyber
	local DropMode
	local Collect
	local Target
	local Limit

	local genItems = {'emerald', 'diamond'}

	local teamCache, cacheExpire = nil, 0
	local function getTeamGenerator()
		if cacheExpire > tick() and teamCache and teamCache.Parent then
			return teamCache
		end
		teamCache, cacheExpire = collectionService:GetTagged(lplr:GetAttribute('Team') .. '_TeamOreGenerator')[1], tick() + 5
		return teamCache
	end

	local cache = nil
	local function getDrone()
		if Limit.Enabled and (not store.hand.tool or store.hand.tool.Name ~= 'drone') then
			return nil
		end
		if cache and cache.Parent then
			return cache
		end
		for _, v in collectionService:GetTagged('Drone') do
			if v:GetAttribute('PlayerUserId') == lplr.UserId then
				local Changed = function()
					if v:GetAttribute('HeldItem') then
						repeat
							bedwars.Handler:Get('DropDroneItem'):Fire('SendToServer', {
								direction = Vector3.new(1000, 10, 0),
								position = v.PrimaryPart.Position
							})
							task.wait(0.1)
						until not v:GetAttribute('HeldItem') or not AutoCyber.Enabled
					end
				end
				AutoCyber:Clean(v:GetAttributeChangedSignal('HeldItem'):Connect(Changed))
				AutoCyber:Clean(v:GetAttributeChangedSignal('HeldItemAmount'):Connect(Changed))
				cache = v
				return v
			end
		end
		if getItem('drone') and bedwars.Handler:Get('FireGuidedProjectile'):Fire('CallServer', 'drone') then
			task.wait(0.1)
			return getDrone()
		end
		return nil
	end

	local function getGenerator(drone, item)
		local children = collectionService:GetTagged(item .. '_OreGenerator')
		local pos = drone.PrimaryPart.Position
		table.sort(children, function(a, b)
			return (pos - a.PrimaryPart.Position).Magnitude < (pos - b.PrimaryPart.Position).Magnitude
		end)
		return children[1] and children[1].PrimaryPart or nil
	end

	local blacklist = {}
	local function getItemDrop(drone)
		local generator = getTeamGenerator()
		generator = generator and generator.PrimaryPart.Position or Vector3.zero
		local children = workspace.ItemDrops:GetChildren()
		local pos = drone.PrimaryPart.Position
		table.sort(children, function(a, b)
			return (pos - a.Position).Magnitude < (pos - b.Position).Magnitude
		end)
		local stealSplit = Collect.Value == 'Steal Split'
		local genOnly = Collect.Value == 'Generator'
		for _, v in children do
			local passesType = true
			if genOnly and not table.find(genItems, v.Name) then
				passesType = false
			end
			if tick() > (blacklist[v] or 0)
				and passesType
				and v.Position.Y > 0
				and math.abs(v.Velocity.Y) <= 0
				and (not stealSplit or (v.Position - generator).Magnitude > 20)
				and (not Target.Enabled or not entitylib.EntityPosition({
					Origin = pos,
					Range = 60,
					Part = 'RootPart',
					Players = true
				}))
			then
				return v
			end
		end
		return nil
	end

	AutoCyber = vape.Categories.Minigames:CreateModule({
		Name = 'AutoCyber',
		Function = function(callback)
			if callback then
				AutoCyber:Clean(workspace.ItemDrops.ChildAdded:Connect(function(v)
					task.wait()
					if v.Velocity.X > 100 then
						blacklist[v] = tick() + 5
						local Amount = v:GetAttribute('Amount')
						local LastParent = v.Parent
						if DropMode.Value == 'Player' then
							notif('AutoCyber', 'Collecting ' .. tostring(Amount) .. ' ' .. v.Name, 4, 'info')
							repeat
								v.Velocity = Vector3.zero
								v.CFrame = entitylib.character.RootPart.CFrame - Vector3.new(0, 4, 0)
								task.spawn(function()
									bedwars.Handler:Get('PickupItemDrop'):Fire('CallServerAsync', {
										itemDrop = v
									}):andThen(function(suc)
										if suc and bedwars.SoundList then
											bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP)
											local sound = bedwars.ItemMeta[v.Name].pickUpOverlaySound
											if sound then
												bedwars.AudioManager:playAudio(sound, {
													position = v.Position,
													volumeMultiplier = 0.9
												})
											end
										end
									end)
								end)
								task.wait(0.02)
							until not v or v.Parent ~= LastParent

							notif('AutoCyber', `Collected {Amount} {v.Name}{Amount > 1 and 's' or ''}`, 4, 'info')
						else
							local start = tick()
							local generator = getTeamGenerator()
							if generator then
								repeat
									v.Velocity = Vector3.zero
									v.CFrame = generator.PrimaryPart.CFrame
									task.wait()
								until (tick() - start) >= 1 or not v or v.Parent ~= LastParent
								notif('AutoCyber', 'Dropped ' .. tostring(Amount) .. ' ' .. v.Name, 8, 'info')
							else
								notif('AutoCyber', 'Base generator not found', 20, 'alert')
							end
						end
					end
				end))

				repeat
					local drone = getDrone()
					if drone then
						local v = getItemDrop(drone)
						if v then
							task.wait(0.3)
							drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
							drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.CFrame.X, 10000, drone.PrimaryPart.CFrame.Z)
							local magnitude, lastmag = 0, 9e9
							local pos = v.Position
							repeat
								if drone and drone.Parent then
									pos = v.Position
									drone.PrimaryPart.CanCollide = false
									drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
									drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(drone.PrimaryPart.Position * Vector3.new(1, 0, 1), pos * Vector3.new(1, 0, 1)).LookVector * 30
									magnitude = ((drone.PrimaryPart.Position * Vector3.new(1, 0, 1)) - (pos * Vector3.new(1, 0, 1))).Magnitude
								else
									break
								end
								task.wait()
							until not v or v.Parent ~= workspace.ItemDrops or not AutoCyber.Enabled or magnitude <= 2
							if not AutoCyber.Enabled then
								break
							end

							if magnitude <= 5 then
								local start = tick()
								repeat
									if drone and drone.Parent then
										drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
										drone.PrimaryPart.AssemblyAngularVelocity = Vector3.new(0, -30, 0)
										drone.PrimaryPart.CFrame = CFrame.new(pos - Vector3.new(0, drone.Hitbox.Size.Y, 0))
									end
									task.wait(0.02)
								until (tick() - start) >= 1.25
							end
						else
							drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.CFrame.X, 10000, drone.PrimaryPart.CFrame.Z)
							drone.PrimaryPart.Velocity = Vector3.zero
							if Collect.Value == 'Generator' then
								for _, v2 in genItems do
									local gen = getGenerator(drone, v2)
									if gen then
										local magnitude = 0
										repeat
											if drone and drone.Parent then
												if getItemDrop(drone) then break end
												drone.PrimaryPart.CanCollide = false
												drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
												drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(drone.PrimaryPart.Position * Vector3.new(1, 0, 1), gen.Position * Vector3.new(1, 0, 1)).LookVector * 30
												magnitude = ((drone.PrimaryPart.Position * Vector3.new(1, 0, 1)) - (gen.Position * Vector3.new(1, 0, 1))).Magnitude
											else
												break
											end
											task.wait()
										until not v or v.Parent ~= workspace.ItemDrops or not AutoCyber.Enabled or magnitude <= 5
									end
								end
							end
						end
					end
					task.wait()
				until not AutoCyber.Enabled
			else
				local drone = getDrone()
				if drone then
					drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.CFrame.X, 500, drone.PrimaryPart.CFrame.Z)
				end
			end
		end,
		Tooltip = 'uses ur drone to grab loot n bring it back gng'
	})

	DropMode = AutoCyber:CreateDropdown({
		Name = 'Drop mode',
		List = {'Player', 'Base'},
		Default = 'Player',
		Tooltip = 'where the drone drops the loot it grabs'
	})

	Collect = AutoCyber:CreateDropdown({
		Name = 'Collect',
		List = {'Generator', 'Closest', 'Steal Split'},
		Default = 'Closest',
		Tooltip = 'Generator = only diamond n emerald gens, Closest = grabs whatevers closest, Steal Split = jacks the loot off the gen'
	})

	Target = AutoCyber:CreateToggle({Name = 'Target check'})
	Limit = AutoCyber:CreateToggle({Name = 'Limit to item'})
end)

run(function()
	local AutoShoot
	local ShootTargets
	local ShootList
	local ShootRange
	local SwitchDelay
	local ShootDelay
	local busy = false
	local readyAt = {}

	local function getControllers()
		return (bedwars.KnitClient and bedwars.KnitClient.Controllers) or (bedwars.Knit and bedwars.Knit.Controllers) or {}
	end

	local function findSourceController(handItem)
		for _, ctrl in getControllers() do
			if type(ctrl) == 'table' and type(ctrl.beginHolding) == 'function' and type(ctrl.releaseChargeInput) == 'function' and type(ctrl.isRelevantItem) == 'function' then
				local ok, relevant = pcall(ctrl.isRelevantItem, ctrl, handItem)
				if ok and relevant then
					return ctrl
				end
			end
		end
	end

	local function projectileName(item)
		local meta = bedwars.ItemMeta[item.itemType]
		local source = meta and meta.projectileSource
		if not source or type(source.projectileType) ~= 'function' then return nil end
		local ammo
		if source.ammoItemTypes then
			for _, ammoType in source.ammoItemTypes do
				for _, inv in store.inventory.inventory.items do
					if inv.itemType == ammoType then
						ammo = ammoType
						break
					end
				end
				if ammo then break end
			end
			if not ammo then return nil end
		end
		local ok, name = pcall(source.projectileType, ammo or item.itemType)
		return ok and name or nil, source
	end

	local function allowed(name)
		for _, entry in (ShootList.ListEnabled or ShootList.List or {}) do
			if entry ~= '' and name:lower():find(entry:lower(), 1, true) then
				return true
			end
		end
		return false
	end

	local function findProjectileSlot()
		for i, slot in (store.inventory.hotbar or {}) do
			local item = slot and slot.item
			if item and item.itemType and item.tool and tick() >= (readyAt[item.itemType] or 0) then
				local name, source = projectileName(item)
				if name and allowed(name) then
					return i - 1, item, source
				end
			end
		end
	end

	local function selectSlot(slot)
		if store.inventory.hotbarSlot == slot then return true end
		bedwars.Store:dispatch({
			type = 'InventorySelectHotbarSlot',
			slot = slot
		})
		local start = tick()
		repeat
			task.wait()
		until store.inventory.hotbarSlot == slot or tick() - start > 0.4
		return store.inventory.hotbarSlot == slot
	end

	local function shoot()
		local slot, item, source = findProjectileSlot()
		if not slot then return end
		busy = true
		store.autoShooting = true
		local previous = store.inventory.hotbarSlot
		local ok = pcall(function()
			if not selectSlot(slot) then return end
			local start = tick()
			local hand
			repeat
				task.wait()
				hand = store.hand
			until (hand and hand.tool == item.tool) or tick() - start > 0.5
			local ctrl = findSourceController(item)
			if not ctrl then return end
			ctrl:beginHolding(item, nil, ctrl.aimingMaid, false)
			task.wait(ShootDelay.Value)
			if AutoShoot.Enabled and store.inventory.hotbarSlot == slot then
				ctrl:releaseChargeInput(ctrl.aimingMaid, function()
					return true
				end, nil)
				readyAt[item.itemType] = tick() + (tonumber(source and source.fireDelaySec) or 0.5) + 0.05
			end
			task.wait(SwitchDelay.Value)
		end)
		if previous and store.inventory.hotbarSlot ~= previous then
			pcall(selectSlot, previous)
		end
		store.autoShooting = false
		busy = false
		return ok
	end

	AutoShoot = vape.Categories.Blatant:CreateModule({
		Name = 'AutoShoot',
		Function = function(callback)
			if callback then
				repeat
					if not busy and entitylib.isAlive then
						local target = entitylib.EntityPosition({
							Range = ShootRange.Value,
							Part = 'RootPart',
							Wallcheck = ShootTargets.Walls.Enabled or nil,
							Players = ShootTargets.Players.Enabled,
							NPCs = ShootTargets.NPCs.Enabled
						})
						if target then
							task.spawn(shoot)
						end
					end
					task.wait(0.05)
				until not AutoShoot.Enabled
			else
				store.autoShooting = false
			end
		end,
		Tooltip = 'switches to ur bow and shoots for u when someone is in range, works on mobile too'
	})
	ShootTargets = AutoShoot:CreateTargets({
		Players = true,
		NPCs = false
	})
	ShootList = AutoShoot:CreateTextList({
		Name = 'Projectiles',
		Default = {'arrow'},
		Placeholder = 'projectile name'
	})
	ShootRange = AutoShoot:CreateSlider({
		Name = 'Range',
		Min = 5,
		Max = 100,
		Default = 50,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	SwitchDelay = AutoShoot:CreateSlider({
		Name = 'Switch delay',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's',
		Tooltip = 'how long it waits after shooting before switching back'
	})
	ShootDelay = AutoShoot:CreateSlider({
		Name = 'Shoot delay',
		Min = 0,
		Max = 2,
		Default = 0.4,
		Decimal = 100,
		Suffix = 's',
		Tooltip = 'how long it waits after switching before shooting (higher = more charge)'
	})
end)

run(function()
    local sillybed
    sillybed = vape.Categories.Minigames:CreateModule({
        Name = 'bed godmode',
        Function = function(callback)
            if callback then
                task.spawn(function()
                    for _, bed in collectionService:GetTagged('bed') do
                        if bed:GetAttribute("TeamId") == lplr:GetAttribute('Team') then
                            local normalpos = (bed:GetAttribute("BlockPosition")) * 3
                            bedwars.Client:Get("RequestPlaceSpiritGardenerFlower"):CallServer(normalpos, "tearbloom_seed")
                            local tung = fetchBedfromPos(bed:GetAttribute("BlockPosition"))
                            bedwars.Client:Get("RequestPlaceSpiritGardenerFlower"):CallServer(tung * 3, "soulvine_seed")
                        end
                    end
                end)
                sillybed:Toggle()
            end
        end,
        Tooltip = 'godmode with bed -- made by crobo'
    })
end)


run(function()
	local AutoKit
	local Legit
	local Targets
	local Toggles = {}
	local Running = {}
	local netFolder, abilityRemote

	local function getNet(name)
		if not netFolder then
			pcall(function()
				netFolder = replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged
			end)
		end
		return netFolder and netFolder:FindFirstChild(name)
	end

	local function useAbility(name, data)
		if not abilityRemote then
			pcall(function()
				abilityRemote = replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility
			end)
		end
		if abilityRemote then
			pcall(function()
				if data ~= nil then
					abilityRemote:FireServer(name, data)
				else
					abilityRemote:FireServer(name)
				end
			end)
		end
	end

	local function range(legit, blatant)
		return Legit.Enabled and legit or blatant
	end

	local function NewSession()
		local Session = {Tasks = {}, Active = true}

		function Session:Clean(Task)
			table.insert(self.Tasks, Task)
			return Task
		end

		function Session:Stop()
			self.Active = false
			if self.Thread and coroutine.status(self.Thread) ~= 'dead' then
				pcall(task.cancel, self.Thread)
			end
			for i = #self.Tasks, 1, -1 do
				local Task = self.Tasks[i]
				pcall(function()
					if type(Task) == 'function' then
						Task()
					elseif typeof(Task) == 'RBXScriptConnection' then
						Task:Disconnect()
					elseif typeof(Task) == 'Instance' then
						Task:Destroy()
					elseif type(Task) == 'table' then
						if Task.Disconnect then Task:Disconnect() elseif Task.Destroy then Task:Destroy() end
					end
				end)
			end
			table.clear(self.Tasks)
		end

		return Session
	end

	local function findTarget(dist, extra)
		if not entitylib.isAlive then return nil end
		local options = {
			Range = dist,
			Part = 'RootPart',
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled or nil,
			Sort = sortmethods.Distance
		}
		for k, v in extra or {} do
			options[k] = v
		end
		return entitylib.EntityPosition(options)
	end

	local function KitCollection(Session, Tag, Range, Callback)
		local Objects = type(Tag) == 'table' and Tag or collection(Tag, Session)
		repeat
			if entitylib.isAlive then
				local here = entitylib.character.RootPart.Position
				for _, v in Objects do
					if not Session.Active then break end
					local part = typeof(v) == 'Instance' and (v:IsA('BasePart') and v or (v:IsA('Model') and (v.PrimaryPart or v:FindFirstChildWhichIsA('BasePart', true))))
					if part and part.Parent and (part.Position - here).Magnitude <= Range() then
						pcall(Callback, v, part)
					end
				end
			end
			task.wait(0.1)
		until not Session.Active
	end

	local function sameTeam(plr)
		local mine, theirs = lplr:GetAttribute('Team'), plr:GetAttribute('Team')
		if mine ~= nil and theirs ~= nil then
			return mine == theirs
		end
		return lplr.Team ~= nil and plr.Team == lplr.Team
	end

	local AutoKitFunctions = {
		trapper = function(Session)
			local traps = setmetatable({}, {__mode = 'k'})
			local nextBoom = 0
			local function isExplosive(trap)
				local kind = tostring(trap:GetAttribute('trapType') or trap:GetAttribute('TrapType') or trap:GetAttribute('Type') or ''):lower()
				return kind:find('explosive', 1, true) or trap.Name:lower():find('explosive', 1, true) or trap:FindFirstChild('explosive_trap', true)
			end
			local function isMine(trap)
				local owner = tonumber(trap:GetAttribute('PlacedByUserId') or trap:GetAttribute('OwnerUserId') or trap:GetAttribute('PlayerUserId') or trap:GetAttribute('ownerId'))
				if owner then return owner == lplr.UserId end
				local team = trap:GetAttribute('TrapperTeamId') or trap:GetAttribute('TeamId')
				return team ~= nil and tostring(team) == tostring(lplr:GetAttribute('Team'))
			end
			local function radiusOf(trap)
				for _, name in {'TriggerRadius', 'DetonationRadius', 'ExplosionRadius', 'ActivationRadius', 'Radius'} do
					local value = tonumber(trap:GetAttribute(name))
					if value and value > 0 then return value end
				end
				local best = 0
				for _, part in trap:GetDescendants() do
					if part:IsA('BasePart') then
						local name = part.Name:lower()
						if name:find('radius', 1, true) or name:find('range', 1, true) or name:find('circle', 1, true) or name:find('trigger', 1, true) or name:find('hitbox', 1, true) then
							best = math.max(best, math.max(part.Size.X, part.Size.Z) / 2)
						end
					end
				end
				return best > 0 and best or 8
			end
			local function track(trap)
				task.wait()
				if trap.Parent and isExplosive(trap) and isMine(trap) then
					traps[trap] = true
				end
			end
			Session:Clean(collectionService:GetInstanceAddedSignal('trapper_trap'):Connect(track))
			Session:Clean(collectionService:GetInstanceRemovedSignal('trapper_trap'):Connect(function(trap)
				traps[trap] = nil
			end))
			for _, trap in collectionService:GetTagged('trapper_trap') do
				task.spawn(track, trap)
			end
			repeat
				if tick() >= nextBoom then
					for trap in traps do
						local part = trap.Parent and (trap:IsA('BasePart') and trap or trap.PrimaryPart or trap:FindFirstChildWhichIsA('BasePart', true))
						if not part then
							traps[trap] = nil
							continue
						end
						local reach = radiusOf(trap)
						for _, plr in playersService:GetPlayers() do
							local root = plr ~= lplr and not sameTeam(plr) and plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')
							local hum = root and plr.Character:FindFirstChildOfClass('Humanoid')
							if hum and hum.Health > 0 and (root.Position - part.Position).Magnitude <= reach then
								nextBoom = tick() + 0.25
								useAbility('trapper_detonate')
								break
							end
						end
						if tick() < nextBoom then break end
					end
				end
				task.wait(0.03)
			until not Session.Active
		end,

		jellyfish = function(Session)
			local jellies = collection('jellyfish', Session, function(list, obj)
				task.delay(0, function()
					if obj:GetAttribute('PlacedByUserId') == lplr.UserId then
						table.insert(list, obj)
					end
				end)
			end)
			repeat
				if entitylib.isAlive and bedwars.AbilityController:canUseAbility('electrify_jellyfish') then
					for _, jelly in jellies do
						if jelly.PrimaryPart and findTarget(range(14, 18), {Origin = jelly.PrimaryPart.Position, Wallcheck = nil}) then
							bedwars.AbilityController:useAbility('electrify_jellyfish')
							break
						end
					end
				end
				task.wait(0.1)
			until not Session.Active
		end,

		tinker = function(Session)
			local abilityNames = {
				'hephaestus_self_repair', 'tinker_self_repair', 'hephaestus_repair', 'tinker_repair',
				'HEPHAESTUS_SELF_REPAIR', 'TINKER_SELF_REPAIR', 'HEPHAESTUS_REPAIR', 'TINKER_REPAIR',
				'self_repair', 'SELF_REPAIR', 'shield_repair', 'SHIELD_REPAIR', 'kit_repair', 'KIT_REPAIR'
			}
			local repairingUntil = 0
			local function kitShield(char)
				local best = 0
				for name, value in char:GetAttributes() do
					if name:find('Shield') and type(value) == 'number' and value > best and name ~= 'Shield_POTION' and name ~= 'TotalShield' then
						best = value
					end
				end
				return best
			end
			local function repair()
				local names = table.clone(abilityNames)
				for _, obj in {lplr.Character, lplr} do
					if obj then
						for _, value in obj:GetAttributes() do
							if type(value) == 'string' and value:lower():find('repair') and not table.find(names, value) then
								table.insert(names, 1, value)
							end
						end
					end
				end
				for _, name in names do
					local ok, can = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, name)
					if ok and can then
						pcall(bedwars.AbilityController.useAbility, bedwars.AbilityController, name)
						return true
					end
				end
				return false
			end
			local function attackUnlocked()
				return not Legit.Enabled and tick() < repairingUntil
			end
			local oldClicking = bedwars.SwordController.isClickingTooFast
			bedwars.SwordController.isClickingTooFast = function(self, ...)
				if attackUnlocked() then
					return false
				end
				return oldClicking(self, ...)
			end
			Session:Clean(function()
				bedwars.SwordController.isClickingTooFast = oldClicking
			end)
			local function watchStun(char)
				if not char then return end
				Session:Clean(char:GetAttributeChangedSignal('StunnedUntilTime'):Connect(function()
					local value = char:GetAttribute('StunnedUntilTime')
					if attackUnlocked() and value and value > workspace:GetServerTimeNow() then
						pcall(function() char:SetAttribute('StunnedUntilTime', 0) end)
					end
				end))
			end
			watchStun(lplr.Character)
			Session:Clean(lplr.CharacterAdded:Connect(watchStun))
			local maxShield, lastRepair, wasAlive = 0, 0, false
			repeat
				task.wait(0.1)
				local char = entitylib.isAlive and lplr.Character
				if not char then
					maxShield, wasAlive = 0, false
					continue
				end
				local current = kitShield(char)
				if not wasAlive or current > maxShield then
					maxShield = current
				end
				wasAlive = true
				if maxShield > 0 and current <= maxShield * 0.5 and tick() - lastRepair >= 6 and repair() then
					lastRepair = tick()
					repairingUntil = tick() + 2
				end
			until not Session.Active
		end,

		soul_broker = function(Session)
			local linked = {}
			repeat
				local ent = findTarget(range(14, 60))
				local count = 0
				for _ in linked do count += 1 end
				if ent and ent.Character and count < 8 and not linked[ent.Character] then
					local char = ent.Character
					useAbility('soul_link')
					task.wait(0.1)
					local remote = getNet('AttemptSoulLink')
					local ok, result = pcall(function() return remote:InvokeServer(char) end)
					if ok and type(result) == 'table' and result.result then
						linked[char] = true
						Session:Clean(char.AncestryChanged:Connect(function()
							if not char.Parent then linked[char] = nil end
						end))
					end
				end
				task.wait(0.3)
			until not Session.Active
		end,

		warrior = function(Session)
			repeat
				if (lplr:GetAttribute('Grit') or 0) >= 100 and findTarget(range(14, 40)) then
					useAbility('warrior_strike')
				end
				task.wait(0.1)
			until not Session.Active
		end,

		builder = function(Session)
			local fortified = {}
			local shapes = {}
			local function pyramid(size)
				if shapes[size] then return shapes[size] end
				local list = {}
				for h = size, 0, -1 do
					for w = h, 0, -1 do
						table.insert(list, Vector3.new(w, size - h, (h + 1) - w) * 3)
						table.insert(list, Vector3.new(-w, size - h, (h + 1) - w) * 3)
						table.insert(list, Vector3.new(w, size - h, -(h - w)) * 3)
						table.insert(list, Vector3.new(-w, size - h, -(h - w)) * 3)
					end
				end
				shapes[size] = list
				return list
			end
			repeat
				local team = lplr:GetAttribute('Team')
				local bedCFrame
				for _, bed in collectionService:GetTagged('bed') do
					if team and bed.Parent and bed:GetAttribute('Team' .. team .. 'NoBreak') then
						bedCFrame = bed:IsA('BasePart') and bed.CFrame or bed:GetPivot()
						break
					end
				end
				local remote = getNet('FortifyBlock')
				if bedCFrame and remote then
					for layer = 1, 3 do
						local sent = false
						for _, offset in pyramid(layer) do
							if not Session.Active then break end
							local block, rounded = getPlacedBlock((bedCFrame * CFrame.new(offset)).Position)
							if block and block.Name ~= 'bed' and fortified[tostring(rounded)] ~= block then
								pcall(function() remote:FireServer(rounded) end)
								fortified[tostring(rounded)] = block
								sent = true
								task.wait(0.05)
							end
						end
						if sent then break end
					end
				end
				task.wait(0.1)
			until not Session.Active
		end,

		dragon_slayer = function(Session)
			local controller = bedwars.DragonSlayerController
			local oldPunch = controller and controller.playPunchAnimation
			if oldPunch then
				controller.playPunchAnimation = function(self, look)
					if Legit.Enabled then
						return oldPunch(self, look)
					end
					local Maid = debug.getupvalue(oldPunch, 1)
					local AnimUtil = debug.getupvalue(oldPunch, 2)
					local Players = debug.getupvalue(oldPunch, 3)
					local AnimType = debug.getupvalue(oldPunch, 4)
					local Run = debug.getupvalue(oldPunch, 6)
					local maid = Maid.new()
					local track = AnimUtil:playAnimation(Players.LocalPlayer, AnimType.DRAGON_SLAYER_PUNCH)
					maid:GiveTask(function()
						if track then track:Stop() end
					end)
					maid:GiveTask(Run.Heartbeat:Connect(function()
						local char = Players.LocalPlayer.Character
						if not (char and char.PrimaryPart) then
							maid:DoCleaning()
							return
						end
						char:PivotTo(CFrame.new(char:GetPrimaryPartCFrame().Position) * look)
					end))
					task.delay(0.46, function()
						maid:DoCleaning()
					end)
					return maid
				end
				Session:Clean(function()
					controller.playPunchAnimation = oldPunch
				end)
			end
			local cooldown = {}
			repeat
				local punched = false
				if entitylib.isAlive and controller and controller.dragonEmblems then
					local here = entitylib.character.RootPart.Position
					local list = {}
					for model, emblem in controller.dragonEmblems do
						if emblem.stackCount >= 3 and model.PrimaryPart and (here - model.PrimaryPart.Position).Magnitude <= range(14, 18) then
							table.insert(list, model)
						end
					end
					table.sort(list, function(a, b)
						return (here - a.PrimaryPart.Position).Magnitude < (here - b.PrimaryPart.Position).Magnitude
					end)
					for _, model in list do
						if not Session.Active then break end
						if not cooldown[model] and bedwars.AbilityController:canUseAbility('dragon_slayer_punch', {disableBlockedAbilityAlert = true}) then
							if Legit.Enabled then
								task.wait(1)
							end
							cooldown[model] = true
							task.delay(0.4, function() cooldown[model] = nil end)
							local char = lplr.Character
							if char and char.PrimaryPart and model.PrimaryPart then
								local from = char:GetPivot().Position
								local look = CFrame.new(from, model.PrimaryPart.Position * Vector3.new(1, 0, 1) + Vector3.new(0, from.Y, 0))
								char:PivotTo(look)
								pcall(function() controller:playPunchAnimation(look - look.Position) end)
								useAbility('dragon_slayer_punch')
								punched = true
								task.wait(0.2)
							end
						end
					end
				end
				task.wait(punched and 0.15 or 0.1)
			until not Session.Active
		end,

