	local Tooltips = {
		jellyfish = 'legit = shocks enemies 14 studs from ur jelly, off = 18 studs',
		tinker = 'repairs ur shield at 50%, legit = just repairs, off = also lets u attack while repairing',
		soul_broker = 'legit = links enemies within 14 studs, off = 60 studs',
		warrior = 'legit = strikes enemies within 14 studs, off = 40 studs',
		dragon_slayer = 'legit = punches within 14 studs with a delay and normal slow, off = 18 studs, no delay, no slow',
		spirit_gardener = 'legit = waters flowers within 14 studs with normal slow, off = 20 studs with no slow',
		hannah = 'legit = executes within 14 studs, off = 16 studs and skips anyone over the void',
		mimic = 'legit = pickpockets within 14 studs, off = 18 studs',
		spirit_assassin = 'legit = uses spirits within 14 studs, off = 150 studs',
		void_dragon = 'legit = breathes on enemies within 14 studs with normal flying, off = 60 studs with fast fly',
		cactus = 'legit = shoots enemies within 14 studs, off = 40 studs',
		mage = 'legit = learns tomes within 14 studs, off = 30 studs',
		warlock = 'legit = links enemies within 10 studs, off = 20 studs',
		drill = 'legit = ur drill shoots enemies within 14 studs, off = 18 studs',
		ghost_catcher = 'legit = catches ghosts within 14 studs with ur vacuum out, off = 30 studs any time',
		miner = 'legit = frees petrified players within 6 studs, off = 10 studs',
		dragon_sword = 'legit = fires at enemies within 14 studs, off = 18 studs',
		ice_queen = 'legit = freezes enemies within 14 studs, off = 60 studs',
		necromancer = 'legit = raises gravestones within 12 studs, off = 40 studs',
		midnight = 'legit = uses nyx with enemies within 14 studs, off = 40 studs',
		jailor = 'legit = grabs souls within 14 studs, off = 40 studs',
		grim_reaper = 'legit = eats souls within 14 studs, off = 150 studs',
		gun_blade = 'legit = shoots enemies within 10 studs, off = 40 studs',
		sheep_herder = 'legit = tames sheep within 14 studs, off = any distance'
	}

	local function StopKits()
		for Kit, Session in Running do
			Running[Kit] = nil
			Session:Stop()
		end
	end

	local function EquippedKits()
		if type(store.equippedKits) == 'table' and #store.equippedKits > 0 then
			return store.equippedKits
		end
		return {store.equippedKit}
	end

	local function SyncKits()
		local Kits = EquippedKits()
		for Kit, Session in Running do
			if not table.find(Kits, Kit) or not Toggles[Kit].Enabled then
				Running[Kit] = nil
				Session:Stop()
			end
		end
		for _, Kit in Kits do
			if AutoKitFunctions[Kit] and Toggles[Kit] and Toggles[Kit].Enabled and not Running[Kit] then
				local Session = NewSession()
				Running[Kit] = Session
				Session.Thread = task.spawn(function()
					local ok, err = pcall(AutoKitFunctions[Kit], Session)
					if not ok then
						warn('[elevate] autokit ' .. Kit .. ': ' .. tostring(err))
					end
				end)
			end
		end
	end

	AutoKit = vape.Categories.Kits:CreateModule({
		Name = 'AutoKit',
		Function = function(Callback)
			if Callback then
				AutoKit:Clean(StopKits)
				repeat
					if store.matchState ~= 0 then
						SyncKits()
					end
					task.wait(0.5)
				until not AutoKit.Enabled
			else
				StopKits()
			end
		end,
		Tooltip = 'uses ur kit for u, works for every kit below when u have it equipped'
	})
	Legit = AutoKit:CreateToggle({
		Name = 'Legit',
		Default = true,
		Tooltip = 'keeps every kit at a normal range (6-14 studs), turn it off for full range and the blatant extras'
	})
	Targets = AutoKit:CreateTargets({
		Players = true,
		NPCs = true
	})

	local function KitName(Kit)
		local Meta = bedwars.BedwarsKitMeta[Kit]
		return Meta and Meta.name or Kit
	end

	local SortTable = {}
	for Kit in AutoKitFunctions do
		table.insert(SortTable, Kit)
	end
	table.sort(SortTable, function(A, B)
		return KitName(A) < KitName(B)
	end)
	for _, Kit in SortTable do
		Toggles[Kit] = AutoKit:CreateToggle({
			Name = KitName(Kit),
			Default = true,
			Tooltip = Tooltips[Kit],
			Function = function()
				if AutoKit.Enabled then
					SyncKits()
				end
			end
		})
	end
end)

run(function()
	local ModelChanger
	local MODEL_ID = '138151705692565'
	local template
	local clone
	local hidden = {}
	local binds = {}
	local token = 0

	local function insideTool(inst, char)
		local node = inst
		while node and node ~= char do
			if node:IsA('Tool') then return true end
			node = node.Parent
		end
		return false
	end

	local function veil(inst, char)
		if not (inst:IsA('BasePart') or inst:IsA('Decal')) then return end
		if insideTool(inst, char) then return end
		hidden[#hidden + 1] = {inst, inst.Transparency}
		inst.Transparency = 1
	end

	local function restore()
		for i = #hidden, 1, -1 do
			local entry = hidden[i]
			if entry[1].Parent then
				pcall(function() entry[1].Transparency = entry[2] end)
			end
			hidden[i] = nil
		end
	end

	local function clear()
		token = token + 1
		for i = #binds, 1, -1 do
			pcall(function() binds[i]:Disconnect() end)
			binds[i] = nil
		end
		if clone then
			pcall(function() clone:Destroy() end)
			clone = nil
		end
		restore()
	end

	local function getTemplate()
		if template then return template end
		local ok, objs = pcall(function()
			return game:GetObjects('rbxassetid://' .. MODEL_ID)
		end)
		if not ok or type(objs) ~= 'table' or not objs[1] then return end
		local root = objs[1]
		if not root:IsA('Model') then
			local holder = Instance.new('Model')
			root.Parent = holder
			root = holder
		end
		local hasPart = false
		for _, obj in root:GetDescendants() do
			if obj:IsA('LuaSourceContainer') or obj:IsA('Humanoid') or obj:IsA('JointInstance')
				or obj:IsA('Constraint') or obj:IsA('BodyMover') then
				pcall(function() obj:Destroy() end)
			elseif obj:IsA('BasePart') then
				hasPart = true
				obj.Anchored = true
				obj.CanCollide = false
				obj.CanQuery = false
				obj.CanTouch = false
				obj.Massless = true
				obj.CastShadow = false
				obj.Locked = true
			end
		end
		if not hasPart then
			pcall(function() root:Destroy() end)
			return
		end
		template = root
		return root
	end

	local function charHeight(char)
		local top, bottom = -math.huge, math.huge
		for _, part in char:GetChildren() do
			if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' then
				top = math.max(top, part.Position.Y + part.Size.Y / 2)
				bottom = math.min(bottom, part.Position.Y - part.Size.Y / 2)
			end
		end
		if top == -math.huge then return 5 end
		return top - bottom
	end

	local function build(char)
		clear()
		local mine = token
		task.spawn(function()
			local hrp = char:WaitForChild('HumanoidRootPart', 10)
			local hum = char:WaitForChild('Humanoid', 10)
			if not (hrp and hum) then return end
			local tpl = getTemplate()
			if not tpl or mine ~= token or not ModelChanger.Enabled or lplr.Character ~= char then return end

			local model = tpl:Clone()
			local rawSize = model:GetExtentsSize()
			local height = charHeight(char)
			if rawSize.Y > 0.05 and height > 0.05 then
				pcall(function() model:ScaleTo(height / rawSize.Y) end)
			end
			local box, size = model:GetBoundingBox()
			local pivotFix = (model:GetPivot():Inverse() * box):Inverse()
			local yOffset = size.Y * 0.5 - hrp.Size.Y * 0.5 - hum.HipHeight

			for _, obj in char:GetDescendants() do
				veil(obj, char)
			end
			binds[#binds + 1] = char.DescendantAdded:Connect(function(obj)
				if ModelChanger.Enabled then veil(obj, char) end
			end)

			model.Name = 'NightFakeModel'
			model.Parent = workspace.CurrentCamera or workspace
			clone = model

			local last
			binds[#binds + 1] = runService.RenderStepped:Connect(function()
				if not model.Parent then return end
				local root = char:FindFirstChild('HumanoidRootPart')
				if not root then return end
				local cf = root.CFrame
				if last == cf then return end
				last = cf
				local look, pos = cf.LookVector, cf.Position
				model:PivotTo(CFrame.new(pos.X, pos.Y + yOffset, pos.Z)
					* CFrame.fromEulerAnglesYXZ(0, math.atan2(-look.X, -look.Z), 0)
					* pivotFix)
			end)
		end)
	end

	ModelChanger = vape.Categories.Render:CreateModule({
		Name = 'ModelChanger',
		Function = function(callback)
			if callback then
				if lplr.Character then build(lplr.Character) end
				ModelChanger:Clean(lplr.CharacterAdded:Connect(function(char)
					clear()
					task.wait(1)
					if ModelChanger.Enabled then build(char) end
				end))
				ModelChanger:Clean(clear)
			else
				clear()
			end
		end,
		Tooltip = 'turns u into tung tung tung sahur, only u can see it'
	})
end)


