	}
	local names = {}
	for name in Presets do
		table.insert(names, name)
	end
	table.sort(names)

	local ours
	local stashed = {}

	local function apply(sky)
		local data = Presets[Preset.Value]
		if not data then return end
		for key, value in data do
			pcall(function()
				sky[key] = value
			end)
		end
	end

	local function stash(obj)
		if obj ~= ours and obj:IsA('Sky') then
			stashed[obj] = obj.Parent
			obj.Parent = nil
		end
	end

	Skybox = vape.Categories.Render:CreateModule({
		Name = 'Skybox',
		Function = function(callback)
			if callback then
				ours = Instance.new('Sky')
				ours.Name = 'NightSky'
				apply(ours)
				ours.Parent = lightingService
				for _, obj in lightingService:GetChildren() do
					stash(obj)
				end
				Skybox:Clean(lightingService.ChildAdded:Connect(function(obj)
					task.defer(stash, obj)
				end))
			else
				if ours then
					ours:Destroy()
					ours = nil
				end
				for obj, parent in stashed do
					if obj then obj.Parent = parent end
				end
				table.clear(stashed)
			end
		end,
		Tooltip = 'changes the skybox'
	})
	Preset = Skybox:CreateDropdown({
		Name = 'Preset',
		List = names,
		Function = function()
			if Skybox.Enabled and ours then apply(ours) end
		end
	})
end)


run(function()
	local HarvestAura
	local Range
	local Delay

	HarvestAura = vape.Categories.Kits:CreateModule({
		Name = 'HarvestAura',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive then
						local here = entitylib.character.RootPart.Position
						for _, crop in collectionService:GetTagged('crop') do
							local part = crop:IsA('BasePart') and crop or crop.PrimaryPart or crop:FindFirstChildWhichIsA('BasePart')
							if part and (part.Position - here).Magnitude <= Range.Value then
								pcall(function()
									bedwars.Client:Get(remotes.Harvest or 'CropHarvest'):SendToServer({
										blockPosition = bedwars.BlockController:getBlockPosition(part.Position)
									})
								end)
							end
						end
						for _, crop in collectionService:GetTagged('Crop') do
							local part = crop:IsA('BasePart') and crop or crop.PrimaryPart or crop:FindFirstChildWhichIsA('BasePart')
							if part and (part.Position - here).Magnitude <= Range.Value then
								pcall(function()
									local remote = bedwars.Client:Get(remotes.HarvestCrop or remotes.Harvest or 'CropHarvest')
									if remote.SendToServer then
										remote:SendToServer({blockPosition = bedwars.BlockController:getBlockPosition(part.Position)})
									elseif remote.instance then
										remote.instance:FireServer({blockPosition = bedwars.BlockController:getBlockPosition(part.Position)})
									end
								end)
							end
						end
					end
					task.wait(Delay.Value)
				until not HarvestAura.Enabled
			end
		end,
		Tooltip = 'Auto harvest nearby crops'
	})
	Range = HarvestAura:CreateSlider({Name = 'Range', Min = 5, Max = 30, Default = 16, Suffix = 'studs'})
	Delay = HarvestAura:CreateSlider({Name = 'Delay', Min = 0.1, Max = 1, Default = 0.25, Decimal = 100, Suffix = 's'})
end)


