end)


run(function()
	local InfiniteFly
	local Speed
	local Vertical
	InfiniteFly = vape.Categories.Blatant:CreateModule({
		Name = 'InfiniteFly',
		Function = function(callback)
			if callback then
				InfiniteFly:Clean(runService.Heartbeat:Connect(function(dt)
					if not entitylib.isAlive then return end
					local root = entitylib.character.RootPart
					local hum = entitylib.character.Humanoid
					if not root or not hum then return end
					local move = hum.MoveDirection
					local vy = 0
					if inputService:IsKeyDown(Enum.KeyCode.Space) then vy = Vertical.Value end
					if inputService:IsKeyDown(Enum.KeyCode.LeftControl) then vy = -Vertical.Value end
					root.AssemblyLinearVelocity = Vector3.new(move.X * Speed.Value, vy, move.Z * Speed.Value)
					root.CFrame = root.CFrame + Vector3.new(0, 0.02, 0)
				end))
			end
		end,
		Tooltip = 'Hold space/ctrl vertical, WASD fly'
	})
	Speed = InfiniteFly:CreateSlider({Name = 'Speed', Min = 10, Max = 80, Default = 40})
	Vertical = InfiniteFly:CreateSlider({Name = 'Vertical', Min = 10, Max = 60, Default = 30})
end)


