	emeraldTimer.Size = UDim2.new(1, -25, 1, 0)
	emeraldTimer.Position = UDim2.new(0, 25, 0, 0)
	emeraldTimer.Text = "00"
	emeraldTimer.TextColor3 = Color3.fromRGB(0, 255, 100)
	emeraldTimer.TextSize = 18
	emeraldTimer.Font = Enum.Font.GothamBold
	emeraldTimer.TextXAlignment = Enum.TextXAlignment.Left

	local diamondTimes = {}
	local emeraldTimes = {}

	local function getMyTeamId()
		local myTeam = lplr:GetAttribute('Team')
		if myTeam == nil then return nil end
		return tonumber(myTeam)
	end

	local function getGeneratorTeamId(generatorId)
		local teamNum = string.match(generatorId, "^(%d+)_generator")
		if teamNum then
			return tonumber(teamNum)
		end
		return nil
	end

	local function isTeamGenerator(generatorId)
		return string.match(generatorId, "^%d+_generator") ~= nil
	end

	local function getGeneratorType(generatorId)
		local idLower = string.lower(generatorId)

		if isTeamGenerator(generatorId) then
			return 'teamgen', {
				color = Color3.fromRGB(200, 200, 200),
				icon = 'iron',
				displayName = 'Team Gen',
				isTeamGen = true
			}
		end

		for genType, config in pairs(generatorTypes) do
			for _, keyword in ipairs(config.keywords) do
				if idLower:find(keyword) then
					return genType, config
				end
			end
		end
		return nil, nil
	end

	local function isGeneratorEnabled(genType, teamId)
		if genType == 'diamond' then
			return DiamondToggle.Enabled
		elseif genType == 'emerald' then
			return EmeraldToggle.Enabled
		elseif genType == 'teamgen' then
			if not TeamGenToggle.Enabled then return false end
			local myTeamId = getMyTeamId()
			if not myTeamId or not teamId then return TeamGenToggle.Enabled end
			if teamId == myTeamId then
				return ShowOwnTeamGen.Enabled
			else
				return ShowEnemyTeamGen.Enabled
			end
		end
		return false
	end

	local function getProperIcon(iconType)
		local icon = bedwars.getIcon({itemType = iconType}, true)
		if not icon or icon == "" then return nil end
		return icon
	end

	local function getTierText(generatorAdornee)
		if not generatorAdornee then return nil end
		if generatorAdornee.Name ~= 'GeneratorAdornee' then return nil end
		local reactTree = generatorAdornee:FindFirstChild('RoactTree')
		if not reactTree then return nil end
		local teamApp = reactTree:FindFirstChild('TeamOreGeneratorApp')
		if not teamApp then return nil end
		local globalGen = teamApp:FindFirstChild('GlobalOreGenerator')
		if globalGen then
			for _, child in pairs(globalGen:GetDescendants()) do
				if child:IsA('TextLabel') then
					local text = child.Text
					if text:find("Tier") or text:match("^[IVX]+$") or text == "0" then
						return child
					end
				end
			end
		end
		local teamGenMain = teamApp:FindFirstChild('TeamGenMain')
		if teamGenMain then
			for _, child in pairs(teamGenMain:GetDescendants()) do
				if child:IsA('TextLabel') then
					local text = child.Text
					if text:find("Tier") or text:match("^[IVX]+$") or text == "0" then
						return child
					end
				end
			end
		end
		return nil
	end

	local function extractTierLevel(tierText)
		if not tierText or tierText == "" then return "0" end
		if tierText == "0" then return "0" end
		local tierMatch = tierText:match("Tier%s+([IVX]+)")
		if tierMatch then return tierMatch end
		if tierText:match("^[IVX]+$") then return tierText end
		local numTier = tierText:match("Tier%s+(%d+)")
		if numTier then
			local num = tonumber(numTier)
			if num == 0 then return "0"
			elseif num == 1 then return "I"
			elseif num == 2 then return "II"
			elseif num == 3 then return "III"
			end
		end
		return "0"
	end

	local function getCountdownText(generatorAdornee)
		if not generatorAdornee then return nil end
		if generatorAdornee.Name ~= 'GeneratorAdornee' then return nil end
		local reactTree = generatorAdornee:FindFirstChild('RoactTree')
		if not reactTree then return nil end
		local teamApp = reactTree:FindFirstChild('TeamOreGeneratorApp')
		if not teamApp then return nil end
		local globalGen = teamApp:FindFirstChild('GlobalOreGenerator')
		if not globalGen then return nil end
		local countdown = globalGen:FindFirstChild('Countdown')
		if not countdown then return nil end
		local textLabel = countdown:FindFirstChild('Text')
		if not textLabel then
			if countdown:IsA('TextLabel') then return countdown end
			return nil
		end
		return textLabel
	end

	local function extractSecondsFromText(text)
		if not text or text == "" then return 0 end
		local seconds = text:match("%[(%d+)%]")
		if seconds then return tonumber(seconds) or 0 end
		local justNumber = text:match("(%d+)")
		if justNumber then return tonumber(justNumber) or 0 end
		return 0
	end

	local function getResourceCount(position, resourceType)
		local count = 0
		for _, drop in pairs(CollectionService:GetTagged('ItemDrop')) do
			if drop:FindFirstChild('Handle') then
				local dropName = drop.Name:lower()
				if dropName:find(resourceType) then
					local dist = (drop.Handle.Position - position).Magnitude
					if dist <= 10 then
						local amount = drop:GetAttribute('Amount') or 1
						count = count + amount
					end
				end
			end
		end
		return count
	end

	local CompactGenerators = {}

	local function rebuildCompactGenerators()
		table.clear(CompactGenerators)
		scanDescendants(workspace, function(obj)
			if obj.Name == 'GeneratorAdornee' then
				local ok, generatorId = pcall(function() return obj:GetAttribute('Id') end)
				if ok and generatorId and type(generatorId) == 'string' and generatorId ~= '' then
					local genType = getGeneratorType(generatorId)
					if genType == 'diamond' or genType == 'emerald' then
						table.insert(CompactGenerators, {obj = obj, genType = genType})
					end
				end
			end
		end)
	end

	local function updateCompactUI()
		if not GeneratorESP.Enabled or UIStyle.Value ~= 'Compact' then
			compactUI.Enabled = false
			return
		end
		compactUI.Enabled = true
		local bestDiamondTime = math.huge
		local bestEmeraldTime = math.huge
		for i = #CompactGenerators, 1, -1 do
			local entry = CompactGenerators[i]
			if not entry.obj or not entry.obj.Parent then
				table.remove(CompactGenerators, i)
				continue
			end
			local countdownText = getCountdownText(entry.obj)
			if countdownText and countdownText.Text then
				local timeLeft = extractSecondsFromText(countdownText.Text)
				if entry.genType == 'diamond' and timeLeft > 0 and timeLeft < bestDiamondTime then
					bestDiamondTime = timeLeft
				elseif entry.genType == 'emerald' and timeLeft > 0 and timeLeft < bestEmeraldTime then
					bestEmeraldTime = timeLeft
				end
			end
		end
		local showDiamond = CompactDiamondToggle and CompactDiamondToggle.Enabled
		local showEmerald = CompactEmeraldToggle and CompactEmeraldToggle.Enabled

		if not showDiamond and not showEmerald then
			compactUI.Enabled = false
			return
		end

		diamondFrame.Visible = showDiamond
		emeraldFrame.Visible = showEmerald

		if showDiamond then
			diamondFrame.Position = UDim2.new(0, 10, 0, 35)
		end
		if showEmerald then
			emeraldFrame.Position = UDim2.new(0, 10, 0, showDiamond and 65 or 35)
		end

		diamondTimes[1] = bestDiamondTime ~= math.huge and bestDiamondTime or 0
		emeraldTimes[1] = bestEmeraldTime ~= math.huge and bestEmeraldTime or 0
		if bestDiamondTime == math.huge then
			diamondTimer.Text = "00"
		else
			diamondTimer.Text = string.format("%02d", bestDiamondTime)
			if bestDiamondTime <= 5 then
				diamondTimer.TextColor3 = Color3.fromRGB(255, 50, 50)
			elseif bestDiamondTime <= 10 then
				diamondTimer.TextColor3 = Color3.fromRGB(255, 165, 0)
			else
				diamondTimer.TextColor3 = Color3.fromRGB(85, 200, 255)
			end
		end
		if bestEmeraldTime == math.huge then
			emeraldTimer.Text = "00"
		else
			emeraldTimer.Text = string.format("%02d", bestEmeraldTime)
			if bestEmeraldTime <= 5 then
				emeraldTimer.TextColor3 = Color3.fromRGB(255, 50, 50)
			elseif bestEmeraldTime <= 10 then
				emeraldTimer.TextColor3 = Color3.fromRGB(255, 165, 0)
			else
				emeraldTimer.TextColor3 = Color3.fromRGB(0, 255, 100)
			end
		end
	end

	local function clearAllESP()
		Folder:ClearAllChildren()
		table.clear(Reference)
		compactUI.Enabled = false
	end

	local function createESP(generatorAdornee, genType, config, position, teamId)
		if not isGeneratorEnabled(genType, teamId) then return end
		if Reference[generatorAdornee] then return end

		if UIStyle.Value == 'Compact' then
			Reference[generatorAdornee] = {
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = config.isTeamGen
			}
			return
		end
		if not generatorAdornee or not generatorAdornee.Parent then return end

		local displayColor = config.color
		local teamName = nil
		if config.isTeamGen and teamId and teamColors[teamId] then
			displayColor = teamColors[teamId].color
			teamName = teamColors[teamId].name
		end

		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'generator-esp-' .. genType
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = generatorAdornee
		billboard.Enabled = true  

		if config.isTeamGen then
			billboard.Size = UDim2.fromOffset(180, 55)
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 5, 0)
		else
			billboard.Size = UDim2.fromOffset(80, 30)
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 4, 0)
		end

		local blur = pcall(function()
			return addBlur(billboard)
		end) and blur or nil
		if blur then
			blur.Visible = true
		end

		if config.isTeamGen and teamName then
			local dot = Instance.new('Frame')
			dot.Name = 'TeamDot'
			dot.Parent = billboard
			dot.Size = UDim2.fromOffset(8, 8)
			dot.Position = UDim2.new(0, 10, 0, 5)
			dot.BackgroundColor3 = displayColor
			dot.BorderSizePixel = 0
			local dotCorner = Instance.new('UICorner')
			dotCorner.CornerRadius = UDim.new(1, 0)
			dotCorner.Parent = dot

			local teamLabel = Instance.new('TextLabel')
			teamLabel.Name = 'TeamLabel'
			teamLabel.Parent = billboard
			teamLabel.BackgroundTransparency = 1
			teamLabel.Size = UDim2.new(1, 0, 0, 18)
			teamLabel.Position = UDim2.new(0, 0, 0, 0)
			teamLabel.Text = teamName
			teamLabel.TextColor3 = displayColor
			teamLabel.TextSize = 13
			teamLabel.Font = Enum.Font.GothamBold
			teamLabel.TextStrokeTransparency = 0.4
			teamLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			teamLabel.TextXAlignment = Enum.TextXAlignment.Center
		end

		local frame = Instance.new('Frame')
		frame.Size = config.isTeamGen and UDim2.new(1, 0, 0, 35) or UDim2.fromScale(1, 1)
		frame.Position = config.isTeamGen and UDim2.new(0, 0, 0, 20) or UDim2.new(0, 0, 0, 0)
		frame.BackgroundColor3 = Color3.new(0, 0, 0)
		frame.BackgroundTransparency = 0.3
		frame.BorderSizePixel = 0
		frame.Parent = billboard

		if config.isTeamGen and teamId and teamColors[teamId] then
			local stripe = Instance.new('Frame')
			stripe.Name = 'TeamStripe'
			stripe.Parent = frame
			stripe.Size = UDim2.new(0, 3, 1, 0)
			stripe.Position = UDim2.new(0, 0, 0, 0)
			stripe.BackgroundColor3 = displayColor
			stripe.BorderSizePixel = 0
			local stripeCorner = Instance.new('UICorner')
			stripeCorner.CornerRadius = UDim.new(0, 3)
			stripeCorner.Parent = stripe
		end

		local uicorner2 = Instance.new('UICorner')
		uicorner2.CornerRadius = UDim.new(0, 6)
		uicorner2.Parent = frame

		if config.isTeamGen then
			local tierLabel = Instance.new('TextLabel')
			tierLabel.Name = 'Tier'
			tierLabel.Size = UDim2.new(0, 25, 1, 0)
			tierLabel.Position = UDim2.new(0, 8, 0, 0)
			tierLabel.BackgroundTransparency = 1
			tierLabel.Text = "0"
			tierLabel.TextColor3 = Color3.fromRGB(255, 255, 100)
			tierLabel.TextSize = 16
			tierLabel.Font = Enum.Font.GothamBold
			tierLabel.TextStrokeTransparency = 0.5
			tierLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			tierLabel.Parent = frame

			local resources = {
				{name = 'iron',    color = Color3.fromRGB(200, 200, 200), icon = 'iron',    xOffset = 35},
				{name = 'diamond', color = Color3.fromRGB(85, 200, 255),  icon = 'diamond', xOffset = 85},
				{name = 'emerald', color = Color3.fromRGB(0, 255, 100),   icon = 'emerald', xOffset = 135}
			}

			local resourceLabels = {}
			for _, resource in ipairs(resources) do
				local iconImage = getProperIcon(resource.icon)
				if iconImage then
					local image = Instance.new('ImageLabel')
					image.Size = UDim2.fromOffset(18, 18)
					image.Position = UDim2.new(0, resource.xOffset, 0.5, 0)
					image.AnchorPoint = Vector2.new(0, 0.5)
					image.BackgroundTransparency = 1
					image.Image = iconImage
					image.Parent = frame
				end
				local countLabel = Instance.new('TextLabel')
				countLabel.Name = resource.name .. '_count'
				countLabel.Size = UDim2.new(0, 25, 1, 0)
				countLabel.Position = UDim2.new(0, resource.xOffset + 20, 0, 0)
				countLabel.BackgroundTransparency = 1
				countLabel.Text = "0"
				countLabel.TextColor3 = resource.color
				countLabel.TextSize = 16
				countLabel.Font = Enum.Font.GothamBold
				countLabel.TextStrokeTransparency = 0.5
				countLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
				countLabel.TextXAlignment = Enum.TextXAlignment.Left
				countLabel.Parent = frame
				resourceLabels[resource.name] = countLabel
			end

			Reference[generatorAdornee] = {
				billboard = billboard,
				tierLabel = tierLabel,
				ironLabel = resourceLabels.iron,
				diamondLabel = resourceLabels.diamond,
				emeraldLabel = resourceLabels.emerald,
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = true
			}
		else
			local iconImage = getProperIcon(config.icon)
			if iconImage then
				local image = Instance.new('ImageLabel')
				image.Size = UDim2.fromOffset(20, 20)
				image.Position = UDim2.new(0, 5, 0.5, 0)
				image.AnchorPoint = Vector2.new(0, 0.5)
				image.BackgroundTransparency = 1
				image.Image = iconImage
				image.Parent = frame
			end
			local timerLabel = Instance.new('TextLabel')
			timerLabel.Name = 'Timer'
			timerLabel.Size = UDim2.new(0, 30, 1, 0)
			timerLabel.Position = UDim2.new(0.5, 0, 0, 0)
			timerLabel.AnchorPoint = Vector2.new(0.5, 0)
			timerLabel.BackgroundTransparency = 1
			timerLabel.Text = "00"
			timerLabel.TextColor3 = displayColor
			timerLabel.TextSize = 18
			timerLabel.Font = Enum.Font.GothamBold
			timerLabel.TextStrokeTransparency = 0.5
			timerLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			timerLabel.Parent = frame
			local amountLabel = Instance.new('TextLabel')
			amountLabel.Name = 'Amount'
			amountLabel.Size = UDim2.new(0, 20, 1, 0)
			amountLabel.Position = UDim2.new(1, -20, 0, 0)
			amountLabel.BackgroundTransparency = 1
			amountLabel.Text = "0"
			amountLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
			amountLabel.TextSize = 16
			amountLabel.Font = Enum.Font.GothamBold
			amountLabel.TextStrokeTransparency = 0.5
			amountLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			amountLabel.Parent = frame
			Reference[generatorAdornee] = {
				billboard = billboard,
				timerLabel = timerLabel,
				amountLabel = amountLabel,
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = false
			}
		end
		billboard.Enabled = true
	end

	local function updateESP(generatorAdornee)
		local ref = Reference[generatorAdornee]
		if not ref then return end
		if UIStyle.Value == 'Compact' then return end

		if ref.isTeamGen then
			if ref.tierLabel then
				local tierTextLabel = getTierText(generatorAdornee)
				if tierTextLabel and tierTextLabel.Text then
					ref.tierLabel.Text = extractTierLevel(tierTextLabel.Text)
				else
					ref.tierLabel.Text = "0"
				end
			end
			if ref.ironLabel then
				ref.ironLabel.Text = tostring(getResourceCount(ref.position, 'iron'))
			end
			if ref.diamondLabel then
				ref.diamondLabel.Text = tostring(getResourceCount(ref.position, 'diamond'))
			end
			if ref.emeraldLabel then
				ref.emeraldLabel.Text = tostring(getResourceCount(ref.position, 'emerald'))
			end
		else
			local countdownText = getCountdownText(generatorAdornee)
			if countdownText and countdownText.Text then
				local timeLeft = extractSecondsFromText(countdownText.Text)
				if ref.timerLabel then
					ref.timerLabel.Text = string.format("%02d", timeLeft)
					if timeLeft <= 5 then
						ref.timerLabel.TextColor3 = Color3.fromRGB(255, 50, 50)
					elseif timeLeft <= 10 then
						ref.timerLabel.TextColor3 = Color3.fromRGB(255, 165, 0)
					else
						ref.timerLabel.TextColor3 = generatorTypes[ref.genType].color
					end
				end
			else
				if ref.timerLabel then
					ref.timerLabel.Text = "00"
					ref.timerLabel.TextColor3 = Color3.fromRGB(150, 150, 150)
				end
			end
			if ref.amountLabel then
				ref.amountLabel.Text = tostring(getResourceCount(ref.position, ref.genType))
			end
		end
	end

	local function processGeneratorAdornee(obj)
		if obj.Name ~= 'GeneratorAdornee' then return end
		local ok, generatorId = pcall(function() return obj:GetAttribute('Id') end)
		if not ok then return end
		if generatorId == nil then return end
		if type(generatorId) ~= 'string' then return end
		if generatorId == '' then return end

		local position = obj:GetPivot().Position
		local genType, config = getGeneratorType(generatorId)
		if not genType or not config then return end

		local teamId = getGeneratorTeamId(generatorId)
		if isGeneratorEnabled(genType, teamId) then
			createESP(obj, genType, config, position, teamId)
		end
	end

	local function findAllGenerators()
		scanDescendants(workspace, function(obj)
			pcall(processGeneratorAdornee, obj)
		end)
	end

	local function refreshESP()
		clearAllESP()
		if GeneratorESP.Enabled then
			findAllGenerators()
		end
	end

	local updateTimer = 0

	GeneratorESP = vape.Categories.Render:CreateModule({
		Name = 'GeneratorESP',
		Function = function(callback)
			if callback then
				findAllGenerators()
				rebuildCompactGenerators()

				GeneratorESP:Clean(workspace.DescendantAdded:Connect(function(obj)
					if not GeneratorESP.Enabled then return end
					task.wait(0.2)
					pcall(processGeneratorAdornee, obj)
					if obj.Name == 'GeneratorAdornee' then
						rebuildCompactGenerators()
					end
				end))

				GeneratorESP:Clean(runService.Heartbeat:Connect(function(dt)
					if not GeneratorESP.Enabled then return end
					updateTimer = updateTimer + dt
					if updateTimer < 0.2 then return end
					updateTimer = 0
					for generatorAdornee, ref in pairs(Reference) do
						if generatorAdornee and generatorAdornee.Parent then
							updateESP(generatorAdornee)
						else
							if ref.billboard then ref.billboard:Destroy() end
							Reference[generatorAdornee] = nil
						end
					end
					updateCompactUI()
				end))

				GeneratorESP:Clean(workspace.DescendantRemoving:Connect(function(obj)
					if not GeneratorESP.Enabled then return end
					if Reference[obj] then
						if Reference[obj].billboard then Reference[obj].billboard:Destroy() end
						Reference[obj] = nil
					end
				end))
			else
				clearAllESP()
			end
		end,
		Tooltip = 'esp for generators showing timer and items count'
	})

	UIStyle = GeneratorESP:CreateDropdown({
		Name = 'UI Style',
		List = {'Original', 'Compact'},
		Default = 'Original',
		Function = function(val)
			local isOriginal = val == 'Original'
			if DiamondToggle then DiamondToggle.Object.Visible = isOriginal end
			if EmeraldToggle then EmeraldToggle.Object.Visible = isOriginal end
			if TeamGenToggle then TeamGenToggle.Object.Visible = isOriginal end
			if ShowOwnTeamGen then ShowOwnTeamGen.Object.Visible = isOriginal and TeamGenToggle.Enabled end
			if ShowEnemyTeamGen then ShowEnemyTeamGen.Object.Visible = isOriginal and TeamGenToggle.Enabled end
			if CompactDiamondToggle then CompactDiamondToggle.Object.Visible = not isOriginal end
			if CompactEmeraldToggle then CompactEmeraldToggle.Object.Visible = not isOriginal end
			refreshESP()
		end,
		Tooltip = 'pick between the norm billboard esp on generators or a ui with timers for generators '
	})

	DiamondToggle = GeneratorESP:CreateToggle({
		Name = 'Diamond',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	EmeraldToggle = GeneratorESP:CreateToggle({
		Name = 'Emerald',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	CompactDiamondToggle = GeneratorESP:CreateToggle({
		Name = 'Compact Diamond',
		Default = false,
		Visible = false,
		Function = function()
			refreshESP()
		end
	})

	CompactEmeraldToggle = GeneratorESP:CreateToggle({
		Name = 'Compact Emerald',
		Default = false,
		Visible = false,
		Function = function()
			refreshESP()
		end
	})

	TeamGenToggle = GeneratorESP:CreateToggle({
		Name = 'Team Generators',
		Function = function(callback)
			if ShowOwnTeamGen then ShowOwnTeamGen.Object.Visible = callback end
			if ShowEnemyTeamGen then ShowEnemyTeamGen.Object.Visible = callback end
			refreshESP()
		end,
		Default = true
	})

	ShowOwnTeamGen = GeneratorESP:CreateToggle({
		Name = 'Show Own Team',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	ShowEnemyTeamGen = GeneratorESP:CreateToggle({
		Name = 'Show Enemy Teams',
		Function = function() refreshESP() end,
		Default = true,
		Visible = true
	})
end)

run(function()
	local MouseTP
	local Mode
	local MovementMode
	local Length
	local Delay
	local rayCheck = RaycastParams.new()
	rayCheck.RespectCanCollide = true
	
	local function getWaypointInMouse()
		local obj, dist, location = nil, math.huge, inputService:GetMouseLocation()
	
		for _, v in WaypointFolder:GetChildren() do
			local position, vis = gameCamera:WorldToViewportPoint(v.StudsOffsetWorldSpace)
			if not vis then continue end
	
			local mag = (location - Vector2.new(position.x, position.y)).Magnitude
			if mag < dist then
				obj, dist = v, mag
			end
		end
	
		return obj
	end
	
	MouseTP = vape.Categories.Blatant:CreateModule({
		Name = 'MouseTP',
		Function = function(callback)
			if callback then
				local position
				if Mode.Value == 'Mouse' then
					local ray = cloneref(lplr:GetMouse()).UnitRay
					rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
					ray = workspace:Raycast(ray.Origin, ray.Direction * 10000, rayCheck)
					position = ray and ray.Position + Vector3.new(0, entitylib.character.HipHeight or 2, 0)
				elseif Mode.Value == 'Waypoint' then
					local waypoint = getWaypointInMouse()
					position = waypoint and waypoint.StudsOffsetWorldSpace
				else
					local ent = entitylib.EntityMouse({
						Range = math.huge,
						Part = 'RootPart',
						Players = true
					})
					position = ent and ent.RootPart.Position
				end
	
				if not position then
					notif('MouseTP', 'No position found.', 5)
					MouseTP:Toggle()
					return
				end
	
				if MovementMode.Value ~= 'Lerp' then
					MouseTP:Toggle()
					if entitylib.isAlive then
						if MovementMode.Value == 'Motor' then
							motorMove(entitylib.character.RootPart, CFrame.lookAlong(position, entitylib.character.RootPart.CFrame.LookVector))
						else
							entitylib.character.RootPart.CFrame = CFrame.lookAlong(position, entitylib.character.RootPart.CFrame.LookVector)
						end
					end
				else
					MouseTP:Clean(runService.Heartbeat:Connect(function()
						if entitylib.isAlive then
							entitylib.character.RootPart.Velocity = Vector3.zero
						end
					end))
	
					repeat
						if entitylib.isAlive then
							local direction = CFrame.lookAt(entitylib.character.RootPart.Position, position).LookVector * math.min((entitylib.character.RootPart.Position - position).Magnitude, Length.Value)
							entitylib.character.RootPart.CFrame += direction
							if (entitylib.character.RootPart.Position - position).Magnitude < 3 and MouseTP.Enabled then
								MouseTP:Toggle()
							end
						elseif MouseTP.Enabled then
							MouseTP:Toggle()
							notif('MouseTP', 'Character missing', 5, 'warning')
						end
	
						task.wait(Delay.Value)
					until not MouseTP.Enabled
				end
			end
		end,
		Tooltip = 'Teleports to a selected position.'
	})
	Mode = MouseTP:CreateDropdown({
		Name = 'Mode',
		List = {'Mouse', 'Player', 'Waypoint'}
	})
	MovementMode = MouseTP:CreateDropdown({
		Name = 'Movement',
		List = {'CFrame', 'Motor', 'Lerp'},
		Function = function(val)
			Length.Object.Visible = val == 'Lerp'
			Delay.Object.Visible = val == 'Lerp'
		end
	})
	Length = MouseTP:CreateSlider({
		Name = 'Length',
		Min = 0,
		Max = 22,
		Darker = true,
		Visible = false,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	Delay = MouseTP:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Decimal = 100,
		Darker = true,
		Visible = false,
		Suffix = function(val)
			return val == 1 and 'second' or 'seconds'
		end
	})
end)

run(function()
    local AutoWhimElement
    local DelaySlider
    
    AutoWhimElement = vape.Categories.Kits:CreateModule({
        Name = 'AutoWhimElement',
        Function = function(callback)
            if callback then
                local replicatedStorage = game:GetService('ReplicatedStorage')
                
                local spawnEvent
                local learnTomeRemote
                
                spawnEvent = replicatedStorage:FindFirstChild('SpawnElementTome', true)
                learnTomeRemote = replicatedStorage:FindFirstChild('LearnElementTome', true)
                
                if not learnTomeRemote then
                    vape:CreateNotification("AutoWhimElement", "LearnElementTome remote not found!", 5)
                    return
                end
                
                if not spawnEvent then
                    vape:CreateNotification("AutoWhimElement", "SpawnElementTome remote event not found!", 5)
                    return
                end
                
                -- Event-driven only: Zero workspace loops, zero lag. It only runs code when the server says a tome spawns.
                AutoWhimElement:Clean(spawnEvent.OnClientEvent:Connect(function(data)
                    if not AutoWhimElement.Enabled then return end
                    if data and data.secret then
                        task.spawn(function()
                            local success, response = pcall(function()
                                if learnTomeRemote:IsA('RemoteFunction') then
                                    return learnTomeRemote:InvokeServer({ secret = data.secret })
                                else
                                    learnTomeRemote:FireServer({ secret = data.secret })
                                    return { success = true, element = "element" }
                                end
                            end)
                            
                            if success and type(response) == "table" and response.success then
                                local elementName = response.element or "element"
                                vape:CreateNotification("AutoWhimElement", "Successfully learned element: " .. tostring(elementName), 3)
                            end
                        end)
                    end
                end))
            end
        end,
        Tooltip = 'Automatically listens to SpawnElementTome and learns elements instantly without lag.'
    })
    
    DelaySlider = AutoWhimElement:CreateSlider({
        Name = 'Delay',
        Min = 0.1,
        Max = 1,
        Default = 0.4,
        Decimal = 1,
        Suffix = function(val)
            return 'seconds'
        end,
        Tooltip = 'Delay between claiming each tome'
    })
end)

run(function()
    local ChatMover
    local ChatPosition
    local guiService = game:GetService("GuiService")
    local textChatService = game:GetService("TextChatService")

    -- Positions map based on ChatWindowConfiguration or legacy Chat Gui
    local function updateChatPosition(posName)
        -- Support for modern TextChatService (New Chat System)
        if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
            local chatWindow = textChatService:FindFirstChildOfClass("ChatWindowConfiguration")
            if chatWindow then
                if posName == "Top Left" then
                    chatWindow.HorizontalAlignment = Enum.HorizontalAlignment.Left
                    chatWindow.VerticalAlignment = Enum.VerticalAlignment.Top
                elseif posName == "Top Right" then
                    chatWindow.HorizontalAlignment = Enum.HorizontalAlignment.Right
                    chatWindow.VerticalAlignment = Enum.VerticalAlignment.Top
                elseif posName == "Bottom Left" then
                    chatWindow.HorizontalAlignment = Enum.HorizontalAlignment.Left
                    chatWindow.VerticalAlignment = Enum.VerticalAlignment.Bottom
                elseif posName == "Bottom Right" then
                    chatWindow.HorizontalAlignment = Enum.HorizontalAlignment.Right
                    chatWindow.VerticalAlignment = Enum.VerticalAlignment.Bottom
                end
            end
        else
            -- Support for Legacy Chat System
            local playerGui = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui")
            local chatGui = playerGui and playerGui:FindFirstChild("Chat")
            if chatGui and chatGui:FindFirstChild("Frame") then
                local frame = chatGui.Frame
                if posName == "Top Left" then
                    frame.Position = UDim2.new(0, 0, 0, 0)
                elseif posName == "Top Right" then
                    frame.Position = UDim2.new(1, -frame.AbsoluteSize.X, 0, 0)
                elseif posName == "Bottom Left" then
                    frame.Position = UDim2.new(0, 0, 1, -frame.AbsoluteSize.Y)
                elseif posName == "Bottom Right" then
                    frame.Position = UDim2.new(1, -frame.AbsoluteSize.X, 1, -frame.AbsoluteSize.Y)
                end
            end
        end
    end

    ChatMover = vape.Categories.Utility:CreateModule({
        Name = 'ChatMover',
        Function = function(callback)
            if callback then
                updateChatPosition(ChatPosition.Value)
            else
                -- Revert back to default Top Left position on disable
                updateChatPosition("Top Left")
            end
        end,
    })

    ChatPosition = ChatMover:CreateDropdown({
        Name = 'Position',
        List = {'Top Left', 'Top Right', 'Bottom Left', 'Bottom Right'},
        Default = 'Bottom Left',
        Function = function(val)
            if ChatMover.Enabled then
                updateChatPosition(val)
            end
        end
    })
end)

run(function()
	local AutoMarina

	AutoMarina = vape.Categories.Kits:CreateModule({
		Name = 'AutoMarina',
		Function = function(callback)
			if callback then
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local lplr = Players.LocalPlayer

				-- Fetch exact RemoteEvent
				local useAbilityRemote
				pcall(function()
					useAbilityRemote = ReplicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility")
				end)

				if not useAbilityRemote then
					if vape.CreateNotification then
						vape:CreateNotification("AutoMarina", "useAbility remote not found!", 5)
					end
					AutoMarina:ToggleButton(false)
					return
				end

				-- Check for nearby Players or Dummies/NPCs
				local function checkTargets()
					if not lplr or not lplr.Character then return false end
					local myRoot = lplr.Character:FindFirstChild("HumanoidRootPart")
					if not myRoot then return false end

					local myTeam = lplr:GetAttribute("Team") or lplr:GetAttribute("TeamId") or -1
					local range = AutoMarina.Options["Detection Range"].Value or 22

					-- 1. Check Players
					if AutoMarina.Targets.Players then
						for _, player in ipairs(Players:GetPlayers()) do
							if player ~= lplr and player.Character then
								local pTeam = player:GetAttribute("Team") or player:GetAttribute("TeamId") or -1
								if pTeam ~= myTeam or myTeam == -1 then
									local root = player.Character:FindFirstChild("HumanoidRootPart")
									local hum = player.Character:FindFirstChildOfClass("Humanoid")

									if root and hum and hum.Health > 0 then
										if (root.Position - myRoot.Position).Magnitude <= range then
											return true
										end
									end
								end
							end
						end
					end

					-- 2. Check NPCs / Dummies
					if AutoMarina.Targets.NPCs then
						for _, ent in entitylib.List do
							if ent.RootPart and ent.Character and ent.Character ~= lplr.Character and not Players:GetPlayerFromCharacter(ent.Character) then
								local hum = ent.Character:FindFirstChildOfClass("Humanoid")
								if hum and hum.Health > 0 then
									if (ent.RootPart.Position - myRoot.Position).Magnitude <= range then
										return true
									end
								end
							end
						end
						for _, entity in collectionService:GetTagged('entity') do
							if entity:IsA("Model") and entity ~= lplr.Character and not Players:GetPlayerFromCharacter(entity) then
								local root = entity:FindFirstChild("HumanoidRootPart") or entity.PrimaryPart or entity:FindFirstChildWhichIsA("BasePart")
								local hum = entity:FindFirstChildOfClass("Humanoid")
								if root and hum and hum.Health > 0 then
									if (root.Position - myRoot.Position).Magnitude <= range then
										return true
									end
								end
							end
						end
					end

					return false
				end

				-- Main execution loop
				local lastUsed = 0
				local loopThread = task.spawn(function()
					while AutoMarina.Enabled do
						task.wait(0.1)

						if checkTargets() then
							if tick() - lastUsed >= 0.5 then
								lastUsed = tick()
								pcall(function()
									useAbilityRemote:FireServer("electrify_jellyfish")
								end)
							end
						end
					end
				end)

				AutoMarina:Clean(function()
					if loopThread then
						task.cancel(loopThread)
					end
				end)
			end
		end,
		Tooltip = 'Triggers Marina\'s electrify_jellyfish ability when enemies or dummies enter range.'
	})

	-- Target Configuration Component
	AutoMarina.Targets = AutoMarina:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})

	-- Detection Range Slider (0 to 22 studs)
	AutoMarina:CreateSlider({
		Name = "Detection Range",
		Min = 0,
		Max = 50,
		Default = 50,
		Suffix = "studs"
	})
end)

run(function()
	local KnitInit, Knit
	repeat
		KnitInit, Knit = pcall(function()
			return debug.getupvalue(require(lplr.PlayerScripts.TS.knit).setup, 9)
		end)
		if KnitInit then break end
		task.wait()
	until KnitInit

	if not debug.getupvalue(Knit.Start, 1) then
		repeat task.wait() until debug.getupvalue(Knit.Start, 1)
	end

	local Players = game:GetService("Players")

	shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT = shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT or Knit.Controllers.PermissionController.hasAnyPermissions
	shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT = shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT or Knit.Controllers.MatchController.getPlayerParty

	local AC_MOD_View = {
		playerConnections = {},
		Enabled = false,
		Friends = {}, 
		parties = {}, 
		teamMap = {}, 
		display = {},
		isRefreshing = false,
		cacheDirty = true,
		disable_disguises = false,
		disguises = {},
		teamData = {}
	}

	AC_MOD_View.controller = Knit.Controllers.PermissionController
	AC_MOD_View.match_controller = Knit.Controllers.MatchController

	function AC_MOD_View:getPartyById(displayId)
		if not displayId then return end
		displayId = tostring(displayId)
		if self.display[displayId] then return self.display[displayId] end
		for _, party in pairs(self.parties) do
			if party.displayId == tostring(displayId) then
				self.display[displayId] = party
				return party
			end
		end
	end

	function AC_MOD_View:refreshDisplayCache()
		for _, plr in pairs(Players:GetPlayers()) do
			local playerId = tostring(plr.UserId)

			local playerPartyId = self.teamMap[playerId]
			if playerPartyId ~= nil then
				self:getPartyById(playerPartyId)
			end
			task.wait()
		end
	end

	function AC_MOD_View:refreshDisplayCacheAsync()
		task.spawn(self.refreshDisplayCache, self)
	end

	function AC_MOD_View:getPlayerTeamData(plr)
		if self.teamData[plr] then return self.teamData[plr] end

		self.teamData[plr] = {}

		local teamMembers = {}
		local playerTeam = plr.Team 
		if not playerTeam then
			return teamMembers 
		end

		local playerId = tostring(plr.UserId)
		self.Friends[playerId] = self.Friends[playerId] or {}

		for _, otherPlayer in pairs(Players:GetPlayers()) do
			if otherPlayer == plr then continue end 

			local otherPlayerId = tostring(otherPlayer.UserId)
			local areFriends = self.Friends[playerId][otherPlayerId]

			if areFriends == nil then
				local suc, res = pcall(function()
					return plr:IsFriendsWith(otherPlayer.UserId)
				end)
				areFriends = suc and res or false

				if suc then
					self.Friends = self.Friends or {}
					self.Friends[playerId] = self.Friends[playerId] or {}
					self.Friends[playerId][otherPlayerId] = areFriends
					self.Friends[otherPlayerId] = self.Friends[otherPlayerId] or {}
					self.Friends[otherPlayerId][playerId] = areFriends
				end
			end

			if areFriends and otherPlayer.Team == playerTeam then
				table.insert(teamMembers, otherPlayerId)
			end
		end

		self.teamData[plr] = teamMembers

		return teamMembers
	end

	function AC_MOD_View:refreshPlayerTeamData()
		for i,v in pairs(Players:GetPlayers()) do
			self:getPlayerTeamData(v)
			task.wait()
		end
	end

	function AC_MOD_View:refreshPlayerTeamDataAsync()
		task.spawn(self.refreshPlayerTeamData, self)
	end

	function AC_MOD_View:refreshTeamMap()
		local allTeams = {}
		for _, p in pairs(Players:GetPlayers()) do
			local teamMembers = self:getPlayerTeamData(p)
			if teamMembers and #teamMembers > 0 then 
				allTeams[p] = teamMembers
			end
		end

		local validTeams = {}
		for playerInTeams, members in pairs(allTeams) do
			local playerIdInTeams = tostring(playerInTeams.UserId)
			local cleanedMembers = {}

			for _, memberId in pairs(members) do
				local memberIdStr = tostring(memberId)
				if memberIdStr == playerIdInTeams then
					--print("Warning: Player " .. playerIdInTeams .. " has themselves in their team list.")
				else
					table.insert(cleanedMembers, memberIdStr)
				end
			end

			if #cleanedMembers > 0 then
				validTeams[playerInTeams] = cleanedMembers
			end
		end

		self.parties = {}
		self.teamMap = {}
		local teamId = 0
		for playerInTeams, members in pairs(validTeams) do
			local playerIdInTeams = tostring(playerInTeams.UserId)
			if not self.teamMap[playerIdInTeams] then
				self.teamMap[playerIdInTeams] = teamId
				table.insert(self.parties, {
					displayId = tostring(teamId),
					members = members
				})
				teamId = teamId + 1

				for _, memberId in pairs(members) do
					self.teamMap[memberId] = teamId - 1
				end
			end
		end

		self.cacheDirty = false
		self.isRefreshing = false
	end

	function AC_MOD_View:refreshTeamMapAsync()
		if self.isRefreshing then return end 
		self.isRefreshing = true
		task.spawn(function()
			self:refreshTeamMap()
		end)
	end

	function AC_MOD_View:getPlayerParty(plr)
		if not plr or not plr:IsA("Player") then
			return nil
		end

		local playerId = tostring(plr.UserId)

		if self.cacheDirty or not next(self.teamMap) then
			self:refreshTeamMapAsync()
		end

		local playerPartyId = self.teamMap[playerId]
		if playerPartyId ~= nil then
			return self:getPartyById(playerPartyId)
		end

		return nil 
	end

	AC_MOD_View.mockGetPlayerParty = function(self, plr)
		local parties = self.parties 
		if parties ~= nil and #parties > 0 then
			return shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT(self, plr)
		end
		return AC_MOD_View:getPlayerParty(plr)
	end

	function AC_MOD_View:toggleDisableDisguises()
		if not self.Enabled then return end
		if self.disable_disguises then
			for _,v in pairs(Players:GetPlayers()) do
				if v == Players.LocalPlayer then continue end
				local disguiseName = v:GetAttribute("DisguiseDisplayName")
				if disguiseName and disguiseName ~= "" then
					self.disguises[v] = disguiseName
					v:SetAttribute("DisguiseDisplayName", "")
					notif("Remove Disguises", "Disabled streamer mode for "..tostring(v.Name).."!", 3)
				end
			end
			pcall(function() Knit.Controllers.StreamerModeController:updateNametags(true) end)
		else
			for v, originalName in pairs(self.disguises) do
				if v and v.Parent then
					v:SetAttribute("DisguiseDisplayName", originalName)
					notif("Remove Disguises", "Re-enabled Streamer mode for "..tostring(v.Name).."!", 2)
				end
			end
			table.clear(self.disguises)
			pcall(function() Knit.Controllers.StreamerModeController:updateNametags(true) end)
		end
	end

	function AC_MOD_View:refreshCore()
		self:refreshTeamMapAsync()
		self:refreshDisplayCacheAsync()
		self:refreshPlayerTeamDataAsync()

		self:toggleDisableDisguises()
	end

	function AC_MOD_View:refreshCoreAsync()
		task.spawn(self.refreshCore, self)
	end

	function AC_MOD_View:init()
		self.Enabled = true
		self.controller.hasAnyPermissions = function(self)
			return true
		end
		self.match_controller.getPlayerParty = self.mockGetPlayerParty

		self.playerConnections = {
			added = Players.PlayerAdded:Connect(function(player)
				self.cacheDirty = true
				self:refreshCoreAsync()
				player:GetPropertyChangedSignal("Team"):Connect(function()
					self.cacheDirty = true
					self:refreshCoreAsync()
				end)
			end),
			removed = Players.PlayerRemoving:Connect(function(player)
				local playerId = tostring(player.UserId)
				self.Friends[playerId] = nil 
				for _, cache in pairs(self.Friends) do
					cache[playerId] = nil
				end
				self.cacheDirty = true
				self:refreshCoreAsync()
			end)
		}

		self:refreshCore()
	end

	function AC_MOD_View:disable()
		self.Enabled = false

		self.controller.hasAnyPermissions = shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT
		self.match_controller.getPlayerParty = shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT

		if self.playerConnections then
			for _, v in pairs(self.playerConnections) do
				pcall(function() v:Disconnect() end)
			end
			table.clear(self.playerConnections)
		end

		self.parties = {}
		self.teamMap = {}
		self.Friends = {}
		self.display = {}
		self.teamData = {}
		self.cacheDirty = true

		self:toggleDisableDisguises()
	end

	shared.ACMODVIEWENABLED = false
	AC_MOD_View.moduleInstance = vape.Categories.World:CreateModule({
		Name = "AC MOD",
		Function = function(call)
			shared.ACMODVIEWENABLED = call
			if call then
				AC_MOD_View:init()
			else
				AC_MOD_View:disable()
			end
		end
	})

	AC_MOD_View.disableDisguisesToggle = AC_MOD_View.moduleInstance:CreateToggle({
		Name = "Remove Disguises",
		Function = function(call)
			AC_MOD_View.disable_disguises = call
			AC_MOD_View:toggleDisableDisguises()
		end
	})
end)

run(function()
	local AutoArmorTrim
	local TrimDropdown
	local ColorDropdown
	local RankDropdown
	local ForceWeldToggle

	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer

	-- Helper function to safely fetch TS modules
	local function getTSModule(modulePath, itemName)
		local success, result = pcall(function()
			local rbxts = ReplicatedStorage:WaitForChild("rbxts_include", 2)
			if not rbxts then return nil end
			local RuntimeLib = require(rbxts:WaitForChild("RuntimeLib"))
			local module = RuntimeLib.import(script, ReplicatedStorage, unpack(modulePath))
			return itemName and module[itemName] or module
		end)
		return success and result or nil
	end

	-- Readable Names -> Internal ArmorTrimType keys
	local TrimNameMap = {
		["Test (Trim 1)"] = "trim_1",
		["Retro (Trim 2)"] = "trim_2",
		["Overgrown (Trim 3)"] = "trim_3",
		["Butterfly (Trim 4)"] = "trim_4",
		["Fire (Trim 5)"] = "trim_5",
		["Frosty (Trim 6)"] = "trim_6",
		["Void (Trim 7)"] = "trim_7",
		["Trim 8"] = "trim_8",
		["Trim 9"] = "trim_9",
		["Trim 10"] = "trim_10",
		["Trim 11"] = "trim_11",
		["Trim 12"] = "trim_12"
	}

	-- Direct body part anchor map
	local TrimAnchorMap = {
		["boots_left_trim"] = "LeftFoot",
		["boots_right_trim"] = "RightFoot",
		["chestplate_left_shoulder_trim"] = "LeftUpperArm",
		["chestplate_right_shoulder_trim"] = "RightUpperArm",
		["chestplate_trim"] = "UpperTorso",
		["helmet_trim"] = "Head"
	}

	-- Attach and weld trim parts directly to avatar body parts
	local function attachAndWeldArmorTrims(character, trimId, colorValue, rankValue)
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then return end

		-- Destroy old custom trim accessories
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Accessory") and child:GetAttribute("AutoArmorTrimAccessory") then
				child:Destroy()
			end
		end

		local ArmorTrimColorMeta = getTSModule({"TS", "armor-trim", "armor-trim-color-meta"}, "ArmorTrimColorMeta")
		local ArmorTrimEffectRankMeta = getTSModule({"TS", "armor-trim", "armor-trim-rank"}, "ArmorTrimEffectRankMeta")

		local colorRGB = (ArmorTrimColorMeta and ArmorTrimColorMeta[colorValue] and ArmorTrimColorMeta[colorValue].color) or Color3.fromRGB(255, 99, 99)
		local rankMeta = ArmorTrimEffectRankMeta and ArmorTrimEffectRankMeta[rankValue]

		-- Fetch trim accessory templates from ReplicatedStorage Assets
		local folder = ReplicatedStorage:FindFirstChild("Assets") and ReplicatedStorage.Assets:FindFirstChild("ArmorTrims") and ReplicatedStorage.Assets.ArmorTrims:FindFirstChild(trimId)
		if not folder then return end

		for _, desc in ipairs(folder:GetDescendants()) do
			if desc:IsA("Accessory") then
				local acc = desc:Clone()
				acc:SetAttribute("AutoArmorTrimAccessory", true)

				-- Recolor & apply rank material to parts
				for _, part in ipairs(acc:GetDescendants()) do
					if part:IsA("BasePart") then
						part.Color = colorRGB
						part.Transparency = 0
						if rankMeta and rankMeta.material then
							part.Material = rankMeta.material
						end
					end
				end

				local accName = acc.Name:lower()
				local targetPartName = nil
				for keyName, partName in pairs(TrimAnchorMap) do
					if accName:find(keyName) then
						targetPartName = partName
						break
					end
				end

				local targetPart = targetPartName and character:FindFirstChild(targetPartName)

				if targetPart then
					acc.Parent = character
					local handle = acc:FindFirstChild("Handle")
					if handle then
						handle.CFrame = targetPart.CFrame
						handle.CanCollide = false
						handle.CanTouch = false
						handle.CanQuery = false

						local weld = Instance.new("WeldConstraint")
						weld.Part0 = handle
						weld.Part1 = targetPart
						weld.Parent = handle
					end
				else
					humanoid:AddAccessory(acc)
				end
			end
		end
	end

	-- Main update function
	local function updateArmorTrim()
		if not AutoArmorTrim or not AutoArmorTrim.Enabled then return end
		local character = LocalPlayer.Character or (entitylib and entitylib.character)
		if not character or not character:FindFirstChildOfClass("Humanoid") then return end

		pcall(function()
			local rawTrimName = TrimDropdown.Value or "Test (Trim 1)"
			local trimId = TrimNameMap[rawTrimName] or "trim_1"
			local colorName = ColorDropdown.Value or "RED"
			local rankName = RankDropdown.Value or "T7"

			local ArmorTrimColor = getTSModule({"TS", "armor-trim", "armor-trim-colors"}, "ArmorTrimColor")
			local ArmorTrimEffectRank = getTSModule({"TS", "armor-trim", "armor-trim-rank"}, "ArmorTrimEffectRank")

			local colorValue = (ArmorTrimColor and ArmorTrimColor[colorName]) or 0
			local rankValue = (ArmorTrimEffectRank and ArmorTrimEffectRank[rankName]) or 6

			-- Update character attributes so game knows armor trim is applied
			character:SetAttribute("ArmorTrimType", trimId)
			character:SetAttribute("ArmorTrimColor", colorValue)
			character:SetAttribute("ArmorTrimEffectRank", rankValue)

			-- 1. Attach Particle & Beam Effects via Knit Controller
			-- Correct Order: (p1 = Controller, p2 = Character, p3 = TrimId, p4 = ColorValue, p5 = RankValue, p6 = EffectType)
			local KnitClient = (shared.bedwars and shared.bedwars.KnitClient) or (bedwars and bedwars.KnitClient)
			if KnitClient and KnitClient.Controllers and KnitClient.Controllers.ArmorTrimController then
				KnitClient.Controllers.ArmorTrimController:attachArmorTrimEffects(character, trimId, colorValue, rankValue, nil)
			end

			-- 2. Attach and weld accessories to body parts
			if not ForceWeldToggle or ForceWeldToggle.Enabled then
				attachAndWeldArmorTrims(character, trimId, colorValue, rankValue)
			else
				for _, child in ipairs(character:GetChildren()) do
					if child:IsA("Accessory") and child:GetAttribute("AutoArmorTrimAccessory") then
						child:Destroy()
					end
				end
			end
		end)
	end

	-- Register Module under Render Category
	AutoArmorTrim = vape.Categories.Render:CreateModule({
		Name = 'AutoArmorTrim',
		Function = function(callback)
			if callback then
				updateArmorTrim()

				local connection
				connection = LocalPlayer.CharacterAdded:Connect(function(newChar)
					if not AutoArmorTrim.Enabled then
						connection:Disconnect()
						return
					end
					newChar:WaitForChild("Humanoid")
					task.wait(0.3)
					updateArmorTrim()
				end)
			else
				local char = LocalPlayer.Character
				if char then
					for _, item in ipairs(char:GetChildren()) do
						if item:IsA("Accessory") and item:GetAttribute("AutoArmorTrimAccessory") then
							item:Destroy()
						end
					end
				end
			end
		end,
		Tooltip = 'Loads Bedwars TS Armor Trim modules, applies particle effects and attaches trim accessories'
	})

	TrimDropdown = AutoArmorTrim:CreateDropdown({
		Name = 'Trim Style',
		List = {
			"Test (Trim 1)",
			"Retro (Trim 2)",
			"Overgrown (Trim 3)",
			"Butterfly (Trim 4)",
			"Fire (Trim 5)",
			"Frosty (Trim 6)",
			"Void (Trim 7)",
		},
		Default = "Test (Trim 1)",
		OnChange = function() updateArmorTrim() end,
		Tooltip = 'Select the Armor Trim style'
	})

	ColorDropdown = AutoArmorTrim:CreateDropdown({
		Name = 'Trim Color',
		List = { "RED", "ORANGE", "YELLOW", "GREEN", "BLUE", "INDIGO", "PURPLE", "WHITE", "BLACK", "BROWN", "PINK" },
		Default = "RED",
		OnChange = function() updateArmorTrim() end,
		Tooltip = 'Select the Armor Trim color'
	})

	RankDropdown = AutoArmorTrim:CreateDropdown({
		Name = 'Rank Tier',
		List = { "T1", "T2", "T3", "T4", "T5", "T6", "T7" },
		Default = "T7",
		OnChange = function() updateArmorTrim() end,
		Tooltip = 'Select rank tier for material & particle intensity'
	})

	ForceWeldToggle = AutoArmorTrim:CreateToggle({
		Name = 'Weld Accessories',
		Default = true,
		OnChange = function() updateArmorTrim() end,
		Tooltip = 'Clones, colors, and attaches trim accessories to designated body parts'
	})
end)

run(function()
	local GhostBlockFixer
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer

	-- Helper function to fetch TS modules safely
	local function getTSModule(modulePath, itemName)
		local success, result = pcall(function()
			local rbxts = ReplicatedStorage:WaitForChild("rbxts_include", 2)
			if not rbxts then return nil end
			local RuntimeLib = require(rbxts:WaitForChild("RuntimeLib"))
			local module = RuntimeLib.import(script, ReplicatedStorage, unpack(modulePath))
			return itemName and module[itemName] or module
		end)
		return success and result or nil
	end

	-- Intercept and fix ghost block prediction desync
	local originalDestroyBlock = nil
	local originalHitBlock = nil
	local isHooked = false
	local predictionDepth = 0

	local function hookGhostBlockFix()
		if isHooked then return end

		local BlockEngine = getTSModule({
			"rbxts_include", "node_modules", "@easy-games", "block-engine", "out"
		}, "BlockEngine")

		local BlockBreaker = getTSModule({
			"rbxts_include", "node_modules", "@easy-games", "block-engine", "out", "client", "break", "block-breaker"
		}, "BlockBreaker")

		if not BlockEngine or not BlockBreaker then return end
		isHooked = true

		-- 1. Hook BlockEngine.destroyBlock to suppress client predicted ghost destroys
		originalDestroyBlock = BlockEngine.destroyBlock
		BlockEngine.destroyBlock = function(self, blockRef, options)
			if GhostBlockFixer and GhostBlockFixer.Enabled then
				if predictionDepth > 0 and options and options.destroyingPlayer == LocalPlayer then
					return { spawnedGreedyBlocks = {} }
				end
			end
			return originalDestroyBlock(self, blockRef, options)
		end

		-- 2. Hook BlockBreaker.hitBlock to manage prediction depth and clear stale predicted breaks
		originalHitBlock = BlockBreaker.hitBlock
		BlockBreaker.hitBlock = function(self, ...)
			if GhostBlockFixer and GhostBlockFixer.Enabled then
				predictionDepth += 1
				local success, ret1, ret2, ret3, ret4 = pcall(originalHitBlock, self, ...)
				predictionDepth -= 1

				if self.clientPredictedBlockBreaks then
					table.clear(self.clientPredictedBlockBreaks)
				end

				if not success then
					error(ret1, 2)
				end
				return ret1, ret2, ret3, ret4
			else
				return originalHitBlock(self, ...)
			end
		end
	end

	local function unhookGhostBlockFix()
		local BlockEngine = getTSModule({
			"rbxts_include", "node_modules", "@easy-games", "block-engine", "out"
		}, "BlockEngine")

		local BlockBreaker = getTSModule({
			"rbxts_include", "node_modules", "@easy-games", "block-engine", "out", "client", "break", "block-breaker"
		}, "BlockBreaker")

		if BlockEngine and originalDestroyBlock then
			BlockEngine.destroyBlock = originalDestroyBlock
		end
		if BlockBreaker and originalHitBlock then
			BlockBreaker.hitBlock = originalHitBlock
		end
	end

	-- Register Module under Utility Category
	GhostBlockFixer = vape.Categories.Utility:CreateModule({
		Name = 'GhostBlockFixer',
		Function = function(callback)
			if callback then
				pcall(hookGhostBlockFix)
			else
				pcall(unhookGhostBlockFix)
			end
		end,
		Tooltip = 'Prevents client-side ghost block desync when breaking bed defense blocks'
	})
end)

run(function()
	local AutoSkoll
	local Targets
	local RangeSlider
	local AutoFacing
	local AutoDetonate
	local DetonateRange

	local isMarked = false
	local markedTarget = nil
	local markedTime = 0

	task.spawn(function()
		local ClientSyncEvents = bedwars.ClientSyncEvents or (bedwars.Client and bedwars.Client:GetNamespace('Default'))
		if ClientSyncEvents and type(ClientSyncEvents.Get) == 'function' then
			local markedEvent = ClientSyncEvents:Get('VoidHunter_TargetMarked')
			if markedEvent and markedEvent.Connect then
				markedEvent:Connect(function(data)
					isMarked = true
					markedTime = tick()
					if data and data.target then
						markedTarget = data.target
					end
				end)
			end
			local removedEvent = ClientSyncEvents:Get('VoidHunter_TargetMarkedRemoved')
			if removedEvent and removedEvent.Connect then
				removedEvent:Connect(function()
					isMarked = false
					markedTarget = nil
				end)
			end
		end
	end)

	local function isTargetValid(ent)
		if not ent or not ent.Targetable then return false end
		if ent.Player and Targets and Targets.Players and Targets.Players.Enabled then return true end
		if not ent.Player and Targets and Targets.NPCs and Targets.NPCs.Enabled then return true end
		return false
	end

	local function getTarget()
		if not entitylib.isAlive or not entitylib.character or not entitylib.character.RootPart then return nil end
		local rootPos = entitylib.character.RootPart.Position
		local maxDist = RangeSlider and RangeSlider.Value or 22
		local bestTarget, bestDist = nil, maxDist

		for _, ent in pairs(entitylib.List) do
			if isTargetValid(ent) and ent.RootPart then
				local dist = (ent.RootPart.Position - rootPos).Magnitude
				if dist <= bestDist then
					bestDist = dist
					bestTarget = ent
				end
			end
		end
		return bestTarget
	end

	AutoSkoll = vape.Categories.Kits:CreateModule({
		Name = 'AutoSkoll',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive and entitylib.character and entitylib.character.RootPart then
						local myPos = entitylib.character.RootPart.Position
						local target = getTarget()

						if not isMarked then
							if target and target.RootPart then
								local targetPos = target.RootPart.Position
								local dir = (targetPos - myPos).Unit

								if AutoFacing and AutoFacing.Enabled then
									pcall(function()
										entitylib.character.RootPart.CFrame = CFrame.lookAt(myPos, Vector3.new(targetPos.X, myPos.Y, targetPos.Z))
									end)
								end

								pcall(function()
									if bedwars.AbilityController then
										bedwars.AbilityController:useAbility('void_hunter_mark')
									elseif bedwars.KnitClient and bedwars.KnitClient.Controllers.VoidHunterKitController then
										bedwars.KnitClient.Controllers.VoidHunterKitController:useMarkAbility(dir)
									end
								end)
								task.wait(0.3)
							end
						else
							if AutoDetonate and AutoDetonate.Enabled then
								local detonateDist = DetonateRange and DetonateRange.Value or 50
								local shouldDetonate = false

								if markedTarget and markedTarget.Parent and markedTarget:FindFirstChild('HumanoidRootPart') then
									local tPos = markedTarget.HumanoidRootPart.Position
									if (tPos - myPos).Magnitude >= detonateDist then
										shouldDetonate = true
									end
								elseif tick() - markedTime > 5 then
									shouldDetonate = true
								end

								if shouldDetonate then
									pcall(function()
										if bedwars.AbilityController then
											bedwars.AbilityController:useAbility('void_hunter_detonate')
										end
									end)
									task.wait(0.3)
								end
							end
						end
					end
					task.wait(0.1)
				until not AutoSkoll.Enabled
			else
				isMarked = false
				markedTarget = nil
			end
		end,
		Tooltip = 'Auto launches & auto detonates Skoll Fenrir wolf mark ability'
	})

	Targets = AutoSkoll:CreateTargets({
		Players = true,
		NPCs = true
	})

	RangeSlider = AutoSkoll:CreateSlider({
		Name = 'Range',
		Min = 0,
		Max = 22,
		Default = 22,
		Suffix = function(val) return val <= 1 and 'stud' or 'studs' end
	})

	AutoFacing = AutoSkoll:CreateToggle({
		Name = 'Auto Facing',
		Default = true,
		Tooltip = 'Faces target when sending wolf'
	})

	AutoDetonate = AutoSkoll:CreateToggle({
		Name = 'Auto Detonate',
		Default = true,
		Tooltip = 'Detonates mark when enemy moves out of detonate range'
	})

	DetonateRange = AutoSkoll:CreateSlider({
		Name = 'Detonate Range',
		Min = 0,
		Max = 50,
		Default = 35,
		Suffix = function(val) return val <= 1 and 'stud' or 'studs' end
	})
end)

run(function()
	local AutoAlchemist
	local PotionSelect
	local BrewDelay

	local RECIPES = {
		['Heal Potion']   = { ingredients = { wild_flower = 3 } },
		['Sleep Potion']  = { ingredients = { mushrooms = 3 } },
		['Poison Potion'] = { ingredients = { thorns = 1, mushrooms = 2 } },
		['Big Shield']    = { ingredients = { thorns = 2, wild_flower = 1 } },
	}

	local INGREDIENT_NAMES = {
		wild_flower = 'Wild Flower',
		mushrooms   = 'Mushrooms',
		thorns      = 'Thorns',
	}

	local ABILITY_MAP = {
		wild_flower = 'alchemist_add_flower',
		mushrooms   = 'alchemist_add_mushrooms',
		thorns      = 'alchemist_add_thorns',
	}

	-- Find the useAbility RemoteEvent from ReplicatedStorage
	local useAbilityRemote
	task.spawn(function()
		for _, desc in replicatedStorage:GetDescendants() do
			if desc.Name == 'useAbility' and desc:IsA('RemoteEvent') then
				useAbilityRemote = desc
				break
			end
		end
		if not useAbilityRemote then
			replicatedStorage.DescendantAdded:Connect(function(desc)
				if desc.Name == 'useAbility' and desc:IsA('RemoteEvent') then
					useAbilityRemote = desc
				end
			end)
		end
	end)

	local lplr = game:GetService('Players').LocalPlayer

	local function getItemCount(itemType)
		if not store or not store.inventory or not store.inventory.inventory then return 0 end
		local count = 0
		for _, item in store.inventory.inventory.items do
			if item.itemType == itemType then
				count += (item.quantity or 1)
			end
		end
		return count
	end

	local function isHoldingFlask()
		if not store or not store.inventory then return false end
		local inv = store.inventory.inventory or store.inventory.observedInventory and store.inventory.observedInventory.inventory
		if not inv then return false end
		local hand = inv.hand
		return hand and hand.itemType == 'alchemist_flask'
	end

	local function getStagedCount(ingredient)
		local attr = lplr:GetAttribute('AlchemistFlaskBrewStage')
		if type(attr) ~= 'string' or attr == '' then return 0 end
		local count = 0
		for t in attr:gmatch('[^,]+') do
			if t:lower() == ingredient then count += 1 end
		end
		return count
	end

	local function fireAbility(abilityId)
		local ok = pcall(function()
			bedwars.AbilityController:useAbility(abilityId)
		end)
		if not ok and useAbilityRemote then
			pcall(function()
				useAbilityRemote:FireServer(abilityId, {})
			end)
		end
	end

	AutoAlchemist = vape.Categories.Kits:CreateModule({
		Name = 'AutoAlchemist',
		Function = function(callback)
			if callback then
				repeat
					task.wait(BrewDelay and BrewDelay.Value or 0.5)
					if not entitylib.isAlive then continue end
					if not isHoldingFlask() then continue end

					local selectedPotion = PotionSelect and PotionSelect.Value or 'Heal Potion'
					local recipe = RECIPES[selectedPotion]
					if not recipe then continue end

					-- Check for missing ingredients
					local missing = {}
					for ingredient, needed in pairs(recipe.ingredients) do
						local staged = getStagedCount(ingredient)
						local have = getItemCount(ingredient)
						local stillNeeded = math.max(0, needed - staged)
						if have < stillNeeded then
							table.insert(missing, (stillNeeded - have) .. 'x ' .. INGREDIENT_NAMES[ingredient])
						end
					end

					if #missing > 0 then
						vape.Notify({
							Title = 'AutoAlchemist',
							Description = 'Missing: ' .. table.concat(missing, ', '),
							Duration = 3
						})
						continue
					end

					-- Stage each ingredient that still needs to be added
					for ingredient, needed in pairs(recipe.ingredients) do
						local toAdd = math.max(0, needed - getStagedCount(ingredient))
						for _ = 1, toAdd do
							fireAbility(ABILITY_MAP[ingredient])
							task.wait(0.2)
						end
					end

				until not AutoAlchemist.Enabled
			end
		end,
		Tooltip = 'Auto brews selected potions with the Alchemist flask. Notifies on missing ingredients.'
	})

	PotionSelect = AutoAlchemist:CreateDropdown({
		Name = 'Potion',
		List = {'Heal Potion', 'Sleep Potion', 'Poison Potion', 'Big Shield'},
		Default = 'Heal Potion',
		Tooltip = 'Potion to auto brew'
	})

	BrewDelay = AutoAlchemist:CreateSlider({
		Name = 'Brew Delay',
		Min = 0.1,
		Max = 2,
		Default = 0.5,
		Decimal = 10,
		Tooltip = 'Delay between brew cycles'
	})
end)

run(function()
	local InfiniteMana
	local manaLoop

	InfiniteMana = vape.Categories.Kits:CreateModule({
		Name = 'InfWhim',
		Tooltip = 'Locks your client-side mana bar to max',
		Function = function(callback)
			if callback then
				manaLoop = task.spawn(function()
					while InfiniteMana.Enabled do
						if lplr then
							pcall(function()
								lplr:SetAttribute("Mana", 100)
							end)
						end
						task.wait(0.05)
					end
				end)
			else
				if manaLoop then
					pcall(task.cancel, manaLoop)
					manaLoop = nil
				end
			end
		end
	})
end)

run(function()
	TrapDisabler = vape.Categories.Utility:CreateModule({
		Name = 'TrapDisabler',
		Tooltip = 'disables Snap Traps'
	})
end)

run(function()
    local BedAssist = {Enabled = false}
    local bedassistrange = {Value = 30}
    local bedassistsmoothness = {Value = 6}
    local bedassistangle = {Value = 70}
    local bedassistfirstperson = {Enabled = false}
    local bedassistshopcheck = {Enabled = false}
	local bedassisthandcheck = {Enabled = false}
	local bedassistlowestblock = {Enabled = false}
	
	local function getBedAimSpeed(speedVal, dt)
		local baseSpeed = 0.01
		local multiplier = 1.35
		local speed = baseSpeed * (multiplier ^ speedVal)
		return math.min(speed, 0.95) * (dt * 60)
	end

	local function checkHand()
		return isHoldingPickaxe() or isHoldingItem({'axe'})
	end

    local camera = gameCamera
    local beds = {}
    local Connections = {}

    local function isFirstPerson()
        if not (lplr.Character and lplr.Character:FindFirstChild("Head")) then return false end
        return (lplr.Character.Head.Position - camera.CFrame.Position).Magnitude < 2
    end

    local function getClosestEnemyBed(playerPos)
        local closestBed = nil
        local closestDistance = bedassistrange.Value
        local lowestY = math.huge

        for _, bed in pairs(beds) do
            if not bed.Parent then continue end

            if tostring(bed:GetAttribute("TeamId")) == tostring(lplr:GetAttribute("Team")) then
                continue
            end

            if bed:GetAttribute("BedShieldEndTime") and bed:GetAttribute("BedShieldEndTime") > workspace:GetServerTimeNow() then
                continue
            end

            local distance = (playerPos - bed.Position).Magnitude
            if distance > bedassistrange.Value then continue end

            local delta = (bed.Position - playerPos)
            local char = lplr.Character
            local localfacing = Vector3.new(1, 0, 0)
            if char and char:FindFirstChild("HumanoidRootPart") then
                localfacing = char.HumanoidRootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
                if localfacing.Magnitude < 0.001 then
                    localfacing = camera.CFrame.LookVector * Vector3.new(1, 0, 1)
                end
                localfacing = localfacing.Unit
            else
                localfacing = camera.CFrame.LookVector * Vector3.new(1, 0, 1)
                if localfacing.Magnitude > 0.001 then
                    localfacing = localfacing.Unit
                else
                    localfacing = Vector3.new(1, 0, 0)
                end
            end

            local flatDelta = delta * Vector3.new(1, 0, 1)
            local angle = math.huge
            if flatDelta.Magnitude > 0.1 then
                angle = math.acos(math.clamp(localfacing:Dot(flatDelta.Unit), -1, 1))
            else
                angle = 0
            end

            if angle <= math.rad(bedassistangle.Value) then
                if bedassistlowestblock.Enabled then
                    if bed.Position.Y < lowestY then
                        lowestY = bed.Position.Y
                        closestBed = bed
                    end
                else
                    if distance < closestDistance then
                        closestDistance = distance
                        closestBed = bed
                    end
                end
            end
        end

        return closestBed
    end

    BedAssist = vape.Categories.Utility:CreateModule({
        Name = "BedAssist",
        Function = function(callback)
            if callback then
                table.clear(beds)
                for _, bed in ipairs(collectionService:GetTagged("bed")) do
                    table.insert(beds, bed)
                end

                table.insert(Connections, collectionService:GetInstanceAddedSignal("bed"):Connect(function(bed)
                    table.insert(beds, bed)
                end))

                table.insert(Connections, collectionService:GetInstanceRemovedSignal("bed"):Connect(function(bed)
                    local i = table.find(beds, bed)
                    if i then
                        table.remove(beds, i)
                    end
                end))

                local heartbeatConn
                heartbeatConn = runService.Heartbeat:Connect(function(dt)
                    if not BedAssist.Enabled then
                        heartbeatConn:Disconnect()
                        camera.CameraType = Enum.CameraType.Custom
                        return
                    end
                    if not lplr.Character or not lplr.Character:FindFirstChild("HumanoidRootPart") then
                        return
                    end
					if bedassisthandcheck.Enabled and not checkHand() then 
						return
					end
                    if bedassistfirstperson.Enabled and not isFirstPerson() then
                        return
                    end
                    if bedassistshopcheck.Enabled then
                        local isShop = lplr:FindFirstChild("PlayerGui") and lplr.PlayerGui:FindFirstChild("ItemShop")
                        if isShop then return end
                    end

                    if #beds == 0 then return end

                    local playerPos = lplr.Character.HumanoidRootPart.Position
                    local closestBed = getClosestEnemyBed(playerPos)

                    if closestBed then
                        local bedPos = closestBed.Position
                        local currentCFrame = camera.CFrame
                        local targetCFrame = CFrame.lookAt(currentCFrame.Position, bedPos)
                        local lerpAmount = bedassistsmoothness.Value / 15
                        camera.CFrame = currentCFrame:Lerp(targetCFrame, math.min(getBedAimSpeed(bedassistsmoothness.Value, dt), 0.95))
                    end
                end)
                table.insert(Connections, heartbeatConn)
            else
                for _, v in pairs(Connections) do
                    pcall(function()
                        v:Disconnect()
                    end)
                end
                Connections = {}
                table.clear(beds)
                camera.CameraType = Enum.CameraType.Custom
            end
        end,
        Tooltip = "aa for beds lol"
    })

