run(function()
	local VoidAxeAura
	local Targets
	local Sort
	local Range
	local Void
	local KATarget
	local busy = false

	local function findVoidAxeSlot()
		for slot, entry in store.inventory.hotbar or {} do
			local item = entry and entry.item
			local tool = item and item.tool
			if (item and item.itemType == 'void_axe') or (tool and tool.Name == 'void_axe') then
				return slot - 1
			end
		end
		return nil
	end

	local function switchHotbar(slot)
		if slot == nil or store.inventory.hotbarSlot == slot then return false end
		bedwars.Store:dispatch({
			type = 'InventorySelectHotbarSlot',
			slot = slot
		})
		return true
	end

	local function hasTargetInRange()
		if not entitylib.isAlive or not entitylib.character or not entitylib.character.RootPart then return false end
		local localRoot = entitylib.character.RootPart
		local maxRange = Range.Value

		for _, entity in entitylib.List do
			local root = entity and entity.RootPart
			local isPlayer = entity and entity.Player ~= nil
			local shouldTarget = false

			if isPlayer and Targets.Players then
				shouldTarget = true
			elseif not isPlayer and Targets.NPCs then
				shouldTarget = true
			end

			if shouldTarget and root and root.Parent and root ~= localRoot then
				if (root.Position - localRoot.Position).Magnitude <= maxRange then
					return true
				end
			end
		end

		local npcList = entitylib.NPCList or entitylib.NPCs
		if Targets.NPCs and npcList then
			for _, entity in npcList do
				local root = entity and entity.RootPart
				if root and root.Parent and (root.Position - localRoot.Position).Magnitude <= maxRange then
					return true
				end
			end
		end

		return false
	end

	local function useAxe()
		if busy or not entitylib.isAlive or not bedwars.VoidAxeController or not bedwars.AbilityController then return end
		if not bedwars.AbilityController:canUseAbility('void_axe_jump', {disableBlockedAbilityAlert = true}) then return end

		local axeSlot = findVoidAxeSlot()
		if axeSlot == nil then return end

		busy = true
		local oldSlot = store.inventory.hotbarSlot
		switchHotbar(axeSlot)
		task.wait(0.02)

		if VoidAxeAura.Enabled and entitylib.isAlive then
			bedwars.VoidAxeController:useVoidAxe()
		end

		task.delay(0.1, function()
			if VoidAxeAura.Enabled and oldSlot ~= nil then
				switchHotbar(oldSlot)
			end
			busy = false
		end)
	end

	VoidAxeAura = vape.Categories.Blatant:CreateModule({
		Name = 'RegentAura',
		Function = function(enabled)
			busy = false
			if enabled then
				VoidAxeAura:Clean(runService.Heartbeat:Connect(function()
					if hasTargetInRange() then useAxe() end
				end))
			end
		end,
		Tooltip = 'Uses Void Axe when a selected target type is nearby'
	})

	Targets = VoidAxeAura:CreateTargets({
		Players = true,
		Walls = false,
		NPCs = false
	})

	local methods = {'Damage', 'Distance'}
	for i in sortmethods do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	Sort = VoidAxeAura:CreateDropdown({Name = 'Sort', List = methods})

	Range = VoidAxeAura:CreateSlider({
		Name = 'Range',
		Min = 0,
		Max = 22,
		Default = 12,
		Suffix = function(value)
			return value == 1 and 'stud' or 'studs'
		end,
		Tooltip = 'Only activate when a selected target is within this distance'
	})

	Void = VoidAxeAura:CreateToggle({
		Name = 'Void',
		Tooltip = 'doesnt use ability if player is falling in the void',
		Default = true,
	})

	KATarget = VoidAxeAura:CreateToggle({
		Name = 'Use KA Target',
		Default = false,
	})
end)

run(function()
	local VoidRegentExtender
	local Multiplier
	
	local old
	
	VoidRegentExtender = vape.Categories.Kits:CreateModule({
