run(function()
	local ChestSteal
	local Range
	local Open
	local Skywars
	local DelayToggle
	local DelaySlider
	local TeamFilter
	local Delays = {}
	
	local function isTeamChest(chest)
		if not TeamFilter.Enabled then return false end
		local myTeam = tostring(lplr:GetAttribute('Team') or '')
		local myBed = nil
		for _, bed in collectionService:GetTagged('bed') do
			if not bed:IsA('BasePart') then continue end
			local bedTeam = tostring(bed:GetAttribute('Team') or bed:GetAttribute('TeamId') or '')
			if bedTeam == myTeam then myBed = bed break end
		end
		if not myBed then return false end
		local dist = (chest.Position - myBed.Position).Magnitude
		return dist <= 60
	end
	
	local function lootChest(chest)
		chest = chest and chest.Value or nil
		if not chest then return end
		
		local chestitems = chest and chest:GetChildren() or {}
		if #chestitems > 1 and (Delays[chest] or 0) < tick() then
			Delays[chest] = tick() + (DelayToggle.Enabled and DelaySlider.Value or 0.2)
			bedwars.Client:GetNamespace('Inventory'):Get('SetObservedChest'):SendToServer(chest)
	
			for _, v in chestitems do
				if v:IsA('Accessory') then
					if DelayToggle.Enabled then
						task.wait(DelaySlider.Value / #chestitems) 
					end
					
					task.spawn(function()
						pcall(function()
							bedwars.Client:GetNamespace('Inventory'):Get('ChestGetItem'):CallServer(chest, v)
						end)
					end)
				end
			end
	
			bedwars.Client:GetNamespace('Inventory'):Get('SetObservedChest'):SendToServer(nil)
		end
	end
	
	ChestSteal = vape.Categories.Inventory:CreateModule({
		Name = 'ChestSteal',
		Function = function(callback)
			if callback then
				local chests = collection('chest', ChestSteal)
				repeat task.wait() until store.queueType ~= 'bedwars_test'
				if (not Skywars.Enabled) or store.queueType:find('skywars') then
					repeat
						if entitylib.isAlive and store.matchState ~= 2 then
							if Open.Enabled then
								if bedwars.AppController:isAppOpen('ChestApp') then
									lootChest(lplr.Character:FindFirstChild('ObservedChestFolder'))
								end
							else
								local localPosition = entitylib.character.RootPart.Position
								for _, v in chests do
									if (localPosition - v.Position).Magnitude <= Range.Value then
										if isTeamChest(v) then continue end
										lootChest(v:FindFirstChild('ChestFolderValue'))
									end
								end
							end
						end
						task.wait(0.1)
					until not ChestSteal.Enabled
				end
			end
		end,
		Tooltip = 'takes items from near chests'
	})
	Range = ChestSteal:CreateSlider({
		Name = 'Range',
		Min = 0,
		Max = 18,
		Default = 18,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	Open = ChestSteal:CreateToggle({Name = 'GUI Check'})
	Skywars = ChestSteal:CreateToggle({
		Name = 'Only Skywars',
		Function = function()
			if ChestSteal.Enabled then
				ChestSteal:Toggle()
				ChestSteal:Toggle()
			end
		end,
		Default = true
	})
	TeamFilter = ChestSteal:CreateToggle({
		Name = 'Team Check',
		Default = false
	})
	DelayToggle = ChestSteal:CreateToggle({
		Name = 'Delay',
		Function = function(callback)
			DelaySlider.Object.Visible = callback
			if ChestSteal.Enabled then
				ChestSteal:Toggle()
				ChestSteal:Toggle()
			end
		end
	})
    DelaySlider = ChestSteal:CreateSlider({
        Name = 'Delay Time',
        Min = 0.1,
        Max = 5,
        Default = 1,
        Decimal = 10,
        Suffix = 's',
        Visible = false
    })

    task.defer(function()
        if DelaySlider and DelaySlider.Object then
            DelaySlider.Object.Visible = false  
        end
    end)
end)

run(function()
	local FPSBooster
	local Cosmetics
	local Animations
	local Clouds
	local Quality
	local Shadows
	local Post
	local Water
	local Kill
	local Visualizer
	local Particles
	local Nametags
	local Compatibility
	local hidden = {}
	local watching = setmetatable({}, {__mode = 'k'})
	local effects = {}
	local killeffects, visualizers, particlesold = {}, {}, {}
	local waterold
	local qualityold
	local shadowsold
	local technologyold
	local nametagold
	local posthook
	local particlehook
	local particleclasses = {'ParticleEmitter', 'Trail', 'Beam', 'Smoke', 'Fire', 'Sparkles'}
	
	local function silenceParticle(obj)
		if not table.find(particleclasses, obj.ClassName) or particlesold[obj] ~= nil or obj.Parent and obj.Parent.Name == 'ProjectileTargeting' then return end
		particlesold[obj] = obj.Enabled
		obj.Enabled = false
	end
	
	local function stripEffect(effect)
		if effects[effect] ~= nil then return end
		for _, v in vape.BlurEffects or {} do
			if v == effect then return end
		end
	
		if effect:IsA('PostEffect') then
			effects[effect] = effect.Enabled
			effect.Enabled = false
		elseif effect:IsA('Atmosphere') then
			effects[effect] = effect.Density
			effect.Density = 0
		end
	end
	
	local function setSpeed(speed)
		for _, v in entitylib.List do
			if v.Player ~= lplr then
				local humanoid = v.Character:FindFirstChildWhichIsA('Humanoid')
				local animator = humanoid and humanoid:FindFirstChildWhichIsA('Animator')
				for _, v2 in animator and animator:GetPlayingAnimationTracks() or {} do
					v2:AdjustSpeed(speed)
				end
			end
		end
	end
	
	local function Added(ent)
		if not Cosmetics.Enabled or ent.Player == lplr then return end
	
		for _, v in ent.Character:GetChildren() do
			if v.Name == 'Clothing' or v.Name == '3DClothing' then
				hidden[v] = v.Parent
				v.Parent = nil
			end
		end
	
		if not watching[ent.Character] then
			watching[ent.Character] = ent.Character.ChildAdded:Connect(function(obj)
				if FPSBooster.Enabled and Cosmetics.Enabled and (obj.Name == 'Clothing' or obj.Name == '3DClothing') then
					task.defer(function()
						if FPSBooster.Enabled and Cosmetics.Enabled and obj.Parent == ent.Character then
							hidden[obj] = ent.Character
							obj.Parent = nil
						end
					end)
				end
			end)
		end
	end
	
	local function Removed(ent)
		if watching[ent.Character] then
			watching[ent.Character]:Disconnect()
			watching[ent.Character] = nil
		end
	
		for i, v in hidden do
			if v == ent.Character then
				hidden[i] = nil
			end
		end
	end
	
	FPSBooster = vape.Categories.Render:CreateModule({
		Name = 'FPSBooster',
		Function = function(callback)
			if callback then
				if Quality.Enabled then
					pcall(function()
						qualityold = settings().Rendering.QualityLevel
						settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
					end)
				end
	
				if Shadows.Enabled then
					shadowsold = lightingService.GlobalShadows
					lightingService.GlobalShadows = false
				end
	
				if Post.Enabled then
					for _, v in lightingService:GetChildren() do
						stripEffect(v)
					end
	
					posthook = lightingService.ChildAdded:Connect(function(v)
						if FPSBooster.Enabled and Post.Enabled then
							task.defer(stripEffect, v)
						end
					end)
				end
	
				if Water.Enabled then
					waterold = {
						Size = workspace.Terrain.WaterWaveSize,
						Speed = workspace.Terrain.WaterWaveSpeed,
						Reflectance = workspace.Terrain.WaterReflectance,
						Transparency = workspace.Terrain.WaterTransparency
					}
					workspace.Terrain.WaterWaveSize = 0
					workspace.Terrain.WaterWaveSpeed = 0
					workspace.Terrain.WaterReflectance = 0
					workspace.Terrain.WaterTransparency = 1
				end
	
				if Compatibility.Enabled then
					technologyold = lightingService.Technology
					lightingService.Technology = Enum.Technology.Compatibility
				end
	
				if Kill.Enabled then
					for i, v in bedwars.KillEffectController.killEffects do
						if not i:find('Custom') then
							killeffects[i] = v
							bedwars.KillEffectController.killEffects[i] = {
								new = function()
									return {
										onKill = function() end,
										isPlayDefaultKillEffect = function()
											return true
										end
									}
								end
							}
						end
					end
				end
	
				if Visualizer.Enabled then
					for i, v in bedwars.VisualizerUtils do
						visualizers[i] = v
						bedwars.VisualizerUtils[i] = function() end
					end
				end
	
				if Particles.Enabled then
					particlehook = workspace.DescendantAdded:Connect(silenceParticle)
					task.spawn(function()
						local clock = os.clock()
						for _, v in workspace:GetDescendants() do
							silenceParticle(v)
	
							if os.clock() - clock > 0.002 then
								task.wait()
								if not FPSBooster.Enabled or not Particles.Enabled then return end
								clock = os.clock()
							end
						end
					end)
				end
	
				if Nametags.Enabled then
					task.spawn(function()
						repeat task.wait() until store.matchState ~= 0 or not FPSBooster.Enabled
						if not FPSBooster.Enabled or not Nametags.Enabled or not bedwars.AppController then return end
	
						nametagold = bedwars.NametagController.addGameNametag
						bedwars.NametagController.addGameNametag = function() end
						for _, v in bedwars.AppController:getOpenApps() do
							if tostring(v):find('Nametag') then
								bedwars.AppController:closeApp(tostring(v))
							end
						end
					end)
				end
	
				if Clouds.Enabled then
					local clouds = workspace:FindFirstChild('Clouds')
					if clouds then
						hidden[clouds] = clouds.Parent
						clouds.Parent = nil
					end
				end
	
				if Cosmetics.Enabled then
					FPSBooster:Clean(entitylib.Events.EntityAdded:Connect(Added))
					FPSBooster:Clean(entitylib.Events.EntityRemoved:Connect(Removed))
					for _, v in entitylib.List do
						Added(v)
					end
				end
	
				if Animations.Enabled then
					task.spawn(function()
						repeat
							setSpeed(0)
							task.wait(0.5)
						until not FPSBooster.Enabled or not Animations.Enabled
					end)
				end
			else
				if posthook then
					posthook:Disconnect()
					posthook = nil
				end
	
				if particlehook then
					particlehook:Disconnect()
					particlehook = nil
				end
	
				for i, v in effects do
					if i.Parent then
						if i:IsA('Atmosphere') then
							i.Density = v
						else
							i.Enabled = v
						end
					end
				end
				table.clear(effects)
	
				for i, v in killeffects do
					bedwars.KillEffectController.killEffects[i] = v
				end
				table.clear(killeffects)
	
				for i, v in visualizers do
					bedwars.VisualizerUtils[i] = v
				end
				table.clear(visualizers)
	
				for i, v in particlesold do
					if i.Parent then
						i.Enabled = v
					end
				end
				table.clear(particlesold)
	
				if nametagold then
					bedwars.NametagController.addGameNametag = nametagold
					nametagold = nil
				end
	
				if technologyold then
					lightingService.Technology = technologyold
					technologyold = nil
				end
	
				if waterold then
					workspace.Terrain.WaterWaveSize = waterold.Size
					workspace.Terrain.WaterWaveSpeed = waterold.Speed
					workspace.Terrain.WaterReflectance = waterold.Reflectance
					workspace.Terrain.WaterTransparency = waterold.Transparency
					waterold = nil
				end
	
				for _, v in watching do
					v:Disconnect()
				end
				table.clear(watching)
	
				for i, v in hidden do
					if v.Parent then
						i.Parent = v
					end
				end
	
				table.clear(hidden)
				setSpeed(1)
	
				if qualityold then
					pcall(function()
						settings().Rendering.QualityLevel = qualityold
					end)
					qualityold = nil
				end
	
				if shadowsold ~= nil then
					lightingService.GlobalShadows = shadowsold
					shadowsold = nil
				end
			end
		end,
		Tooltip = 'Strips the parts of the scene that actually cost frames'
	})
	
	Cosmetics = FPSBooster:CreateToggle({
		Name = 'Cosmetics',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Hides everyone else\'s skins, the biggest win of the four.\nBodies and held items stay visible'
	})
	Animations = FPSBooster:CreateToggle({
		Name = 'Freeze animations',
		Function = function(callback)
			if FPSBooster.Enabled and not callback then
				setSpeed(1)
			end
	
			if FPSBooster.Enabled and callback then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Tooltip = 'Stops everyone else animating, they slide around instead.\nUnverified on your machine, A/B it yourself'
	})
	Clouds = FPSBooster:CreateToggle({
		Name = 'Clouds',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Removes the cloud decoration, around 700 parts on most maps'
	})
	Quality = FPSBooster:CreateToggle({
		Name = 'Render quality',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Drops the engine render quality to its lowest level'
	})
	Shadows = FPSBooster:CreateToggle({
		Name = 'Shadows',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Turns off global shadows'
	})
	Post = FPSBooster:CreateToggle({
		Name = 'Post effects',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Turns off sun rays, depth of field and colour correction, whole render passes the card does every frame.\nThe GUI blur is left alone'
	})
	Water = FPSBooster:CreateToggle({
		Name = 'Water',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Flattens terrain water, no waves and no reflection.\nOnly does anything on maps that have water'
	})
	Compatibility = FPSBooster:CreateToggle({
		Name = 'Compatibility lighting',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Drops the map to compatibility lighting, the cheapest renderer Roblox has'
	})
	Kill = FPSBooster:CreateToggle({
		Name = 'Kill effects',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Stops other peoples kill effects from playing'
	})
	Visualizer = FPSBooster:CreateToggle({
		Name = 'Visualizer',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Turns off the games own visual effect helpers'
	})
	Particles = FPSBooster:CreateToggle({
		Name = 'Particles',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Stops every particle, trail and beam in the map from rendering'
	})
	Nametags = FPSBooster:CreateToggle({
		Name = 'Nametags',
		Function = function()
			if FPSBooster.Enabled then
				FPSBooster:Toggle()
				FPSBooster:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Hides the game nametags once the match starts'
	})
end)

run(function()
    local BlockIn
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude
    local PlaceSpeed
    local LimitItem
    local Blacklist

    local function isBlacklisted(itemType)
        return Blacklist and table.find(Blacklist.ListEnabled, itemType)
    end

    local function getBlocks()
        local blocks = {}

        if LimitItem and LimitItem.Enabled then
            local itemType = store.hand.toolType == 'block' and store.hand.tool and store.hand.tool.Name
            local meta = itemType and bedwars.ItemMeta[itemType]
            local block = meta and meta.block
            if block and not isBlacklisted(itemType) and (store.hand.amount or 0) > 0 then
                table.insert(blocks, { itemType, block.health or 0, store.hand.tool, store.hand.amount })
            end
            return blocks
        end

        for _, item in store.inventory.inventory.items do
            local itemType = item.itemType
            local meta = itemType and bedwars.ItemMeta[itemType]
            local block = meta and meta.block
            if block and not isBlacklisted(itemType) and (item.amount or 0) > 0 then
                table.insert(blocks, { itemType, block.health or 0, item.tool, item.amount })
            end
        end
        table.sort(blocks, function(a, b)
            return a[2] > b[2]
        end)
        return blocks
    end

    local function getPyramid()
        return {
            Vector3.new(0, 0, 3),
            Vector3.new(0, 3, 3),
            Vector3.new(-3, 0, 0),
            Vector3.new(-3, 3, 0),
            Vector3.new(0, 0, -3),
            Vector3.new(0, 3, -3),
            Vector3.new(3, 0, 0),
            Vector3.new(3, 3, 0),
            Vector3.new(3, 6, 0),
            Vector3.new(0, 6, 0),
        }
    end

    local function isMoving()
        if not entitylib.isAlive then return false end
        local vel = entitylib.character.RootPart.AssemblyLinearVelocity
        return Vector3.new(vel.X, 0, vel.Z).Magnitude > 2
    end

    local function doBuild()
        local basePos = bedwars.BlockController:getBlockPosition(entitylib.character.RootPart.Position) * 3
        rayCheck.FilterDescendantsInstances = { lplr.Character, gameCamera }
        local oldPlaceCPS = bedwars.SharedConstants.BLOCK_PLACE_CPS
        bedwars.SharedConstants.BLOCK_PLACE_CPS = 20
        local blocks = getBlocks()
        if #blocks < 1 then
            notif('BlockIn', 'Missing blocks', 4, 'warning')
        end
        local pattern = getPyramid()
        local aborted = false
        for attempt = 1, 4 do
            if not BlockIn.Enabled or not entitylib.isAlive then break end
            for _, block in blocks do
                if not BlockIn.Enabled or not entitylib.isAlive then break end
                if (block[4] or 0) <= 0 then continue end
                local switched = false
                for _, pos in pattern do
                    if not BlockIn.Enabled or not entitylib.isAlive then break end
                    if isMoving() then
                        aborted = true
                        break
                    end
                    local target = basePos + pos
                    if getPlacedBlock(target) then continue end
                    if not switched then
                        for index, v in store.inventory.hotbar do
                            if v.item and v.item.tool == block[3] and index ~= (store.inventory.hotbarSlot + 1) then
                                hotbarSwitch(index - 1)
                                break
                            end
                        end
                        switched = true
                    end
                    bedwars.placeBlock(target, block[1])
                    local delay = PlaceSpeed.Value
                    if delay > 0 then task.wait(delay) end
                end
                if aborted then break end
            end
            if aborted then break end
            local complete = true
            for _, pos in pattern do
                if not getPlacedBlock(basePos + pos) then
                    complete = false
                    break
                end
            end
            if complete then break end
            task.wait(0.08)
        end
        bedwars.SharedConstants.BLOCK_PLACE_CPS = oldPlaceCPS or 13
        return aborted
    end

    BlockIn = vape.Categories.World:CreateModule({
        Name = 'AutoBlockIn',
        Function = function(callback)
            if callback then
                if not entitylib.isAlive then
                elseif LimitItem and LimitItem.Enabled and store.hand.toolType ~= 'block' then
                    notif('BlockIn', 'Hold a block first', 2, 'warning')
                else
                    doBuild()
                end
                if BlockIn.Enabled then
                    BlockIn:Toggle()
                end
            end
        end,
        Tooltip = 'auto places blocks around yo self'
    })

    PlaceSpeed = BlockIn:CreateSlider({
        Name = 'Placement Speed',
        Min = 0,
        Max = 0.5,
        Default = 0,
        Decimal = 100,
        Suffix = 'seconds',
    })
    LimitItem = BlockIn:CreateToggle({
        Name = 'Limit to items',
    })
    Blacklist = BlockIn:CreateTextList({
        Name = 'Blacklists',
        Placeholder = 'block',
        Default = {
            'cannon',
            'tnt',
            'siege_tnt',
        }
    })
end)

run(function()
	local ProjectileTrails
	local ColorMode
	local RedSlider
	local GreenSlider
	local BlueSlider
	local RGBTextList
	local RainbowSpeed
	local TrailLifetime
	local TrailWidth
	local OnlyLocal

	local activeTrails = {}
	local projectileNames = {
		arrow = true,
		telepearl = true,
		fireball = true,
		snowball = true,
		guided_missile = true,
		spectral_arrow = true,
		tactical_crossbow_arrow = true,
		carrot_cannon_projectile = true,
		glue_projectile = true,
		void_turret_projectile = true
	}

	-- Parse "255,0,0" or "255, 255, 255" string into Color3
	local function parseRGB(str)
		if not str or type(str) ~= 'string' then return nil end
		local r, g, b = str:match('(%d+)%s*[,%s]%s*(%d+)%s*[,%s]%s*(%d+)')
		if r and g and b then
			return Color3.fromRGB(
				math.clamp(tonumber(r) or 255, 0, 255),
				math.clamp(tonumber(g) or 255, 0, 255),
				math.clamp(tonumber(b) or 255, 0, 255)
			)
		end
		return nil
	end

	local function getTrailColor()
		local mode = ColorMode and ColorMode.Value or 'RGB Sliders'
		if mode == 'Rainbow' then
			local speed = RainbowSpeed and RainbowSpeed.Value or 1
			local hue = (tick() * (speed * 0.2)) % 1
			return Color3.fromHSV(hue, 1, 1)
		elseif mode == 'Custom Text' then
			if RGBTextList and RGBTextList.List and #RGBTextList.List > 0 then
				local text = RGBTextList.List[1]
				local parsed = parseRGB(text)
				if parsed then return parsed end
			end
		end

		local r = RedSlider and RedSlider.Value or 255
		local g = GreenSlider and GreenSlider.Value or 255
		local b = BlueSlider and BlueSlider.Value or 255
		return Color3.fromRGB(r, g, b)
	end

	local function attachTrail(projectile)
		if not projectile or not projectile.Parent then return end
		if activeTrails[projectile] then return end

		local targetPart = projectile:IsA('BasePart') and projectile or projectile:FindFirstChildWhichIsA('BasePart') or projectile.PrimaryPart
		if not targetPart then
			task.spawn(function()
				targetPart = projectile:WaitForChild('Handle', 1) or projectile:FindFirstChildWhichIsA('BasePart')
				if targetPart then attachTrail(projectile) end
			end)
			return
		end

		if OnlyLocal and OnlyLocal.Enabled then
			local shooterAttr = projectile:GetAttribute('ProjectileShooter')
			if shooterAttr and shooterAttr ~= lplr.UserId then
				return
			end
		end

		local color = getTrailColor()
		local lifetime = TrailLifetime and TrailLifetime.Value or 0.8
		local width = TrailWidth and TrailWidth.Value or 0.4

		local a0 = Instance.new('Attachment')
		a0.Name = 'TrailA0'
		a0.Position = Vector3.new(0, width / 2, 0)
		a0.Parent = targetPart

		local a1 = Instance.new('Attachment')
		a1.Name = 'TrailA1'
		a1.Position = Vector3.new(0, -width / 2, 0)
		a1.Parent = targetPart

		local trail = Instance.new('Trail')
		trail.Name = 'CustomProjectileTrail'
		trail.Attachment0 = a0
		trail.Attachment1 = a1
		trail.Lifetime = lifetime
		trail.Color = ColorSequence.new(color)
		trail.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(1, 1)
		})
		trail.LightEmission = 1
		trail.LightInfluence = 0
		trail.FaceCamera = true
		trail.Parent = targetPart

		activeTrails[projectile] = { trail = trail, a0 = a0, a1 = a1 }

		projectile.AncestryChanged:Connect(function(_, parent)
			if not parent then
				if trail and trail.Parent then
					trail.Parent = workspace
					a0.Parent = workspace.Terrain
					a1.Parent = workspace.Terrain
					task.delay(lifetime, function()
						pcall(function() trail:Destroy() end)
						pcall(function() a0:Destroy() end)
						pcall(function() a1:Destroy() end)
					end)
				end
				activeTrails[projectile] = nil
			end
		end)
	end

	local function checkProjectile(obj)
		if not obj then return end
		local name = obj.Name:lower()
		if projectileNames[name] or name:find('arrow') or name:find('pearl') or name:find('projectile') or name:find('missile') then
			attachTrail(obj)
		end
	end

	ProjectileTrails = vape.Categories.Render:CreateModule({
		Name = 'ProjectileTrails',
		Function = function(callback)
			if callback then
				for _, obj in ipairs(workspace:GetChildren()) do checkProjectile(obj) end

				local conn1 = workspace.ChildAdded:Connect(function(child)
					task.wait()
					checkProjectile(child)
				end)
				ProjectileTrails:Clean(function() if conn1 then conn1:Disconnect() end end)

				if bedwars and bedwars.SyncEvents and bedwars.SyncEvents.ProjectileLaunched then
					local conn2 = bedwars.SyncEvents.ProjectileLaunched:connect(function(data)
						task.wait()
						for _, obj in ipairs(workspace:GetChildren()) do
							if obj.Name:lower() == tostring(data.projectileType):lower() and not activeTrails[obj] then
								attachTrail(obj)
								break
							end
						end
					end)
					ProjectileTrails:Clean(function() if conn2 and conn2.Disconnect then conn2:Disconnect() end end)
				end

				task.spawn(function()
					while ProjectileTrails.Enabled do
						local col = getTrailColor()
						for proj, data in pairs(activeTrails) do
							if data.trail and data.trail.Parent then
								data.trail.Color = ColorSequence.new(col)
							end
						end
						task.wait(0.05)
					end
				end)
			else
				for proj, data in pairs(activeTrails) do
					pcall(function() data.trail:Destroy() end)
					pcall(function() data.a0:Destroy() end)
					pcall(function() data.a1:Destroy() end)
				end
				table.clear(activeTrails)
			end
		end,
		Tooltip = 'Leaves custom colored trails behind fired projectiles'
	})

	ColorMode = ProjectileTrails:CreateDropdown({
		Name = 'Color Mode',
		List = {'RGB Sliders', 'Custom Text', 'Rainbow'},
		Default = 'RGB Sliders'
	})

	RedSlider = ProjectileTrails:CreateSlider({
		Name = 'Red',
		Min = 0,
		Max = 255,
		Default = 255,
		Tooltip = 'Red channel (0-255)'
	})

	GreenSlider = ProjectileTrails:CreateSlider({
		Name = 'Green',
		Min = 0,
		Max = 255,
		Default = 0,
		Tooltip = 'Green channel (0-255)'
	})

	BlueSlider = ProjectileTrails:CreateSlider({
		Name = 'Blue',
		Min = 0,
		Max = 255,
		Default = 255,
		Tooltip = 'Blue channel (0-255)'
	})

	RGBTextList = ProjectileTrails:CreateTextList({
		Name = 'RGB Input',
		Default = {'255, 0, 0', '255, 255, 255'},
		Tooltip = 'Type exact RGB values like 255,0,0 or 255,255,255'
	})

	RainbowSpeed = ProjectileTrails:CreateSlider({
		Name = 'Rainbow Speed',
		Min = 1,
		Max = 10,
		Default = 3
	})

	TrailLifetime = ProjectileTrails:CreateSlider({
		Name = 'Lifetime',
		Min = 0.1,
		Max = 3,
		Default = 0.8,
		Decimal = 10,
		Suffix = 's'
	})

	TrailWidth = ProjectileTrails:CreateSlider({
		Name = 'Width',
		Min = 0.1,
		Max = 2,
		Default = 0.4,
		Decimal = 10,
		Suffix = 'studs'
	})

	OnlyLocal = ProjectileTrails:CreateToggle({
		Name = 'Only Local',
		Default = false,
		Tooltip = 'Only render trails on your own projectiles'
	})
end)

run(function()
	local DeathAdderAimbot
	local Mode
	local BedRange
	local Targets
	local Sort
	local TargetPart
	local FOV
	
	local old
	
	local function getBed(localPosition)
		local closest, magnitude = nil, BedRange.Value
		for _, bed in collectionService:GetTagged('bed') do
			if not bed:GetAttribute(`Team{lplr:GetAttribute('Team') or -1}NoBreak`) then
				local mag = (localPosition - bed.Position).Magnitude
				if mag <= magnitude then
					closest, magnitude = bed, mag
				end
			end
		end
		return closest
	end
	
	local function getAim(localPosition)
		if Mode.Value == 'Bed' then
			local bed = getBed(localPosition)
			return bed and bed.Position or nil
		end
	
		local ent = entitylib.EntityMouse({
			Range = FOV.Value,
			Part = 'RootPart',
			Wallcheck = Targets.Walls.Enabled,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Origin = localPosition,
			Sort = sortmethods[Sort.Value]
		})
		if not ent then return nil end
	
		targetinfo.Targets[ent] = tick() + 1
		local tierdata = bedwars.SorcererBalance.getSorcererTierData(bedwars.SorcererBalance.getSorcererTier(lplr))
		local aim = ent[TargetPart.Value].Position
		local speed = tierdata and tierdata.projectileVelocity or 70
		return aim + (ent.RootPart.AssemblyLinearVelocity * ((aim - localPosition).Magnitude / speed))
	end
	
	DeathAdderAimbot = vape.Categories.Blatant:CreateModule({
		Name = 'DeathAdderAimbot',
		Function = function(callback)
			if callback then
				old = bedwars.SorcererController.getProjectileDirection
				bedwars.SorcererController.getProjectileDirection = function(self, ...)
					if entitylib.isAlive then
						local localPosition = entitylib.character.RootPart.Position
						local aim = getAim(localPosition)
						if aim and aim ~= localPosition then
							return (aim - localPosition).Unit
						end
					end
	
					return old(self, ...)
				end
			else
				bedwars.SorcererController.getProjectileDirection = old
			end
		end,
		Tooltip = 'deathadderaimbot for your shitty ass aim'
	})
	Mode = DeathAdderAimbot:CreateDropdown({
		Name = 'Mode',
		List = {'Player', 'Bed'},
		Function = function(val)
			if BedRange then
				BedRange.Object.Visible = val == 'Bed'
				FOV.Object.Visible = val == 'Player'
				TargetPart.Object.Visible = val == 'Player'
				Sort.Object.Visible = val == 'Player'
			end
		end,
		Tooltip = 'aims at the bed'
	})
	BedRange = DeathAdderAimbot:CreateSlider({
		Name = 'Bed range',
		Min = 1,
		Max = 60,
		Default = 60,
		Darker = true,
		Visible = false,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	Targets = DeathAdderAimbot:CreateTargets({
		Players = true,
		Walls = true
	})
	local methods = {'Distance', 'Damage'}
	for i in sortmethods do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	Sort = DeathAdderAimbot:CreateDropdown({
		Name = 'Target mode',
		List = methods,
		Default = 'Distance',
		Darker = true
	})
	TargetPart = DeathAdderAimbot:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head'},
		Darker = true
	})
	FOV = DeathAdderAimbot:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000,
		Darker = true
	})
end)


run(function()
    local BedPlates
    local Background
    local TeamColor
    local Color = {}
    local Reference = {}
    local BlockCache = {}
	local LayerCounter
	local LayerColor
	local UIStyle
	local PositionDropdown
	local IgnoreTeam
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local compactUI = Instance.new('ScreenGui')
    compactUI.Name = 'BedPlatesCompactUI'
    compactUI.Parent = vape.gui
    compactUI.Enabled = false
    compactUI.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    compactUI.DisplayOrder = 10
    compactUI.ResetOnSpawn = false
    local compactMainFrame = Instance.new('Frame')
    compactMainFrame.Name = 'MainFrame'
    compactMainFrame.Parent = compactUI
    compactMainFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
    compactMainFrame.BackgroundTransparency = 0.3
    compactMainFrame.BorderSizePixel = 0
    compactMainFrame.Position = UDim2.new(1, -8, 1, -8)
    compactMainFrame.Size = UDim2.new(0, 150, 0, 0)
    compactMainFrame.AutomaticSize = Enum.AutomaticSize.Y
    compactMainFrame.AnchorPoint = Vector2.new(1, 1)
    local compactCorner = Instance.new('UICorner')
    compactCorner.CornerRadius = UDim.new(0, 8)
    compactCorner.Parent = compactMainFrame
    local compactListLayout = Instance.new('UIListLayout')
    compactListLayout.Padding = UDim.new(0, 4)
    compactListLayout.SortOrder = Enum.SortOrder.LayoutOrder
    compactListLayout.Parent = compactMainFrame
    local compactPadding = Instance.new('UIPadding')
    compactPadding.PaddingTop = UDim.new(0, 6)
    compactPadding.PaddingBottom = UDim.new(0, 6)
    compactPadding.PaddingLeft = UDim.new(0, 6)
    compactPadding.PaddingRight = UDim.new(0, 6)
    compactPadding.Parent = compactMainFrame
    
	local teamColors = getgenv().aeroTeamColors
    
    local function getBedTeamColor(bed)
        local teamId = bed:GetAttribute('TeamID') or bed:GetAttribute('Team') or bed:GetAttribute('TeamId')
        teamId = tonumber(teamId)
        if teamId and teamColors[teamId] then
            return teamColors[teamId]
        end
        return {name = 'Enemy', color = Color3.new(1, 1, 1)}
    end
    
    local function isMyBed(bed)
        local myTeam = lplr.Character and (lplr.Character:GetAttribute('Team') or lplr.Character:GetAttribute('TeamId'))
        local bedTeam = bed:GetAttribute('TeamID') or bed:GetAttribute('Team') or bed:GetAttribute('TeamId')
        if not myTeam or not bedTeam then return false end
        return tonumber(myTeam) == tonumber(bedTeam)
    end
    
	local function updateLayerTextColor()
		for _, ref in pairs(Reference) do
			for _, img in ref.billboard.Frame:GetChildren() do
				if img:IsA('ImageLabel') then
					local txt = img:FindFirstChild('Amount')
					if txt then
						txt.TextColor3 = LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.fromRGB(250,250,250)
					end
				end
			end
		end
	end

    local function scanSide(self, start, tab, dirsHit)
		local checkDirs = {
			Vector3.new(3,0,0), Vector3.new(-3,0,0),
			Vector3.new(0,0,3), Vector3.new(0,0,-3),
			Vector3.new(3,0,3), Vector3.new(3,0,-3),
			Vector3.new(-3,0,3), Vector3.new(-3,0,-3),
			Vector3.new(0,3,0),
		}
		for _, side in ipairs(checkDirs) do
			for i = 1, 15 do
				local block = getPlacedBlock(start + (side * i))
				if not block or block == self or block.Name == 'bed' then break end
				if not block:GetAttribute('NoBreak') then
					tab[block.Name] = math.max(tab[block.Name] or 0, i)
					dirsHit[block.Name] = dirsHit[block.Name] or {}
					dirsHit[block.Name][tostring(side)] = true
				end
			end
		end
    end

	local function getBlockHealth(blck)
		local meta = bedwars.ItemMeta[blck]
		if not meta then  return 0 end
		local blockmeta = meta.block
		if not blockmeta then  return 0 end
		return blockmeta.health or 0
	end
    
    local BedTotals = {}

    local function getBedLayers(bed)
		local start = bedwars.BlockController:getBlockPosition(bed.Position) * 3
		local layers = {}
		local dirsHit = {}
		local founded = {}
		scanSide(bed, start, layers, dirsHit)
		scanSide(bed, start + Vector3.new(0,0,3), layers, dirsHit)
		for blocks, amount in layers do 
			local coverage = 0
			for _ in pairs(dirsHit[blocks] or {}) do
				coverage = coverage + 1
			end
			if coverage >= 5 then
				table.insert(founded, {blocks, amount})
			end
		end
		table.sort(founded, function(a,b)
			local healthA, healthB = getBlockHealth(a[1]), getBlockHealth(b[1])			
			return healthA == healthB and a[1] < b[1] or healthA > healthB
		end)
		return founded
    end

    local function renderLayers(frame, founded)
		for _, obj in frame:GetChildren() do
			if obj and (obj:IsA("ImageLabel") and obj.Name ~= 'Blur') then
				obj:Destroy()
			end
		end
		for _, data in founded do
			local block, amt = data[1], data[2]
			local image = Instance.new('ImageLabel')
			image.Size = UDim2.fromOffset(32,32)
			image.BackgroundTransparency = 1
			image.Image = bedwars.getIcon({itemType=block}, true)
			image.Parent = frame
			if amt >= 1 and (not LayerCounter or LayerCounter.Enabled) then
				local txt = Instance.new('TextLabel')
				txt.Name = 'Amount'
				txt.Size = UDim2.fromScale(1,1)
				txt.BackgroundTransparency = 1
				local newamt = amt
				txt.Text = tostring(newamt)
				txt.TextColor3 = LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.fromRGB(250,250,250)
				txt.TextSize = 24
				txt.TextStrokeTransparency = 0.3
				txt.Font = Enum.Font.Arial
				txt.Parent = image
			end
		end
    end

    local function refreshAdornee(v)
		local bed = v.Adornee
		local founded = getBedLayers(bed)
		local total = 0
		for _, data in founded do total = math.max(total, data[2]) end
		BedTotals[bed] = total
		local mine = isMyBed(bed)
		v.Enabled = #founded > 0 and UIStyle.Value == 'Original' and not mine
		renderLayers(v.Frame, founded)
		if Reference[bed] and Reference[bed].compactRow then
			renderLayers(Reference[bed].compactRow.iconsFrame, founded)
			Reference[bed].compactRow.countLabel.Text = tostring(total)
			Reference[bed].compactRow.frame.Visible = #founded > 0 and not (mine and IgnoreTeam and IgnoreTeam.Enabled)
		end
    end
    
    local function Added(v)
        if Reference[v] then return end
        local _bpUserId = v:GetAttribute('PlacedByUserId')
        if _bpUserId then
            local _bpOk, _bpOwner = pcall(function() return playersService:GetPlayerByUserId(_bpUserId) end)
        end
        
        local billboard = Instance.new('BillboardGui')
        billboard.Parent = Folder
        billboard.Name = 'bed'
        billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
        billboard.Size = UDim2.fromOffset(36, TeamColor.Enabled and 50 or 36)
        billboard.AlwaysOnTop = true
        billboard.ClipsDescendants = false
        billboard.Adornee = v
        billboard.Enabled = UIStyle.Value == 'Original'
        
        local blur = addBlur(billboard)
        blur.Visible = Background.Enabled
        
        local frame = Instance.new('Frame')
        frame.Size = TeamColor.Enabled and UDim2.new(1, 0, 1, -16) or UDim2.fromScale(1, 1)
        frame.Position = TeamColor.Enabled and UDim2.new(0, 0, 0, 16) or UDim2.new(0, 0, 0, 0)
        frame.BackgroundColor3 = TeamColor.Enabled and getBedTeamColor(v).color or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        frame.BackgroundTransparency = 1 - (Background.Enabled and (TeamColor.Enabled and 0.5 or Color.Opacity) or 0)
        frame.Parent = billboard

        local teamLabel = Instance.new('TextLabel')
        teamLabel.Name = 'TeamLabel'
        teamLabel.Size = UDim2.new(1, 0, 0, 14)
        teamLabel.Position = UDim2.new(0, 0, 0, 0)
        teamLabel.BackgroundTransparency = 1
        teamLabel.Text = getBedTeamColor(v).name
        teamLabel.TextColor3 = getBedTeamColor(v).color
        teamLabel.TextSize = 13
        teamLabel.Font = Enum.Font.GothamBold
        teamLabel.TextStrokeTransparency = 0.4
        teamLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
        teamLabel.Visible = TeamColor.Enabled
        teamLabel.Parent = billboard
        
        local layout = Instance.new('UIListLayout')
        layout.FillDirection = Enum.FillDirection.Horizontal
        layout.Padding = UDim.new(0, 4)
        layout.VerticalAlignment = Enum.VerticalAlignment.Center
        layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
        layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
            billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 4, 36), TeamColor.Enabled and 50 or 36)
        end)
        layout.Parent = frame
        
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 4)
        corner.Parent = frame

        local rowFrame = Instance.new('Frame')
        rowFrame.BackgroundTransparency = 1
        rowFrame.Size = UDim2.new(1, 0, 0, 50)
        rowFrame.LayoutOrder = #compactMainFrame:GetChildren()
        rowFrame.Visible = false
        rowFrame.Parent = compactMainFrame

        local rowTeamLabel = Instance.new('TextLabel')
        rowTeamLabel.Size = UDim2.new(1, 0, 0, 14)
        rowTeamLabel.BackgroundTransparency = 1
        rowTeamLabel.Text = getBedTeamColor(v).name
        rowTeamLabel.TextColor3 = getBedTeamColor(v).color
        rowTeamLabel.TextSize = 13
        rowTeamLabel.Font = Enum.Font.GothamBold
        rowTeamLabel.TextStrokeTransparency = 0.4
        rowTeamLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
        rowTeamLabel.Parent = rowFrame

        local rowBG = Instance.new('Frame')
        rowBG.Position = UDim2.new(0, 0, 0, 16)
        rowBG.Size = UDim2.new(1, 0, 0, 34)
        rowBG.BackgroundColor3 = Color3.new(0, 0, 0)
        rowBG.BackgroundTransparency = 0.3
        rowBG.Parent = rowFrame

        local rowCorner = Instance.new('UICorner')
        rowCorner.CornerRadius = UDim.new(0, 4)
        rowCorner.Parent = rowBG

        local rowIcons = Instance.new('Frame')
        rowIcons.BackgroundTransparency = 1
        rowIcons.Size = UDim2.new(1, -30, 1, 0)
        rowIcons.Parent = rowBG

        local rowIconLayout = Instance.new('UIListLayout')
        rowIconLayout.FillDirection = Enum.FillDirection.Horizontal
        rowIconLayout.Padding = UDim.new(0, 2)
        rowIconLayout.VerticalAlignment = Enum.VerticalAlignment.Center
        rowIconLayout.Parent = rowIcons

        local rowCount = Instance.new('TextLabel')
        rowCount.Size = UDim2.new(0, 28, 1, 0)
        rowCount.Position = UDim2.new(1, -28, 0, 0)
        rowCount.BackgroundTransparency = 1
        rowCount.Text = "0"
        rowCount.TextColor3 = Color3.fromRGB(255, 255, 255)
        rowCount.TextSize = 14
        rowCount.Font = Enum.Font.GothamBold
        rowCount.Parent = rowBG

        Reference[v] = {
            billboard = billboard,
            compactRow = {
                frame = rowFrame,
                iconsFrame = rowIcons,
                countLabel = rowCount
            }
        }
        BlockCache[v] = ""
        refreshAdornee(billboard)
    end
    
    local _refreshNearPending = false
    local function refreshNear(data)
        if _refreshNearPending then return end
        _refreshNearPending = true
        task.defer(function()
            _refreshNearPending = false
            local blockPos = data.blockRef.blockPosition * 3
            local maxDistanceSq = 30 * 30
            for bed, ref in pairs(Reference) do
                if bed.Parent then
                    local offset = blockPos - bed.Position
                    local distanceSq = offset.X * offset.X + offset.Y * offset.Y + offset.Z * offset.Z
                    if distanceSq <= maxDistanceSq then
                        refreshAdornee(ref.billboard)
                    end
                end
            end
        end)
    end

    local currentCorner = 'Bottom Right'

    local function updateCompactPosition()
        local genUI = vape.gui:FindFirstChild('GeneratorCompactUI')
        local offset = 8
        if genUI and genUI.Enabled and currentCorner == 'Bottom Right' then
            offset = offset + 128
        end
        local invHost = (gethui and gethui()) or game:GetService('CoreGui')
        if invHost:FindFirstChild('InventoryESP') and (currentCorner == 'Bottom Right' or currentCorner == 'Top Right') then
            offset = offset + 200
        end
        if currentCorner == 'Top Right' then
            compactMainFrame.AnchorPoint = Vector2.new(1, 0)
            compactMainFrame.Position = UDim2.new(1, -offset, 0, 8)
        elseif currentCorner == 'Top Left' then
            compactMainFrame.AnchorPoint = Vector2.new(0, 0)
            compactMainFrame.Position = UDim2.new(0, 8, 0, 8)
        elseif currentCorner == 'Bottom Left' then
            compactMainFrame.AnchorPoint = Vector2.new(0, 1)
            compactMainFrame.Position = UDim2.new(0, 8, 1, -8)
        else
            compactMainFrame.AnchorPoint = Vector2.new(1, 1)
            compactMainFrame.Position = UDim2.new(1, -offset, 1, -8)
        end
    end
    
    BedPlates = vape.Categories.Minigames:CreateModule({
        Name = 'BedPlates',
        Function = function(callback)
            if callback then
                table.clear(BlockCache)
                compactUI.Enabled = UIStyle.Value == 'Compact'
                
                local tagged = collectionService:GetTagged('bed')
                for _, v in ipairs(tagged) do 
                    Added(v)
                end
                
                BedPlates:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(refreshNear))
                BedPlates:Clean(vapeEvents.BreakBlockEvent.Event:Connect(refreshNear))
                BedPlates:Clean(collectionService:GetInstanceAddedSignal('bed'):Connect(Added))

                local worldFolder = getWorldFolder()
                local blocksFolder = worldFolder and worldFolder:FindFirstChild('Blocks')
                if blocksFolder then
                    local function onBlockChange(obj)
                        if not (obj:IsA('BasePart')) then return end
                        refreshNear({blockRef = {blockPosition = obj.Position / 3}})
                    end
                    BedPlates:Clean(blocksFolder.ChildAdded:Connect(onBlockChange))
                    BedPlates:Clean(blocksFolder.ChildRemoved:Connect(onBlockChange))
                end
                BedPlates:Clean(collectionService:GetInstanceRemovedSignal('bed'):Connect(function(v)
                    if Reference[v] then
                        Reference[v].billboard:Destroy()
                        Reference[v].compactRow.frame:Destroy()
                        Reference[v] = nil
                        BlockCache[v] = nil
                    end
                end))
                BedPlates:Clean(runService.Heartbeat:Connect(updateCompactPosition))
                BedPlates:Clean(runService.Heartbeat:Connect(function()
                    if not TeamColor.Enabled and Background.Enabled then
                        local col = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                        for bed, ref in pairs(Reference) do
                            ref.billboard.Frame.BackgroundColor3 = col
                        end
                    end
                    if LayerCounter.Enabled then
                        updateLayerTextColor()
                    end
                end))
            else
                for _, v in pairs(Reference) do
                    v.billboard:Destroy()
                    v.compactRow.frame:Destroy()
                end
                table.clear(Reference)
                table.clear(BlockCache)
                compactUI.Enabled = false
            end
        end,
        Tooltip = 'shows enemys bed defence'
    })

    UIStyle = BedPlates:CreateDropdown({
        Name = 'UI Style',
        List = {'Original', 'Compact'},
        Default = 'Original',
        Function = function(val)
            local isOriginal = val == 'Original'
            compactUI.Enabled = BedPlates.Enabled and not isOriginal
            for bed, ref in pairs(Reference) do
                ref.billboard.Enabled = isOriginal
                refreshAdornee(ref.billboard)
            end
            if PositionDropdown.Object then
                PositionDropdown.Object.Visible = not isOriginal
            end
            if IgnoreTeam and IgnoreTeam.Object then
                IgnoreTeam.Object.Visible = not isOriginal
            end
        end,
        Tooltip = 'pick between the floating world esp or a corner panel'
    })

    PositionDropdown = BedPlates:CreateDropdown({
        Name = 'Position',
        List = {'Top Right', 'Top Left', 'Bottom Left', 'Bottom Right'},
        Default = 'Bottom Right',
        Function = function(val)
            currentCorner = val
            updateCompactPosition()
        end,
        Tooltip = 'pick w corner u want the panel chillin in'
    })

    task.defer(function()
        if PositionDropdown and PositionDropdown.Object then
            PositionDropdown.Object.Visible = (UIStyle.Value == 'Compact')
        end
        if IgnoreTeam and IgnoreTeam.Object then
            IgnoreTeam.Object.Visible = (UIStyle.Value == 'Compact')
        end
    end)
    
    IgnoreTeam = BedPlates:CreateToggle({
        Name = 'Ignore Team',
        Default = false,
        Function = function(callback)
            for bed, ref in pairs(Reference) do
                refreshAdornee(ref.billboard)
            end
        end,
        Tooltip = 'wont show ur own team bed on the compact panel'
    })
    
    Background = BedPlates:CreateToggle({
        Name = 'Background',
        Function = function(callback)
            if Color.Object then 
                Color.Object.Visible = callback and not TeamColor.Enabled
            end
            for _, v in pairs(Reference) do
                v.Frame.BackgroundTransparency = 1 - (callback and (TeamColor.Enabled and 0.5 or Color.Opacity) or 0)
                local blur = v:FindFirstChild('Blur')
                if blur then
                    blur.Visible = callback
                end
            end
        end,
        Default = true
    })

    Color = BedPlates:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for bed, v in pairs(Reference) do
                if not TeamColor.Enabled then
                    v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
                end
                if Background.Enabled and not TeamColor.Enabled then
                    v.Frame.BackgroundTransparency = 1 - opacity
                end
            end
        end,
        Visible = false,
        Darker = true
    })
    
    TeamColor = BedPlates:CreateToggle({
        Name = 'Team Color',
        Default = true,
        Function = function(callback)
            if Color.Object then
                Color.Object.Visible = Background.Enabled and not callback
            end
            for bed, billboard in pairs(Reference) do
                billboard.Frame.BackgroundColor3 = callback and getBedTeamColor(bed).color or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                billboard.Frame.BackgroundTransparency = 1 - (Background.Enabled and (callback and 0.5 or Color.Opacity) or 0)
            end
        end
    })

	LayerCounter = BedPlates:CreateToggle({
		Name = 'Layer Counter',
		Function = function(callback)
			if LayerColor and LayerColor.Object then
				LayerColor.Object.Visible = callback
			end
			for _, billboard in pairs(Reference) do
				refreshAdornee(billboard)
			end
		end,
		Default = true
	})
	LayerColor = BedPlates:CreateColorSlider({
		Name = 'Counter Text Color',
		DefaultSat = 1,
		DefaultValue = 1,
		Function = function()
			updateLayerTextColor()
		end,
		Visible = LayerCounter.Enabled
	})	
end)

run(function()
	local AutoBedDefence
	local LimitItemToggle
	local AutoSwitchToggle
	local RangeSlider
	local LayerSlider
	
	local currentLayer = 1
	local buildingComplete = false
	local heldBlockType = nil
	local previousSlot = nil
	local lastPlaceTime = 0

	local ALLOWED_BLOCKS = {
		obsidian = true,
		wood_plank_oak = true,
		wood_oak_plank = true,
		ceramic = true,
		stone_brick = true
	}

	local function isAllowedBlock(itemType)
		if ALLOWED_BLOCKS[itemType] then return true end
		return itemType:find('wool') ~= nil
	end

	local function getPyramidPositions(size, gridSize)
		local positions = {}
		for height = size, 0, -1 do
			for width = height, 0, -1 do
				table.insert(positions, Vector3.new(width, (size - height), ((height + 1) - width)) * gridSize)
				table.insert(positions, Vector3.new(width * -1, (size - height), ((height + 1) - width)) * gridSize)
				table.insert(positions, Vector3.new(width, (size - height), (height - width) * -1) * gridSize)
				table.insert(positions, Vector3.new(width * -1, (size - height), (height - width) * -1) * gridSize)
			end
		end
		return positions
	end

	local function getMyBed()
		local myTeam = lplr:GetAttribute('Team')
		if not myTeam then return nil end
		
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return nil end
		
		for _, bed in collectionService:GetTagged('bed') do
			if bed and bed.Parent and bed:GetAttribute('Team'..myTeam..'NoBreak') then
				local bedPos = bed:IsA('BasePart') and bed.Position or (bed.PrimaryPart and bed.PrimaryPart.Position or bed:GetPivot().Position)
				if (root.Position - bedPos).Magnitude < 40 then
					return bed
				end
			end
		end
		return nil
	end

	local function getAvailableBlocks()
		local blocks = {}
		for _, item in store.inventory.inventory.items do
			local meta = bedwars.ItemMeta[item.itemType]
			if meta and meta.block and not meta.block.seeThrough and (item.amount or 0) > 0 and isAllowedBlock(item.itemType) then
				table.insert(blocks, {itemType = item.itemType, tool = item.tool, health = meta.block.health or 0})
			end
		end
		table.sort(blocks, function(a, b) return a.health > b.health end)
		return blocks
	end

	local function getBestBlockForLayer(blocks)
		if #blocks == 0 then return nil end
		return blocks[1]
	end

	local function getHotbarSlotForBlock(itemType)
		for i, v in store.inventory.hotbar do
			if v.item and v.item.itemType == itemType then
				return i - 1
			end
		end
		return nil
	end

	local function getBlockInHand()
		if store.hand.toolType ~= 'block' then return nil end
		local handBlockName = store.hand.tool.Name
		if isAllowedBlock(handBlockName) then
			return {itemType = handBlockName}
		end
		return nil
	end

	local function restorePreviousSlot()
		if heldBlockType then
			if previousSlot then hotbarSwitch(previousSlot) end
			heldBlockType = nil
			previousSlot = nil
		end
	end

	local function switchToBlock(itemType)
		if LimitItemToggle.Enabled then return end
		if not AutoSwitchToggle.Enabled then return end
		if heldBlockType == itemType then return end
		
		local slot = getHotbarSlotForBlock(itemType)
		if slot then
			previousSlot = previousSlot or store.inventory.hotbarSlot
			hotbarSwitch(slot)
			heldBlockType = itemType
		end
	end

	local function isPositionInRange(worldPos)
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return false end
		return (root.Position - worldPos).Magnitude <= RangeSlider.Value
	end

	local function buildLayer(bedCFrame, blocks, layer)
		local block = nil
		
		if LimitItemToggle.Enabled then
			block = getBlockInHand()
			if not block then return false end
		else
			block = getBestBlockForLayer(blocks) or (blocks[1] or nil)
			if not block then return false end
		end

		local positions = getPyramidPositions(layer, 3)
		local allPlaced = true
		local hasMissingInRange = false

		for _, pos in positions do
			local worldPos = (bedCFrame * CFrame.new(pos)).Position
			if not getPlacedBlock(worldPos) then
				allPlaced = false
				if isPositionInRange(worldPos) then
					hasMissingInRange = true
				end
			end
		end

		if not hasMissingInRange then return false end

		for _, pos in positions do
			if not AutoBedDefence.Enabled then break end
			local worldPos = (bedCFrame * CFrame.new(pos)).Position
			if isPositionInRange(worldPos) and not getPlacedBlock(worldPos) then
				if tick() - lastPlaceTime >= 0.05 then
					switchToBlock(block.itemType)
					task.spawn(bedwars.placeBlock, worldPos, block.itemType, false)
					lastPlaceTime = tick()
					task.wait(0.05)
				end
			end
		end
		return true
	end

	AutoBedDefence = vape.Categories.World:CreateModule({
		Name = 'AutoBedDefence',
		Function = function(enabled)
			if enabled then
				currentLayer = 1
				buildingComplete = false
				heldBlockType = nil
				previousSlot = nil
				
				repeat
					pcall(function()
						if not entitylib.isAlive then return end
						
						local bed = getMyBed()
						if not bed then
							restorePreviousSlot()
							return
						end
						
						local bedCFrame = bed:IsA('BasePart') and bed.CFrame or (bed.PrimaryPart and bed.PrimaryPart.CFrame or bed:GetPivot())
						local blocks = getAvailableBlocks()
						
						if LimitItemToggle.Enabled then
							if not getBlockInHand() then return end
						else
							if #blocks == 0 then return end
						end
						
						if currentLayer <= LayerSlider.Value then
							buildLayer(bedCFrame, blocks, currentLayer)
							currentLayer += 1
						else
							buildingComplete = true
							restorePreviousSlot()
							notif('AutoBedDefence', 'AutoBedDefence completed!', 4)
						end
					end)
					task.wait(0.05)
				until not AutoBedDefence.Enabled or buildingComplete
				
				restorePreviousSlot()
			end
		end,
		Tooltip = 'Automatically protects your bed with pyramid layers'
	})

	LimitItemToggle = AutoBedDefence:CreateToggle({
		Name = 'Limit to Hand',
		Tooltip = 'Only use the block currently in your hand'
	})
	
	AutoSwitchToggle = AutoBedDefence:CreateToggle({
		Name = 'Auto Switch',
		Default = true,
		Tooltip = 'Auto switch to block then back when finished'
	})
	
	RangeSlider = AutoBedDefence:CreateSlider({
		Name = 'Place Range',
		Min = 1,
		Max = 30,
		Default = 15,
		Suffix = ' studs'
	})
	
	LayerSlider = AutoBedDefence:CreateSlider({
		Name = 'Layers',
		Min = 1,
		Max = 5,
		Default = 3,
		Suffix = ' layers'
	})
end)

run(function()
	local Nuker
	local TargetMode
	local Mode
	local Range
	local BreakSpeed
	local UpdateRate
	local Bed
	local BedCheck
	local LuckyBlock
	local IronOre
	local Tesla
	local Hive
	local Pinata
	local Crops
	local Effect
	local CustomHealth = {}
	local Animation
	local SelfBreak
	local LimitItem
	local AutoTool
	local Snow
	local ShowPath
	local BlockHighlight
	local NukerHighlightColor
	local NukerAngle
	local BlockBreakMode
	local ClosestBreak
	local ViewAngle
	local PlayerCheck
	local SmartBreak
	local Priority

	local blockHighlightInstance
	local parts = {}
	local cachedTeammates = {}
	local cachedTeammatesTime = 0
	local breakabilityCache = {}
	local BREAK_CACHE_TTL = 0.35

	local legitRoute = {}
	local legitTarget = nil
	local legitAnchor = nil
	local legitLastPlayerPos = nil
	local legitLastHit = 0

	local _hbMounted = nil
	local _hbPart = nil
	local _hbProgressRef = nil
	local _hbBlock = nil
	local _hbUpdateConnection = nil

	local ActiveBlock
	local NextBreak = 0
	local PathShown = false

	local MouseParams = RaycastParams.new()
	MouseParams.FilterType = Enum.RaycastFilterType.Exclude
	local MouseOrigin, MouseDirection, MouseHit = Vector3.zero, Vector3.zero, nil
	local PlayerParams = RaycastParams.new()
	PlayerParams.FilterType = Enum.RaycastFilterType.Include

	local function screenPoint()
		if inputService.TouchEnabled then
			return gameCamera.ViewportSize / 2
		end
		return inputService:GetMouseLocation()
	end

	local function frontPoint()
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return nil end
		local look = gameCamera.CFrame.LookVector * Vector3.new(1, 0, 1)
		if look.Magnitude < 0.01 then return root.Position end
		return root.Position + look.Unit * 5
	end

	local function cleanupHealthbar()
		if _hbUpdateConnection then
			_hbUpdateConnection:Disconnect()
			_hbUpdateConnection = nil
		end
		if _hbMounted then
			pcall(bedwars.Roact.unmount, _hbMounted)
			_hbMounted = nil
		end
		if _hbPart then
			pcall(function() _hbPart:Destroy() end)
			_hbPart = nil
		end
		_hbProgressRef = nil
		_hbBlock = nil
		local stray = workspace:FindFirstChild('AeroNukerHB')
		while stray do
			pcall(function() stray:Destroy() end)
			stray = workspace:FindFirstChild('AeroNukerHB')
		end
	end

	local function customHealthbar(self, blockRef, health, maxHealth, changeHealth, block)
		if not Nuker or not Nuker.Enabled or not Effect.Enabled or not CustomHealth.Enabled then return end
		if not block or not block.Parent then
			cleanupHealthbar()
			return
		end
		if block:GetAttribute('NoHealthbar') then return end

		maxHealth = maxHealth or block:GetAttribute('MaxHealth') or 100
		health = health or block:GetAttribute('Health') or maxHealth

		if health <= 0 then
			cleanupHealthbar()
			return
		end

		if _hbBlock ~= block or not _hbPart or not _hbPart.Parent then
			cleanupHealthbar()
			_hbBlock = block
			local create = bedwars.Roact.createElement
			local percent = math.clamp(health / maxHealth, 0, 1)
			_hbProgressRef = bedwars.Roact.createRef()
			local part = Instance.new('Part')
			part.Name = 'AeroNukerHB'
			part.Size = Vector3.one
			part.CFrame = CFrame.new(block.Position + Vector3.new(0, 1.5, 0))
			part.Transparency = 1
			part.Anchored = true
			part.CanCollide = false
			part.Parent = workspace
			_hbPart = part
			pcall(function() bedwars.QueryUtil:setQueryIgnored(part, true) end)

			local displayName = (bedwars.ItemMeta[block.Name] and bedwars.ItemMeta[block.Name].displayName) or block.Name

			_hbMounted = bedwars.Roact.mount(create('BillboardGui', {
				Size = UDim2.fromOffset(200, 80),
				StudsOffset = Vector3.new(0, 2.2, 0),
				Adornee = part,
				MaxDistance = 50,
				AlwaysOnTop = true
			}, {
				create('Frame', {
					Size = UDim2.fromOffset(150, 42),
					Position = UDim2.fromOffset(25, 20),
					BackgroundColor3 = Color3.fromRGB(20, 20, 25),
					BackgroundTransparency = 0.25
				}, {
					create('UICorner', {CornerRadius = UDim.new(0, 6)}),
					create('TextLabel', {
						Size = UDim2.new(1, -16, 0, 16),
						Position = UDim2.fromOffset(8, 6),
						BackgroundTransparency = 1,
						Text = displayName,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextColor3 = Color3.fromRGB(255, 255, 255),
						TextScaled = true,
						Font = Enum.Font.GothamBold
					}),
					create('Frame', {
						Size = UDim2.new(1, -16, 0, 6),
						Position = UDim2.fromOffset(8, 26),
						BackgroundColor3 = Color3.fromRGB(40, 40, 50)
					}, {
						create('UICorner', {CornerRadius = UDim.new(1, 0)}),
						create('Frame', {
							[bedwars.Roact.Ref] = _hbProgressRef,
							Size = UDim2.fromScale(percent, 1),
							BackgroundColor3 = Color3.fromHSV(math.clamp(percent / 3, 0, 0.35), 0.9, 0.9)
						}, {create('UICorner', {CornerRadius = UDim.new(1, 0)})})
					})
				})
			}), part)

			if _hbUpdateConnection then
				_hbUpdateConnection:Disconnect()
			end
			_hbUpdateConnection = game:GetService('RunService').Heartbeat:Connect(function()
				if not _hbBlock or not _hbBlock.Parent or not Nuker.Enabled or not CustomHealth.Enabled then
					cleanupHealthbar()
					return
				end
				local currentHealth = _hbBlock:GetAttribute('Health') or 100
				local currentMax = _hbBlock:GetAttribute('MaxHealth') or 100
				if currentHealth <= 0 then
					cleanupHealthbar()
					return
				end
				local newpercent = math.clamp(currentHealth / currentMax, 0, 1)
				if _hbProgressRef and _hbProgressRef:getValue() then
					_hbProgressRef:getValue():TweenSize(
						UDim2.fromScale(newpercent, 1),
						Enum.EasingDirection.Out,
						Enum.EasingStyle.Quad,
						0.1
					)
					_hbProgressRef:getValue().BackgroundColor3 = Color3.fromHSV(math.clamp(newpercent / 3, 0, 0.35), 0.9, 0.9)
				end
			end)
		end
	end

	local function cachedIsBreakable(v)
		local now = tick()
		local cached = breakabilityCache[v]
		if cached and (now - cached.t) < BREAK_CACHE_TTL then
			return cached.v
		end
		local ok, result = pcall(function()
			local blockPos = bedwars.BlockController:getBlockPosition(v.Position)
			return bedwars.BlockController:isBlockBreakable({blockPosition = blockPos}, lplr)
		end)
		local val = ok and result or false
		breakabilityCache[v] = {v = val, t = now}
		return val
	end

	local function rebuildTeammateCache()
		local now = tick()
		if now - cachedTeammatesTime < 2 then return end
		cachedTeammatesTime = now
		table.clear(cachedTeammates)
		local localTeam = lplr:GetAttribute('Team') or lplr.Team
		if not localTeam then return end
		for _, player in playersService:GetPlayers() do
			local pt = player:GetAttribute('Team') or player.Team
			if pt == localTeam then
				cachedTeammates[player.UserId] = true
			end
		end
	end

	local function isSameTeam(userId)
		if not userId or userId == 0 then return false end
		rebuildTeammateCache()
		return cachedTeammates[userId] == true
	end

	local function myTeamId()
		return lplr:GetAttribute('Team')
			or (lplr.Character and (lplr.Character:GetAttribute('Team') or lplr.Character:GetAttribute('TeamId')))
	end

	local function passesChecks(v, localPosition)
		if v:GetAttribute('NoBreak') then return false end

		if (v:GetAttribute('BedShieldEndTime') or 0) > workspace:GetServerTimeNow() then
			return false
		end

		local blockTeam = v:GetAttribute('Team') or v:GetAttribute('TeamId')
		local mineNow = myTeamId()
		if mineNow and v:GetAttribute('Team' .. tostring(mineNow) .. 'NoBreak') then
			return false
		end

		if not SelfBreak.Enabled then
			local mine = myTeamId()
			if blockTeam and mine and tonumber(blockTeam) == tonumber(mine) then
				return false
			end
			if v:GetAttribute('PlacedByUserId') == lplr.UserId then
				return false
			end
			if isSameTeam(v:GetAttribute('PlacedByUserId')) then
				return false
			end
		end

		if LimitItem.Enabled then
			local hand = store.hand and store.hand.tool
			local hmeta = hand and bedwars.ItemMeta[hand.Name]
			if not (hmeta and hmeta.breakBlock) then return false end
		end

		if v ~= ActiveBlock and Mode.Value ~= 'Legit' and ViewAngle.Value < 180 then
			local offset = v.Position - gameCamera.CFrame.Position
			if offset.Magnitude > 0 then
				local angle = math.deg(math.acos(math.clamp(offset.Unit:Dot(gameCamera.CFrame.LookVector), -1, 1)))
				if angle > ViewAngle.Value then
					return false
				end
			end
		end

		if PlayerCheck.Enabled then
			local root = entitylib.character and entitylib.character.RootPart
			if root then
				if workspace:Raycast(root.Position, v.Position - root.Position, PlayerParams) then
					return false
				end
			end
		end

		return true
	end

	local function ensureParts(count)
		if not (Nuker and Nuker.Enabled) then return end
		while #parts < count do
			local part = Instance.new('Part')
			part.Anchored = true
			part.CanQuery = false
			part.CanCollide = false
			part.Transparency = 1
			part.Position = Vector3.zero
			part.Parent = gameCamera
			local adorn = Instance.new('BoxHandleAdornment')
			adorn.Size = Vector3.one
			adorn.AlwaysOnTop = true
			adorn.ZIndex = 1
			adorn.Transparency = 0.5
			adorn.Adornee = part
			adorn.Parent = part
			table.insert(parts, part)
		end
	end

	local function hideParts()
		for _, p in parts do
			p.Position = Vector3.zero
		end
	end

	local function destroyParts()
		for _, p in parts do
			pcall(function()
				p:ClearAllChildren()
				p:Destroy()
			end)
		end
		table.clear(parts)
	end

	local function highlightColor(fallback)
		if NukerHighlightColor then
			return Color3.fromHSV(NukerHighlightColor.Hue, NukerHighlightColor.Sat, NukerHighlightColor.Value)
		end
		return fallback
	end

	local function setHighlight(block)
		if not (BlockHighlight and BlockHighlight.Enabled) then
			if blockHighlightInstance then blockHighlightInstance.Adornee = nil end
			return
		end
		if not blockHighlightInstance then
			if not (Nuker and Nuker.Enabled) then return end
			blockHighlightInstance = Instance.new('BoxHandleAdornment')
			blockHighlightInstance.AlwaysOnTop = true
			blockHighlightInstance.ZIndex = 10
			blockHighlightInstance.Transparency = 0.3
			blockHighlightInstance.Parent = gameCamera
		end
		blockHighlightInstance.Color3 = highlightColor(Color3.fromRGB(255, 255, 0))
		if block and block.Parent then
			blockHighlightInstance.Size = block.Size + Vector3.new(0.05, 0.05, 0.05)
			blockHighlightInstance.Adornee = block
		else
			blockHighlightInstance.Adornee = nil
		end
	end

	local function clearVisuals()
		hideParts()
		setHighlight(nil)
		activeBreachBlock = nil
		activeBreachBed = nil
		activeRouteBlock = nil
		activeRouteBed = nil
	end

	local function clearLegit()
		table.clear(legitRoute)
		legitTarget = nil
		legitAnchor = nil
		legitLastPlayerPos = nil
	end

	local function cleanupAll()
		table.clear(breakabilityCache)
		clearLegit()
		if AnimTween then
			pcall(function() AnimTween:Destroy() end)
			AnimTween = nil
		end
		if breakAnimTrack then
			pcall(function() breakAnimTrack:Stop() end)
			breakAnimTrack = nil
		end
		if blockHighlightInstance then
			pcall(function() blockHighlightInstance:Destroy() end)
			blockHighlightInstance = nil
		end
		destroyParts()
		cleanupHealthbar()
	end

	local equipRemote
	task.spawn(function()
		pcall(function()
			equipRemote = replicatedStorage
				:WaitForChild('rbxts_include'):WaitForChild('node_modules')
				:WaitForChild('@easy-games'):WaitForChild('game-core')
				:WaitForChild('node_modules'):WaitForChild('@rbxts')
				:WaitForChild('net'):WaitForChild('out')
				:WaitForChild('_NetManaged'):WaitForChild('EquipItemSet')
		end)
	end)

	local function equipTool(toolObj)
		if not toolObj then return end
		pcall(function()
			if bedwars.ItemHandController then
				bedwars.ItemHandController:setItemInHand(toolObj)
			end
			if equipRemote then
				equipRemote:InvokeServer({hand = toolObj})
			end
		end)
	end

	local function getBestToolForBlock(blockName)
		local isBed = (blockName == 'bed' or blockName:find('bed') ~= nil)
		if isBed then
			if store.tools.axe then return store.tools.axe.tool end
			if store.tools.wood_axe then return store.tools.wood_axe.tool end
			if store.tools.shears then return store.tools.shears.tool end
			for k, v in pairs(store.tools) do
				if k:find('axe') and v.tool then return v.tool end
			end
			return nil
		end

		local blockMeta = bedwars.ItemMeta[blockName]
		local breaktype = (blockName == 'gumdrop_bounce_pad' and 'stone')
			or (blockName:find('wool') and 'shears')
			or (blockMeta and blockMeta.block and blockMeta.block.breakType) 
			or 'wood'

		if breaktype == 'shears' and store.tools.shears then
			return store.tools.shears.tool
		end

		local toolData = store.tools[breaktype]
		if toolData and toolData.tool then
			return toolData.tool
		end
		return nil
	end

	local function holdingCorrectTool(v)
		if not AutoTool.Enabled then return true end
		
		local correctTool = getBestToolForBlock(v.Name)
		if correctTool then
			local currentHand = store.hand and store.hand.tool
			if not currentHand or currentHand.Name ~= correctTool.Name then
				equipTool(correctTool)
				task.wait(0.03)
			end
		end
		return true
	end

	local function drawPath(target, path, endpos)
		if not (ShowPath and ShowPath.Enabled) or not path or not target then
			hideParts()
			return
		end
		local currentnode = target
		for _, part in parts do
			part.Position = currentnode or Vector3.zero
			if currentnode then
				part.BoxHandleAdornment.Color3 = currentnode == endpos and Color3.new(1, 0.2, 0.2)
					or currentnode == target and Color3.new(0.2, 0.2, 1)
					or Color3.new(0.2, 1, 0.2)
			end
			currentnode = path[currentnode]
		end
	end

	local function drawRoute(activePos)
		if not (ShowPath and ShowPath.Enabled) then
			hideParts()
			return
		end
		for i, part in parts do
			local node = legitRoute[i]
			part.Position = node or Vector3.zero
			if node then
				part.BoxHandleAdornment.Color3 = node == activePos and Color3.new(1, 0.2, 0.2) or Color3.new(0.2, 1, 0.2)
			end
		end
	end

	local damageRemote
	task.spawn(function()
		pcall(function()
			damageRemote = replicatedStorage
				:WaitForChild('rbxts_include'):WaitForChild('node_modules')
				:WaitForChild('@easy-games'):WaitForChild('block-engine')
				:WaitForChild('node_modules'):WaitForChild('@rbxts')
				:WaitForChild('net'):WaitForChild('out')
				:WaitForChild('_NetManaged'):WaitForChild('DamageBlock')
		end)
	end)

	local function rawBreak(block, targetWorldPos)
		if not damageRemote or not block or not block.Parent then return false end
		local hitPos = targetWorldPos or (block.Position + Vector3.new(0, block.Size.Y / 2, 0))
		local bp = bedwars.BlockController:getBlockPosition(targetWorldPos or block.Position)
		task.spawn(function()
			pcall(function()
				damageRemote:InvokeServer({
					blockRef = {blockPosition = bp},
					hitPosition = hitPos,
					hitNormal = Vector3.yAxis
				})
				if CustomHealth.Enabled and Effect.Enabled then
					customHealthbar(nil, {blockPosition = bp}, block:GetAttribute('Health') or 100, block:GetAttribute('MaxHealth') or 100, 0, block)
				end
			end)
		end)
		return true
	end

	local ignoreList = {}
	local cursorParams = RaycastParams.new()
	cursorParams.FilterType = Enum.RaycastFilterType.Exclude

	local function cursorBlock()
		local sp = screenPoint()
		local unit = gameCamera:ViewportPointToRay(sp.X, sp.Y, 0)
		table.clear(ignoreList)
		if lplr.Character then
			table.insert(ignoreList, lplr.Character)
		end
		for _, plr in playersService:GetPlayers() do
			if plr.Character then
				table.insert(ignoreList, plr.Character)
			end
		end
		for _, ent in entitylib.List do
			if ent.Character then
				table.insert(ignoreList, ent.Character)
			end
		end
		cursorParams.FilterDescendantsInstances = ignoreList
		local result = workspace:Raycast(unit.Origin, unit.Direction * 999, cursorParams)
		if not result then return nil, nil end
		local inst = result.Instance
		return (inst and inst:IsA('BasePart')) and inst or nil, result.Position
	end

	local function getContainedBedPositions(block)
		if not block or not block.Parent then return {} end
		local ok, handler = pcall(function()
			return bedwars.BlockController:getHandlerRegistry():getHandler(block.Name)
		end)
		if ok and handler then
			local ok2, cp = pcall(function() return handler:getContainedPositions(block) end)
			if ok2 and cp and #cp >= 2 then
				local out = {}
				for _, v in cp do table.insert(out, v * 3) end
				return out
			end
		end

		local forward = block.CFrame.LookVector
		local p1 = bedwars.BlockController:getBlockPosition(block.Position + forward * 1.5) * 3
		local p2 = bedwars.BlockController:getBlockPosition(block.Position - forward * 1.5) * 3
		if (p1 - p2).Magnitude >= 2.5 then
			return { p1, p2 }
		end

		local right = block.CFrame.RightVector
		p1 = bedwars.BlockController:getBlockPosition(block.Position + right * 1.5) * 3
		p2 = bedwars.BlockController:getBlockPosition(block.Position - right * 1.5) * 3
		if (p1 - p2).Magnitude >= 2.5 then
			return { p1, p2 }
		end

		local baseGrid = bedwars.BlockController:getBlockPosition(block.Position)
		local rotY = select(2, block.CFrame:ToOrientation())
		local deg = math.floor((math.deg(rotY) + 45) / 90) * 90 % 360
		local offset = Vector3.new(0, 0, 1)
		if deg == 90 then offset = Vector3.new(1, 0, 0)
		elseif deg == 180 then offset = Vector3.new(0, 0, -1)
		elseif deg == 270 then offset = Vector3.new(-1, 0, 0) end

		return { baseGrid * 3, (baseGrid + offset) * 3 }
	end

	local sides = {
		Vector3.new(3, 0, 0), Vector3.new(-3, 0, 0),
		Vector3.new(0, 3, 0),
		Vector3.new(0, 0, 3), Vector3.new(0, 0, -3)
	}

	local function isBedExposed(bed, localPosition)
		if not bed or not bed.Parent then return false, nil end

		local eye = localPosition + Vector3.new(0, 2, 0)
		local expParams = RaycastParams.new()
		expParams.FilterType = Enum.RaycastFilterType.Exclude
		local expIgnore = {lplr.Character, gameCamera}
		for _, plr in playersService:GetPlayers() do
			if plr.Character then table.insert(expIgnore, plr.Character) end
		end
		for _, ent in entitylib.List do
			if ent.Character then table.insert(expIgnore, ent.Character) end
		end
		expParams.FilterDescendantsInstances = expIgnore

		local bestDist, bestPos = math.huge, nil
		for _, bPos in getContainedBedPositions(bed) do
			local cellCenter = bPos + Vector3.new(1.5, 1.5, 1.5)
			for _, side in sides do
				local neighbor = bPos + side
				local blk = getPlacedBlock(neighbor)
				if not blk then
					local dist = (cellCenter - localPosition).Magnitude
					if dist <= Range.Value then
						local dir = cellCenter - eye
						local result = workspace:Raycast(eye, dir, expParams)
						if not result or result.Instance == bed or result.Instance:IsDescendantOf(bed) or (result.Position - cellCenter).Magnitude <= 2 then
							if dist < bestDist then
								bestDist = dist
								bestPos = bPos
							end
						end
					end
				end
			end
		end
		if bestPos then return true, bestPos end
		return false, nil
	end

	local function calculateSmartScore(block, localPosition)
		local health = block:GetAttribute('Health') or 100
		local maxHealth = block:GetAttribute('MaxHealth') or 100
		local distance = (block.Position - localPosition).Magnitude

		local healthScore = (maxHealth - health) / maxHealth
		local distanceScore = 1 - math.min(distance / Range.Value, 1)
		local combinedScore = (healthScore * 0.6) + (distanceScore * 0.4)

		if health > 80 then
			combinedScore = combinedScore + 0.5
		end

		return combinedScore
	end

	local function isBedVisible(bed, localPosition)
		if not bed or not bed.Parent then return false, nil end

		local visibleParams = RaycastParams.new()
		visibleParams.FilterType = Enum.RaycastFilterType.Exclude
		local visibleIgnore = {lplr.Character, gameCamera}
		for _, plr in playersService:GetPlayers() do
			if plr.Character then table.insert(visibleIgnore, plr.Character) end
		end
		for _, ent in entitylib.List do
			if ent.Character then table.insert(visibleIgnore, ent.Character) end
		end
		visibleParams.FilterDescendantsInstances = visibleIgnore

		local eye = localPosition + Vector3.new(0, 2, 0)
		local bestDist, bestPos = math.huge, nil

		for _, bPos in getContainedBedPositions(bed) do
			local cellCenter = bPos + Vector3.new(1.5, 1.5, 1.5)
			local dist = (cellCenter - localPosition).Magnitude
			if dist <= Range.Value then
				local dir = cellCenter - eye
				local result = workspace:Raycast(eye, dir, visibleParams)
				if not result or result.Instance == bed or result.Instance:IsDescendantOf(bed) or (result.Position - cellCenter).Magnitude <= 2 then
					if dist < bestDist then
						bestDist = dist
						bestPos = bPos
					end
				end
			end
		end

		if bestPos then
			return true, bestPos
		end
		return false, nil
	end

	local activeBreachBlock = nil
	local activeBreachBed = nil
	local activeRouteBlock = nil
	local activeRouteBed = nil

	local function getBlockLayer(block, bed)
		if not block or not bed then return 0 end
		local dist = (block.Position - bed.Position).Magnitude
		if dist < 6 then return 1 end
		if dist < 12 then return 2 end
		return 3
	end

	local function calculateLayerScore(block, bed, localPosition)
		local layer = getBlockLayer(block, bed)
		local health = block:GetAttribute('Health') or 100
		local maxHealth = block:GetAttribute('MaxHealth') or 100
		local dist = (block.Position - localPosition).Magnitude

		local layerBonus = (4 - layer) * 20
		local healthPenalty = (health / maxHealth) * 15
		local distPenalty = dist * 0.5
		local isExposed = 0
		
		for _, side in sides do
			local neighbor = block.Position + side
			if not getPlacedBlock(neighbor) then
				isExposed = 30
				break
			end
		end

		return layerBonus + isExposed - healthPenalty - distPenalty
	end

	local anims = vape.Libraries and vape.Libraries.auraanims or {}
	local AnimTween = nil
	local armC0 = nil
	local lastAnimTime = 0
	local NORMAL_SWING_SPEED = 0.35
	local breakAnimTrack = nil

	local function playBreakAnimation()
		if not Animation.Enabled then return end
		
		local breakSpeed = BreakSpeed.Value or 0.25
		if (tick() - lastAnimTime) < breakSpeed then return end
		lastAnimTime = tick()

		pcall(function()
			local humanoid = lplr.Character and lplr.Character:FindFirstChildOfClass('Humanoid')
			if not humanoid then return end

			if breakAnimTrack then
				breakAnimTrack:Stop()
				breakAnimTrack = nil
			end

			local animId = 'rbxassetid://507770453'
			local anim = Instance.new('Animation')
			anim.AnimationId = animId
			breakAnimTrack = humanoid:LoadAnimation(anim)
			breakAnimTrack:Play()
		end)
	end

	local function findFastestBreachBlock(bed, localPosition)
		if activeBreachBlock and activeBreachBlock.Parent and activeBreachBed == bed then
			local hp = activeBreachBlock:GetAttribute('Health') or 1
			local dist = (activeBreachBlock.Position - localPosition).Magnitude
			if hp > 0 and dist <= Range.Value and cachedIsBreakable(activeBreachBlock) then
				return activeBreachBlock
			end
		end
		activeBreachBlock = nil
		activeBreachBed = nil

		local bestBlock, bestScore = nil, math.huge
		for _, bPos in getContainedBedPositions(bed) do
			for _, side in sides do
				local neighbor = bPos + side
				local blk = getPlacedBlock(neighbor)
				if blk and blk.Parent and blk ~= bed and cachedIsBreakable(blk) then
					local dist = (blk.Position - localPosition).Magnitude
					if dist <= Range.Value then
						local score = calculateLayerScore(blk, bed, localPosition)
						if score < bestScore then
							bestScore = score
							bestBlock = blk
						end
					end
				end
			end
		end

		if bestBlock then
			activeBreachBlock = bestBlock
			activeBreachBed = bed
		end
		return bestBlock
	end

	local function buildSmartBedRoute(target, localPosition)
		local anchor = frontPoint() or localPosition

		if activeRouteBlock and activeRouteBed == target then
			local currentBlock = getPlacedBlock(activeRouteBlock)
			if currentBlock and currentBlock.Parent and cachedIsBreakable(currentBlock) then
				return activeRouteBlock, nil, nil
			end
		end

		activeRouteBlock = nil
		activeRouteBed = nil

		local bestPos, bestPath, bestStart, bestScore = nil, nil, nil, math.huge
		
		for _, startPos in getContainedBedPositions(target) do
			local ok, pos, cost, path = pcall(bedwars.calculatePath, target, startPos, NukerAngle.Value, anchor)
			if ok and pos and cost then
				local distToAnchor = (pos - anchor).Magnitude
				local score = cost + distToAnchor * 0.12
				if score < bestScore then
					bestPos, bestPath, bestStart, bestScore = pos, path, startPos, score
				end
			end
		end

		if not bestPos then return nil, nil, nil end

		local coverBlock = getPlacedBlock(bestPos)
		if coverBlock then
			activeRouteBlock = bestPos
			activeRouteBed = target
		end
		return bestPos, bestPath, bestStart
	end

	local function buildLegitRoute(target)
		local anchor = frontPoint()
		if not anchor then return false end

		local bestPos, bestPath, bestStart, bestScore = nil, nil, nil, math.huge
		for _, startPos in getContainedBedPositions(target) do
			local ok, pos, cost, path = pcall(bedwars.calculatePath, target, startPos, NukerAngle.Value, anchor)
			if ok and pos and cost then
				local distToAnchor = (pos - anchor).Magnitude
				local score = cost + distToAnchor * 0.08
				if score < bestScore then
					bestPos, bestPath, bestStart, bestScore = pos, path, startPos, score
				end
			end
		end
		if not bestPos then return false end

		table.clear(legitRoute)
		local cur = bestPos
		local guard = 0
		while cur and guard < 128 do
			guard = guard + 1
			table.insert(legitRoute, cur)
			if cur == bestStart then break end
			cur = bestPath and bestPath[cur]
		end

		legitAnchor = anchor
		legitTarget = target
		legitLastPlayerPos = entitylib.character and entitylib.character.RootPart.Position
		return #legitRoute > 0
	end

	local BreakMethods = {
		Health = function(block)
			return block:GetAttribute('Health') or 0
		end,
		Distance = function(block, localPosition)
			return (block.Position - localPosition).Magnitude
		end
	}

	local function GetBlockDistance(Block, LocalPosition)
		local positions = getContainedBedPositions(Block)
		local Closest = math.huge
		local ClosestPos = nil
		for _, Position in positions do
			local bp = bedwars.BlockController:getBlockPosition(Position)
			if bedwars.BlockController:isBlockBreakable({blockPosition = bp}, lplr) then
				local d = (Position - LocalPosition).Magnitude
				if d < Closest then
					Closest = d
					ClosestPos = Position
				end
			end
		end
		return Closest, ClosestPos
	end

	local function pickBest(list, localPosition)
		if not list or #list == 0 then return nil end
		local best, bestScore = nil, math.huge
		local mode = TargetMode.Value
		local method = BreakMethods[mode] or BreakMethods.Distance

		for _, v in list do
			if not v or not v.Parent then continue end
			local dist = (v.Position - localPosition).Magnitude
			if dist > Range.Value then continue end
			if not passesChecks(v, localPosition) then continue end
			if not cachedIsBreakable(v) then continue end

			if v.Name:lower():find('bed') then
				local isVis, visPos = isBedVisible(v, localPosition)
				if isVis then
					return v
				end
			end

			if SmartBreak.Enabled then
				local score = calculateSmartScore(v, localPosition)
				if score < bestScore then
					best, bestScore = v, score
				end
			else
				local score = method(v, localPosition)
				if ClosestBreak.Enabled then
					if v == MouseHit then
						return v
					end
					local offset = v.Position - MouseOrigin
					local along = offset:Dot(MouseDirection)
					local spread = along > 0 and (offset - MouseDirection * along).Magnitude or offset.Magnitude
					score = spread
				end

				if score < bestScore then
					best, bestScore = v, score
				end
			end
		end
		return best
	end

	Nuker = vape.Categories.Minigames:CreateModule({
		Name = 'Nuker',
		Function = function(callback)
			if callback then
				local beds = {}
				local function bedAdd(obj)
					if (obj.Name:lower():find('bed') and obj:IsA('BasePart')) or obj:HasTag('BedPart') then
						if not table.find(beds, obj) then
							table.insert(beds, obj)
						end
					end
				end
				local function bedRemove(obj)
					local i = table.find(beds, obj)
					if i then table.remove(beds, i) end
				end
				for _, obj in workspace:GetDescendants() do
					bedAdd(obj)
				end
				Nuker:Clean(workspace.DescendantAdded:Connect(bedAdd))
				Nuker:Clean(workspace.DescendantRemoving:Connect(bedRemove))
				task.spawn(function()
					while Nuker.Enabled do
						task.wait(1)
						for i = #beds, 1, -1 do
							if not beds[i] or not beds[i].Parent then
								table.remove(beds, i)
							end
						end
					end
				end)

				local luckyblock = collection('LuckyBlock', Nuker)
				local ironores = collection('iron_ore_mesh_block', Nuker)

				local trackedSpecial = {tesla_trap = {}, beehive = {}, pinata = {}, carrot = {}, melon = {}, pumpkin = {}, snow_pile = {}}
				local _trackedNames = {tesla_trap = true, beehive = true, pinata = true, carrot = true, melon = true, pumpkin = true, snow_pile = true}

				local function trackAdd(obj)
					if not _trackedNames[obj.Name] then return end
					local t = trackedSpecial[obj.Name]
					if not t then return end
					if obj:IsA('BasePart') then
						table.insert(t, obj)
					elseif obj:IsA('Model') then
						local part = obj.PrimaryPart or obj:FindFirstChildWhichIsA('BasePart')
						if part then table.insert(t, part) end
					end
				end

				local function trackRemove(obj)
					if not _trackedNames[obj.Name] then return end
					local t = trackedSpecial[obj.Name]
					if t then
						local part = obj
						if obj:IsA('Model') then
							part = obj.PrimaryPart or obj:FindFirstChildWhichIsA('BasePart')
						end
						if part then
							local i = table.find(t, part)
							if i then table.remove(t, i) end
						end
					end
					breakabilityCache[obj] = nil
				end

				ensureParts(30)
				scanDescendants(workspace, trackAdd, Nuker)
				Nuker:Clean(workspace.DescendantAdded:Connect(trackAdd))
				Nuker:Clean(workspace.DescendantRemoving:Connect(trackRemove))

				local function candidateLists()
					local lists = {}
					local priority = Priority and Priority.Value or 'All'
					
					if priority == 'Beds' then
						if Bed and Bed.Enabled then table.insert(lists, beds) end
					elseif priority == 'Lucky Blocks' then
						if LuckyBlock and LuckyBlock.Enabled then table.insert(lists, luckyblock) end
					elseif priority == 'Ores' then
						if IronOre and IronOre.Enabled then table.insert(lists, ironores) end
					else
						if Bed and Bed.Enabled then table.insert(lists, beds) end
						if Tesla and Tesla.Enabled then table.insert(lists, trackedSpecial.tesla_trap) end
						if Hive and Hive.Enabled then table.insert(lists, trackedSpecial.beehive) end
						if LuckyBlock and LuckyBlock.Enabled then table.insert(lists, luckyblock) end
						if IronOre and IronOre.Enabled then table.insert(lists, ironores) end
						if Snow and Snow.Enabled then table.insert(lists, trackedSpecial.snow_pile) end
						if Pinata and Pinata.Enabled then table.insert(lists, trackedSpecial.pinata) end
						if Crops and Crops.Enabled then
							table.insert(lists, trackedSpecial.carrot)
							table.insert(lists, trackedSpecial.melon)
							table.insert(lists, trackedSpecial.pumpkin)
						end
					end
					
					return lists
				end

				local function runNormal(localPosition)
					if ClosestBreak.Enabled then
						local ignore = {lplr.Character, gameCamera}
						for _, v in entitylib.List do
							if v.Character then
								table.insert(ignore, v.Character)
							end
						end
						MouseParams.FilterDescendantsInstances = ignore
						MouseOrigin, MouseDirection = inputService:GetMouseLocation(), gameCamera.ViewportSize
						local unit = gameCamera:ViewportPointToRay(MouseOrigin.X, MouseOrigin.Y, 0)
						MouseOrigin = unit.Origin
						MouseDirection = unit.Direction
						local result = workspace:Raycast(MouseOrigin, MouseDirection * 999, MouseParams)
						MouseHit = result and result.Instance or nil
					end

					if PlayerCheck.Enabled then
						local characters = {}
						for _, v in entitylib.List do
							if v.Player and v.Character then
								table.insert(characters, v.Character)
							end
						end
						PlayerParams.FilterDescendantsInstances = characters
					end

					if Bed and Bed.Enabled and (not Priority or Priority.Value == 'All' or Priority.Value == 'Beds') then
						local bestBed = pickBest(beds, localPosition)
						if bestBed then
							local isVis, visPos = isBedVisible(bestBed, localPosition)
							if isVis and visPos then
								holdingCorrectTool(bestBed)
								setHighlight(bestBed)
								ActiveBlock = bestBed
								if tick() >= NextBreak then
									playBreakAnimation()
									rawBreak(bestBed, visPos)
									local target, path, endpos = bedwars.breakBlock(
										bestBed,
										Effect.Enabled,
										Animation.Enabled,
										CustomHealth.Enabled and customHealthbar or nil,
										AutoTool.Enabled,
										NukerAngle.Value
									)
									drawPath(target, path, endpos)
									local breakWait = BreakSpeed.Value
									if BedCheck and BedCheck.Enabled then
										breakWait = math.max(breakWait, 0.3)
									end
									NextBreak = tick() + breakWait
								end
								return true
							end

							local isExp, expPos = isBedExposed(bestBed, localPosition)
							if isExp and expPos then
								holdingCorrectTool(bestBed)
								setHighlight(bestBed)
								ActiveBlock = bestBed
								if tick() >= NextBreak then
									playBreakAnimation()
									rawBreak(bestBed, expPos)
									local target, path, endpos = bedwars.breakBlock(
										bestBed,
										Effect.Enabled,
										Animation.Enabled,
										CustomHealth.Enabled and customHealthbar or nil,
										AutoTool.Enabled,
										NukerAngle.Value
									)
									drawPath(target, path, endpos)
									local breakWait = BreakSpeed.Value
									if BedCheck and BedCheck.Enabled then
										breakWait = math.max(breakWait, 0.3)
									end
									NextBreak = tick() + breakWait
								end
								return true
							end

							local breachBlock = findFastestBreachBlock(bestBed, localPosition)
							if breachBlock then
								holdingCorrectTool(breachBlock)
								setHighlight(breachBlock)
								ActiveBlock = breachBlock
								if tick() >= NextBreak then
									playBreakAnimation()
									rawBreak(breachBlock)
									local target, path, endpos = bedwars.breakBlock(
										breachBlock,
										Effect.Enabled,
										Animation.Enabled,
										CustomHealth.Enabled and customHealthbar or nil,
										AutoTool.Enabled,
										NukerAngle.Value
									)
									drawPath(target, path, endpos)
									NextBreak = tick() + BreakSpeed.Value
								end
								return true
							end

							local targetPos, path, endpos = buildSmartBedRoute(bestBed, localPosition)
							if targetPos then
								local coverBlock = getPlacedBlock(targetPos)
								if coverBlock then
									holdingCorrectTool(coverBlock)
									setHighlight(coverBlock)
									ActiveBlock = coverBlock
									if tick() >= NextBreak then
										playBreakAnimation()
										rawBreak(coverBlock, targetPos)
										local target, path, endpos = bedwars.breakBlock(
											coverBlock,
											Effect.Enabled,
											Animation.Enabled,
											CustomHealth.Enabled and customHealthbar or nil,
											AutoTool.Enabled,
											NukerAngle.Value
										)
										drawPath(target, path, endpos)
										NextBreak = tick() + BreakSpeed.Value
									end
									return true
								end
							end
						end
					end

					for _, tab in candidateLists() do
						local best = pickBest(tab, localPosition)
						if best then
							if holdingCorrectTool(best) then
								setHighlight(best)
								ActiveBlock = best
								if tick() >= NextBreak then
									playBreakAnimation()
									rawBreak(best)
									local target, path, endpos = bedwars.breakBlock(
										best,
										Effect.Enabled,
										Animation.Enabled,
										CustomHealth.Enabled and customHealthbar or nil,
										AutoTool.Enabled,
										NukerAngle.Value
									)
									drawPath(target, path, endpos)
									NextBreak = tick() + BreakSpeed.Value
								end
								return true
							end
						end
					end
					return false
				end

				local function runLegit(localPosition)
					local function pickClosestAny()
						local best, bestDist = nil, math.huge
						for _, tab in candidateLists() do
							for i = 1, #tab do
								local v = tab[i]
								if v and v.Parent and passesChecks(v, localPosition) and cachedIsBreakable(v) then
									if v.Name:lower():find('bed') and isBedVisible(v, localPosition) then
										return v
									end
									local dist = (v.Position - localPosition).Magnitude
									if dist < Range.Value and dist < bestDist then
										best, bestDist = v, dist
									end
								end
							end
						end
						return best
					end

					local target = pickClosestAny()
					if not target then
						clearLegit()
						return false
					end

					if target.Name:lower():find('bed') then
						local isVis, visPos = isBedVisible(target, localPosition)
						if isVis and visPos then
							holdingCorrectTool(target)
							setHighlight(target)
							ActiveBlock = target
							if (tick() - legitLastHit) >= BreakSpeed.Value then
								legitLastHit = tick()
								playBreakAnimation()
								rawBreak(target, visPos)
								bedwars.breakBlock(
									target,
									Effect.Enabled,
									Animation.Enabled,
									CustomHealth.Enabled and customHealthbar or nil,
									AutoTool.Enabled,
									NukerAngle.Value
								)
							end
							return true
						end
					end

					local currentPos = frontPoint() or localPosition
					local movedDist = (localPosition - (legitLastPlayerPos or localPosition)).Magnitude

					if movedDist > 2.5 then
						clearLegit()
					end

					if legitTarget ~= target or not legitTarget.Parent or #legitRoute == 0 then
						clearLegit()
					elseif legitAnchor and (currentPos - legitAnchor).Magnitude > 6 then 
						clearLegit()
					end

					for i = #legitRoute, 1, -1 do
						local pos = legitRoute[i]
						local block = getPlacedBlock(pos)
						if not block then
							table.remove(legitRoute, i)
						end
					end

					if #legitRoute == 0 then
						if not buildLegitRoute(target) then
							clearVisuals()
							return false
						end
					end

					local frontPos = legitRoute[1]
					local frontBlock = frontPos and getPlacedBlock(frontPos)

					if not frontBlock then
						clearLegit()
						clearVisuals()
						return false
					end

					holdingCorrectTool(frontBlock)

					local aimed = frontBlock
					if BlockBreakMode.Value == 'Cursor' then
						local raw, hitPos = cursorBlock()
						aimed = nil
						if raw and raw.Parent then
							if raw == frontBlock or raw:IsDescendantOf(frontBlock) then
								aimed = frontBlock
							elseif frontBlock:IsA('BasePart') and raw:IsDescendantOf(frontBlock.Parent) and raw.Name == frontBlock.Name then
								aimed = frontBlock
							end
						end
						if not aimed and hitPos and (hitPos - frontBlock.Position).Magnitude <= 4.5 then
							aimed = frontBlock
						end
					end

					drawRoute(aimed and frontPos or nil)

					if not aimed or (aimed.Position - localPosition).Magnitude > Range.Value then
						setHighlight(nil)
						return true
					end

					setHighlight(aimed)
					if (tick() - legitLastHit) >= BreakSpeed.Value then
						legitLastHit = tick()
						if holdingCorrectTool(aimed) then
							ActiveBlock = aimed
							playBreakAnimation()
							rawBreak(aimed, frontPos)
							bedwars.breakBlock(
								aimed,
								Effect.Enabled,
								Animation.Enabled,
								CustomHealth.Enabled and customHealthbar or nil,
								AutoTool.Enabled,
								NukerAngle.Value
							)
						end
					end
					return true
				end

				repeat
					task.wait(1 / UpdateRate.Value)
					if not Nuker.Enabled then break end

					if _hbBlock and (not _hbBlock.Parent or (_hbBlock:GetAttribute('Health') or 0) <= 0) then
						cleanupHealthbar()
					end
					if blockHighlightInstance and blockHighlightInstance.Adornee then
						local a = blockHighlightInstance.Adornee
						if not a.Parent or (a:GetAttribute('Health') or 1) <= 0 then
							blockHighlightInstance.Adornee = nil
							hideParts()
						end
					end
					if legitTarget and not legitTarget.Parent then
						clearLegit()
						hideParts()
					end

					if entitylib.isAlive then
						local localPosition = entitylib.character.RootPart.Position
						local acted
						if Mode and Mode.Value == 'Legit' then
							acted = runLegit(localPosition)
						else
							acted = runNormal(localPosition)
						end
						if not acted then
							ActiveBlock = nil
							clearVisuals()
						end
					else
						ActiveBlock = nil
						clearVisuals()
					end
				until not Nuker.Enabled
			else
				cleanupAll()
			end
		end,
		Tooltip = 'nuker helps you bb'
	})

	vape:Clean(cleanupAll)

	TargetMode = Nuker:CreateDropdown({
		Name = 'Target Mode',
		List = {'Distance', 'Health'},
		Default = 'Distance',
		Tooltip = 'distance picks the closest block, health picks the weakest one'
	})
	ClosestBreak = Nuker:CreateToggle({
		Name = 'Closest break',
		Function = function(callback)
			if TargetMode then TargetMode.Object.Visible = not callback end
		end,
		Tooltip = 'Ignores the break mode and always takes the block nearest your crosshair, seeing straight through players'
	})
	Mode = Nuker:CreateDropdown({
		Name = 'Mode',
		List = {'Legit', 'Blatant'},
		Default = 'Legit',
		Tooltip = 'Legit digs to the block on its own, Blatant breaks everything in range',
		Function = function(val)
			if TargetMode and TargetMode.Object then
				TargetMode.Object.Visible = val ~= 'Legit'
			end
			if ClosestBreak and ClosestBreak.Object then
				ClosestBreak.Object.Visible = val ~= 'Legit'
			end
			if ViewAngle and ViewAngle.Object then
				ViewAngle.Object.Visible = val ~= 'Legit'
			end
			if SmartBreak and SmartBreak.Object then
				SmartBreak.Object.Visible = val == 'Legit'
			end
			if BlockBreakMode and BlockBreakMode.Object then
				BlockBreakMode.Object.Visible = val == 'Legit'
			end
			clearLegit()
		end
	})
	Priority = Nuker:CreateDropdown({
		Name = 'Priority',
		List = {'All', 'Beds', 'Lucky Blocks', 'Ores'},
		Default = 'All',
		Tooltip = 'Only target the selected block type',
		Function = function(val)
			if Bed and Bed.Object then
				Bed.Object.Visible = val == 'All' or val == 'Beds'
			end
			if BedCheck and BedCheck.Object then
				BedCheck.Object.Visible = (val == 'All' or val == 'Beds') and Bed and Bed.Enabled
			end
			if LuckyBlock and LuckyBlock.Object then
				LuckyBlock.Object.Visible = val == 'All' or val == 'Lucky Blocks'
			end
			if IronOre and IronOre.Object then
				IronOre.Object.Visible = val == 'All' or val == 'Ores'
			end
			if Snow and Snow.Object then
				Snow.Object.Visible = val == 'All'
			end
			if Tesla and Tesla.Object then
				Tesla.Object.Visible = val == 'All'
			end
			if Hive and Hive.Object then
				Hive.Object.Visible = val == 'All'
			end
			if Pinata and Pinata.Object then
				Pinata.Object.Visible = val == 'All'
			end
			if Crops and Crops.Object then
				Crops.Object.Visible = val == 'All'
			end
		end
	})
	SmartBreak = Nuker:CreateToggle({
		Name = 'Smart Break',
		Default = true,
		Tooltip = 'Prioritizes low health blocks and visible beds'
	})
	BlockBreakMode = Nuker:CreateDropdown({
		Name = 'Block Break',
		List = {'Closest', 'Cursor'},
		Default = 'Closest',
		Tooltip = 'Closest breaks the closest block in range automatically, Cursor only breaks blocks under your crosshair'
	})
	Range = Nuker:CreateSlider({
		Name = 'Break range',
		Min = 1,
		Max = 30,
		Default = 30,
		Tooltip = 'how far away a block can be for u to hit it'
	})
	NukerAngle = Nuker:CreateSlider({
		Name = 'Break Angle',
		Min = 0,
		Max = 360,
		Default = 360,
		Tooltip = 'only digs thru blocks inside this cone in front of ur cam'
	})
	ViewAngle = Nuker:CreateSlider({
		Name = 'View angle',
		Min = 5,
		Max = 180,
		Default = 60,
		Suffix = 'degrees',
		Tooltip = 'How far off your crosshair a block can sit in legit mode, 180 breaks anything in range'
	})
	BreakSpeed = Nuker:CreateSlider({
		Name = 'Break speed',
		Min = 0,
		Max = 0.3,
		Default = 0.25,
		Decimal = 100,
		Tooltip = 'wait between each hit, lower is faster'
	})
	UpdateRate = Nuker:CreateSlider({
		Name = 'Update rate',
		Min = 1,
		Max = 120,
		Default = 60,
		Tooltip = 'how often it re checks for blocks, leave it high'
	})
	Bed = Nuker:CreateToggle({
		Name = 'Break Bed',
		Default = true,
		Function = function(callback)
			if BedCheck and BedCheck.Object then
