		Visible = false
	})

	task.defer(function()
		if CustomHealth and CustomHealth.Object and Effect then
			CustomHealth.Object.Visible = Effect.Enabled
		end
		if BedCheck and BedCheck.Object and Bed then
			BedCheck.Object.Visible = Bed.Enabled
		end
		if NukerHighlightColor and NukerHighlightColor.Object and BlockHighlight then
			NukerHighlightColor.Object.Visible = BlockHighlight.Enabled
		end
		if TargetMode and TargetMode.Object and Mode then
			TargetMode.Object.Visible = Mode.Value ~= 'Legit'
		end
		if ClosestBreak and ClosestBreak.Object and Mode then
			ClosestBreak.Object.Visible = Mode.Value ~= 'Legit'
		end
		if ViewAngle and ViewAngle.Object and Mode then
			ViewAngle.Object.Visible = Mode.Value ~= 'Legit'
		end
		if SmartBreak and SmartBreak.Object and Mode then
			SmartBreak.Object.Visible = Mode.Value == 'Legit'
		end
		if BlockBreakMode and BlockBreakMode.Object and Mode then
			BlockBreakMode.Object.Visible = Mode.Value == 'Legit'
		end
		if Priority and Priority.Object then
			local val = Priority.Value or 'All'
			if Bed and Bed.Object then
				Bed.Object.Visible = val == 'All' or val == 'Beds'
			end
			if LuckyBlock and LuckyBlock.Object then
				LuckyBlock.Object.Visible = val == 'All' or val == 'Lucky Blocks'
			end
			if IronOre and IronOre.Object then
				IronOre.Object.Visible = val == 'All' or val == 'Ores'
			end
			if Snow and Snow.Object then
				Snow.Object.Visible = val == 'All'
			end
			if Tesla and Tesla.Object then
				Tesla.Object.Visible = val == 'All'
			end
			if Hive and Hive.Object then
				Hive.Object.Visible = val == 'All'
			end
			if Pinata and Pinata.Object then
				Pinata.Object.Visible = val == 'All'
			end
			if Crops and Crops.Object then
				Crops.Object.Visible = val == 'All'
			end
		end
	end)
end)

run(function()
	local DamageIndicator
	local FontOption
	local Color
	local Size
	local Anchor
	local Stroke

	local fn = bedwars.DamageIndicator

	local suc, tab = pcall(function()
		return debug.getupvalue(fn, 2)
	end)
	tab = suc and tab or {}

	local fontIndices = {}
	local strokeIndex
	do
		local ok, consts = pcall(debug.getconstants, fn)
		if ok and consts then
			for i, v in consts do
				if typeof(v) == 'EnumItem' and v.EnumType == Enum.Font then
					table.insert(fontIndices, i)
				elseif v == 'Thickness' or v == 'Enabled' then
					strokeIndex = i
				end
			end
		end
	end
	if #fontIndices == 0 then fontIndices = {86} end
	if not strokeIndex then strokeIndex = 119 end

	local oldvalues = {}
	local oldfonts = {}

	local function applyFont(fontName)
		local font = Enum.Font[fontName]
		if not font then return end
		for _, i in fontIndices do
			pcall(debug.setconstant, fn, i, font)
		end
	end

	local function applyStroke(on)
		pcall(debug.setconstant, fn, strokeIndex, on and 'Thickness' or 'Enabled')
		tab.strokeThickness = on and 1 or false
	end
	
	DamageIndicator = vape.Categories.Legit:CreateModule({
		Name = 'DamageIndicator',
		Function = function(callback)
			if callback then
				oldvalues = table.clone(tab)
				oldfonts = {}
				for _, i in fontIndices do
					oldfonts[i] = debug.getconstant(fn, i)
				end
				applyFont(FontOption.Value)
				applyStroke(Stroke.Enabled)
				tab.textSize = Size.Value
				tab.blowUpSize = Size.Value
				tab.blowUpDuration = 0
				tab.baseColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
				tab.blowUpCompleteDuration = 0
				tab.anchoredDuration = Anchor.Value
			else
				for i, v in oldvalues do
					tab[i] = v
				end
				for i, v in oldfonts do
					pcall(debug.setconstant, fn, i, v)
				end
				pcall(debug.setconstant, fn, strokeIndex, 'Thickness')
			end
		end,
		Tooltip = 'customize the damage indicator'
	})
	local fontitems = {'GothamBlack'}
	for _, v in Enum.Font:GetEnumItems() do
		if v.Name ~= 'GothamBlack' then
			table.insert(fontitems, v.Name)
		end
	end
	FontOption = DamageIndicator:CreateDropdown({
		Name = 'Font',
		List = fontitems,
		Function = function(val)
			if DamageIndicator.Enabled then
				applyFont(val)
			end
		end
	})
	Color = DamageIndicator:CreateColorSlider({
		Name = 'Color',
		DefaultHue = 0,
		Function = function(hue, sat, val)
			if DamageIndicator.Enabled then
				tab.baseColor = Color3.fromHSV(hue, sat, val)
			end
		end
	})
	Size = DamageIndicator:CreateSlider({
		Name = 'Size',
		Min = 1,
		Max = 32,
		Default = 32,
		Function = function(val)
			if DamageIndicator.Enabled then
				tab.textSize = val
				tab.blowUpSize = val
			end
		end
	})
	Anchor = DamageIndicator:CreateSlider({
		Name = 'Anchor',
		Min = 0,
		Max = 1,
		Decimal = 10,
		Function = function(val)
			if DamageIndicator.Enabled then
				tab.anchoredDuration = val
			end
		end
	})
	Stroke = DamageIndicator:CreateToggle({
		Name = 'Stroke',
		Function = function(callback)
			if DamageIndicator.Enabled then
				applyStroke(callback)
			end
		end
	})
end)

run(function()
    local AutoHeph
    local AutoRepair
    local AttackOnRepair

    local COOLDOWN = 6
    local ABILITY_NAMES = {
        'hephaestus_self_repair', 'tinker_self_repair',
        'hephaestus_repair', 'tinker_repair',
        'HEPHAESTUS_SELF_REPAIR', 'TINKER_SELF_REPAIR',
        'HEPHAESTUS_REPAIR', 'TINKER_REPAIR',
        'self_repair', 'SELF_REPAIR',
        'shield_repair', 'SHIELD_REPAIR',
        'kit_repair', 'KIT_REPAIR',
        'forge_repair', 'FORGE_REPAIR',
    }

    local repairingUntil = 0

    local function getKitShield(char)
        local best = 0
        for name, val in char:GetAttributes() do
            if name:find('Shield') and type(val) == 'number' and val > best and name ~= 'Shield_POTION' then
                best = val
            end
        end
        return best
    end

    local function discoverRepairAbilities()
        local found = {}
        pcall(function()
            local ac = bedwars.AbilityController
            for _, v in next, ac do
                if type(v) ~= 'table' then continue end
                for k in next, v do
                    if type(k) == 'string' and k:lower():find('repair') and not table.find(found, k) then
                        table.insert(found, k)
                    end
                end
            end
            for _, fn in {ac.canUseAbility, ac.useAbility, ac.getAbilityCooldown, ac.registerAbility} do
                if type(fn) ~= 'function' then continue end
                for i = 1, 40 do
                    local ok, _, val = pcall(debug.getupvalue, fn, i)
                    if not ok then break end
                    if type(val) ~= 'table' then continue end
                    for k in next, val do
                        if type(k) == 'string' and k:lower():find('repair') and not table.find(found, k) then
                            table.insert(found, k)
                        end
                    end
                end
            end
        end)
        return found
    end

    local function getCharAbilityName()
        local char = lplr.Character
        if char then
            for _, obj in {char, lplr} do
                for attrName, attrVal in obj:GetAttributes() do
                    if type(attrVal) == 'string' and attrVal:lower():find('repair') then
                        return attrVal
                    end
                end
            end
        end
        return nil
    end

    local function fireRepair()
        local ac = bedwars.AbilityController
        local names = discoverRepairAbilities()
        local charAbility = getCharAbilityName()
        if charAbility and not table.find(names, charAbility) then
            table.insert(names, 1, charAbility)
        end
        for _, n in ABILITY_NAMES do
            if not table.find(names, n) then table.insert(names, n) end
        end
        for _, name in names do
            local ok, canUse = pcall(function() return ac:canUseAbility(name) end)
            if ok and canUse then
                pcall(function() ac:useAbility(name) end)
                return true
            end
        end
        return false
    end

    local weaponConfig = nil
    pcall(function()
        local swc = bedwars.SwordController
        for _, fn in {swc.sendServerRequest, swc.swingSwordAtMouse, swc.swingSwordInRegion, swc.isClickingTooFast} do
            if type(fn) ~= 'function' then continue end
            for i = 1, 40 do
                local ok2, weapon, ok3
                local ok, _, val = pcall(debug.getupvalue, fn, i)
                if not ok then break end
                if type(val) ~= 'table' then continue end
                ok2, weapon = pcall(function() return val.Weapon end)
                if not ok2 or type(weapon) ~= 'table' then continue end
                ok3 = pcall(function() return weapon.respectAttackOverride end)
                if ok3 then weaponConfig = val return end
            end
        end
    end)

    local oldIsClickingTooFast = bedwars.SwordController.isClickingTooFast
    local syncConn = nil
    local stunConn = nil
    local charConn = nil

    local function attackUnlocked()
        if not AttackOnRepair or not AttackOnRepair.Enabled then return false end
        return tick() < repairingUntil
    end

    local function connectStunClear(char)
        if stunConn then stunConn:Disconnect() stunConn = nil end
        if not char then return end
        stunConn = char:GetAttributeChangedSignal('StunnedUntilTime'):Connect(function()
            if not attackUnlocked() then return end
            local val = char:GetAttribute('StunnedUntilTime')
            if val and val > workspace:GetServerTimeNow() then
                pcall(function() char:SetAttribute('StunnedUntilTime', 0) end)
            end
        end)
    end

    AutoHeph = vape.Categories.Kits:CreateModule({
        Name = 'AutoHeph',
        Function = function(callback)
            if callback then
                repairingUntil = 0

                bedwars.SwordController.isClickingTooFast = function(self, ...)
                    if attackUnlocked() then
                        if weaponConfig then
                            pcall(function() weaponConfig.Weapon.respectAttackOverride = false end)
                        end
                        return false
                    end
                    return oldIsClickingTooFast(self, ...)
                end

                connectStunClear(lplr.Character)
                charConn = lplr.CharacterAdded:Connect(function(char)
                    connectStunClear(char)
                end)

                pcall(function()
                    local sync = bedwars.ClientSync
                    if sync and type(sync.SwordSwing) == 'table' and type(sync.SwordSwing.setPriority) == 'function' then
                        syncConn = sync.SwordSwing:setPriority(1):Connect(function()
                            if attackUnlocked() and weaponConfig then
                                pcall(function() weaponConfig.Weapon.respectAttackOverride = false end)
                            end
                        end)
                    end
                end)

                local maxShield = 0
                local lastFired = 0
                local prevAlive = false
                local stableVal = -1
                local stableCount = 0

                repeat
                    local alive, char, current, now, cooldownLeft, needsRepair, healPoint
                    task.wait(0.1)

                    if not AutoRepair or not AutoRepair.Enabled then
                        prevAlive = false
                        continue
                    end

                    alive = entitylib.isAlive
                    if not alive then
                        maxShield = 0
                        lastFired = 0
                        prevAlive = false
                        continue
                    end

                    char = lplr.Character
                    if not char then continue end

                    current = getKitShield(char)

                    if current == stableVal then
                        stableCount = stableCount + 1
                    else
                        stableVal = current
                        stableCount = 1
                    end

                    if not prevAlive and current > 0 then
                        maxShield = current
                    elseif stableCount >= 2 and current > maxShield then
                        maxShield = current
                    end
                    prevAlive = true

                    now = tick()
                    cooldownLeft = math.max(0, COOLDOWN - (now - lastFired))
                    healPoint = maxShield * 0.5
                    needsRepair = maxShield > 0 and current <= healPoint

                    if cooldownLeft <= 0 and needsRepair then
                        if fireRepair() then
                            repairingUntil = now + 2
                            lastFired = now
                        end
                    end

                until not AutoHeph.Enabled
            else
                repairingUntil = 0
                bedwars.SwordController.isClickingTooFast = oldIsClickingTooFast
                if stunConn then stunConn:Disconnect() stunConn = nil end
                if charConn then charConn:Disconnect() charConn = nil end
                if syncConn then
                    pcall(function() syncConn:Disconnect() end)
                    syncConn = nil
                end
            end
        end,
        Tooltip = 'fixes ur heph shield by itself when it gets low so u dont gotta think about it'
    })

    AutoRepair = AutoHeph:CreateToggle({
        Name = 'Auto Repair',
        Default = true,
        Tooltip = 'turns the auto fixing on. leave this on gng'
    })

    AttackOnRepair = AutoHeph:CreateToggle({
        Name = 'Attack on Repair',
        Default = true,
        Tooltip = 'lets u keep swingin while ur shield is fixing instead of getting frozen'
    })
end)

run(function()
	local AutoFlora
	local Mode
	local Height
	local Speed
	local nextGlide = 0
	
	AutoFlora = vape.Categories.Kits:CreateModule({
		Name = 'AutoFlora',
		Function = function(callback)
			if callback then
				nextGlide = 0
	
				repeat
					if entitylib.isAlive and store.equippedKit == 'queen_bee' and tick() >= nextGlide and bedwars.AbilityController:canUseAbility('QUEEN_BEE_GLIDE', {disableBlockedAbilityAlert = true}) then
						local root = entitylib.character.RootPart
	
						if root.AssemblyLinearVelocity.Y <= -Speed.Value then
							local drop = Mode.Value == 'Void' and 2000 or Height.Value
							local ground = workspace:Raycast(root.Position, Vector3.new(0, -drop, 0), store.airRay)
	
							if not ground then
								nextGlide = tick() + 1
								bedwars.AbilityController:useAbility('QUEEN_BEE_GLIDE')
							end
						end
					end
					task.wait(0.05)
				until not AutoFlora.Enabled
			end
		end,
		Tooltip = 'Opens the glide the moment you drop with nothing under you'
	})
	
	Mode = AutoFlora:CreateDropdown({
		Name = 'Mode',
		List = {'Void', 'Any Drop'},
		Default = 'Void',
		Function = function(val)
			if Height then
				Height.Object.Visible = val == 'Any Drop'
			end
		end,
		Tooltip = 'autovoids when theres no floor to land on'
	})
	Height = AutoFlora:CreateSlider({
		Name = 'Ground check',
		Min = 5,
		Max = 200,
		Default = 40,
		Visible = false,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	Speed = AutoFlora:CreateSlider({
		Name = 'Fall speed',
		Min = 1,
		Max = 100,
		Default = 20,
		Tooltip = 'change the fall speed of the drop'
	})
	
end)

run(function()
    local AutoStyx
    
    AutoStyx = vape.Categories.Kits:CreateModule({
        Name = 'AutoStyx',
        Function = function(callback)
            if callback then
                local replicatedStorage = game:GetService('ReplicatedStorage')
                
                -- Locate the spawn event and the try open client remote safely
                local spawnEvent
                local tryOpenRemote
                
                spawnEvent = replicatedStorage:FindFirstChild('StyxSpawnExitPortalFromServer', true)
                tryOpenRemote = replicatedStorage:FindFirstChild('StyxTryOpenExitPortalFromClient', true)
                
                if not spawnEvent or not tryOpenRemote then
                    vape:CreateNotification("AutoStyx", "Styx remotes not found!", 5)
                    return
                end
                
                -- Listen for when a Styx portal is spawned/appears and instantly trigger it
                AutoStyx:Clean(spawnEvent.OnClientEvent:Connect(function(data)
                    if not AutoStyx.Enabled then return end
                    if data and data.exitPortalData and data.exitPortalData.uuid then
                        pcall(function()
                            tryOpenRemote:InvokeServer(data.exitPortalData.uuid)
                        end)
                    end
                end))
            end
        end,
        Tooltip = 'Automatically triggers Styx portals the moment they appear.'
    })
end)

run(function()
	local AutoArachne
	local Targets
