		end,
		Tooltip = 'auto strikes enemies when ur grit is full'
	})

	Targets = AutoWarrior:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})
	Range = AutoWarrior:CreateSlider({
		Name = 'Range',
