		Max = 2,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's'
	})
end)

run(function()
	local AutoFortify

	local function getOwnBedPosition()
		local playerTeam = lplr:GetAttribute('Team')
		if not playerTeam then return nil end
		local tagged = collectionService:GetTagged('bed')
		for _, bed in ipairs(tagged) do
			if bed:GetAttribute('Team'..playerTeam..'NoBreak') then
				return bed.Position
			end
		end
		return nil
	end

	local function fortifyAround(start)
		for x = -3, 3 do
			for y = -3, 3 do
				for z = -3, 3 do
					local offset = Vector3.new(x * 3, y * 3, z * 3)
					local block, roundedPos = getPlacedBlock(start + offset)
					if block and block.Name ~= 'bed' then
						pcall(function()
							game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("FortifyBlock"):FireServer(roundedPos)
						end)
					end
				end
			end
		end
	end

	AutoFortify = vape.Categories.Kits:CreateModule({
		Name = 'AutoFortify',
		Function = function(callback)
			if not callback then return end
			task.spawn(function()
				repeat
					local bedPos = getOwnBedPosition()
					if bedPos then
						fortifyAround(bedPos)
						fortifyAround(bedPos + Vector3.new(0,0,3))
					end
					task.wait(2)
				until not AutoFortify or not AutoFortify.Enabled
			end)
		end,
		Tooltip = 'auto fortifies blocks around your bed from anywhere'
	})
end)

run(function()
	local AutoKaliyah
	local Range
	local Delay
	local NoSlow
	local StackMode
	
	local Legit = (getFunctionRange and getFunctionRange(bedwars.DragonSlayerController.hasEligiblePunchTarget)) or 14.4
	local modifier, old
	local noSlowUntil = 0
	
	local stackValues = {
		['S1'] = 1,
		['S2'] = 2,
		['S3'] = 3
	}
	
	local function punch()
		if NoSlow and NoSlow.Enabled then
			if not old then
				modifier = bedwars.SprintController and bedwars.SprintController:getMovementStatusModifier()
				if modifier then
					old = modifier.addModifier
					modifier.addModifier = function(self, tab)
						if NoSlow.Enabled and tick() < noSlowUntil and tab and tab.moveSpeedMultiplier == 0 then
							tab.moveSpeedMultiplier = 1
						end
						return old(self, tab)
					end
				end
			end
			if Delay then
				noSlowUntil = math.max(noSlowUntil, tick() + Delay.Value + 0.1)
			end
		end
	
		if Delay then
			task.wait(Delay.Value)
		end
		bedwars.AbilityController:useAbility('dragon_slayer_punch')
	end
	
	AutoKaliyah = vape.Categories.Kits:CreateModule({
		Name = 'AutoKaliyah',
		Function = function(call)
			if call then
				task.spawn(function()
					repeat
						if entitylib.isAlive and store.equippedKit == 'dragon_slayer' and bedwars.AbilityController:canUseAbility('dragon_slayer_punch', {disableBlockedAbilityAlert = true}) then
							local localPosition = entitylib.character.RootPart.Position
							local requiredStacks = stackValues[StackMode.Value] or 1
							
							if bedwars.DragonSlayerController and bedwars.DragonSlayerController.dragonEmblems then
								for target, v in bedwars.DragonSlayerController.dragonEmblems do
									if v.stackCount >= requiredStacks and target.PrimaryPart and (target.PrimaryPart.Position - localPosition).Magnitude <= Range.Value then
										punch()
										break
									end
								end
							end
						end
						task.wait(0.1)
					until not AutoKaliyah.Enabled
				end)
			end
		end,
		Tooltip = 'Automatically uses the "punch" ability from kaliyah'
	})

	StackMode = AutoKaliyah:CreateDropdown({
		Name = 'Stack Mode',
		List = {'S1', 'S2', 'S3'},
		Default = 'S1',
		Tooltip = 'Minimum dragon slayer stacks required before activating punch'
	})

	NoSlow = AutoKaliyah:CreateToggle({
		Name = 'No Slow',
		Default = true,
		Tooltip = 'Prevents you from being slowed down after using the "Punch" ability'
	})

	Range = AutoKaliyah:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 20,
		Default = 18,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})

	AutoKaliyah:CreateButton({
		Name = 'Sync to legit range',
		Function = function()
			Range:SetValue(Legit)
		end
	})

	Delay = AutoKaliyah:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100
	})
end)

run(function()
	local MetalDetectorSpy
	local TeamCheckToggle
	
	MetalDetectorSpy = vape.Categories.KitSpy:CreateModule({
		Name = 'MetalDetectorSpy',
		Function = function(callback)
			if callback then
				local remote = nil
				pcall(function()
					remote = replicatedStorage.rbxts_include.node_modules["@rbxts"].net.out._NetManaged.BillboardRiseEffect
				end)
				
				local validItems = {
					iron = true,
					diamond = true,
					emerald = true,
					gold = true
				}
				
				local debounceCache = {}
				
				if remote then
					MetalDetectorSpy:Clean(remote.OnClientEvent:Connect(function(data)
						if type(data) ~= 'table' or not data.itemType or not data.position then return end
						
						local item = tostring(data.itemType):lower()
						if not validItems[item] then return end
						
						local pos = data.position
						
						local posKey = math.floor(pos.X / 15) .. "_" .. math.floor(pos.Y / 15) .. "_" .. math.floor(pos.Z / 15)
						local cacheKey = item .. "_" .. posKey
						
						if debounceCache[cacheKey] and (tick() - debounceCache[cacheKey]) < 1.5 then
							return 
						end
						debounceCache[cacheKey] = tick()
						
						local closestPlayer = nil
						local closestDist = 25 
						
						for _, ent in entitylib.List do
							if ent and ent.RootPart then
								local dist = (ent.RootPart.Position - pos).Magnitude
								if dist < closestDist then
									closestDist = dist
									closestPlayer = ent
								end
							end
						end
						
						local isLocalPlayer = false
						if entitylib.isAlive and entitylib.character.RootPart then
							local dist = (entitylib.character.RootPart.Position - pos).Magnitude
							if dist < closestDist then
								closestDist = dist
								isLocalPlayer = true
							end
						end
						
						if isLocalPlayer then
							return
						end
						
						if closestPlayer and closestPlayer.Player then
							-- Strict team check: ignore if teammate found the item
							if TeamCheckToggle.Enabled then
								local p = closestPlayer.Player
								local isTeammate = false
								if shared.isPlayerOnTeam and shared.isPlayerOnTeam(p) then
									isTeammate = true
								elseif p.Team and lplr.Team and p.Team == lplr.Team then
									isTeammate = true
								end
								if isTeammate then return end
							end

							local playerName = closestPlayer.Player.DisplayName or closestPlayer.Player.Name
							local formattedItem = item:gsub("^%l", string.upper)
							
							notif('MetalDetectorSpy', `{playerName} found {formattedItem}!`, 5, 'info')
						end
					end))
				else
					if MetalDetectorSpy.Enabled then
						notif('MetalDetectorSpy', 'Could not find the BillboardRiseEffect remote.', 5, 'warning')
					end
				end
			end
		end,
		Tooltip = 'Notifies you when other players get metal detector loot'
	})

	TeamCheckToggle = MetalDetectorSpy:CreateToggle({
		Name = 'TeamCheck',
		Default = false,
		Tooltip = 'Ignores teammates for metal detector notifications'
	})
end)

run(function()
	local BountyHunterSpy
	local TeamCheckToggle
	
	BountyHunterSpy = vape.Categories.KitSpy:CreateModule({
		Name = 'BountyHunterSpy',
		Function = function(callback)
			if callback then
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local Players = game:GetService("Players")
				local lplr = Players.LocalPlayer
				
				local remotePath = ReplicatedStorage:FindFirstChild("rbxts_include")
				and ReplicatedStorage.rbxts_include:FindFirstChild("node_modules")
				and ReplicatedStorage.rbxts_include.node_modules:FindFirstChild("@rbxts")
				and ReplicatedStorage.rbxts_include.node_modules["@rbxts"].net
				and ReplicatedStorage.rbxts_include.node_modules["@rbxts"].net.out
				and ReplicatedStorage.rbxts_include.node_modules["@rbxts"].net.out._NetManaged
				and ReplicatedStorage.rbxts_include.node_modules["@rbxts"].net.out._NetManaged:FindFirstChild("BountyHunterTargetChanged")
				
				if not remotePath then
					warning("[BountyHunterSpy] BountyHunterTargetChanged remote not found!")
					return
				end

				local activeBounties = {}

				local function formatReward(reward)
					if not reward then return "Unknown" end
					local parts = {}
					for item, amount in pairs(reward) do
						if item ~= "assignedTime" and type(amount) == "number" and amount > 0 then
							table.insert(parts, amount .. " " .. item)
						end
					end
					return #parts > 0 and table.concat(parts, ", ") or "No reward"
				end

				local function checkTeam(plr)
					if not plr then return false end
					if shared.isPlayerOnTeam and shared.isPlayerOnTeam(plr) then
						return true
					end
					if plr.Team and lplr.Team and plr.Team == lplr.Team then
						return true
					end
					return false
				end

				BountyHunterSpy:Clean(remotePath.OnClientEvent:Connect(function(data)
					if not data or not data.hunter then return end
					
					local hunter = data.hunter
					local newTargetUserId = data.newTargetUserId
					local reward = data.reward
					
					local targetPlayer = Players:GetPlayerByUserId(newTargetUserId)
					
					if TeamCheckToggle.Enabled then
						-- Ignore if the target OR the hunter is on your team
						if checkTeam(targetPlayer) or checkTeam(hunter) then
							return
						end
					end

					local targetName = targetPlayer and targetPlayer.Name or ("UserId: " .. tostring(newTargetUserId))
					local rewardStr = formatReward(reward)

					activeBounties[hunter] = {
						targetUserId = newTargetUserId,
						targetPlayer = targetPlayer,
						reward = reward
					}

					vape:CreateNotification("Bounty Hunter Spy", string.format("%s is now hunting %s! Reward: %s", hunter.Name, targetName, rewardStr), 6)

					if targetPlayer then
						local connection
						connection = game:GetService("RunService").Heartbeat:Connect(function()
							if not BountyHunterSpy.Enabled then
								connection:Disconnect()
								return
							end

							local char = targetPlayer.Character
							local hum = char and char:FindFirstChildOfClass("Humanoid")
							
							if not targetPlayer.Parent or (hum and hum.Health <= 0) then
								connection:Disconnect()
								if activeBounties[hunter] and activeBounties[hunter].targetUserId == newTargetUserId then
									vape:CreateNotification("Bounty Eliminated!", string.format("%s successfully killed their target %s and claimed %s!", hunter.Name, targetName, rewardStr), 8)
									activeBounties[hunter] = nil
								end
							end
						end)
						BountyHunterSpy:Clean(connection)
					end
				end))
			end
		end,
		Tooltip = 'Notifies you when players take bounties, who their targets are, their rewards, and when they secure a kill.'
	})

	TeamCheckToggle = BountyHunterSpy:CreateToggle({
		Name = 'TeamCheck',
		Default = false,
		Tooltip = 'Ignores bounties involving your teammates'
	})
end)

