run(function()
	local TurretRecall
	local HPThreshold
	local recalled = {}
	local takeBackRemote = game:GetService('ReplicatedStorage'):WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('TakeBackCameraTurret')

	local function getMaxHealth(turret)
		local ok, result = pcall(function()
			return bedwars.ItemMeta[turret.Name].block.health
		end)
		return (ok and result) or turret:GetAttribute('MaxHealth') or 50
	end

	local function getCurrentHealth(turret)
		local blockpos = bedwars.BlockController:getBlockPosition(turret.Position)
		local blockdata = bedwars.BlockController:getStore():getBlockData(blockpos)
		return (blockdata and (blockdata:GetAttribute('1') or blockdata:GetAttribute('Health'))) or turret:GetAttribute('Health') or 0
	end

	local function recallTurret(turret)
		if recalled[turret] then return end
		recalled[turret] = true
		local blockPos = bedwars.BlockController:getBlockPosition(turret.Position)
		pcall(function()
			takeBackRemote:FireServer({turretBlockPos = blockPos})
		end)
	end

	local function watchTurret(turret)
		if not (TurretRecall and TurretRecall.Enabled) then return end
		if turret:GetAttribute('PlacedByUserId') ~= lplr.UserId then return end
		local maxHp = getMaxHealth(turret)
		task.spawn(function()
			while turret and turret.Parent do
				task.wait(0.1)
				if not TurretRecall.Enabled then continue end
				local hp = getCurrentHealth(turret)
				local threshold = (HPThreshold.Value / 100) * maxHp
				if hp <= threshold then
					recallTurret(turret)
					break
				end
			end
		end)
		turret.AncestryChanged:Connect(function()
			if not turret.Parent then
				recalled[turret] = nil
			end
		end)
	end

	collectionService:GetInstanceAddedSignal('Turret'):Connect(watchTurret)
	for _, v in collectionService:GetTagged('Turret') do
		watchTurret(v)
	end

	TurretRecall = vape.Categories.Kits:CreateModule({
		Name = 'TurretRecall',
		Tooltip = 'picks up your turrent based off hp threshold'
	})
	HPThreshold = TurretRecall:CreateSlider({
		Name = 'HP Threshold',
		Min = 1,
		Max = 50,
		Default = 20,
		Suffix = function(v) return '%' end
	})
end)

run(function()
    local DeviceSpoofer
    local Device
    local oldDevice, old
    
    DeviceSpoofer = vape.Categories.Utility:CreateModule({
        Name = 'DeviceSpoofer',
        Function = function(callback)
            if callback then
                oldDevice, old = bedwars.UserInputController:getUserInputType(), bedwars.UserInputController.getUserInputType
                bedwars.UserInputController.getUserInputType = function()
                    local val = Device.Value
                    if val == 'SmartFridge' then
                        return 'SMART_FRIDGE'
                    elseif val == 'VR' then
                        return 'VR'
                    end
                    return val:upper()
                end
                
                local sendVal = Device.Value == 'SmartFridge' and 'SMART_FRIDGE' or (Device.Value == 'VR' and 'VR' or Device.Value:upper())
                bedwars.Handler:Get('SendUserInputType'):Fire('SendToServer', {userInputType = sendVal})
            else
                bedwars.UserInputController.getUserInputType = old
                bedwars.Handler:Get('SendUserInputType'):Fire('SendToServer', {userInputType = oldDevice})
                old = nil
            end
        end,
        Tooltip = 'Spoofs the device you show up as to the server',
        ExtraText = function()
            return Device.Value
        end
    })
    
    Device = DeviceSpoofer:CreateDropdown({
        Name = 'Device',
        List = {'Mobile', 'PC', 'Gamepad'},
        Function = function(val)
            if DeviceSpoofer.Enabled then
                local sendVal = val == 'SmartFridge' and 'SMART_FRIDGE' or (val == 'VR' and 'VR' or val:upper())
                bedwars.Handler:Get('SendUserInputType'):Fire('SendToServer', {userInputType = sendVal})
            end
        end
    })
end)

run(function()
	local TerraAimbot
	local TATargets
	local TAFOV
	local TARange
	local TASort
	local TATargetPart
	local terraOldNC

	TerraAimbot = vape.Categories.Blatant:CreateModule({
		Name = 'TerraAimbot',
		Tooltip = 'aimbot for terra',
		Function = function(callback)
			if callback then
				local tryBlockKick
				pcall(function()
					tryBlockKick = replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged:FindFirstChild('TryBlockKick')
				end)
				if not tryBlockKick then
					notif('TerraAimbot', 'terra kick remote not found', 3, 'warning')
					if TerraAimbot.Enabled then TerraAimbot:Toggle() end
					return
				end

				local terraAim = nil

				local targetThread = task.spawn(function()
					while TerraAimbot.Enabled do
						local aim = nil
						local root = entitylib.isAlive and entitylib.character and entitylib.character.RootPart
						if root then
							local origin = root.Position
							local ent = entitylib.EntityMouse({
								Part = TATargetPart.Value,
								Range = TAFOV.Value,
								Players = TATargets.Players.Enabled,
								NPCs = TATargets.NPCs and TATargets.NPCs.Enabled or false,
								Wallcheck = TATargets.Walls.Enabled,
								Origin = origin,
							}) or entitylib.EntityPosition({
								Origin = origin,
								Range = TARange.Value,
								Part = TATargetPart.Value,
								Players = TATargets.Players.Enabled,
								NPCs = TATargets.NPCs and TATargets.NPCs.Enabled or false,
								Wallcheck = TATargets.Walls.Enabled,
								Sort = sortmethods[TASort.Value],
							})
							if ent and ent[TATargetPart.Value] then
								local targetPos = ent[TATargetPart.Value].Position
								local targetVel = ent[TATargetPart.Value].AssemblyLinearVelocity or ent[TATargetPart.Value].Velocity or Vector3.zero
								local dist = (targetPos - origin).Magnitude
								local travelTime = math.clamp(dist / 40, 0, 0.4)
								local predictedPos = targetPos + targetVel * travelTime
								local aimPoint = predictedPos + Vector3.new(0, 6, 0)
								local dir = aimPoint - origin
								if dir.Magnitude > 0 then
									dir = dir.Unit
									aim = {
										direction = dir,
										originPosition = origin + Vector3.new(0, 3, 0) + dir * 2,
									}
								end
							end
						end
						terraAim = aim
						task.wait()
					end
				end)

				terraOldNC = hookmetamethod(game, '__namecall', newcclosure(function(self, ...)
					if self == tryBlockKick and getnamecallmethod() == 'FireServer' then
						if TerraAimbot.Enabled and terraAim then
							local argsTable = ...
							if type(argsTable) == 'table' then
								argsTable.direction = terraAim.direction
								argsTable.originPosition = terraAim.originPosition
							end
						end
					end
					return terraOldNC(self, ...)
				end))

				TerraAimbot:Clean(function()
					if terraOldNC then
						hookmetamethod(game, '__namecall', terraOldNC)
						terraOldNC = nil
					end
				end)
				TerraAimbot:Clean(function()
					if targetThread then
						task.cancel(targetThread)
						targetThread = nil
					end
				end)
			end
		end,
	})

	TATargets = TerraAimbot:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = false,
	})

	TAFOV = TerraAimbot:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 800,
		Default = 200,
	})

	TARange = TerraAimbot:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 1000,
		Default = 60,
		Suffix = function(val) return val == 1 and 'stud' or 'studs' end,
	})

	TATargetPart = TerraAimbot:CreateDropdown({
		Name = 'Target Part',
		List = {'RootPart', 'Head'},
		Default = 'RootPart',
	})

	TASort = TerraAimbot:CreateDropdown({
		Name = 'Sort',
		List = {'Cursor', 'Angle'},
		Default = 'Cursor',
	})
end)

run(function()
	local SigridDisabler
	local elkCtrl = nil
	local modMaid = nil
	local sentMount = false

	local function getElk()
		local ok, Knit = pcall(function()
			return require(game.ReplicatedStorage.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
		end)
		if not ok or not Knit then return nil end
		return Knit.Controllers.ElkMasterController
	end

	SigridDisabler = vape.Categories.Kits:CreateModule({
		Name = 'Sigrid Disabler',
		Function = function(callback)
			if callback then
				elkCtrl = getElk()
				if not elkCtrl then
					notif('Sigrid Disabler', 'u aint on sigrid gng', 5, 'alert')
					task.defer(function()
						if SigridDisabler.Enabled then
							SigridDisabler:Toggle()
						end
					end)
					return
				end

				sentMount = false
				pcall(function()
					local Knit = require(game.ReplicatedStorage.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
					local Maid = require(game.ReplicatedStorage.rbxts_include.node_modules['@rbxts'].maid.Maid)
					modMaid = Maid.new()
					modMaid:GiveTask(Knit.Controllers.SprintController:getMovementStatusModifier():addModifier({
						blockSprint = false,
						moveSpeedMultiplier = 1.5
					}))
					modMaid:GiveTask(Knit.Controllers.JumpHeightController:getJumpModifier():addModifier({
						jumpHeightMultiplier = 1.6
					}))
				end)

				local lastForce = 0
				SigridDisabler:Clean(runService.Heartbeat:Connect(function()
					if not elkCtrl or not SigridDisabler.Enabled then return end
					if (tick() - lastForce) < 0.25 then return end
					lastForce = tick()
					pcall(function()
						elkCtrl.isMounted = true
						if elkCtrl.summonAbilityMaid then
							elkCtrl.summonAbilityMaid:DoCleaning()
							elkCtrl.summonAbilityMaid = nil
						end
						local Knit = require(game.ReplicatedStorage.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
						Knit.Controllers.BlockPlacementController:enableBlockPlacer()
					end)
				end))

				task.spawn(function()
					repeat
						if entitylib.isAlive and store.equippedKit == 'elk_master' then
							if not sentMount then
								sentMount = true
								pcall(function()
									bedwars.Client:Get('ElkKitMounted'):SendToServer()
								end)
							end
						else
							sentMount = false
						end
						task.wait(0.5)
					until not SigridDisabler.Enabled
				end)
			else
				sentMount = false
				if modMaid then
					pcall(function() modMaid:DoCleaning() end)
					modMaid = nil
				end
				if elkCtrl then
					pcall(function() elkCtrl.isMounted = false end)
					pcall(function()
						if elkCtrl.summonAbilityMaid then
							elkCtrl.summonAbilityMaid:DoCleaning()
							elkCtrl.summonAbilityMaid = nil
						end
						if elkCtrl.playerModifierMaid then
							elkCtrl.playerModifierMaid:DoCleaning()
							elkCtrl.playerModifierMaid = nil
						end
					end)
					pcall(function()
						local Knit = require(game.ReplicatedStorage.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
						Knit.Controllers.SwordController:toggleSwordSwing(false)
						Knit.Controllers.BlockPlacementController:enableBlockPlacer()
					end)
					pcall(function()
						local MountType = require(game.ReplicatedStorage.TS.mount['mount-type']).MountType
						bedwars.Client:Get('Dismount'):SendToServer({mountType = MountType.ELK})
					end)
					pcall(function()
						bedwars.Client:Get('Dismount'):SendToServer({mountType = 'elk'})
					end)
				end
				elkCtrl = nil
			end
		end
	})
end)

run(function()
	local KrystalDisabler
	local oldMomentum = nil
	local krystalCtrl = nil

